import type { BankQuestion } from "@/lib/bank";

/** Human Body and Biology Basics (General Science): 375 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"sci-biology-1","question":"Which organelle is called the “powerhouse of the cell”?","options":["Ribosome","Chloroplast","Mitochondria","Golgi apparatus"],"answer":2,"explanation":"Mitochondria carry out aerobic respiration (Krebs cycle and oxidative phosphorylation) and make most of the cell's ATP. Chloroplasts trap light energy but only in plant cells, and they store it as sugar rather than supplying ATP to the whole cell.","difficulty":"easy","questionHi":"किस कोशिकांग को “कोशिका का ऊर्जा घर (पावरहाउस)” कहा जाता है?","optionsHi":["राइबोसोम","हरित लवक (क्लोरोप्लास्ट)","माइटोकॉन्ड्रिया","गॉल्जी उपकरण"],"explanationHi":"माइटोकॉन्ड्रिया में वायवीय श्वसन (क्रेब्स चक्र और ऑक्सीडेटिव फॉस्फोरिलेशन) होता है और कोशिका का अधिकांश ATP यहीं बनता है। हरित लवक प्रकाश ऊर्जा को ग्रहण करते हैं, परंतु केवल पादप कोशिकाओं में, और वे उसे पूरी कोशिका को ATP देने के बजाय शर्करा के रूप में संचित करते हैं।"},
  {"id":"sci-biology-2","question":"Insulin is secreted by the:","options":["Liver","Pancreas","Adrenal gland","Thyroid"],"answer":1,"explanation":"The beta cells of the pancreas (islets of Langerhans) secrete insulin.","difficulty":"easy","questionHi":"इंसुलिन का स्राव किसके द्वारा होता है?","optionsHi":["यकृत","अग्न्याशय","अधिवृक्क ग्रंथि","थायरॉइड"],"explanationHi":"अग्न्याशय की बीटा कोशिकाएँ (लैंगरहैंस की द्वीपिकाएँ) इंसुलिन का स्राव करती हैं।"},
  {"id":"sci-biology-3","question":"Which is the largest organ of the human body?","options":["Liver","Skin","Heart","Lungs"],"answer":1,"explanation":"The skin is the largest organ; the liver is the largest internal organ and gland.","difficulty":"easy","questionHi":"मानव शरीर का सबसे बड़ा अंग कौन-सा है?","optionsHi":["यकृत","त्वचा","हृदय","फेफड़े"],"explanationHi":"त्वचा सबसे बड़ा अंग है; यकृत सबसे बड़ा आंतरिक अंग और ग्रंथि है।"},
  {"id":"sci-biology-4","question":"Deficiency of Vitamin C causes:","options":["Rickets","Scurvy","Night blindness","Beriberi"],"answer":1,"explanation":"Vitamin C is needed to make collagen, so its lack gives scurvy with bleeding, spongy gums and poor wound healing. Rickets is vitamin D, night blindness vitamin A and beriberi vitamin B1 deficiency.","difficulty":"moderate","questionHi":"विटामिन C की कमी से कौन-सा रोग होता है?","optionsHi":["रिकेट्स","स्कर्वी","रतौंधी","बेरी-बेरी"],"explanationHi":"कोलेजन बनाने के लिए विटामिन C आवश्यक है, इसलिए इसकी कमी से स्कर्वी होता है, जिसमें रक्तस्राव, मसूड़ों में सूजन और घाव देर से भरना जैसे लक्षण दिखते हैं। रिकेट्स विटामिन D की, रतौंधी विटामिन A की और बेरी-बेरी विटामिन B1 की कमी से होता है।"},
  {"id":"sci-biology-5","question":"Which is the largest gland in the human body?","options":["Pancreas","Thyroid","Liver","Pituitary"],"answer":2,"explanation":"The liver is the largest gland; the skin is the largest organ.","difficulty":"moderate","questionHi":"मानव शरीर की सबसे बड़ी ग्रंथि कौन-सी है?","optionsHi":["अग्न्याशय","थायरॉइड","यकृत","पीयूष ग्रंथि"],"explanationHi":"यकृत सबसे बड़ी ग्रंथि है; त्वचा सबसे बड़ा अंग है।"},
  {"id":"sci-biology-6","question":"Which blood group is called the universal donor?","options":["A","B","AB","O"],"answer":3,"explanation":"Group O (negative) red cells carry no A or B antigens, so they can be given to any group.","difficulty":"moderate","questionHi":"कौन-सा रक्त समूह सार्वभौमिक दाता (यूनिवर्सल डोनर) कहलाता है?","optionsHi":["A","B","AB","O"],"explanationHi":"समूह O (ऋणात्मक) की लाल रक्त कोशिकाओं में A या B प्रतिजन नहीं होते, इसलिए इसे किसी भी समूह को दिया जा सकता है।"},
  {"id":"sci-biology-7","question":"Which vitamin is made in the skin in sunlight?","options":["Vitamin A","Vitamin B12","Vitamin C","Vitamin D"],"answer":3,"explanation":"Ultraviolet light converts a cholesterol derivative in the skin into Vitamin D.","difficulty":"hard","questionHi":"धूप में त्वचा में कौन-सा विटामिन बनता है?","optionsHi":["विटामिन A","विटामिन B12","विटामिन C","विटामिन D"],"explanationHi":"पराबैंगनी प्रकाश त्वचा में उपस्थित कोलेस्ट्रॉल के एक व्युत्पन्न को विटामिन D में बदल देता है।"},
  {"id":"sci-biology-8","question":"A normal human cell has how many pairs of chromosomes?","options":["22","23","44","46"],"answer":1,"explanation":"A normal diploid human cell has 46 chromosomes arranged as 23 pairs (22 pairs of autosomes plus one pair of sex chromosomes). 46 is the trap: it counts single chromosomes, not pairs.","difficulty":"hard","questionHi":"एक सामान्य मानव कोशिका में गुणसूत्रों के कितने जोड़े होते हैं?","optionsHi":["22","23","44","46"],"explanationHi":"एक सामान्य द्विगुणित मानव कोशिका में 46 गुणसूत्र 23 जोड़ों में व्यवस्थित होते हैं (22 जोड़े अलिंगी गुणसूत्र और एक जोड़ा लिंग गुणसूत्र)। 46 भ्रम का विकल्प है: यह जोड़ों की नहीं, अलग-अलग गुणसूत्रों की संख्या है।"},
  {"id":"sci-biology-9","question":"Red blood cells are produced in the:","options":["Liver","Bone marrow","Spleen","Lymph nodes"],"answer":1,"explanation":"Red bone marrow produces red blood cells; the spleen destroys old ones.","difficulty":"hard","questionHi":"लाल रक्त कोशिकाओं का निर्माण कहाँ होता है?","optionsHi":["यकृत","अस्थि मज्जा","प्लीहा","लसीका ग्रंथियाँ"],"explanationHi":"लाल अस्थि मज्जा लाल रक्त कोशिकाओं का निर्माण करती है; प्लीहा पुरानी कोशिकाओं को नष्ट करती है।"},
  {"id":"sci-biology-10","question":"Which part of the brain controls balance and coordination?","options":["Cerebrum","Cerebellum","Medulla oblongata","Hypothalamus"],"answer":1,"explanation":"The cerebellum, in the hindbrain, coordinates voluntary movements and keeps posture and balance (drunken staggering reflects it being affected). The medulla controls heartbeat and breathing, and the cerebrum handles thinking and voluntary action.","difficulty":"very-hard","questionHi":"मस्तिष्क का कौन-सा भाग संतुलन और समन्वय को नियंत्रित करता है?","optionsHi":["प्रमस्तिष्क","अनुमस्तिष्क","मेडुला ऑब्लांगेटा (सुषुम्ना शीर्ष)","हाइपोथैलेमस"],"explanationHi":"पश्च मस्तिष्क में स्थित अनुमस्तिष्क ऐच्छिक गतियों का समन्वय करता है तथा शरीर की मुद्रा और संतुलन बनाए रखता है (शराबी का लड़खड़ाना इसके प्रभावित होने का परिणाम है)। मेडुला हृदय गति और श्वसन को नियंत्रित करता है, और प्रमस्तिष्क सोचने तथा ऐच्छिक क्रियाओं को संभालता है।"},
  {"id":"sci-biology-11","question":"The structural and functional unit of the kidney is the:","options":["Neuron","Nephron","Alveolus","Villus"],"answer":1,"explanation":"Each kidney has about a million nephrons that filter blood to form urine.","difficulty":"very-hard","questionHi":"वृक्क (गुर्दे) की संरचनात्मक और क्रियात्मक इकाई क्या है?","optionsHi":["न्यूरॉन","नेफ्रॉन","वायुकोष्ठिका","अंकुर (विलाई)"],"explanationHi":"प्रत्येक वृक्क में लगभग दस लाख नेफ्रॉन होते हैं, जो रक्त को छानकर मूत्र बनाते हैं।"},
  {"id":"sci-biology-12","question":"The average lifespan of a human red blood cell is about:","options":["12 days","60 days","120 days","365 days"],"answer":2,"explanation":"Red blood cells live about 120 days before being broken down in the spleen and liver.","difficulty":"very-hard","questionHi":"मानव लाल रक्त कोशिका का औसत जीवनकाल लगभग कितना होता है?","optionsHi":["12 दिन","60 दिन","120 दिन","365 दिन"],"explanationHi":"लाल रक्त कोशिकाएँ लगभग 120 दिन जीवित रहती हैं, उसके बाद प्लीहा और यकृत में टूटकर नष्ट हो जाती हैं।"},
  {"id":"sci-biology-13","question":"The largest organ of the human body is the:","options":["Liver","Skin","Lungs","Brain"],"answer":1,"explanation":"Skin is the largest organ; the liver is the largest internal organ.","difficulty":"easy","source":"RRB Group D · SSC CHSL","questionHi":"मानव शरीर का सबसे बड़ा अंग कौन-सा है?","optionsHi":["यकृत","त्वचा","फेफड़े","मस्तिष्क"],"explanationHi":"त्वचा सबसे बड़ा अंग है; यकृत सबसे बड़ा आंतरिक अंग है।"},
  {"id":"sci-biology-14","question":"Which blood group is the “universal donor”?","options":["A positive","B negative","AB positive","O negative"],"answer":3,"explanation":"O negative has no A, B or Rh antigens, so it can be given to anyone.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"कौन-सा रक्त समूह “सार्वभौमिक दाता” है?","optionsHi":["A धनात्मक","B ऋणात्मक","AB धनात्मक","O ऋणात्मक"],"explanationHi":"O ऋणात्मक में A, B या Rh प्रतिजन नहीं होते, इसलिए इसे किसी को भी दिया जा सकता है।"},
  {"id":"sci-biology-15","question":"Pellagra, marked by dermatitis, diarrhoea and dementia, is caused by deficiency of:","options":["Thiamine (vitamin B1)","Niacin (vitamin B3)","Riboflavin (vitamin B2)","Vitamin B12 (cobalamin)"],"answer":1,"explanation":"Pellagra (the '3 Ds') results from lack of niacin, common where diets depend heavily on maize. Thiamine lack causes beriberi, riboflavin lack causes cracked lips and mouth sores, and B12 lack causes pernicious anaemia.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"पेलाग्रा, जिसमें त्वचाशोथ, दस्त और मनोभ्रंश (डिमेंशिया) के लक्षण होते हैं, किसकी कमी से होता है?","optionsHi":["थायमिन (विटामिन B1)","नायसिन (विटामिन B3)","राइबोफ्लेविन (विटामिन B2)","विटामिन B12 (कोबालामिन)"],"explanationHi":"पेलाग्रा (तीन ‘D’ वाला रोग) नायसिन की कमी से होता है, जो उन क्षेत्रों में आम है जहाँ भोजन मुख्यतः मक्के पर निर्भर है। थायमिन की कमी से बेरी-बेरी, राइबोफ्लेविन की कमी से होंठ फटना और मुँह के छाले, तथा B12 की कमी से घातक रक्ताल्पता होती है।"},
  {"id":"sci-biology-16","question":"Insulin is produced by which cells of the pancreas?","options":["Alpha cells","Beta cells","Delta cells","Kupffer cells"],"answer":1,"explanation":"Beta cells of the islets of Langerhans secrete insulin; alpha cells secrete glucagon.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"इंसुलिन अग्न्याशय की किन कोशिकाओं द्वारा बनाया जाता है?","optionsHi":["ऐल्फा कोशिकाएँ","बीटा कोशिकाएँ","डेल्टा कोशिकाएँ","कुफ़्फ़र कोशिकाएँ"],"explanationHi":"लैंगरहैंस की द्वीपिकाओं की बीटा कोशिकाएँ इंसुलिन का स्राव करती हैं; ऐल्फा कोशिकाएँ ग्लूकागॉन का स्राव करती हैं।"},
  {"id":"sci-biology-17","question":"The normal human body has how many pairs of chromosomes?","options":["22","23","24","46"],"answer":1,"explanation":"Humans have 23 pairs (46 chromosomes), including one pair of sex chromosomes.","difficulty":"hard","source":"SSC CGL · RRB Group D","questionHi":"सामान्य मानव शरीर में गुणसूत्रों के कितने जोड़े होते हैं?","optionsHi":["22","23","24","46"],"explanationHi":"मनुष्य में 23 जोड़े (46 गुणसूत्र) होते हैं, जिनमें एक जोड़ा लिंग गुणसूत्रों का होता है।"},
  {"id":"sci-biology-18","question":"Which part of the human eye controls the amount of light entering it?","options":["Cornea","Iris","Retina","Lens"],"answer":1,"explanation":"The iris adjusts the size of the pupil; the retina forms the image.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"मानव नेत्र का कौन-सा भाग आँख में प्रवेश करने वाले प्रकाश की मात्रा को नियंत्रित करता है?","optionsHi":["कॉर्निया","परितारिका (आइरिस)","दृष्टिपटल (रेटिना)","लेंस"],"explanationHi":"परितारिका पुतली के आकार को समायोजित करती है; प्रतिबिंब दृष्टिपटल पर बनता है।"},
  {"id":"sci-biology-19","question":"Which vessel carries oxygenated blood from the lungs to the heart?","options":["Pulmonary artery","Pulmonary vein","Aorta","Vena cava"],"answer":1,"explanation":"Pulmonary veins are the only veins that carry oxygenated blood.","difficulty":"hard","questionHi":"कौन-सी वाहिका फेफड़ों से हृदय तक ऑक्सीजनयुक्त रक्त ले जाती है?","optionsHi":["फुफ्फुसीय धमनी","फुफ्फुसीय शिरा","महाधमनी","महाशिरा"],"explanationHi":"फुफ्फुसीय शिराएँ ही एकमात्र शिराएँ हैं जो ऑक्सीजनयुक्त रक्त ले जाती हैं।"},
  {"id":"sci-biology-20","question":"Which of these is NOT a function of the liver?","options":["Making bile","Storing glycogen","Detoxifying drugs","Producing insulin"],"answer":3,"explanation":"The liver makes bile, stores glucose as glycogen and detoxifies drugs and alcohol, but insulin is made by the beta cells of the islets of Langerhans in the pancreas, which lies next to the liver.","difficulty":"hard","questionHi":"इनमें से कौन-सा यकृत का कार्य नहीं है?","optionsHi":["पित्त बनाना","ग्लाइकोजन का संचय करना","औषधियों का विषहरण करना","इंसुलिन बनाना"],"explanationHi":"यकृत पित्त बनाता है, ग्लूकोज को ग्लाइकोजन के रूप में संचित करता है और औषधियों तथा शराब का विषहरण करता है, परंतु इंसुलिन अग्न्याशय की लैंगरहैंस द्वीपिकाओं की बीटा कोशिकाओं द्वारा बनाया जाता है, जो यकृत के पास स्थित होता है।"},
  {"id":"sci-biology-21","question":"Consider: 1. Mature mammalian red blood cells have no nucleus. 2. Haemoglobin contains iron. 3. Platelets help blood to clot. Which are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":3,"explanation":"All three are true: mature mammalian RBCs lose their nucleus to hold more haemoglobin, haemoglobin has an iron atom in each haem group, and platelets start clotting at a cut. Students wrongly drop statement 1 because RBCs of birds and frogs do have a nucleus.","difficulty":"very-hard","questionHi":"निम्नलिखित पर विचार कीजिए: 1. परिपक्व स्तनधारी लाल रक्त कोशिकाओं में केंद्रक नहीं होता। 2. हीमोग्लोबिन में लोहा होता है। 3. प्लेटलेट्स रक्त का थक्का जमाने में सहायता करती हैं। कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"तीनों कथन सही हैं: परिपक्व स्तनधारी लाल रक्त कोशिकाएँ अधिक हीमोग्लोबिन रखने के लिए अपना केंद्रक खो देती हैं, हीमोग्लोबिन के प्रत्येक हीम समूह में एक लोहे का परमाणु होता है, और प्लेटलेट्स कटने पर थक्का बनाना शुरू करती हैं। छात्र प्रायः कथन 1 को गलत मानकर छोड़ देते हैं, क्योंकि पक्षियों और मेंढकों की लाल रक्त कोशिकाओं में केंद्रक होता है।"},
  {"id":"sci-biology-22","question":"A colour-blind man marries a woman with normal vision who is not a carrier. What is the chance that their son is colour-blind?","options":["0%","25%","50%","100%"],"answer":0,"explanation":"Colour blindness is X-linked; a son gets his X from his mother, who has two normal X chromosomes.","difficulty":"very-hard","questionHi":"एक वर्णांध पुरुष का विवाह सामान्य दृष्टि वाली ऐसी स्त्री से होता है जो वाहक नहीं है। उनके पुत्र के वर्णांध होने की संभावना कितनी है?","optionsHi":["0%","25%","50%","100%"],"explanationHi":"वर्णांधता X-सहलग्न होती है; पुत्र को अपना X गुणसूत्र माता से मिलता है, जिसके दोनों X गुणसूत्र सामान्य हैं।"},
  {"id":"sci-biology-23","question":"How many of these statements are correct? I. Vitamin E helps blood clot. II. Rickets is caused by a lack of vitamin C. III. Night blindness is caused by a lack of vitamin B1. IV. Beriberi is caused by a lack of vitamin B1.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only IV is correct (beriberi, vitamin B1). Vitamin K, not E, is needed for blood clotting; rickets is caused by a lack of vitamin D (lack of C causes scurvy); night blindness comes from a lack of vitamin A.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. विटामिन E रक्त का थक्का जमाने में सहायता करता है। II. रिकेट्स विटामिन C की कमी से होता है। III. रतौंधी विटामिन B1 की कमी से होती है। IV. बेरी-बेरी विटामिन B1 की कमी से होता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल IV सही है (बेरी-बेरी, विटामिन B1)। रक्त का थक्का जमाने के लिए विटामिन K आवश्यक है, E नहीं; रिकेट्स विटामिन D की कमी से होता है (C की कमी से स्कर्वी होता है); और रतौंधी विटामिन A की कमी से होती है।"},
  {"id":"sci-biology-24","question":"How many of these statements are correct? I. Mitochondria are called the powerhouse of the cell. II. Ribosomes are the site of protein synthesis. III. Plant cells have no cell wall.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"I and II are true: mitochondria make ATP and ribosomes build proteins. III is false because plant cells have a rigid cellulose cell wall outside the membrane; it is animal cells that lack one, so only two statements are correct.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. माइटोकॉन्ड्रिया को कोशिका का ऊर्जा घर कहा जाता है। II. राइबोसोम प्रोटीन संश्लेषण का स्थान हैं। III. पादप कोशिकाओं में कोशिका भित्ति नहीं होती।","optionsHi":["केवल एक","केवल दो","सभी तीन","कोई नहीं"],"explanationHi":"I और II सही हैं: माइटोकॉन्ड्रिया ATP बनाते हैं और राइबोसोम प्रोटीन का निर्माण करते हैं। III गलत है क्योंकि पादप कोशिकाओं में कोशिका झिल्ली के बाहर कठोर सेलुलोज की कोशिका भित्ति होती है; कोशिका भित्ति जंतु कोशिकाओं में नहीं होती, इसलिए केवल दो कथन सही हैं।"},
  {"id":"sci-biology-25","question":"How many of these statements are correct? I. Mature red blood cells in mammals have no nucleus. II. Platelets help blood to clot. III. Lymphocytes are a type of red blood cell.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"I and II are true: mature mammalian RBCs have no nucleus and platelets start clotting. III is false because lymphocytes are white blood cells (B and T cells) of the immune system, so only two statements are correct.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. स्तनधारियों की परिपक्व लाल रक्त कोशिकाओं में केंद्रक नहीं होता। II. प्लेटलेट्स रक्त का थक्का जमाने में सहायता करती हैं। III. लिम्फोसाइट एक प्रकार की लाल रक्त कोशिका है।","optionsHi":["केवल एक","केवल दो","सभी तीन","कोई नहीं"],"explanationHi":"I और II सही हैं: परिपक्व स्तनधारी लाल रक्त कोशिकाओं में केंद्रक नहीं होता और प्लेटलेट्स थक्का बनाना शुरू करती हैं। III गलत है क्योंकि लिम्फोसाइट श्वेत रक्त कोशिकाएँ (B और T कोशिकाएँ) हैं जो प्रतिरक्षा तंत्र का भाग हैं, इसलिए केवल दो कथन सही हैं।"},
  {"id":"sci-biology-26","question":"Which vitamin is made by bacteria in the human large intestine?","options":["Vitamin A","Vitamin C","Vitamin K","Vitamin D"],"answer":2,"explanation":"Gut bacteria make vitamin K. Vitamin D is made in the skin in sunlight, not by bacteria.","difficulty":"very-hard","questionHi":"मनुष्य की बड़ी आँत में जीवाणुओं द्वारा कौन-सा विटामिन बनाया जाता है?","optionsHi":["विटामिन A","विटामिन C","विटामिन K","विटामिन D"],"explanationHi":"आँत के जीवाणु विटामिन K बनाते हैं। विटामिन D धूप में त्वचा में बनता है, जीवाणुओं द्वारा नहीं।"},
  {"id":"sci-biology-27","question":"A father has blood group AB and a mother has group O. Which blood groups can their children have?","options":["A or B only","AB or O only","A, B, AB or O","O only"],"answer":0,"explanation":"The father passes A or B, the mother always passes O: children are AO (group A) or BO (group B).","difficulty":"very-hard","questionHi":"पिता का रक्त समूह AB और माता का समूह O है। उनके बच्चों का रक्त समूह क्या हो सकता है?","optionsHi":["केवल A या B","केवल AB या O","A, B, AB या O","केवल O"],"explanationHi":"पिता A या B देता है, माता सदैव O देती है: इसलिए बच्चे AO (समूह A) या BO (समूह B) होंगे।"},
  {"id":"sci-biology-28","question":"Which pair of hormone and the gland that secretes it is NOT correctly matched?","options":["Insulin – pancreas","Thyroxine – thyroid","Adrenaline – adrenal gland","Oxytocin – thyroid"],"answer":3,"explanation":"Oxytocin is released by the posterior pituitary. The thyroid secretes thyroxine and calcitonin.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"हॉर्मोन और उसे स्रावित करने वाली ग्रंथि का कौन-सा युग्म सही सुमेलित नहीं है?","optionsHi":["इंसुलिन – अग्न्याशय","थायरॉक्सिन – थायरॉइड","एड्रीनलीन – अधिवृक्क ग्रंथि","ऑक्सीटोसिन – थायरॉइड"],"explanationHi":"ऑक्सीटोसिन पश्च पीयूष ग्रंथि से निकलता है। थायरॉइड थायरॉक्सिन और कैल्सिटोनिन का स्राव करती है।"},
  {"id":"sci-biology-29","question":"In pea plants tallness (T) is dominant over dwarfness (t). Two heterozygous tall plants are crossed and 400 offspring are obtained. How many are expected to be tall but heterozygous?","options":["200","300","100","400"],"answer":0,"explanation":"Tt × Tt gives TT : Tt : tt = 1 : 2 : 1. Heterozygous tall (Tt) is half the offspring: 200. (300 would be all tall plants.)","difficulty":"very-hard","source":"SSC CGL · CTET","questionHi":"मटर के पौधों में लंबापन (T), बौनेपन (t) पर प्रभावी है। दो विषमयुग्मजी लंबे पौधों का संकरण कराने पर 400 संतति प्राप्त होती हैं। इनमें से कितने के लंबे परंतु विषमयुग्मजी होने की आशा है?","optionsHi":["200","300","100","400"],"explanationHi":"Tt × Tt से TT : Tt : tt = 1 : 2 : 1 प्राप्त होता है। विषमयुग्मजी लंबे (Tt) कुल संतति के आधे होते हैं: 200। (300 सभी लंबे पौधों की संख्या होगी।)"},
  {"id":"sci-biology-30","question":"The normal body temperature of a healthy human being is about:","options":["35 °C","37 °C","39 °C","42 °C"],"answer":1,"explanation":"Normal core temperature is about 37 °C (98.6 °F); 39 °C and above indicates fever.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"एक स्वस्थ मनुष्य के शरीर का सामान्य तापमान लगभग कितना होता है?","optionsHi":["35 °C","37 °C","39 °C","42 °C"],"explanationHi":"शरीर का सामान्य क्रोड तापमान लगभग 37 °C (98.6 °F) होता है; 39 °C और उससे अधिक तापमान बुखार का सूचक है।"},
  {"id":"sci-biology-31","question":"Which blood cells defend the body against infection?","options":["Red blood cells","Platelets","White blood cells","Plasma cells only"],"answer":2,"explanation":"White blood cells (leucocytes) fight infection; red cells carry oxygen and platelets help clotting.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"कौन-सी रक्त कोशिकाएँ शरीर की संक्रमण से रक्षा करती हैं?","optionsHi":["लाल रक्त कोशिकाएँ","प्लेटलेट्स","श्वेत रक्त कोशिकाएँ","केवल प्लाज्मा कोशिकाएँ"],"explanationHi":"श्वेत रक्त कोशिकाएँ (ल्यूकोसाइट) संक्रमण से लड़ती हैं; लाल कोशिकाएँ ऑक्सीजन ले जाती हैं और प्लेटलेट्स थक्का जमाने में सहायता करती हैं।"},
  {"id":"sci-biology-32","question":"The pigment responsible for the colour of human skin is:","options":["Haemoglobin","Melanin","Carotene","Keratin"],"answer":1,"explanation":"Melanin, produced by melanocytes, gives skin, hair and eyes their colour and protects against ultraviolet light.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"मानव त्वचा के रंग के लिए उत्तरदायी वर्णक कौन-सा है?","optionsHi":["हीमोग्लोबिन","मेलेनिन","कैरोटीन","केराटिन"],"explanationHi":"मेलेनोसाइट द्वारा बनाया गया मेलेनिन त्वचा, बालों और आँखों को रंग देता है तथा पराबैंगनी किरणों से रक्षा करता है।"},
  {"id":"sci-biology-33","question":"The number of bones in an adult human body is:","options":["196","206","212","300"],"answer":1,"explanation":"An adult has 206 bones; a newborn has about 300 bony elements, many of which fuse during growth.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"वयस्क मानव शरीर में अस्थियों की संख्या कितनी होती है?","optionsHi":["196","206","212","300"],"explanationHi":"वयस्क में 206 अस्थियाँ होती हैं; नवजात शिशु में लगभग 300 अस्थि-खंड होते हैं, जिनमें से कई वृद्धि के दौरान जुड़ जाते हैं।"},
  {"id":"sci-biology-34","question":"The smallest bone in the human body is the:","options":["Stapes","Femur","Patella","Malleus"],"answer":0,"explanation":"The stapes (stirrup) in the middle ear is the smallest bone; the femur (thigh bone) is the longest and strongest.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"मानव शरीर की सबसे छोटी अस्थि कौन-सी है?","optionsHi":["स्टेपीज़ (रकाब)","फीमर (जाँघ की हड्डी)","पटेला (घुटने की चक्की)","मैलियस (हथौड़ा)"],"explanationHi":"मध्य कर्ण की स्टेपीज़ (रकाब) अस्थि सबसे छोटी है; फीमर (जाँघ की हड्डी) सबसे लंबी और सबसे मजबूत अस्थि है।"},
  {"id":"sci-biology-35","question":"The hormone that prepares the body for a “fight or flight” response is:","options":["Insulin","Thyroxine","Adrenaline","Progesterone"],"answer":2,"explanation":"Adrenaline (epinephrine) from the adrenal medulla raises heart rate, blood pressure and blood sugar during stress.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"“लड़ो या भागो” की प्रतिक्रिया के लिए शरीर को तैयार करने वाला हॉर्मोन कौन-सा है?","optionsHi":["इंसुलिन","थायरॉक्सिन","एड्रीनलीन","प्रोजेस्टेरोन"],"explanationHi":"अधिवृक्क मध्यांशक से निकलने वाला एड्रीनलीन (एपिनेफ्रिन) तनाव के समय हृदय गति, रक्तचाप और रक्त शर्करा को बढ़ा देता है।"},
  {"id":"sci-biology-36","question":"Which organ removes urea from the blood?","options":["Liver","Kidney","Spleen","Pancreas"],"answer":1,"explanation":"Urea is made in the liver but filtered out of the blood by the kidneys and excreted in urine.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"कौन-सा अंग रक्त से यूरिया को निकालता है?","optionsHi":["यकृत","वृक्क (गुर्दा)","प्लीहा","अग्न्याशय"],"explanationHi":"यूरिया यकृत में बनता है, परंतु वृक्क रक्त से इसे छानकर मूत्र के साथ बाहर निकालते हैं।"},
  {"id":"sci-biology-37","question":"The normal blood pressure of a healthy adult is about:","options":["80/120 mm Hg","120/80 mm Hg","140/90 mm Hg","100/100 mm Hg"],"answer":1,"explanation":"Normal pressure is about 120 mm Hg systolic over 80 mm Hg diastolic; 140/90 is the threshold for hypertension.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"एक स्वस्थ वयस्क का सामान्य रक्तचाप लगभग कितना होता है?","optionsHi":["80/120 mm Hg","120/80 mm Hg","140/90 mm Hg","100/100 mm Hg"],"explanationHi":"सामान्य रक्तचाप लगभग 120 mm Hg (प्रकुंचन) और 80 mm Hg (अनुशिथिलन) होता है; 140/90 उच्च रक्तचाप की सीमा है।"},
  {"id":"sci-biology-38","question":"The human heart has how many chambers?","options":["Two","Three","Four","Five"],"answer":2,"explanation":"The human heart has four chambers: two atria and two ventricles, keeping oxygenated and deoxygenated blood separate.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"मानव हृदय में कितने कक्ष होते हैं?","optionsHi":["दो","तीन","चार","पाँच"],"explanationHi":"मानव हृदय में चार कक्ष होते हैं: दो अलिंद और दो निलय, जो ऑक्सीजनयुक्त और ऑक्सीजनरहित रक्त को अलग रखते हैं।"},
  {"id":"sci-biology-39","question":"Bile is produced in the liver but stored in the:","options":["Pancreas","Gall bladder","Small intestine","Spleen"],"answer":1,"explanation":"Bile is secreted by liver cells and concentrated and stored in the gall bladder, which releases it into the duodenum to emulsify fats.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"पित्त का निर्माण यकृत में होता है, परंतु उसका संचय कहाँ होता है?","optionsHi":["अग्न्याशय","पित्ताशय","छोटी आँत","प्लीहा"],"explanationHi":"पित्त का स्राव यकृत कोशिकाओं द्वारा होता है और वह पित्ताशय में सांद्रित होकर संचित रहता है, जो उसे ग्रहणी में छोड़ता है ताकि वसा का इमल्सीकरण हो सके।"},
  {"id":"sci-biology-40","question":"Starch digestion begins in the mouth because saliva contains the enzyme:","options":["Pepsin","Lipase","Ptyalin","Trypsin"],"answer":2,"explanation":"Salivary amylase (ptyalin) converts starch into maltose in the mouth; pepsin and trypsin digest proteins.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"मुँह में स्टार्च का पाचन शुरू हो जाता है क्योंकि लार में कौन-सा एंजाइम होता है?","optionsHi":["पेप्सिन","लाइपेज","टायलिन","ट्रिप्सिन"],"explanationHi":"लार का एमाइलेज (टायलिन) मुँह में स्टार्च को माल्टोज़ में बदल देता है; पेप्सिन और ट्रिप्सिन प्रोटीन का पाचन करते हैं।"},
  {"id":"sci-biology-41","question":"Body temperature, hunger and thirst are regulated by which part of the brain?","options":["Cerebellum","Medulla oblongata","Hypothalamus","Cerebrum"],"answer":2,"explanation":"The hypothalamus is the body’s thermostat and also controls hunger, thirst, sleep and the pituitary gland.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"शरीर का तापमान, भूख और प्यास का नियमन मस्तिष्क के किस भाग द्वारा होता है?","optionsHi":["अनुमस्तिष्क","मेडुला ऑब्लांगेटा","हाइपोथैलेमस","प्रमस्तिष्क"],"explanationHi":"हाइपोथैलेमस शरीर का तापस्थापी (थर्मोस्टेट) है और यह भूख, प्यास, नींद तथा पीयूष ग्रंथि को भी नियंत्रित करता है।"},
  {"id":"sci-biology-42","question":"The total volume of blood in an average adult human is about:","options":["2 litres","5 litres","8 litres","10 litres"],"answer":1,"explanation":"An adult has about 5 litres of blood, roughly 7–8% of body weight.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"एक औसत वयस्क मनुष्य में रक्त की कुल मात्रा लगभग कितनी होती है?","optionsHi":["2 लीटर","5 लीटर","8 लीटर","10 लीटर"],"explanationHi":"एक वयस्क में लगभग 5 लीटर रक्त होता है, जो शरीर के भार का लगभग 7–8% है।"},
  {"id":"sci-biology-43","question":"Pernicious anaemia is caused by the deficiency of:","options":["Vitamin B1","Vitamin B12","Vitamin C","Dietary iron"],"answer":1,"explanation":"Vitamin B12 (cobalamin) is needed to make red blood cells; its deficiency, often due to poor absorption, causes pernicious anaemia. Iron deficiency also causes anaemia, but a different, microcytic type, not pernicious anaemia.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"घातक रक्ताल्पता (परनीशियस एनीमिया) किसकी कमी से होती है?","optionsHi":["विटामिन B1","विटामिन B12","विटामिन C","आहार में लोहा"],"explanationHi":"लाल रक्त कोशिकाएँ बनाने के लिए विटामिन B12 (कोबालामिन) आवश्यक है; इसकी कमी, जो प्रायः अवशोषण की खराबी के कारण होती है, घातक रक्ताल्पता का कारण बनती है। लोहे की कमी से भी रक्ताल्पता होती है, पर वह अलग प्रकार की (सूक्ष्मकोशिकीय) होती है, घातक रक्ताल्पता नहीं।"},
  {"id":"sci-biology-44","question":"The exchange of oxygen and carbon dioxide in the lungs takes place in the:","options":["Bronchi","Trachea","Alveoli","Pleura"],"answer":2,"explanation":"The alveoli are tiny thin-walled air sacs surrounded by capillaries where gases diffuse between air and blood.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"फेफड़ों में ऑक्सीजन और कार्बन डाइऑक्साइड का आदान-प्रदान कहाँ होता है?","optionsHi":["श्वसनिकाएँ (ब्रोंकाई)","श्वास नली (ट्रेकिया)","वायुकोष्ठिकाएँ (ऐल्वियोलाई)","फुफ्फुस आवरण (प्लूरा)"],"explanationHi":"वायुकोष्ठिकाएँ पतली दीवार वाली छोटी वायु-थैलियाँ हैं, जो केशिकाओं से घिरी होती हैं और यहाँ वायु तथा रक्त के बीच गैसों का विसरण होता है।"},
  {"id":"sci-biology-45","question":"Dengue is transmitted by the bite of which mosquito?","options":["Female Anopheles stephensi","Female Aedes aegypti","Female Culex quinquefasciatus","Male Aedes aegypti"],"answer":1,"explanation":"Female Aedes aegypti (a day-biting mosquito) spreads dengue, chikungunya and Zika; Anopheles spreads malaria and Culex filariasis. Male mosquitoes feed on plant juices and never bite.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"डेंगू किस मच्छर के काटने से फैलता है?","optionsHi":["मादा ऐनोफ़िलीज़ स्टीफेंसाई","मादा एडीज़ इजिप्टाई","मादा क्यूलेक्स क्विंक्वेफैसिएटस","नर एडीज़ इजिप्टाई"],"explanationHi":"मादा एडीज़ इजिप्टाई (दिन में काटने वाला मच्छर) डेंगू, चिकनगुनिया और ज़ीका फैलाती है; ऐनोफ़िलीज़ मलेरिया और क्यूलेक्स फाइलेरिया (फीलपाँव) फैलाता है। नर मच्छर पौधों का रस पीते हैं और कभी नहीं काटते।"},
  {"id":"sci-biology-46","question":"The BCG vaccine gives protection against:","options":["Whooping cough","Tetanus","Tuberculosis","Measles"],"answer":2,"explanation":"BCG (Bacillus Calmette–Guérin) is given at birth in India to protect against tuberculosis.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"BCG का टीका किस रोग से सुरक्षा देता है?","optionsHi":["काली खाँसी","टेटनस","क्षय रोग (तपेदिक)","खसरा"],"explanationHi":"BCG (बैसिलस कैल्मेट–गेरिन) का टीका भारत में जन्म के समय क्षय रोग से बचाव के लिए लगाया जाता है।"},
  {"id":"sci-biology-47","question":"The longest cell in the human body is the:","options":["Muscle cell","Nerve cell","Red blood cell","Bone cell"],"answer":1,"explanation":"A single neuron can be over a metre long, running from the spinal cord to the toes; the ovum is the largest cell by volume.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"मानव शरीर की सबसे लंबी कोशिका कौन-सी है?","optionsHi":["पेशी कोशिका","तंत्रिका कोशिका","लाल रक्त कोशिका","अस्थि कोशिका"],"explanationHi":"एक अकेला न्यूरॉन एक मीटर से भी अधिक लंबा हो सकता है, जो मेरुरज्जु से पैर की उँगलियों तक जाता है; आयतन की दृष्टि से अंडाणु सबसे बड़ी कोशिका है।"},
  {"id":"sci-biology-48","question":"How many of these statements are correct? I. An adult has 206 bones while a newborn has about 300. II. The resting human heart beats about 72 times a minute. III. An adult has 32 permanent teeth. IV. There are 31 pairs of spinal nerves.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct standard numbers; the trap is 12 pairs of cranial nerves, which is a different count from the 31 pairs of spinal nerves.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"इनमें से कितने कथन सही हैं? I. वयस्क में 206 अस्थियाँ होती हैं जबकि नवजात में लगभग 300। II. विश्राम की अवस्था में मानव हृदय लगभग 72 बार प्रति मिनट धड़कता है। III. वयस्क में 32 स्थायी दाँत होते हैं। IV. मेरु तंत्रिकाओं के 31 जोड़े होते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों मानक संख्याएँ सही हैं; भ्रम की बात यह है कि कपाल तंत्रिकाओं के 12 जोड़े होते हैं, जो मेरु तंत्रिकाओं के 31 जोड़ों से भिन्न संख्या है।"},
  {"id":"sci-biology-49","question":"Assertion (A): Vaccination provides active immunity. Reason (R): A vaccine stimulates the body to make its own antibodies and memory cells.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Immunity produced by the body’s own response is active; passive immunity comes from ready-made antibodies such as antiserum or a mother’s milk.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"अभिकथन (A): टीकाकरण सक्रिय प्रतिरक्षा प्रदान करता है। कारण (R): टीका शरीर को अपने ही प्रतिरक्षी (एंटीबॉडी) और स्मृति कोशिकाएँ बनाने के लिए प्रेरित करता है।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है परंतु R गलत है","A गलत है परंतु R सही है"],"explanationHi":"शरीर की अपनी प्रतिक्रिया से उत्पन्न प्रतिरक्षा सक्रिय होती है; निष्क्रिय प्रतिरक्षा बने-बनाए प्रतिरक्षियों से मिलती है, जैसे प्रतिसीरम या माँ का दूध।"},
  {"id":"sci-biology-50","question":"Match the vitamin with its chemical name: 1. Vitamin A 2. Vitamin B1 3. Vitamin C 4. Vitamin D; a. Ascorbic acid b. Calciferol c. Retinol d. Thiamine","options":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-a, 3-d, 4-b","1-b, 2-d, 3-a, 4-c"],"answer":0,"explanation":"Vitamin A is retinol, B1 thiamine, C ascorbic acid and D calciferol.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"विटामिन का उसके रासायनिक नाम से मिलान कीजिए: 1. विटामिन A 2. विटामिन B1 3. विटामिन C 4. विटामिन D; a. ऐस्कॉर्बिक अम्ल b. कैल्सिफेरॉल c. रेटिनॉल d. थायमिन","optionsHi":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-a, 3-d, 4-b","1-b, 2-d, 3-a, 4-c"],"explanationHi":"विटामिन A रेटिनॉल है, B1 थायमिन, C ऐस्कॉर्बिक अम्ल और D कैल्सिफेरॉल है।"},
  {"id":"sci-biology-51","question":"A man of blood group A (genotype IᴬI°) marries a woman of blood group B (genotype IᴮI°). Which blood groups are possible among their children?","options":["Only A and B","Only A, B and AB","A, B, AB and O","Only AB and O"],"answer":2,"explanation":"The gametes Iᴬ or I° combine with Iᴮ or I°, giving IᴬIᴮ (AB), IᴬI° (A), IᴮI° (B) and I°I° (O), each with probability 1/4.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"रक्त समूह A (जीनप्ररूप IᴬI°) वाला एक पुरुष रक्त समूह B (जीनप्ररूप IᴮI°) वाली स्त्री से विवाह करता है। उनकी संतानों में कौन-से रक्त समूह संभव हैं?","optionsHi":["केवल A और B","केवल A, B और AB","A, B, AB और O","केवल AB और O"],"explanationHi":"युग्मक Iᴬ या I° का संयोग Iᴮ या I° से होने पर IᴬIᴮ (AB), IᴬI° (A), IᴮI° (B) और I°I° (O) बनते हैं, प्रत्येक की प्रायिकता 1/4 है।"},
  {"id":"sci-biology-52","question":"Which of the following is NOT a function of the kidney?","options":["Regulating the water balance of the body","Producing the hormone erythropoietin","Producing bile","Removing urea from the blood"],"answer":2,"explanation":"Bile is made by the liver; the kidney excretes nitrogenous waste, controls water and salt balance and secretes erythropoietin, which stimulates red-cell production.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"निम्नलिखित में से कौन-सा वृक्क का कार्य नहीं है?","optionsHi":["शरीर के जल संतुलन का नियमन करना","हॉर्मोन एरिथ्रोपॉइटिन बनाना","पित्त बनाना","रक्त से यूरिया निकालना"],"explanationHi":"पित्त यकृत द्वारा बनता है; वृक्क नाइट्रोजनी अपशिष्ट का उत्सर्जन करते हैं, जल और लवण का संतुलन नियंत्रित करते हैं तथा एरिथ्रोपॉइटिन का स्राव करते हैं, जो लाल रक्त कोशिकाओं के निर्माण को प्रेरित करता है।"},
  {"id":"sci-biology-53","question":"How many of these statements about blood are correct? I. Blood group O has no A or B antigens on the red cells. II. Blood group AB has no anti-A or anti-B antibodies in its plasma. III. An Rh-negative mother carrying an Rh-positive foetus can face erythroblastosis foetalis. IV. Haemoglobin is found in white blood cells.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct (which is why O is the universal donor and AB the universal recipient). IV is wrong: haemoglobin is in red blood cells.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"रक्त से संबंधित इनमें से कितने कथन सही हैं? I. रक्त समूह O की लाल रक्त कोशिकाओं पर A या B प्रतिजन नहीं होते। II. रक्त समूह AB के प्लाज्मा में anti-A या anti-B प्रतिरक्षी नहीं होते। III. Rh-ऋणात्मक माता में Rh-धनात्मक भ्रूण होने पर एरिथ्रोब्लास्टोसिस फीटैलिस हो सकता है। IV. हीमोग्लोबिन श्वेत रक्त कोशिकाओं में पाया जाता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं (इसीलिए O सार्वभौमिक दाता और AB सार्वभौमिक ग्राही है)। IV गलत है: हीमोग्लोबिन लाल रक्त कोशिकाओं में होता है।"},
  {"id":"sci-biology-54","question":"Match the disease with its causative organism: 1. Tuberculosis 2. Malaria 3. Rabies 4. Ringworm; a. Virus b. Fungus c. Bacterium d. Protozoan","options":["1-c, 2-d, 3-a, 4-b","1-c, 2-a, 3-d, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-b, 4-a"],"answer":0,"explanation":"TB is caused by the bacterium Mycobacterium tuberculosis, malaria by the protozoan Plasmodium, rabies by a virus and ringworm by a fungus.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"रोग का उसके कारक जीव से मिलान कीजिए: 1. क्षय रोग (तपेदिक) 2. मलेरिया 3. रेबीज़ 4. दाद (रिंगवर्म); a. विषाणु b. कवक c. जीवाणु d. प्रोटोज़ोआ","optionsHi":["1-c, 2-d, 3-a, 4-b","1-c, 2-a, 3-d, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-b, 4-a"],"explanationHi":"क्षय रोग माइकोबैक्टीरियम ट्यूबरकुलोसिस जीवाणु से, मलेरिया प्लास्मोडियम प्रोटोज़ोआ से, रेबीज़ विषाणु से और दाद कवक से होता है।"},
  {"id":"sci-biology-55","question":"The correct sequence in which these enzymes act on proteins in the human digestive tract is:","options":["Trypsin → pepsin → peptidases","Pepsin → trypsin → peptidases","Peptidases → pepsin → trypsin","Pepsin → peptidases → trypsin"],"answer":1,"explanation":"Pepsin in the stomach starts protein digestion, pancreatic trypsin continues it in the small intestine, and intestinal peptidases finish breaking peptides into amino acids.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"मानव पाचन तंत्र में प्रोटीन पर क्रिया करने वाले इन एंजाइमों का सही क्रम क्या है?","optionsHi":["ट्रिप्सिन → पेप्सिन → पेप्टिडेज़","पेप्सिन → ट्रिप्सिन → पेप्टिडेज़","पेप्टिडेज़ → पेप्सिन → ट्रिप्सिन","पेप्सिन → पेप्टिडेज़ → ट्रिप्सिन"],"explanationHi":"आमाशय में पेप्सिन प्रोटीन का पाचन शुरू करता है, छोटी आँत में अग्न्याशयी ट्रिप्सिन उसे आगे बढ़ाता है, और आँत के पेप्टिडेज़ पेप्टाइड को अमीनो अम्लों में तोड़कर पाचन पूरा करते हैं।"},
  {"id":"sci-biology-56","question":"Assertion (A): Insulin and glucagon have opposite effects on blood sugar. Reason (R): Both insulin and glucagon are secreted by the pancreas.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"Insulin (beta cells) lowers and glucagon (alpha cells) raises blood glucose; both are pancreatic, but sharing a gland is not the reason their actions are opposite.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"अभिकथन (A): इंसुलिन और ग्लूकागॉन का रक्त शर्करा पर विपरीत प्रभाव पड़ता है। कारण (R): इंसुलिन और ग्लूकागॉन दोनों का स्राव अग्न्याशय द्वारा होता है।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है परंतु R गलत है","A गलत है परंतु R सही है"],"explanationHi":"इंसुलिन (बीटा कोशिकाएँ) रक्त ग्लूकोज को घटाता है और ग्लूकागॉन (ऐल्फा कोशिकाएँ) बढ़ाता है; दोनों अग्न्याशय से निकलते हैं, परंतु एक ही ग्रंथि से स्रवित होना उनके विपरीत प्रभाव का कारण नहीं है।"},
  {"id":"sci-biology-57","question":"How many of these statements about the nervous system are correct? I. The cerebellum is the largest part of the brain. II. The medulla oblongata controls heartbeat and breathing. III. Reflex actions are controlled by the cerebellum. IV. Humans have 31 pairs of cranial nerves.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only II is correct. I is wrong: the cerebrum is the largest part. III is wrong: reflexes are handled by the spinal cord. IV is wrong: humans have 12 pairs of cranial nerves; 31 is the number of pairs of spinal nerves.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"तंत्रिका तंत्र से संबंधित इनमें से कितने कथन सही हैं? I. अनुमस्तिष्क मस्तिष्क का सबसे बड़ा भाग है। II. मेडुला ऑब्लांगेटा हृदय गति और श्वसन को नियंत्रित करता है। III. प्रतिवर्ती क्रियाएँ अनुमस्तिष्क द्वारा नियंत्रित होती हैं। IV. मनुष्य में कपाल तंत्रिकाओं के 31 जोड़े होते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल II सही है। I गलत है: प्रमस्तिष्क सबसे बड़ा भाग है। III गलत है: प्रतिवर्ती क्रियाएँ मेरुरज्जु द्वारा नियंत्रित होती हैं। IV गलत है: मनुष्य में कपाल तंत्रिकाओं के 12 जोड़े होते हैं; 31 मेरु तंत्रिकाओं के जोड़ों की संख्या है।"},
  {"id":"sci-biology-58","question":"Two pea plants heterozygous for both seed colour and seed shape (YyRr × YyRr) produce 1,600 offspring. The expected number showing both recessive traits is:","options":["100","300","400","900"],"answer":0,"explanation":"The dihybrid ratio is 9:3:3:1, so double recessives (yyrr) are 1/16 of 1,600 = 100.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"बीज के रंग और बीज के आकार, दोनों के लिए विषमयुग्मजी (YyRr × YyRr) दो मटर के पौधे 1,600 संतति उत्पन्न करते हैं। दोनों अप्रभावी लक्षण दिखाने वाली संतति की अपेक्षित संख्या कितनी है?","optionsHi":["100","300","400","900"],"explanationHi":"द्विसंकर अनुपात 9:3:3:1 होता है, इसलिए दोनों अप्रभावी (yyrr) 1,600 का 1/16 = 100 होंगे।"},
  {"id":"sci-biology-59","question":"Which pair of hormone and disorder is NOT correctly matched?","options":["Thyroxine deficiency (iodine lack) – goitre","Insulin deficiency (beta cells) – diabetes mellitus","ADH deficiency (posterior pituitary) – diabetes insipidus","Excess growth hormone in adults – cretinism"],"answer":3,"explanation":"Excess growth hormone in adults causes acromegaly (and gigantism in children); cretinism results from thyroxine deficiency in infancy.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"हॉर्मोन और विकार का कौन-सा युग्म सही सुमेलित नहीं है?","optionsHi":["थायरॉक्सिन की कमी (आयोडीन की कमी) – घेंघा","इंसुलिन की कमी (बीटा कोशिकाएँ) – मधुमेह (डायबिटीज़ मेलिटस)","ADH की कमी (पश्च पीयूष ग्रंथि) – डायबिटीज़ इन्सिपिडस","वयस्कों में वृद्धि हॉर्मोन की अधिकता – जड़वामनता (क्रेटिनिज़्म)"],"explanationHi":"वयस्कों में वृद्धि हॉर्मोन की अधिकता से अग्रातिकायता (एक्रोमेगेली) होती है (और बच्चों में महाकायता); जड़वामनता शैशवावस्था में थायरॉक्सिन की कमी से होती है।"},
  {"id":"sci-biology-60","question":"Blood vessels that carry blood away from the heart to the body are called:","options":["Veins","Arteries","Capillaries","Venules"],"answer":1,"explanation":"Arteries carry blood away from the heart, veins bring it back, and capillaries link the two in the tissues.","difficulty":"easy","source":"SSC GD · RRB Group D","questionHi":"हृदय से शरीर की ओर रक्त ले जाने वाली रक्त वाहिकाएँ क्या कहलाती हैं?","optionsHi":["शिराएँ","धमनियाँ","केशिकाएँ","शिरिकाएँ"],"explanationHi":"धमनियाँ हृदय से दूर रक्त ले जाती हैं, शिराएँ उसे वापस लाती हैं, और केशिकाएँ ऊतकों में दोनों को जोड़ती हैं।"},
  {"id":"sci-biology-61","question":"The basic functional unit of heredity is the:","options":["Cell","Ribosome","Nucleus","Gene"],"answer":3,"explanation":"A gene is a segment of DNA that carries the information for a trait and is passed from parents to offspring.","difficulty":"easy","source":"SSC CHSL · RRB Group D","questionHi":"आनुवंशिकता की मूल क्रियात्मक इकाई क्या है?","optionsHi":["कोशिका","राइबोसोम","केंद्रक","जीन"],"explanationHi":"जीन DNA का वह खंड है जिसमें किसी लक्षण की सूचना होती है और जो माता-पिता से संतान में जाता है।"},
  {"id":"sci-biology-62","question":"Most of the digested food is absorbed in the:","options":["Stomach","Large intestine","Small intestine","Oesophagus"],"answer":2,"explanation":"Finger-like villi lining the small intestine give a huge surface for absorption. The large intestine mainly absorbs water and salts.","difficulty":"moderate","source":"RRB Group D · SSC CHSL","questionHi":"पचे हुए भोजन का अधिकांश अवशोषण कहाँ होता है?","optionsHi":["आमाशय","बड़ी आँत","छोटी आँत","ग्रासनली"],"explanationHi":"छोटी आँत की भीतरी सतह पर उँगली जैसे अंकुर (विलाई) अवशोषण के लिए बहुत बड़ा क्षेत्रफल प्रदान करते हैं। बड़ी आँत मुख्यतः जल और लवणों का अवशोषण करती है।"},
  {"id":"sci-biology-63","question":"Goitre, a swelling of the thyroid gland, is caused by a deficiency of:","options":["Iodine","Iron","Calcium","Zinc"],"answer":0,"explanation":"Iodine is needed to make thyroxine; without it the thyroid enlarges. This is why salt is iodised in India.","difficulty":"moderate","source":"RRB Group D · SSC CHSL","questionHi":"घेंघा (गॉयटर), जिसमें थायरॉइड ग्रंथि सूज जाती है, किसकी कमी से होता है?","optionsHi":["आयोडीन","लोहा","कैल्शियम","जिंक"],"explanationHi":"थायरॉक्सिन बनाने के लिए आयोडीन आवश्यक है; इसके बिना थायरॉइड ग्रंथि बढ़ जाती है। इसीलिए भारत में नमक में आयोडीन मिलाया जाता है।"},
  {"id":"sci-biology-64","question":"Photosynthesis in a green plant cell takes place in the:","options":["Mitochondria","Chloroplasts","Ribosomes","Golgi bodies"],"answer":1,"explanation":"Chloroplasts contain chlorophyll, which traps light energy to make glucose from carbon dioxide and water. Mitochondria carry out respiration.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"हरे पादप की कोशिका में प्रकाश संश्लेषण कहाँ होता है?","optionsHi":["माइटोकॉन्ड्रिया","हरित लवक (क्लोरोप्लास्ट)","राइबोसोम","गॉल्जी काय"],"explanationHi":"हरित लवक में पर्णहरित (क्लोरोफिल) होता है, जो प्रकाश ऊर्जा ग्रहण करके कार्बन डाइऑक्साइड और जल से ग्लूकोज बनाता है। माइटोकॉन्ड्रिया श्वसन करते हैं।"},
  {"id":"sci-biology-65","question":"Which of the following diseases is caused by a virus?","options":["Typhoid","Cholera","Tuberculosis","Polio"],"answer":3,"explanation":"Polio is caused by the poliovirus. Typhoid, cholera and tuberculosis are bacterial diseases.","difficulty":"moderate","source":"RRB Group D · SSC CHSL","questionHi":"निम्नलिखित में से कौन-सा रोग विषाणु (वायरस) से होता है?","optionsHi":["टाइफाइड","हैजा","क्षय रोग (तपेदिक)","पोलियो"],"explanationHi":"पोलियो पोलियोवायरस से होता है। टाइफाइड, हैजा और क्षय रोग जीवाणुजनित रोग हैं।"},
  {"id":"sci-biology-66","question":"Iron is an essential component of:","options":["Insulin","Haemoglobin","Chlorophyll","Thyroxine"],"answer":1,"explanation":"Each haem group of haemoglobin contains an iron atom that binds oxygen. Chlorophyll contains magnesium, a common trap, and thyroxine contains iodine.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"लोहा किसका आवश्यक घटक है?","optionsHi":["इंसुलिन","हीमोग्लोबिन","पर्णहरित (क्लोरोफिल)","थायरॉक्सिन"],"explanationHi":"हीमोग्लोबिन के प्रत्येक हीम समूह में एक लोहे का परमाणु होता है जो ऑक्सीजन से जुड़ता है। पर्णहरित में मैग्नीशियम होता है, जो आम भ्रम है, और थायरॉक्सिन में आयोडीन होता है।"},
  {"id":"sci-biology-67","question":"The cells of the retina responsible for colour vision and vision in bright light are:","options":["Rods","Cones","Bipolar cells","Ganglion cells"],"answer":1,"explanation":"Cones work in bright light and detect colour; rods contain rhodopsin and work in dim light but cannot detect colour.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"दृष्टिपटल की कौन-सी कोशिकाएँ रंग देखने और तेज प्रकाश में देखने के लिए उत्तरदायी हैं?","optionsHi":["शलाका (रॉड)","शंकु (कोन)","द्विध्रुवी कोशिकाएँ","गुच्छिका कोशिकाएँ"],"explanationHi":"शंकु तेज प्रकाश में कार्य करते हैं और रंगों की पहचान करते हैं; शलाकाओं में रोडॉप्सिन होता है, वे मंद प्रकाश में कार्य करती हैं परंतु रंग नहीं पहचान सकतीं।"},
  {"id":"sci-biology-68","question":"Which enzyme of the pancreatic juice digests fats?","options":["Amylase","Trypsin","Lipase","Pepsin"],"answer":2,"explanation":"Pancreatic lipase breaks emulsified fats into fatty acids and glycerol. Amylase acts on starch, trypsin on proteins, and pepsin is a stomach enzyme.","difficulty":"hard","source":"RRB Group D · SSC CHSL","questionHi":"अग्न्याशयी रस का कौन-सा एंजाइम वसा का पाचन करता है?","optionsHi":["एमाइलेज","ट्रिप्सिन","लाइपेज","पेप्सिन"],"explanationHi":"अग्न्याशयी लाइपेज इमल्सीकृत वसा को वसा अम्लों और ग्लिसरॉल में तोड़ता है। एमाइलेज स्टार्च पर, ट्रिप्सिन प्रोटीन पर क्रिया करता है और पेप्सिन आमाशय का एंजाइम है।"},
  {"id":"sci-biology-69","question":"Haemophilia is best described as:","options":["A Y-linked disorder in which red blood cells become sickle-shaped","An X-linked recessive disorder in which blood clots very slowly","A dietary vitamin K deficiency that develops later in adult life","An autosomal dominant disorder that causes red–green colour blindness"],"answer":1,"explanation":"Haemophilia is an X-linked recessive condition, so it is far commoner in males; a minor cut can bleed for a long time. Vitamin K lack also slows clotting, but it is acquired, not inherited.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"हीमोफीलिया का सबसे सही वर्णन कौन-सा है?","optionsHi":["Y-सहलग्न विकार जिसमें लाल रक्त कोशिकाएँ हँसिया के आकार की हो जाती हैं","X-सहलग्न अप्रभावी विकार जिसमें रक्त बहुत धीरे-धीरे जमता है","विटामिन K की आहार संबंधी कमी जो वयस्क जीवन में आगे चलकर विकसित होती है","अलिंगसूत्री प्रभावी विकार जो लाल-हरे रंग की वर्णांधता उत्पन्न करता है"],"explanationHi":"हीमोफीलिया X-सहलग्न अप्रभावी रोग है, इसलिए यह पुरुषों में कहीं अधिक आम है; एक छोटी-सी चोट से भी लंबे समय तक रक्त बह सकता है। विटामिन K की कमी से भी रक्त का थक्का देर से जमता है, पर वह अर्जित होती है, वंशानुगत नहीं।"},
  {"id":"sci-biology-70","question":"The part of the human inner ear that helps maintain the balance of the body is the:","options":["Cochlea (organ of Corti)","Semicircular canals","Tympanic membrane","Eustachian tube"],"answer":1,"explanation":"The fluid-filled semicircular canals (with the vestibule) sense head movement and position. The cochlea with its organ of Corti is concerned with hearing, and the Eustachian tube only equalises air pressure.","difficulty":"hard","source":"RRB Group D · SSC CHSL","questionHi":"मानव आंतरिक कर्ण का कौन-सा भाग शरीर का संतुलन बनाए रखने में सहायता करता है?","optionsHi":["कर्णावर्त (कॉक्लिया – कॉर्टाई का अंग)","अर्धवृत्ताकार नलिकाएँ","कर्णपटह (टिम्पैनिक झिल्ली)","यूस्टेकियन नली"],"explanationHi":"द्रव से भरी अर्धवृत्ताकार नलिकाएँ (प्रघाण के साथ) सिर की गति और स्थिति का संवेदन करती हैं। कर्णावर्त और उसका कॉर्टाई अंग सुनने से संबंधित हैं, और यूस्टेकियन नली केवल वायु दाब को बराबर करती है।"},
  {"id":"sci-biology-71","question":"In humans, the sex of a child is determined by:","options":["The X chromosome contributed by the mother's egg","The X or Y chromosome carried by the father's sperm","The nutrition and health of the mother during pregnancy","The number of autosomes in the egg compared with the sperm"],"answer":1,"explanation":"Every egg carries an X chromosome; a sperm carries X or Y. An X sperm gives a girl (XX) and a Y sperm a boy (XY).","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"मनुष्यों में शिशु का लिंग किसके द्वारा निर्धारित होता है?","optionsHi":["माता के अंडाणु द्वारा दिया गया X गुणसूत्र","पिता के शुक्राणु में उपस्थित X या Y गुणसूत्र","गर्भावस्था के दौरान माता का पोषण और स्वास्थ्य","अंडाणु की तुलना में शुक्राणु में अलिंगसूत्रों की संख्या"],"explanationHi":"प्रत्येक अंडाणु में X गुणसूत्र होता है; शुक्राणु में X या Y होता है। X शुक्राणु से लड़की (XX) और Y शुक्राणु से लड़का (XY) होता है।"},
  {"id":"sci-biology-72","question":"Antibodies in the human body are produced by:","options":["T-lymphocytes (helper T cells)","Platelets (thrombocytes)","Red blood cells (erythrocytes)","B-lymphocytes (plasma cells)"],"answer":3,"explanation":"B-lymphocytes turn into plasma cells that secrete antibodies (humoral immunity). Helper T cells only signal B cells to respond; T-lymphocytes give cell-mediated immunity and do not make antibodies.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"मानव शरीर में प्रतिरक्षी (एंटीबॉडी) किनके द्वारा बनाए जाते हैं?","optionsHi":["T-लिम्फोसाइट (सहायक T कोशिकाएँ)","प्लेटलेट्स (थ्रोम्बोसाइट)","लाल रक्त कोशिकाएँ (इरिथ्रोसाइट)","B-लिम्फोसाइट (प्लाज्मा कोशिकाएँ)"],"explanationHi":"B-लिम्फोसाइट प्लाज्मा कोशिकाओं में बदल जाते हैं जो प्रतिरक्षी का स्राव करती हैं (तरल प्रतिरक्षा)। सहायक T कोशिकाएँ केवल B कोशिकाओं को प्रतिक्रिया के लिए संकेत देती हैं; T-लिम्फोसाइट कोशिका-मध्यित प्रतिरक्षा देते हैं और प्रतिरक्षी नहीं बनाते।"},
  {"id":"sci-biology-73","question":"The cell organelle that modifies, sorts and packages proteins for secretion is the:","options":["Endoplasmic reticulum","Golgi apparatus","Lysosome","Nucleolus"],"answer":1,"explanation":"Proteins made on the rough ER travel to the Golgi apparatus, which modifies and packs them into vesicles for secretion.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"प्रोटीन को रूपांतरित करके, छाँटकर और बाँधकर स्राव के लिए तैयार करने वाला कोशिकांग कौन-सा है?","optionsHi":["अंतःप्रद्रव्यी जालिका","गॉल्जी उपकरण","लयनकाय (लाइसोसोम)","केंद्रिका"],"explanationHi":"खुरदरी अंतःप्रद्रव्यी जालिका पर बने प्रोटीन गॉल्जी उपकरण में पहुँचते हैं, जो उन्हें रूपांतरित करके स्राव के लिए पुटिकाओं में बाँध देता है।"},
  {"id":"sci-biology-74","question":"How many of these statements about cells are correct? I. Plant cells contain plastids. II. Animal cells usually have centrioles. III. Ribosomes are found in both prokaryotic and eukaryotic cells. IV. Mitochondria have their own DNA.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: plant cells have plastids, animal cells usually have centrioles, ribosomes (membraneless RNA–protein particles) occur in prokaryotes and eukaryotes alike, and mitochondria carry their own circular DNA.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"कोशिकाओं से संबंधित इनमें से कितने कथन सही हैं? I. पादप कोशिकाओं में लवक होते हैं। II. जंतु कोशिकाओं में प्रायः तारककेंद्र (सेंट्रीओल) होते हैं। III. राइबोसोम प्रोकैरियोटिक और यूकैरियोटिक दोनों कोशिकाओं में पाए जाते हैं। IV. माइटोकॉन्ड्रिया का अपना DNA होता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं: पादप कोशिकाओं में लवक होते हैं, जंतु कोशिकाओं में प्रायः तारककेंद्र होते हैं, राइबोसोम (झिल्लीरहित RNA–प्रोटीन कण) प्रोकैरियोटिक और यूकैरियोटिक दोनों में मिलते हैं, और माइटोकॉन्ड्रिया में अपना वृत्ताकार DNA होता है।"},
  {"id":"sci-biology-75","question":"Assertion (A): Arteries have thicker and more elastic walls than veins. Reason (R): Arteries carry blood away from the heart under high pressure.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"The thick muscular, elastic walls let arteries withstand and smooth out the high pressure of each heartbeat. R explains A.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"अभिकथन (A): धमनियों की दीवारें शिराओं की तुलना में अधिक मोटी और लचीली होती हैं। कारण (R): धमनियाँ हृदय से दूर रक्त को उच्च दाब पर ले जाती हैं।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है परंतु R गलत है","A गलत है परंतु R सही है"],"explanationHi":"मोटी, पेशीय और लचीली दीवारें धमनियों को प्रत्येक हृदय स्पंदन के उच्च दाब को सहने और संतुलित करने में समर्थ बनाती हैं। R, A की व्याख्या करता है।"},
  {"id":"sci-biology-76","question":"Assertion (A): The pulmonary artery carries oxygenated blood. Reason (R): Arteries carry blood away from the heart.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"A is false: the pulmonary artery carries deoxygenated blood from the right ventricle to the lungs. R is true, which is why it is still called an artery.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"अभिकथन (A): फुफ्फुसीय धमनी ऑक्सीजनयुक्त रक्त ले जाती है। कारण (R): धमनियाँ हृदय से दूर रक्त ले जाती हैं।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है परंतु R गलत है","A गलत है परंतु R सही है"],"explanationHi":"A गलत है: फुफ्फुसीय धमनी दाएँ निलय से फेफड़ों तक ऑक्सीजनरहित रक्त ले जाती है। R सही है, इसीलिए इसे फिर भी धमनी कहा जाता है।"},
  {"id":"sci-biology-77","question":"Match the disease with its vector: 1. Malaria 2. Dengue 3. Sleeping sickness 4. Plague; a. Rat flea b. Tsetse fly c. Female Anopheles mosquito d. Aedes mosquito","options":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a","1-c, 2-d, 3-a, 4-b","1-c, 2-b, 3-d, 4-a"],"answer":0,"explanation":"Anopheles spreads malaria, Aedes spreads dengue, the tsetse fly spreads African sleeping sickness and the rat flea spreads plague.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"रोग का उसके वाहक से मिलान कीजिए: 1. मलेरिया 2. डेंगू 3. निद्रा रोग (स्लीपिंग सिकनेस) 4. प्लेग; a. चूहे का पिस्सू b. सी-सी मक्खी (ट्सेट्सी) c. मादा ऐनोफ़िलीज़ मच्छर d. एडीज़ मच्छर","optionsHi":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a","1-c, 2-d, 3-a, 4-b","1-c, 2-b, 3-d, 4-a"],"explanationHi":"ऐनोफ़िलीज़ मलेरिया फैलाता है, एडीज़ डेंगू, सी-सी मक्खी अफ्रीकी निद्रा रोग और चूहे का पिस्सू प्लेग फैलाता है।"},
  {"id":"sci-biology-78","question":"A tall pea plant is crossed with a dwarf plant (tt), and half the offspring are tall and half dwarf. The genotype of the tall parent is:","options":["Homozygous tall (TT)","Heterozygous tall (Tt)","Homozygous dwarf (tt)","It cannot be determined"],"answer":1,"explanation":"This is a test cross: Tt × tt gives Tt and tt in a 1 : 1 ratio, matching the half-tall, half-dwarf result. If the tall parent were TT, every offspring would be tall.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"एक लंबे मटर के पौधे का संकरण बौने पौधे (tt) से कराया जाता है, और आधी संतानें लंबी तथा आधी बौनी होती हैं। लंबे जनक का जीनोटाइप क्या है?","optionsHi":["समयुग्मजी लंबा (TT)","विषमयुग्मजी लंबा (Tt)","समयुग्मजी बौना (tt)","निर्धारित नहीं किया जा सकता"],"explanationHi":"यह परीक्षार्थ संकरण (टेस्ट क्रॉस) है: Tt × tt से Tt और tt 1 : 1 अनुपात में मिलते हैं, जो आधी लंबी और आधी बौनी संतानों से मेल खाता है। यदि लंबा जनक TT होता, तो सभी संतानें लंबी होतीं।"},
  {"id":"sci-biology-79","question":"A woman who is a carrier of colour blindness marries a man with normal vision. What is expected among their children?","options":["50% of the sons colour-blind and none of the daughters","25% of the sons and 25% of the daughters colour-blind","All the sons colour-blind and none of the daughters","No sons colour-blind and 50% of the daughters colour-blind"],"answer":0,"explanation":"Mother XᶜX × father XY. Sons get the X from the mother, so half are XᶜY (colour-blind). Daughters get the father’s normal X, so none are colour-blind, though half are carriers.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"वर्णांधता की वाहक एक स्त्री का विवाह सामान्य दृष्टि वाले पुरुष से होता है। उनकी संतानों में क्या अपेक्षित है?","optionsHi":["50% पुत्र वर्णांध और कोई पुत्री नहीं","25% पुत्र और 25% पुत्रियाँ वर्णांध","सभी पुत्र वर्णांध और कोई पुत्री नहीं","कोई पुत्र वर्णांध नहीं और 50% पुत्रियाँ वर्णांध"],"explanationHi":"माता XᶜX × पिता XY। पुत्रों को X माता से मिलता है, इसलिए आधे XᶜY (वर्णांध) होते हैं। पुत्रियों को पिता का सामान्य X मिलता है, इसलिए कोई वर्णांध नहीं होती, यद्यपि आधी वाहक होती हैं।"},
  {"id":"sci-biology-80","question":"Which pair of digestive enzyme and the food it acts on is NOT correctly matched?","options":["Pepsin – proteins","Salivary amylase – starch","Trypsin – starch","Lipase – fats"],"answer":2,"explanation":"Trypsin, from the pancreas, digests proteins. Starch is digested by salivary and pancreatic amylase.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"पाचक एंजाइम और जिस भोजन पर वह क्रिया करता है, उसका कौन-सा युग्म सही सुमेलित नहीं है?","optionsHi":["पेप्सिन – प्रोटीन","लार का एमाइलेज – स्टार्च","ट्रिप्सिन – स्टार्च","लाइपेज – वसा"],"explanationHi":"अग्न्याशय से निकलने वाला ट्रिप्सिन प्रोटीन का पाचन करता है। स्टार्च का पाचन लार के और अग्न्याशय के एमाइलेज द्वारा होता है।"},
  {"id":"sci-biology-81","question":"How many of these statements are correct? I. Anaerobic respiration in human muscles produces lactic acid. II. Anaerobic respiration in yeast produces ethanol and carbon dioxide. III. Glycolysis requires oxygen. IV. The breakdown of glucose to pyruvate takes place in the mitochondria.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only I and II are correct. Glycolysis needs no oxygen and occurs in the cytoplasm; only the later breakdown of pyruvate in aerobic respiration takes place in the mitochondria.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इनमें से कितने कथन सही हैं? I. मानव पेशियों में अवायवीय श्वसन से लैक्टिक अम्ल बनता है। II. यीस्ट में अवायवीय श्वसन से एथेनॉल और कार्बन डाइऑक्साइड बनते हैं। III. ग्लाइकोलिसिस के लिए ऑक्सीजन आवश्यक है। IV. ग्लूकोज का पाइरूवेट में विघटन माइटोकॉन्ड्रिया में होता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I और II सही हैं। ग्लाइकोलिसिस में ऑक्सीजन की आवश्यकता नहीं होती और यह कोशिकाद्रव्य में होता है; वायवीय श्वसन में पाइरूवेट का आगे का विघटन ही माइटोकॉन्ड्रिया में होता है।"},
  {"id":"sci-biology-82","question":"Arrange these discoveries in chronological order: 1. Discovery of penicillin 2. Discovery of the cell 3. Double-helix model of DNA 4. First smallpox vaccine","options":["2, 4, 3, 1","4, 2, 1, 3","2, 1, 4, 3","2, 4, 1, 3"],"answer":3,"explanation":"Robert Hooke saw cells in 1665, Edward Jenner made the smallpox vaccine in 1796, Alexander Fleming found penicillin in 1928, and Watson and Crick proposed the double helix in 1953.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"इन खोजों को कालक्रम के अनुसार व्यवस्थित कीजिए: 1. पेनिसिलिन की खोज 2. कोशिका की खोज 3. DNA का द्वि-कुंडलित (डबल-हेलिक्स) मॉडल 4. चेचक का पहला टीका","optionsHi":["2, 4, 3, 1","4, 2, 1, 3","2, 1, 4, 3","2, 4, 1, 3"],"explanationHi":"रॉबर्ट हुक ने 1665 में कोशिकाएँ देखीं, एडवर्ड जेनर ने 1796 में चेचक का टीका बनाया, अलेक्ज़ेंडर फ्लेमिंग ने 1928 में पेनिसिलिन खोजी, और वाटसन तथा क्रिक ने 1953 में द्वि-कुंडलित संरचना प्रस्तावित की।"},
  {"id":"sci-biology-83","question":"How many of these statements about deficiency diseases are correct? I. Kwashiorkor is caused mainly by a lack of protein. II. Marasmus results from a deficiency of both protein and calories. III. Lack of iron causes anaemia. IV. Children with kwashiorkor often show swelling (oedema) of the body.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The swollen belly and limbs in kwashiorkor distinguish it from marasmus, where the child is severely wasted.","difficulty":"very-hard","source":"RRB Group D · SSC CHSL","questionHi":"कमी से होने वाले रोगों से संबंधित इनमें से कितने कथन सही हैं? I. क्वाशिओरकर मुख्यतः प्रोटीन की कमी से होता है। II. मरास्मस प्रोटीन और कैलोरी दोनों की कमी से होता है। III. लोहे की कमी से रक्ताल्पता होती है। IV. क्वाशिओरकर से पीड़ित बच्चों के शरीर में प्रायः सूजन (शोफ) दिखाई देती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। क्वाशिओरकर में पेट और हाथ-पैरों की सूजन इसे मरास्मस से अलग करती है, जिसमें बच्चा अत्यंत दुबला हो जाता है।"},
  {"id":"sci-biology-84","question":"A person’s heart beats 72 times a minute and pumps 70 mL of blood per beat from the left ventricle. The cardiac output is about:","options":["504 mL per minute","5.04 litres per minute","50.4 litres per minute","1.4 litres per minute"],"answer":1,"explanation":"Cardiac output = heart rate × stroke volume = 72 × 70 mL = 5,040 mL ≈ 5.04 litres per minute, roughly the whole blood volume every minute.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"एक व्यक्ति का हृदय 72 बार प्रति मिनट धड़कता है और बाएँ निलय से प्रति धड़कन 70 mL रक्त पंप करता है। हृदय निर्गम (कार्डियक आउटपुट) लगभग कितना है?","optionsHi":["504 mL प्रति मिनट","5.04 लीटर प्रति मिनट","50.4 लीटर प्रति मिनट","1.4 लीटर प्रति मिनट"],"explanationHi":"हृदय निर्गम = हृदय गति × स्ट्रोक आयतन = 72 × 70 mL = 5,040 mL ≈ 5.04 लीटर प्रति मिनट, अर्थात लगभग पूरे रक्त आयतन के बराबर प्रति मिनट।"},
  {"id":"sci-biology-85","question":"Plants lose water vapour mainly through tiny pores on their leaves called:","options":["Xylem vessels","Root hairs","Lenticels","Stomata"],"answer":3,"explanation":"Transpiration takes place mostly through stomata, each opened and closed by a pair of guard cells. Lenticels are pores in woody stems and lose only a little water.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"पौधे अपनी पत्तियों के किन सूक्ष्म छिद्रों से मुख्यतः जलवाष्प खोते हैं?","optionsHi":["जाइलम वाहिकाएँ","मूल रोम","वातरंध्र (लेंटिसेल)","रंध्र (स्टोमेटा)"],"explanationHi":"वाष्पोत्सर्जन मुख्यतः रंध्रों से होता है, जिनमें से प्रत्येक को द्वार कोशिकाओं का एक जोड़ा खोलता और बंद करता है। वातरंध्र काष्ठीय तनों के छिद्र हैं और उनसे बहुत थोड़ा जल निकलता है।"},
  {"id":"sci-biology-86","question":"The scientific name of modern human beings is:","options":["Homo erectus","Homo sapiens","Pan troglodytes","Homo habilis"],"answer":1,"explanation":"In binomial naming the genus comes first (Homo) and the species second (sapiens). Homo erectus and Homo habilis are extinct human species, and Pan troglodytes is the chimpanzee.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"आधुनिक मानव का वैज्ञानिक नाम क्या है?","optionsHi":["होमो इरेक्टस","होमो सेपियंस","पैन ट्रोग्लोडाइटीज़","होमो हैबिलिस"],"explanationHi":"द्विनाम पद्धति में वंश का नाम पहले (होमो) और जाति का नाम बाद में (सेपियंस) आता है। होमो इरेक्टस और होमो हैबिलिस विलुप्त मानव जातियाँ हैं, और पैन ट्रोग्लोडाइटीज़ चिंपैंजी है।"},
  {"id":"sci-biology-87","question":"The branch of biology that studies the relationship between living organisms and their environment is:","options":["Ethology","Ecology","Taxonomy","Physiology"],"answer":1,"explanation":"Ecology deals with interactions among organisms and with their surroundings. Ethology is the study of animal behaviour and taxonomy the science of classification.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"जीव विज्ञान की वह शाखा कौन-सी है जो जीवों और उनके पर्यावरण के बीच संबंध का अध्ययन करती है?","optionsHi":["व्यवहार विज्ञान (एथोलॉजी)","पारिस्थितिकी (इकोलॉजी)","वर्गिकी (टैक्सोनॉमी)","शरीर क्रिया विज्ञान (फिजियोलॉजी)"],"explanationHi":"पारिस्थितिकी जीवों के आपसी संबंधों तथा उनके परिवेश के साथ अंतःक्रियाओं का अध्ययन करती है। एथोलॉजी जंतु व्यवहार का अध्ययन है और वर्गिकी वर्गीकरण का विज्ञान।"},
  {"id":"sci-biology-88","question":"Which plant hormone is used to ripen fruits artificially?","options":["Gibberellin","Ethylene","Cytokinin","Auxin"],"answer":1,"explanation":"Ethylene, a gaseous hormone, speeds up the ripening of fruits such as bananas and mangoes. Auxin promotes cell elongation and cytokinin cell division.","difficulty":"moderate","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"फलों को कृत्रिम रूप से पकाने के लिए किस पादप हॉर्मोन का उपयोग किया जाता है?","optionsHi":["जिबरेलिन","एथिलीन","साइटोकाइनिन","ऑक्सिन"],"explanationHi":"एथिलीन गैसीय हॉर्मोन है जो केले और आम जैसे फलों के पकने की गति बढ़ाता है। ऑक्सिन कोशिका दीर्घन को और साइटोकाइनिन कोशिका विभाजन को बढ़ावा देता है।"},
  {"id":"sci-biology-89","question":"The shoulder joint and the hip joint are examples of:","options":["Gliding (plane) joints","Hinge joints","Ball-and-socket joints","Pivot (rotary) joints"],"answer":2,"explanation":"The rounded head of one bone fits into a cup of the other, allowing movement in all directions. The knee and elbow are hinge joints, and the joint between the first two neck vertebrae is a pivot joint.","difficulty":"moderate","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"कंधे का जोड़ और कूल्हे का जोड़ किसके उदाहरण हैं?","optionsHi":["विसर्पी (सरल) संधि","कब्जा संधि","गेंद-खल्लिका (बॉल-सॉकेट) संधि","धुरी (चूलदार) संधि"],"explanationHi":"एक अस्थि का गोल सिरा दूसरी अस्थि के प्याले में बैठता है, जिससे सभी दिशाओं में गति संभव होती है। घुटना और कोहनी कब्जा संधियाँ हैं, और गर्दन की पहली दो कशेरुकाओं के बीच का जोड़ धुरी संधि है।"},
  {"id":"sci-biology-90","question":"Lymph differs from blood mainly because it has no:","options":["Red blood cells","White blood cells","Proteins","Water"],"answer":0,"explanation":"Lymph is tissue fluid collected by lymph vessels; it contains lymphocytes and some protein but no red blood cells, which is why it is colourless.","difficulty":"moderate","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"लसीका रक्त से मुख्यतः इस बात में भिन्न होती है कि उसमें नहीं होता:","optionsHi":["लाल रक्त कोशिकाएँ","श्वेत रक्त कोशिकाएँ","प्रोटीन","जल"],"explanationHi":"लसीका लसीका वाहिकाओं द्वारा एकत्र किया गया ऊतक द्रव है; इसमें लिम्फोसाइट और कुछ प्रोटीन होते हैं पर लाल रक्त कोशिकाएँ नहीं होतीं, इसीलिए यह रंगहीन होती है।"},
  {"id":"sci-biology-91","question":"In a flowering plant, water and minerals are carried from the roots to the leaves by the:","options":["Cambium","Cortex","Phloem","Xylem"],"answer":3,"explanation":"Xylem carries water and dissolved minerals upward, pulled mainly by transpiration. Phloem carries food made in the leaves to other parts in both directions.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"पुष्पीय पादप में जल और खनिज जड़ों से पत्तियों तक किसके द्वारा पहुँचाए जाते हैं?","optionsHi":["एधा (कैम्बियम)","वल्कुट (कॉर्टेक्स)","फ्लोएम","जाइलम"],"explanationHi":"जाइलम जल और घुले हुए खनिजों को ऊपर की ओर ले जाता है, जो मुख्यतः वाष्पोत्सर्जन के खिंचाव से होता है। फ्लोएम पत्तियों में बने भोजन को दोनों दिशाओं में अन्य भागों तक पहुँचाता है।"},
  {"id":"sci-biology-92","question":"Insectivorous plants such as the pitcher plant trap insects mainly to obtain:","options":["Water","Oxygen","Nitrogen","Carbohydrates"],"answer":2,"explanation":"These plants grow in nitrogen-poor soils and digest insects to get nitrogen compounds. They still make their own carbohydrates by photosynthesis, since they have green leaves.","difficulty":"moderate","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"घटपर्णी जैसे कीटभक्षी पौधे कीटों को मुख्यतः किसकी प्राप्ति के लिए फँसाते हैं?","optionsHi":["जल","ऑक्सीजन","नाइट्रोजन","कार्बोहाइड्रेट"],"explanationHi":"ये पौधे नाइट्रोजन की कमी वाली मृदा में उगते हैं और नाइट्रोजन यौगिक प्राप्त करने के लिए कीटों का पाचन करते हैं। हरी पत्तियाँ होने के कारण वे अपने कार्बोहाइड्रेट प्रकाश संश्लेषण से स्वयं बनाते हैं।"},
  {"id":"sci-biology-93","question":"The dark reactions (Calvin cycle) of photosynthesis take place in the:","options":["Thylakoid membranes of the grana","Stroma of the chloroplast","Matrix of the mitochondria","Cytoplasm of the leaf cell"],"answer":1,"explanation":"Light reactions occur on the thylakoids and make ATP and NADPH; these are used in the stroma, the fluid around the thylakoids, to fix CO₂ into sugar.","difficulty":"moderate","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"प्रकाश संश्लेषण की अंधकार अभिक्रियाएँ (केल्विन चक्र) कहाँ होती हैं?","optionsHi":["ग्रैना की थायलेकॉइड झिल्लियों में","हरित लवक के स्ट्रोमा में","माइटोकॉन्ड्रिया के आधात्री (मैट्रिक्स) में","पत्ती कोशिका के कोशिकाद्रव्य में"],"explanationHi":"प्रकाश अभिक्रियाएँ थायलेकॉइड पर होती हैं और ATP तथा NADPH बनाती हैं; इनका उपयोग स्ट्रोमा में, जो थायलेकॉइड के चारों ओर का द्रव है, CO₂ को शर्करा में स्थिर करने के लिए होता है।"},
  {"id":"sci-biology-94","question":"In human males, sperms are produced in the:","options":["Head and tail of the epididymis","Seminiferous tubules of testes","Vas deferens (sperm duct)","Prostate and seminal vesicles"],"answer":1,"explanation":"Sperms form in the seminiferous tubules and then mature and are stored in the epididymis. The vas deferens carries them, and the prostate adds fluid to semen.","difficulty":"hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"मानव पुरुषों में शुक्राणुओं का निर्माण कहाँ होता है?","optionsHi":["अधिवृषण (एपिडिडिमिस) का सिर और पूँछ","वृषणों की शुक्रजनक नलिकाएँ","शुक्रवाहिका (वास डेफेरेंस)","पुरःस्थ ग्रंथि (प्रोस्टेट) और शुक्राशय"],"explanationHi":"शुक्राणु शुक्रजनक नलिकाओं में बनते हैं और फिर अधिवृषण में परिपक्व होकर संचित रहते हैं। शुक्रवाहिका उन्हें ले जाती है, और पुरःस्थ ग्रंथि वीर्य में तरल जोड़ती है।"},
  {"id":"sci-biology-95","question":"In a food chain, producers fix 10,000 J of energy. Following the ten per cent law, the energy available to the tertiary consumers is:","options":["1 J","10 J","100 J","1,000 J"],"answer":1,"explanation":"About 10% passes to each higher level: primary consumers get 1,000 J, secondary 100 J and tertiary 10 J. Stopping one level early gives 100 J.","difficulty":"hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"एक खाद्य श्रृंखला में उत्पादक 10,000 J ऊर्जा स्थिर करते हैं। दस प्रतिशत के नियम के अनुसार तृतीयक उपभोक्ताओं को उपलब्ध ऊर्जा कितनी होगी?","optionsHi":["1 J","10 J","100 J","1,000 J"],"explanationHi":"प्रत्येक उच्चतर स्तर को लगभग 10% ऊर्जा मिलती है: प्राथमिक उपभोक्ताओं को 1,000 J, द्वितीयक को 100 J और तृतीयक को 10 J। एक स्तर पहले रुक जाने पर 100 J आता है।"},
  {"id":"sci-biology-96","question":"Which plant hormone makes stomata close when a plant faces water shortage?","options":["Gibberellic acid","Abscisic acid","Cytokinin","Auxin"],"answer":1,"explanation":"Abscisic acid (ABA) is the ‘stress hormone’: it builds up during drought and closes stomata to save water. It also promotes dormancy, while gibberellins break it.","difficulty":"hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"पौधे के सामने जल की कमी होने पर कौन-सा पादप हॉर्मोन रंध्रों को बंद कर देता है?","optionsHi":["जिबरेलिक अम्ल","एब्सिसिक अम्ल","साइटोकाइनिन","ऑक्सिन"],"explanationHi":"एब्सिसिक अम्ल (ABA) ‘तनाव हॉर्मोन’ है: सूखे के समय यह जमा हो जाता है और जल बचाने के लिए रंध्र बंद कर देता है। यह सुप्तावस्था को भी बढ़ावा देता है, जबकि जिबरेलिन उसे तोड़ते हैं।"},
  {"id":"sci-biology-97","question":"Blood rich in digested food is carried from the intestines to the liver by the:","options":["Hepatic portal vein","Inferior vena cava","Superior mesenteric artery","Hepatic vein"],"answer":0,"explanation":"The hepatic portal vein brings nutrient-rich blood from the gut to the liver for processing. The mesenteric artery carries blood to the intestine, not away from it, and the hepatic vein drains the liver into the vena cava.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"पचे हुए भोजन से समृद्ध रक्त आँतों से यकृत तक किसके द्वारा पहुँचाया जाता है?","optionsHi":["यकृत निवाहिका शिरा","अधो महाशिरा","ऊर्ध्व आंत्रयोजनी धमनी","यकृत शिरा"],"explanationHi":"यकृत निवाहिका शिरा आँतों से पोषक तत्वों से भरपूर रक्त को संसाधन के लिए यकृत तक लाती है। आंत्रयोजनी धमनी रक्त को आँत तक ले जाती है, आँत से दूर नहीं, और यकृत शिरा यकृत से रक्त को महाशिरा में पहुँचाती है।"},
  {"id":"sci-biology-98","question":"Human insulin made by recombinant DNA technology, first marketed in 1982, was produced using:","options":["The bacterium Escherichia coli","Genetically modified tobacco plants","Pancreas of pigs and cattle","Yeast extract from bread"],"answer":0,"explanation":"The human insulin gene was put into E. coli, which made the hormone in bulk (Humulin). Before that, diabetics used insulin taken from the pancreas of pigs and cattle.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"पुनर्योगज DNA प्रौद्योगिकी से बनी मानव इंसुलिन, जो 1982 में पहली बार बाज़ार में आई, किसके उपयोग से बनाई गई थी?","optionsHi":["जीवाणु एशेरिकिया कोलाई","आनुवंशिक रूप से रूपांतरित तंबाकू के पौधे","सूअरों और मवेशियों का अग्न्याशय","ब्रेड से प्राप्त यीस्ट का सत्त"],"explanationHi":"मानव इंसुलिन जीन को E. coli में डाला गया, जिसने इस हॉर्मोन को बड़ी मात्रा में बनाया (ह्यूमुलिन)। इससे पहले मधुमेह रोगी सूअरों और मवेशियों के अग्न्याशय से प्राप्त इंसुलिन का उपयोग करते थे।"},
  {"id":"sci-biology-99","question":"Which of the following is NOT a fungus?","options":["Yeast","Penicillium","Mushroom","Euglena"],"answer":3,"explanation":"Euglena is a single-celled protist with chloroplasts that can also feed like an animal. Yeast, mushrooms and the mould Penicillium are all fungi.","difficulty":"hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"निम्नलिखित में से कौन-सा कवक नहीं है?","optionsHi":["यीस्ट","पेनिसिलियम","मशरूम (खुंबी)","यूग्लीना"],"explanationHi":"यूग्लीना हरित लवक वाला एककोशिकीय प्रोटिस्ट है जो जंतु की तरह भी भोजन ग्रहण कर सकता है। यीस्ट, मशरूम और फफूँद पेनिसिलियम सभी कवक हैं।"},
  {"id":"sci-biology-100","question":"Most of the carbon dioxide in human blood is transported as:","options":["Dissolved CO₂ in plasma","Bicarbonate ions in plasma","Carbaminohaemoglobin","Carbonic acid inside platelets"],"answer":1,"explanation":"About 70% travels as bicarbonate, formed inside red cells with the enzyme carbonic anhydrase; about 20–25% is bound to haemoglobin and only about 7% is dissolved.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"मानव रक्त में कार्बन डाइऑक्साइड का अधिकांश भाग किस रूप में परिवहित होता है?","optionsHi":["प्लाज्मा में घुले CO₂ के रूप में","प्लाज्मा में बाइकार्बोनेट आयनों के रूप में","कार्बामिनोहीमोग्लोबिन के रूप में","प्लेटलेट्स के भीतर कार्बोनिक अम्ल के रूप में"],"explanationHi":"लगभग 70% भाग बाइकार्बोनेट के रूप में जाता है, जो लाल कोशिकाओं के भीतर कार्बोनिक एनहाइड्रेज़ एंजाइम से बनता है; लगभग 20–25% हीमोग्लोबिन से जुड़ा होता है और केवल लगभग 7% घुला होता है।"},
  {"id":"sci-biology-101","question":"The metal ion at the centre of a chlorophyll molecule and the one at the centre of the haem in haemoglobin are respectively:","options":["Magnesium and copper","Magnesium and iron","Iron and magnesium","Copper and iron"],"answer":1,"explanation":"Chlorophyll has a magnesium ion in its porphyrin ring and haem has an iron ion. Copper is found in haemocyanin, the blue oxygen carrier of some molluscs and arthropods.","difficulty":"hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"पर्णहरित (क्लोरोफिल) अणु के केंद्र में और हीमोग्लोबिन के हीम के केंद्र में स्थित धातु आयन क्रमशः कौन-से हैं?","optionsHi":["मैग्नीशियम और तांबा","मैग्नीशियम और लोहा","लोहा और मैग्नीशियम","तांबा और लोहा"],"explanationHi":"पर्णहरित की पॉर्फिरिन वलय में मैग्नीशियम आयन और हीम में लोहे का आयन होता है। तांबा हीमोसायनिन में पाया जाता है, जो कुछ मोलस्कों और संधिपादों का नीला ऑक्सीजन वाहक है।"},
  {"id":"sci-biology-102","question":"In the nephron, ultrafiltration of blood takes place in the:","options":["Glomerulus and Bowman's capsule","Distal convoluted tubule","Collecting duct and renal pelvis","Loop of Henle in the medulla"],"answer":0,"explanation":"High pressure in the glomerular capillaries forces water and small solutes into Bowman’s capsule. Reabsorption of water and salts happens later along the tubule and collecting duct.","difficulty":"hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"नेफ्रॉन में रक्त का परानिस्यंदन (अल्ट्राफिल्ट्रेशन) कहाँ होता है?","optionsHi":["केशिका गुच्छ (ग्लोमेरुलस) और बोमन संपुट","दूरस्थ कुंडलित नलिका","संग्राहक नलिका और वृक्क पेल्विस","मध्यांश में हेनले का लूप"],"explanationHi":"केशिका गुच्छ की केशिकाओं में उच्च दाब जल और छोटे विलेयों को बोमन संपुट में धकेल देता है। जल और लवणों का पुनरावशोषण बाद में नलिका और संग्राहक नलिका में होता है।"},
  {"id":"sci-biology-103","question":"How many of these statements about photosynthesis are correct? I. The oxygen released comes from carbon dioxide, not from water. II. The light reactions take place in the stroma. III. Making glucose in the Calvin cycle uses ATP and NADPH from the light reactions. IV. Photosynthesis is an exothermic process.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only III is correct. I is wrong: heavy-oxygen experiments showed the O₂ comes from splitting water. II is wrong: light reactions occur in the thylakoid membranes; the stroma hosts the Calvin cycle. IV is wrong: photosynthesis is endothermic.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"प्रकाश संश्लेषण से संबंधित इनमें से कितने कथन सही हैं? I. मुक्त होने वाली ऑक्सीजन कार्बन डाइऑक्साइड से आती है, जल से नहीं। II. प्रकाश अभिक्रियाएँ स्ट्रोमा में होती हैं। III. केल्विन चक्र में ग्लूकोज बनाने में प्रकाश अभिक्रियाओं से प्राप्त ATP और NADPH का उपयोग होता है। IV. प्रकाश संश्लेषण एक ऊष्माक्षेपी प्रक्रिया है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल III सही है। I गलत है: भारी ऑक्सीजन के प्रयोगों ने दिखाया कि O₂ जल के विघटन से आती है। II गलत है: प्रकाश अभिक्रियाएँ थायलेकॉइड झिल्लियों में होती हैं; स्ट्रोमा में केल्विन चक्र होता है। IV गलत है: प्रकाश संश्लेषण ऊष्माशोषी है।"},
  {"id":"sci-biology-104","question":"Match the plant hormone with its main effect: 1. Auxin 2. Gibberellin 3. Cytokinin 4. Ethylene; a. Ripening of fruits b. Cell division and delay of leaf ageing c. Stem elongation and bolting d. Apical dominance and bending towards light","options":["1-d, 2-c, 3-a, 4-b","1-d, 2-c, 3-b, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-b, 3-c, 4-a"],"answer":1,"explanation":"Auxin causes phototropism and apical dominance, gibberellins lengthen stems and cause bolting, cytokinins promote cell division and delay senescence, and ethylene ripens fruit.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"पादप हॉर्मोन का उसके मुख्य प्रभाव से मिलान कीजिए: 1. ऑक्सिन 2. जिबरेलिन 3. साइटोकाइनिन 4. एथिलीन; a. फलों का पकना b. कोशिका विभाजन और पत्तियों की जरावस्था में देरी c. तने का दीर्घन और बोल्टिंग d. शीर्षस्थ प्रभाविता और प्रकाश की ओर मुड़ना","optionsHi":["1-d, 2-c, 3-a, 4-b","1-d, 2-c, 3-b, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-b, 3-c, 4-a"],"explanationHi":"ऑक्सिन प्रकाशानुवर्तन और शीर्षस्थ प्रभाविता उत्पन्न करता है, जिबरेलिन तनों को लंबा करते हैं और बोल्टिंग कराते हैं, साइटोकाइनिन कोशिका विभाजन को बढ़ावा देते हैं और जरावस्था में देरी करते हैं, तथा एथिलीन फलों को पकाता है।"},
  {"id":"sci-biology-105","question":"Assertion (A): Birds and most reptiles excrete nitrogenous waste mainly as uric acid. Reason (R): Uric acid is nearly insoluble and can be removed with very little loss of water.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Ammonia needs much water to flush out, urea less, and uric acid the least because it is passed as a paste. Being uricotelic saves water, which suits flying birds and egg-laying reptiles, so R explains A.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): पक्षी और अधिकांश सरीसृप नाइट्रोजनी अपशिष्ट को मुख्यतः यूरिक अम्ल के रूप में उत्सर्जित करते हैं। कारण (R): यूरिक अम्ल लगभग अविलेय होता है और बहुत कम जल की हानि के साथ बाहर निकाला जा सकता है।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है परंतु R गलत है","A गलत है परंतु R सही है"],"explanationHi":"अमोनिया को बाहर निकालने में बहुत जल लगता है, यूरिया में उससे कम, और यूरिक अम्ल में सबसे कम, क्योंकि यह लेई के रूप में निकलता है। यूरिकोटेलिक होना जल बचाता है, जो उड़ने वाले पक्षियों और अंडे देने वाले सरीसृपों के लिए उपयुक्त है, इसलिए R, A की व्याख्या करता है।"},
  {"id":"sci-biology-106","question":"How many of these statements about energy flow in ecosystems are correct? I. Energy flows through an ecosystem in one direction only. II. The pyramid of energy is always upright. III. The pyramid of biomass in a pond ecosystem is usually inverted. IV. Only about 10% of the energy at one trophic level passes to the next.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Energy is lost as heat at every level, so it cannot cycle and its pyramid is never inverted; in a pond, the small biomass of fast-reproducing phytoplankton supports a larger biomass of consumers.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"पारिस्थितिक तंत्र में ऊर्जा प्रवाह से संबंधित इनमें से कितने कथन सही हैं? I. ऊर्जा पारिस्थितिक तंत्र में केवल एक ही दिशा में प्रवाहित होती है। II. ऊर्जा का पिरामिड सदैव सीधा होता है। III. तालाब पारिस्थितिक तंत्र में जैव मात्रा का पिरामिड प्रायः उलटा होता है। IV. एक पोषी स्तर की ऊर्जा का केवल लगभग 10% अगले स्तर में पहुँचता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। प्रत्येक स्तर पर ऊर्जा ऊष्मा के रूप में नष्ट हो जाती है, इसलिए वह चक्रित नहीं हो सकती और उसका पिरामिड कभी उलटा नहीं होता; तालाब में तेजी से बढ़ने वाले पादपप्लवकों की कम जैव मात्रा उपभोक्ताओं की अधिक जैव मात्रा का भरण करती है।"},
  {"id":"sci-biology-107","question":"Arrange in chronological order: 1. Rediscovery of Mendel’s laws 2. Publication of Darwin’s ‘On the Origin of Species’ 3. Birth of the first ‘test-tube baby’ 4. Mendel presents his experiments on pea plants","options":["4, 2, 1, 3","2, 1, 4, 3","2, 4, 1, 3","2, 4, 3, 1"],"answer":2,"explanation":"Darwin’s book appeared in 1859, Mendel published in 1865–66, his work was rediscovered by de Vries, Correns and Tschermak in 1900, and Louise Brown, the first IVF baby, was born in 1978.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"कालक्रम के अनुसार व्यवस्थित कीजिए: 1. मेंडल के नियमों की पुनःखोज 2. डार्विन की ‘ऑन द ओरिजिन ऑफ़ स्पीशीज़’ का प्रकाशन 3. प्रथम ‘टेस्ट-ट्यूब बेबी’ का जन्म 4. मेंडल द्वारा मटर के पौधों पर अपने प्रयोग प्रस्तुत करना","optionsHi":["4, 2, 1, 3","2, 1, 4, 3","2, 4, 1, 3","2, 4, 3, 1"],"explanationHi":"डार्विन की पुस्तक 1859 में आई, मेंडल ने 1865–66 में अपना कार्य प्रकाशित किया, उनके कार्य की पुनःखोज 1900 में डी व्रीस, कॉरेन्स और शेरमाक ने की, और पहली IVF शिशु लुईस ब्राउन का जन्म 1978 में हुआ।"},
  {"id":"sci-biology-108","question":"In snapdragon, red-flowered and white-flowered plants show incomplete dominance and give pink-flowered plants in F₁. If 200 F₂ plants are raised from selfing the F₁, how many are expected to have pink flowers?","options":["100","150","200","50"],"answer":0,"explanation":"With incomplete dominance the F₂ ratio is 1 red : 2 pink : 1 white, so half the plants, 100 of 200, are pink (heterozygous). Using the 3 : 1 Mendelian ratio gives the trap 150.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"स्नैपड्रैगन में लाल पुष्प और श्वेत पुष्प वाले पौधे अपूर्ण प्रभाविता दर्शाते हैं और F₁ में गुलाबी पुष्प वाले पौधे देते हैं। यदि F₁ के स्वपरागण से 200 F₂ पौधे उगाए जाएँ, तो कितने के गुलाबी पुष्प वाले होने की आशा है?","optionsHi":["100","150","200","50"],"explanationHi":"अपूर्ण प्रभाविता में F₂ अनुपात 1 लाल : 2 गुलाबी : 1 श्वेत होता है, इसलिए आधे पौधे, अर्थात 200 में से 100, गुलाबी (विषमयुग्मजी) होंगे। मेंडल का 3 : 1 अनुपात लगाने पर 150 का भ्रम होता है।"},
  {"id":"sci-biology-109","question":"Which of the following is NOT secreted by the human stomach?","options":["Mucus","Trypsinogen","Hydrochloric acid","Pepsinogen"],"answer":1,"explanation":"Trypsinogen is secreted by the pancreas and activated to trypsin in the small intestine. The gastric glands secrete pepsinogen, hydrochloric acid, mucus and, in infants, rennin.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"निम्नलिखित में से किसका स्राव मानव आमाशय द्वारा नहीं होता?","optionsHi":["श्लेष्मा (म्यूकस)","ट्रिप्सिनोजन","हाइड्रोक्लोरिक अम्ल","पेप्सिनोजन"],"explanationHi":"ट्रिप्सिनोजन का स्राव अग्न्याशय करता है और छोटी आँत में यह ट्रिप्सिन में सक्रिय होता है। जठर ग्रंथियाँ पेप्सिनोजन, हाइड्रोक्लोरिक अम्ल, श्लेष्मा और शिशुओं में रेनिन का स्राव करती हैं।"},
  {"id":"sci-biology-110","question":"Assertion (A): In many desert plants the leaves are reduced to spines. Reason (R): Reducing the leaf surface cuts down water loss by transpiration.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Smaller leaf area means fewer stomata and less water lost, which is vital where water is scarce; photosynthesis is then often taken over by a green, fleshy stem, as in cactus. So R explains A.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"अभिकथन (A): अनेक मरुस्थलीय पौधों में पत्तियाँ काँटों में बदल जाती हैं। कारण (R): पत्ती की सतह घटने से वाष्पोत्सर्जन द्वारा जल की हानि कम हो जाती है।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है परंतु R गलत है","A गलत है परंतु R सही है"],"explanationHi":"पत्ती का क्षेत्रफल कम होने से रंध्र कम होते हैं और जल की हानि घटती है, जो जल की कमी वाले स्थानों में अत्यंत आवश्यक है; तब प्रकाश संश्लेषण प्रायः हरे, मांसल तने द्वारा किया जाता है, जैसे नागफनी में। अतः R, A की व्याख्या करता है।"},
  {"id":"sci-biology-111","question":"Match the gland with a hormone it secretes: 1. Thymus 2. Pineal gland 3. Adrenal cortex 4. Parathyroid; a. Parathormone b. Cortisol c. Melatonin d. Thymosin","options":["1-b, 2-c, 3-d, 4-a","1-d, 2-c, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-b, 4-a"],"answer":1,"explanation":"The thymus secretes thymosin (T-cell maturation), the pineal gland melatonin (sleep–wake rhythm), the adrenal cortex cortisol (stress, glucose metabolism) and the parathyroids parathormone (raises blood calcium).","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"ग्रंथि का उसके द्वारा स्रावित हॉर्मोन से मिलान कीजिए: 1. थाइमस 2. पीनियल ग्रंथि 3. अधिवृक्क वल्कुट 4. पैराथायरॉइड; a. पैराथॉर्मोन b. कॉर्टिसोल c. मेलाटोनिन d. थाइमोसिन","optionsHi":["1-b, 2-c, 3-d, 4-a","1-d, 2-c, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-b, 4-a"],"explanationHi":"थाइमस थाइमोसिन (T कोशिकाओं का परिपक्वन) का, पीनियल ग्रंथि मेलाटोनिन (नींद–जागरण चक्र) का, अधिवृक्क वल्कुट कॉर्टिसोल (तनाव, ग्लूकोज उपापचय) का और पैराथायरॉइड पैराथॉर्मोन (रक्त कैल्शियम बढ़ाने वाला) का स्राव करते हैं।"},
  {"id":"sci-biology-112","question":"A person breathes 12 times a minute with a tidal volume of 500 mL, of which 150 mL stays in the anatomical dead space (air passages). The volume of fresh air reaching the alveoli each minute is:","options":["6.0 litres","1.8 litres","4.2 litres","7.8 litres"],"answer":2,"explanation":"Air reaching the alveoli per breath = 500 − 150 = 350 mL; per minute = 350 × 12 = 4,200 mL = 4.2 L. The total pulmonary ventilation, 500 × 12 = 6 L, includes the dead-space air that never takes part in gas exchange.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"एक व्यक्ति प्रति मिनट 12 बार साँस लेता है, ज्वारीय आयतन 500 mL है, जिसमें से 150 mL शारीरिक मृत स्थान (वायु मार्ग) में रह जाता है। प्रति मिनट वायुकोष्ठिकाओं तक पहुँचने वाली ताज़ी वायु का आयतन है:","optionsHi":["6.0 लीटर","1.8 लीटर","4.2 लीटर","7.8 लीटर"],"explanationHi":"प्रति श्वास वायुकोष्ठिकाओं तक पहुँचने वाली वायु = 500 − 150 = 350 mL; प्रति मिनट = 350 × 12 = 4,200 mL = 4.2 L। कुल फुफ्फुसीय संवातन, 500 × 12 = 6 L, में मृत स्थान की वह वायु भी शामिल है जो गैस विनिमय में भाग नहीं लेती।"},
  {"id":"sci-biology-113","question":"How many of these statements about immunity are correct? I. Colostrum gives the newborn passive immunity through IgA antibodies. II. Antibodies are proteins. III. HIV mainly destroys B-lymphocytes. IV. An injection of antivenom gives active immunity against snake venom.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only I and II are correct. HIV attacks helper T-lymphocytes (CD4 cells), and antivenom supplies ready-made antibodies, which is passive, short-lived immunity.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"प्रतिरक्षा से संबंधित इनमें से कितने कथन सही हैं? I. खीस (कोलोस्ट्रम) IgA प्रतिरक्षियों द्वारा नवजात को निष्क्रिय प्रतिरक्षा देता है। II. प्रतिरक्षी प्रोटीन होते हैं। III. HIV मुख्यतः B-लिम्फोसाइट को नष्ट करता है। IV. प्रतिविष (एंटीवेनम) का इंजेक्शन साँप के विष के विरुद्ध सक्रिय प्रतिरक्षा देता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I और II सही हैं। HIV सहायक T-लिम्फोसाइट (CD4 कोशिकाओं) पर आक्रमण करता है, और प्रतिविष बने-बनाए प्रतिरक्षी प्रदान करता है, जो निष्क्रिय और अल्पकालिक प्रतिरक्षा है।"},
  {"id":"sci-biology-114","question":"How many of these statements about the human skeletal system are correct? I. The femur is the longest bone in the body. II. The knee is a hinge joint. III. Humans have 12 pairs of ribs. IV. Ligaments join muscles to bones.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: tendons join muscles to bones, while ligaments join bone to bone at joints.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"मानव कंकाल तंत्र से संबंधित इनमें से कितने कथन सही हैं? I. फीमर शरीर की सबसे लंबी अस्थि है। II. घुटना एक कब्जा संधि है। III. मनुष्य में पसलियों के 12 जोड़े होते हैं। IV. स्नायुबंध (लिगामेंट) पेशियों को अस्थियों से जोड़ते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। IV गलत है: कंडरा (टेंडन) पेशियों को अस्थियों से जोड़ती है, जबकि स्नायुबंध जोड़ों पर अस्थि को अस्थि से जोड़ते हैं।"},
  {"id":"sci-biology-115","question":"Which blood components help the blood to clot at a cut?","options":["Red blood cells","Platelets","White blood cells","Plasma proteins only, without any cells"],"answer":1,"explanation":"Platelets gather at the injury and release factors that, with plasma proteins such as fibrinogen, form a clot. Red cells carry oxygen and white cells fight infection.","difficulty":"easy","source":"SSC CHSL · RRB Group D","questionHi":"कटने पर रक्त का थक्का जमाने में कौन-से रक्त घटक सहायता करते हैं?","optionsHi":["लाल रक्त कोशिकाएँ","प्लेटलेट्स","श्वेत रक्त कोशिकाएँ","केवल प्लाज्मा प्रोटीन, बिना किसी कोशिका के"],"explanationHi":"प्लेटलेट्स चोट के स्थान पर एकत्र होकर ऐसे कारक छोड़ती हैं जो फाइब्रिनोजन जैसे प्लाज्मा प्रोटीनों के साथ मिलकर थक्का बनाते हैं। लाल कोशिकाएँ ऑक्सीजन ले जाती हैं और श्वेत कोशिकाएँ संक्रमण से लड़ती हैं।"},
  {"id":"sci-biology-116","question":"The kidneys are part of which organ system of the human body?","options":["Digestive system","Respiratory system","Excretory system","Nervous system"],"answer":2,"explanation":"The kidneys filter blood and remove urea and excess salts as urine, together with the ureters, bladder and urethra.","difficulty":"easy","source":"SSC CHSL · RRB Group D","questionHi":"वृक्क (गुर्दे) मानव शरीर के किस तंत्र का भाग हैं?","optionsHi":["पाचन तंत्र","श्वसन तंत्र","उत्सर्जन तंत्र","तंत्रिका तंत्र"],"explanationHi":"वृक्क रक्त को छानते हैं और मूत्रवाहिनियों, मूत्राशय तथा मूत्रमार्ग के साथ मिलकर यूरिया और अतिरिक्त लवणों को मूत्र के रूप में बाहर निकालते हैं।"},
  {"id":"sci-biology-117","question":"Which class of nutrients is the body's most readily used source of energy and normally supplies the largest share of daily calories in an Indian diet?","options":["Carbohydrates","Vitamins","Fats and oils","Proteins"],"answer":0,"explanation":"Carbohydrates such as starch and sugars are quickly broken down to glucose and supply over half of daily calories in a typical Indian diet. Fats give more energy per gram but are used more slowly and mainly stored; proteins build tissues, and vitamins regulate processes and give no energy.","difficulty":"easy","source":"SSC CHSL · RRB Group D","questionHi":"पोषक तत्वों का कौन-सा वर्ग शरीर के लिए ऊर्जा का सबसे शीघ्र उपयोग होने वाला स्रोत है और भारतीय आहार में सामान्यतः दैनिक कैलोरी का सबसे बड़ा भाग देता है?","optionsHi":["कार्बोहाइड्रेट","विटामिन","वसा और तेल","प्रोटीन"],"explanationHi":"स्टार्च और शर्करा जैसे कार्बोहाइड्रेट शीघ्र ही ग्लूकोज में टूट जाते हैं और सामान्य भारतीय आहार की आधी से अधिक दैनिक कैलोरी देते हैं। वसा प्रति ग्राम अधिक ऊर्जा देती है, पर उसका उपयोग धीमा होता है और वह मुख्यतः संचित होती है; प्रोटीन ऊतकों का निर्माण करते हैं, और विटामिन क्रियाओं का नियमन करते हैं तथा ऊर्जा नहीं देते।"},
  {"id":"sci-biology-118","question":"The basic structural and functional unit of the nervous system is the:","options":["Nephron","Alveolus","Sarcomere","Neuron"],"answer":3,"explanation":"Neurons carry electrical and chemical signals. The nephron is the unit of the kidney, the alveolus of the lung and the sarcomere of muscle.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"तंत्रिका तंत्र की मूल संरचनात्मक और क्रियात्मक इकाई क्या है?","optionsHi":["नेफ्रॉन","वायुकोष्ठिका","सार्कोमियर","न्यूरॉन"],"explanationHi":"न्यूरॉन विद्युत और रासायनिक संकेत ले जाते हैं। नेफ्रॉन वृक्क की, वायुकोष्ठिका फेफड़े की और सार्कोमियर पेशी की इकाई है।"},
  {"id":"sci-biology-119","question":"In the human eye, the image of an object is formed on the:","options":["Retina","Cornea","Iris","Lens"],"answer":0,"explanation":"The cornea and lens focus light onto the retina, whose rods and cones convert it into nerve signals carried by the optic nerve to the brain.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"मानव नेत्र में किसी वस्तु का प्रतिबिंब कहाँ बनता है?","optionsHi":["दृष्टिपटल (रेटिना)","कॉर्निया","परितारिका (आइरिस)","लेंस"],"explanationHi":"कॉर्निया और लेंस प्रकाश को दृष्टिपटल पर फोकस करते हैं, जिसकी शलाकाएँ और शंकु उसे तंत्रिका संकेतों में बदलते हैं, जो दृक् तंत्रिका द्वारा मस्तिष्क तक पहुँचते हैं।"},
  {"id":"sci-biology-120","question":"Which gland is often called the “master gland” because its hormones control several other endocrine glands?","options":["Thyroid","Pituitary","Adrenal cortex","Pancreas"],"answer":1,"explanation":"The pituitary, at the base of the brain, releases hormones that regulate the thyroid, adrenal cortex and gonads; it is itself controlled by the hypothalamus.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"किस ग्रंथि को प्रायः “मास्टर ग्रंथि” कहा जाता है क्योंकि इसके हॉर्मोन कई अन्य अंतःस्रावी ग्रंथियों को नियंत्रित करते हैं?","optionsHi":["थायरॉइड","पीयूष ग्रंथि","अधिवृक्क वल्कुट","अग्न्याशय"],"explanationHi":"मस्तिष्क के आधार पर स्थित पीयूष ग्रंथि ऐसे हॉर्मोन छोड़ती है जो थायरॉइड, अधिवृक्क वल्कुट और जनन ग्रंथियों का नियमन करते हैं; स्वयं यह हाइपोथैलेमस द्वारा नियंत्रित होती है।"},
  {"id":"sci-biology-121","question":"The largest part of the human brain, responsible for thinking, memory and voluntary actions, is the:","options":["Cerebellum","Medulla oblongata","Cerebrum","Pons"],"answer":2,"explanation":"The cerebrum forms most of the brain. The cerebellum coordinates balance and the medulla controls involuntary actions such as breathing and heartbeat.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"मानव मस्तिष्क का सबसे बड़ा भाग, जो सोचने, स्मृति और ऐच्छिक क्रियाओं के लिए उत्तरदायी है, कौन-सा है?","optionsHi":["अनुमस्तिष्क","मेडुला ऑब्लांगेटा","प्रमस्तिष्क","पोन्स"],"explanationHi":"प्रमस्तिष्क मस्तिष्क का अधिकांश भाग बनाता है। अनुमस्तिष्क संतुलन का समन्वय करता है और मेडुला श्वसन तथा हृदय गति जैसी अनैच्छिक क्रियाओं को नियंत्रित करता है।"},
  {"id":"sci-biology-122","question":"A person with which blood group can, in principle, receive red cells from donors of any ABO group?","options":["Group O","Group A","Group B","Group AB"],"answer":3,"explanation":"Group AB plasma has neither anti-A nor anti-B antibodies, so AB is the universal recipient. Group O, whose red cells carry no A or B antigen, is the universal donor.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"किस रक्त समूह का व्यक्ति सिद्धांततः किसी भी ABO समूह के दाताओं से लाल रक्त कोशिकाएँ प्राप्त कर सकता है?","optionsHi":["समूह O","समूह A","समूह B","समूह AB"],"explanationHi":"समूह AB के प्लाज्मा में न anti-A और न ही anti-B प्रतिरक्षी होते हैं, इसलिए AB सार्वभौमिक ग्राही है। समूह O, जिसकी लाल कोशिकाओं पर A या B प्रतिजन नहीं होता, सार्वभौमिक दाता है।"},
  {"id":"sci-biology-123","question":"Erythroblastosis fetalis, a serious condition of the newborn, can occur when:","options":["An Rh-negative mother, sensitised earlier, carries an Rh-positive foetus","An Rh-positive mother, sensitised earlier, carries an Rh-negative foetus","Both parents are Rh-negative, so the foetus is also Rh-negative","The mother has blood group AB and the foetus has blood group O"],"answer":0,"explanation":"Anti-Rh antibodies made by the mother after a first Rh-positive baby cross the placenta in a later pregnancy and destroy the foetus's red cells. An anti-D injection after delivery prevents sensitisation.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"एरिथ्रोब्लास्टोसिस फीटैलिस, जो नवजात की एक गंभीर स्थिति है, कब हो सकती है?","optionsHi":["जब Rh-ऋणात्मक माता, जो पहले संवेदित हो चुकी है, Rh-धनात्मक भ्रूण को धारण करती है","जब Rh-धनात्मक माता, जो पहले संवेदित हो चुकी है, Rh-ऋणात्मक भ्रूण को धारण करती है","जब दोनों जनक Rh-ऋणात्मक हों, इसलिए भ्रूण भी Rh-ऋणात्मक हो","जब माता का रक्त समूह AB और भ्रूण का रक्त समूह O हो"],"explanationHi":"पहली Rh-धनात्मक संतान के बाद माता द्वारा बनाए गए anti-Rh प्रतिरक्षी बाद की गर्भावस्था में अपरा पार करके भ्रूण की लाल रक्त कोशिकाओं को नष्ट कर देते हैं। प्रसव के बाद anti-D का इंजेक्शन संवेदीकरण को रोकता है।"},
  {"id":"sci-biology-124","question":"During blood clotting, soluble fibrinogen is converted into insoluble fibrin threads by the enzyme:","options":["Pepsin","Thrombin","Thromboplastin","Lipase"],"answer":1,"explanation":"Thromboplastin from injured tissue and platelets helps convert prothrombin into thrombin, and thrombin then turns fibrinogen into a mesh of fibrin that traps blood cells. Thromboplastin acts one step earlier, so it is the tempting wrong choice; vitamin K is needed to make prothrombin.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"रक्त का थक्का बनते समय घुलनशील फाइब्रिनोजन को अघुलनशील फाइब्रिन तंतुओं में कौन-सा एंजाइम बदलता है?","optionsHi":["पेप्सिन","थ्रोम्बिन","थ्रोम्बोप्लास्टिन","लाइपेज"],"explanationHi":"क्षतिग्रस्त ऊतक और प्लेटलेट्स से निकला थ्रोम्बोप्लास्टिन प्रोथ्रोम्बिन को थ्रोम्बिन में बदलने में सहायता करता है, और थ्रोम्बिन फाइब्रिनोजन को फाइब्रिन के जाल में बदल देता है, जो रक्त कोशिकाओं को फँसा लेता है। थ्रोम्बोप्लास्टिन एक चरण पहले कार्य करता है, इसलिए यह भ्रमित करने वाला गलत विकल्प है; प्रोथ्रोम्बिन बनाने के लिए विटामिन K आवश्यक है।"},
  {"id":"sci-biology-125","question":"A nerve impulse passes from one neuron to the next across a synapse mainly by means of:","options":["Direct flow of blood plasma from one neuron into the next","Hormones carried in the bloodstream to the next neuron","Chemical neurotransmitters such as acetylcholine","Mechanical pressure from the swelling of the axon"],"answer":2,"explanation":"At most synapses the arriving impulse releases neurotransmitter molecules that cross the tiny gap and trigger a new impulse in the next cell, which is why signals flow in one direction.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"तंत्रिका आवेग एक न्यूरॉन से अगले न्यूरॉन तक सिनैप्स (अंतर्ग्रथन) के पार मुख्यतः किसके द्वारा पहुँचता है?","optionsHi":["एक न्यूरॉन से अगले में रक्त प्लाज्मा का सीधा प्रवाह","रक्तधारा द्वारा अगले न्यूरॉन तक ले जाए गए हॉर्मोन","एसिटाइलकोलीन जैसे रासायनिक तंत्रिका संचारी","तंत्रिकाक्ष (ऐक्सॉन) के फूलने से उत्पन्न यांत्रिक दाब"],"explanationHi":"अधिकांश सिनैप्स पर आने वाला आवेग तंत्रिका संचारी अणुओं को मुक्त करता है, जो सूक्ष्म अंतराल को पार करके अगली कोशिका में नया आवेग उत्पन्न करते हैं; इसीलिए संकेत एक ही दिशा में प्रवाहित होते हैं।"},
  {"id":"sci-biology-126","question":"In the human ear, sound vibrations are converted into nerve impulses in the:","options":["Ear drum","Ear ossicles","Semicircular canals","Cochlea"],"answer":3,"explanation":"The eardrum and ossicles pass vibrations to the fluid-filled cochlea, whose hair cells generate impulses for the auditory nerve. The semicircular canals deal with balance.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"मानव कर्ण में ध्वनि कंपनों को तंत्रिका आवेगों में कहाँ बदला जाता है?","optionsHi":["कर्णपटह (कान का पर्दा)","कर्ण अस्थिकाएँ","अर्धवृत्ताकार नलिकाएँ","कर्णावर्त (कॉक्लिया)"],"explanationHi":"कर्णपटह और अस्थिकाएँ कंपनों को द्रव से भरे कर्णावर्त तक पहुँचाती हैं, जिसकी रोम कोशिकाएँ श्रवण तंत्रिका के लिए आवेग उत्पन्न करती हैं। अर्धवृत्ताकार नलिकाएँ संतुलन से संबंधित हैं।"},
  {"id":"sci-biology-127","question":"Bacteria become resistant to antibiotics mainly because:","options":["Resistant mutants already present survive the antibiotic and multiply","Exposure to the antibiotic makes each bacterium develop resistance","Antibiotics change bacteria into viruses, which drugs cannot kill","Bacteria learn to recognise the medicine and avoid it after the first dose"],"answer":0,"explanation":"Antibiotics act as a selection pressure: random mutations already give a few bacteria resistance, and these survive and multiply. The idea that exposure itself makes each bacterium resistant is a Lamarckian error; resistance genes can also spread through plasmids.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"जीवाणु प्रतिजैविकों (एंटीबायोटिक) के प्रति मुख्यतः इसलिए प्रतिरोधी बन जाते हैं क्योंकि:","optionsHi":["पहले से मौजूद प्रतिरोधी उत्परिवर्ती प्रतिजैविक से बच जाते हैं और बढ़ते हैं","प्रतिजैविक के संपर्क से प्रत्येक जीवाणु में प्रतिरोध विकसित हो जाता है","प्रतिजैविक जीवाणुओं को विषाणुओं में बदल देते हैं, जिन्हें दवाएँ नहीं मार सकतीं","जीवाणु दवा को पहचानना सीख लेते हैं और पहली खुराक के बाद उससे बचने लगते हैं"],"explanationHi":"प्रतिजैविक चयन दाब की तरह कार्य करते हैं: यादृच्छिक उत्परिवर्तन कुछ जीवाणुओं को पहले से प्रतिरोध दे देते हैं, और वे जीवित रहकर बढ़ते हैं। यह धारणा कि संपर्क स्वयं प्रत्येक जीवाणु को प्रतिरोधी बना देता है, लैमार्कवादी भूल है; प्रतिरोध जीन प्लाज्मिडों द्वारा भी फैल सकते हैं।"},
  {"id":"sci-biology-128","question":"mRNA vaccines give protection by:","options":["Injecting live but weakened viruses that multiply slowly in the body","Instructing cells to make a viral protein that trains the immune system","Permanently inserting the viral gene into the DNA of the person's cells","Supplying ready-made antibodies that neutralise the virus on contact"],"answer":1,"explanation":"The mRNA is read in the cytoplasm and soon broken down; it does not enter the nucleus or alter DNA. Ready-made antibodies give passive, short-lived immunity instead.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"mRNA टीके सुरक्षा कैसे प्रदान करते हैं?","optionsHi":["जीवित परंतु दुर्बल विषाणुओं को इंजेक्ट करके, जो शरीर में धीरे-धीरे बढ़ते हैं","कोशिकाओं को विषाणु का प्रोटीन बनाने का निर्देश देकर, जो प्रतिरक्षा तंत्र को प्रशिक्षित करता है","विषाणु के जीन को व्यक्ति की कोशिकाओं के DNA में स्थायी रूप से जोड़कर","बने-बनाए प्रतिरक्षी देकर, जो संपर्क होते ही विषाणु को निष्क्रिय कर देते हैं"],"explanationHi":"mRNA को कोशिकाद्रव्य में पढ़ा जाता है और वह शीघ्र ही टूट जाता है; वह केंद्रक में प्रवेश नहीं करता और DNA को नहीं बदलता। बने-बनाए प्रतिरक्षी इसके बजाय निष्क्रिय और अल्पकालिक प्रतिरक्षा देते हैं।"},
  {"id":"sci-biology-129","question":"Which cell organelle is called the “suicide bag” because its enzymes can digest the cell's own parts?","options":["Ribosome","Golgi apparatus","Lysosome","Centrosome"],"answer":2,"explanation":"Lysosomes contain digestive enzymes that break down worn-out organelles and foreign particles; if they burst, they can digest the cell itself.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"किस कोशिकांग को “आत्मघाती थैली” कहा जाता है क्योंकि इसके एंजाइम कोशिका के अपने ही भागों को पचा सकते हैं?","optionsHi":["राइबोसोम","गॉल्जी उपकरण","लयनकाय (लाइसोसोम)","तारककाय (सेंट्रोसोम)"],"explanationHi":"लयनकायों में पाचक एंजाइम होते हैं जो घिसे हुए कोशिकांगों और बाहरी कणों को तोड़ते हैं; यदि वे फट जाएँ, तो कोशिका को ही पचा सकते हैं।"},
  {"id":"sci-biology-130","question":"Valves that prevent the backflow of blood are found in the:","options":["Arteries","Capillaries","Alveoli","Veins"],"answer":3,"explanation":"Blood in veins is under low pressure, especially in the legs, so valves stop it flowing backwards. Arteries carry blood at high pressure and do not need such valves (apart from those at the heart's exits).","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"रक्त के वापस बहने को रोकने वाले कपाट (वाल्व) कहाँ पाए जाते हैं?","optionsHi":["धमनियाँ","केशिकाएँ","वायुकोष्ठिकाएँ","शिराएँ"],"explanationHi":"शिराओं में रक्त निम्न दाब पर होता है, विशेषकर पैरों में, इसलिए कपाट उसे पीछे की ओर बहने से रोकते हैं। धमनियाँ रक्त को उच्च दाब पर ले जाती हैं और उन्हें ऐसे कपाटों की आवश्यकता नहीं होती (हृदय के निकासों पर लगे कपाटों को छोड़कर)।"},
  {"id":"sci-biology-131","question":"How many of these statements about hormones are correct? I. Thyroxine regulates the body's rate of metabolism. II. Antidiuretic hormone (ADH) reduces the volume of urine. III. Adrenaline raises the heart rate. IV. Excess of growth hormone in childhood causes gigantism.","options":["Only three","Only one","Only two","All four"],"answer":3,"explanation":"All four are correct: thyroxine sets the metabolic rate, ADH increases water reabsorption and so reduces urine volume, adrenaline raises the heart rate, and too much growth hormone in childhood causes gigantism (too little causes dwarfism).","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"हॉर्मोनों से संबंधित इनमें से कितने कथन सही हैं? I. थायरॉक्सिन शरीर की उपापचय दर का नियमन करता है। II. प्रतिमूत्रल हॉर्मोन (ADH) मूत्र की मात्रा घटाता है। III. एड्रीनलीन हृदय गति बढ़ाता है। IV. बचपन में वृद्धि हॉर्मोन की अधिकता से महाकायता होती है।","optionsHi":["केवल तीन","केवल एक","केवल दो","सभी चार"],"explanationHi":"चारों सही हैं: थायरॉक्सिन उपापचय दर निर्धारित करता है, ADH जल के पुनरावशोषण को बढ़ाकर मूत्र की मात्रा घटाता है, एड्रीनलीन हृदय गति बढ़ाता है, और बचपन में वृद्धि हॉर्मोन की अधिकता से महाकायता होती है (कमी से बौनापन)।"},
  {"id":"sci-biology-132","question":"Match the disease with the organ it mainly affects. A. Hepatitis  B. Pneumonia  C. Glaucoma  D. Arthritis; 1. Joints  2. Eye  3. Lungs  4. Liver","options":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1"],"answer":3,"explanation":"Hepatitis is inflammation of the liver; pneumonia infects the air sacs of the lungs; glaucoma damages the optic nerve, often through raised pressure in the eye; arthritis inflames the joints.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"रोग का उस अंग से मिलान कीजिए जिसे वह मुख्यतः प्रभावित करता है। A. हेपेटाइटिस B. निमोनिया C. ग्लूकोमा D. गठिया (आर्थ्राइटिस); 1. जोड़ 2. आँख 3. फेफड़े 4. यकृत","optionsHi":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1"],"explanationHi":"हेपेटाइटिस यकृत की सूजन है; निमोनिया फेफड़ों की वायुकोष्ठिकाओं का संक्रमण है; ग्लूकोमा दृक् तंत्रिका को क्षति पहुँचाता है, प्रायः आँख के बढ़े हुए दाब के कारण; गठिया जोड़ों में सूजन करता है।"},
  {"id":"sci-biology-133","question":"Assertion (A): People of blood group O are called universal donors. Reason (R): Their red blood cells carry neither A nor B antigens.","options":["Both A and R are true but R is not the correct explanation of A","A is true but R is false","Both A and R are true and R is the correct explanation of A","A is false but R is true"],"answer":2,"explanation":"With no A or B antigens on the donated cells, the recipient's anti-A or anti-B antibodies have nothing to attack, so O red cells can be given across ABO groups (Rh must still match).","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"अभिकथन (A): रक्त समूह O वाले व्यक्तियों को सार्वभौमिक दाता कहा जाता है। कारण (R): उनकी लाल रक्त कोशिकाओं पर न तो A और न ही B प्रतिजन होता है।","optionsHi":["A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है परंतु R गलत है","A और R दोनों सही हैं और R, A की सही व्याख्या है","A गलत है परंतु R सही है"],"explanationHi":"दान की गई कोशिकाओं पर A या B प्रतिजन न होने से ग्राही के anti-A या anti-B प्रतिरक्षियों के पास आक्रमण करने को कुछ नहीं होता, इसलिए O लाल कोशिकाएँ ABO समूहों में दी जा सकती हैं (Rh का मेल फिर भी आवश्यक है)।"},
  {"id":"sci-biology-134","question":"How many of these statements about digestion are correct? I. Pepsin works best in the acidic medium of the stomach. II. Trypsin works in the alkaline medium of the small intestine. III. Bile, which emulsifies fats, is produced by the gall bladder. IV. Salivary amylase begins the digestion of proteins in the mouth.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct. III is wrong: bile is produced by the liver and only stored in the gall bladder. IV is wrong: salivary amylase acts on starch; protein digestion begins in the stomach with pepsin.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"पाचन से संबंधित इनमें से कितने कथन सही हैं? I. पेप्सिन आमाशय के अम्लीय माध्यम में सबसे अच्छा कार्य करता है। II. ट्रिप्सिन छोटी आँत के क्षारीय माध्यम में कार्य करता है। III. पित्त, जो वसा का इमल्सीकरण करता है, पित्ताशय द्वारा बनाया जाता है। IV. लार का एमाइलेज मुँह में प्रोटीन का पाचन शुरू करता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और II सही हैं। III गलत है: पित्त यकृत द्वारा बनता है और पित्ताशय में केवल संचित होता है। IV गलत है: लार का एमाइलेज स्टार्च पर क्रिया करता है; प्रोटीन का पाचन आमाशय में पेप्सिन से शुरू होता है।"},
  {"id":"sci-biology-135","question":"Arrange in the order in which light passes through the human eye: 1. Lens  2. Cornea  3. Retina  4. Vitreous humour","options":["2-1-4-3","1-2-4-3","2-4-1-3","2-1-3-4"],"answer":0,"explanation":"Light enters through the cornea, crosses the aqueous humour and pupil, is focused by the lens, passes through the jelly-like vitreous humour and falls on the retina.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"मानव नेत्र में प्रकाश जिस क्रम में इनसे गुजरता है, उसके अनुसार व्यवस्थित कीजिए: 1. लेंस 2. कॉर्निया 3. दृष्टिपटल (रेटिना) 4. काचाभ द्रव","optionsHi":["2-1-4-3","1-2-4-3","2-4-1-3","2-1-3-4"],"explanationHi":"प्रकाश कॉर्निया से प्रवेश करता है, नेत्रोद और पुतली से गुजरता है, लेंस द्वारा फोकस होता है, जेली जैसे काचाभ द्रव से होकर दृष्टिपटल पर पड़ता है।"},
  {"id":"sci-biology-136","question":"Arrange in the order in which inhaled air passes through them: 1. Trachea  2. Alveoli  3. Larynx  4. Bronchioles","options":["1-3-4-2","3-1-4-2","3-4-1-2","3-1-2-4"],"answer":1,"explanation":"Air goes from the nose and pharynx into the larynx (voice box), down the trachea, into the bronchi and finer bronchioles, and finally into the alveoli, where gas exchange takes place.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"अंदर ली गई वायु जिस क्रम में इनसे गुजरती है, उसके अनुसार व्यवस्थित कीजिए: 1. श्वास नली (ट्रेकिया) 2. वायुकोष्ठिकाएँ 3. स्वर यंत्र (लैरिंक्स) 4. श्वसनिकाएँ (ब्रोंकिओल)","optionsHi":["1-3-4-2","3-1-4-2","3-4-1-2","3-1-2-4"],"explanationHi":"वायु नाक और ग्रसनी से स्वर यंत्र (वॉइस बॉक्स) में, फिर श्वास नली से नीचे, श्वसनियों और उनसे महीन श्वसनिकाओं में जाती है, और अंत में वायुकोष्ठिकाओं में पहुँचती है, जहाँ गैसों का विनिमय होता है।"},
  {"id":"sci-biology-137","question":"Match the term with its description. A. Antigen  B. Antibody  C. Vaccine  D. Antiserum; 1. Ready-made antibodies giving immediate, passive immunity, such as anti-snake venom  2. A foreign substance that triggers an immune response  3. A protein made by plasma cells that binds a specific antigen  4. A killed or weakened pathogen, or part of it, that induces active immunity","options":["A-2, B-3, C-1, D-4","A-3, B-2, C-4, D-1","A-2, B-4, C-3, D-1","A-2, B-3, C-4, D-1"],"answer":3,"explanation":"Antigens provoke the response and antibodies neutralise them. A vaccine trains the body's own immunity, which lasts; an antiserum lends antibodies for quick but short protection.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"पद का उसके वर्णन से मिलान कीजिए। A. प्रतिजन (एंटीजन) B. प्रतिरक्षी (एंटीबॉडी) C. टीका D. प्रतिसीरम; 1. बने-बनाए प्रतिरक्षी जो तत्काल निष्क्रिय प्रतिरक्षा देते हैं, जैसे साँप के विष का प्रतिविष 2. कोई बाहरी पदार्थ जो प्रतिरक्षा प्रतिक्रिया को प्रेरित करता है 3. प्लाज्मा कोशिकाओं द्वारा बनाया गया प्रोटीन जो किसी विशिष्ट प्रतिजन से जुड़ता है 4. मारा हुआ या दुर्बल रोगाणु, या उसका कोई भाग, जो सक्रिय प्रतिरक्षा उत्पन्न करता है","optionsHi":["A-2, B-3, C-1, D-4","A-3, B-2, C-4, D-1","A-2, B-4, C-3, D-1","A-2, B-3, C-4, D-1"],"explanationHi":"प्रतिजन प्रतिक्रिया को उत्तेजित करते हैं और प्रतिरक्षी उन्हें निष्क्रिय करते हैं। टीका शरीर की अपनी प्रतिरक्षा को प्रशिक्षित करता है, जो लंबे समय तक रहती है; प्रतिसीरम तुरंत परंतु अल्पकालिक सुरक्षा के लिए प्रतिरक्षी उधार देता है।"},
  {"id":"sci-biology-138","question":"Assertion (A): People living at high altitudes tend to have more red blood cells than people in the plains. Reason (R): Low oxygen levels stimulate the kidneys to release more erythropoietin, which boosts red cell production.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Erythropoietin from the kidneys signals the bone marrow to make more red cells, raising the blood's capacity to carry the scarcer oxygen; this is part of acclimatisation.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"अभिकथन (A): ऊँचाई पर रहने वाले लोगों में मैदानी इलाकों के लोगों की तुलना में लाल रक्त कोशिकाएँ अधिक होती हैं। कारण (R): ऑक्सीजन का निम्न स्तर वृक्कों को अधिक एरिथ्रोपॉइटिन छोड़ने के लिए प्रेरित करता है, जो लाल कोशिकाओं का निर्माण बढ़ाता है।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है परंतु R गलत है","A गलत है परंतु R सही है"],"explanationHi":"वृक्कों से निकला एरिथ्रोपॉइटिन अस्थि मज्जा को अधिक लाल कोशिकाएँ बनाने का संकेत देता है, जिससे दुर्लभ ऑक्सीजन ले जाने की रक्त की क्षमता बढ़ती है; यह अनुकूलन का भाग है।"},
  {"id":"sci-biology-139","question":"How many of these statements about vitamins are correct? I. Vitamins A, B, D and E are fat-soluble. II. Vitamin B12 contains iron. III. Excess intake of fat-soluble vitamins can build up to toxic levels. IV. Vitamin C is fat-soluble and can be stored in the liver for years.","options":["Only one","Only two","All four","Only three"],"answer":0,"explanation":"Only III is correct. I is wrong: the fat-soluble vitamins are A, D, E and K; the B vitamins are water-soluble. II is wrong: vitamin B12 contains cobalt, not iron. IV is wrong: vitamin C is water-soluble and excess is lost in urine.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"विटामिनों से संबंधित इनमें से कितने कथन सही हैं? I. विटामिन A, B, D और E वसा में घुलनशील हैं। II. विटामिन B12 में लोहा होता है। III. वसा में घुलनशील विटामिनों का अधिक सेवन जमा होकर विषैले स्तर तक पहुँच सकता है। IV. विटामिन C वसा में घुलनशील है और यकृत में वर्षों तक संचित रह सकता है।","optionsHi":["केवल एक","केवल दो","सभी चार","केवल तीन"],"explanationHi":"केवल III सही है। I गलत है: वसा में घुलनशील विटामिन A, D, E और K हैं; B विटामिन जल में घुलनशील हैं। II गलत है: विटामिन B12 में कोबाल्ट होता है, लोहा नहीं। IV गलत है: विटामिन C जल में घुलनशील है और अधिकता मूत्र में निकल जाती है।"},
  {"id":"sci-biology-140","question":"A dry raisin placed in plain water swells up, while a fresh grape placed in thick sugar syrup shrinks. Which single idea explains both observations?","options":["Osmosis: water crosses the membrane from the dilute side to the concentrated side","Sugar diffuses into the raisin and out of the grape, carrying water with it","Osmosis: water crosses the membrane from the concentrated side to the dilute side","Active transport: membrane pumps move water in or out using energy from ATP"],"answer":0,"explanation":"Osmosis moves water from the dilute side to the concentrated side through a selectively permeable membrane: the raisin's cytoplasm is more concentrated than water, the syrup is more concentrated than the grape's cytoplasm.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"सादे पानी में रखी सूखी किशमिश फूल जाती है, जबकि गाढ़ी चीनी की चाशनी में रखा ताज़ा अंगूर सिकुड़ जाता है। कौन-सा एक विचार दोनों प्रेक्षणों की व्याख्या करता है?","optionsHi":["परासरण: जल झिल्ली के पार तनु पक्ष से सांद्र पक्ष की ओर जाता है","चीनी किशमिश के भीतर और अंगूर के बाहर विसरित होती है और अपने साथ जल को ले जाती है","परासरण: जल झिल्ली के पार सांद्र पक्ष से तनु पक्ष की ओर जाता है","सक्रिय परिवहन: झिल्ली के पंप ATP की ऊर्जा से जल को भीतर या बाहर ले जाते हैं"],"explanationHi":"परासरण में जल वरणात्मक पारगम्य झिल्ली के पार तनु पक्ष से सांद्र पक्ष की ओर जाता है: किशमिश का कोशिकाद्रव्य जल से अधिक सांद्र है, और चाशनी अंगूर के कोशिकाद्रव्य से अधिक सांद्र है।"},
  {"id":"sci-biology-141","question":"A red blood cell placed in distilled water swells and bursts, but an onion peel cell placed in distilled water only becomes stiff (turgid). The structure mainly responsible for this difference is the:","options":["Large central vacuole of the plant cell","Rigid cell wall of the plant cell","Selectively permeable cell membrane of the plant cell","Plastids present in the plant cell"],"answer":1,"explanation":"Both cells take in water by osmosis; the plant cell's rigid cellulose wall resists the expansion of the swelling vacuole, so it becomes turgid instead of bursting. The vacuole is what swells, not what resists.","difficulty":"hard","source":"SSC CGL · RRB Group D","questionHi":"आसुत जल में रखी लाल रक्त कोशिका फूलकर फट जाती है, परंतु आसुत जल में रखी प्याज के छिलके की कोशिका केवल कड़ी (स्फीत) हो जाती है। इस अंतर के लिए मुख्यतः कौन-सी संरचना उत्तरदायी है?","optionsHi":["पादप कोशिका की बड़ी केंद्रीय रिक्तिका","पादप कोशिका की कठोर कोशिका भित्ति","पादप कोशिका की वरणात्मक पारगम्य कोशिका झिल्ली","पादप कोशिका में उपस्थित लवक"],"explanationHi":"दोनों कोशिकाएँ परासरण से जल लेती हैं; पादप कोशिका की कठोर सेलुलोज भित्ति फूलती हुई रिक्तिका के प्रसार का प्रतिरोध करती है, इसलिए वह फटने के बजाय स्फीत हो जाती है। रिक्तिका वह है जो फूलती है, प्रतिरोध करने वाली नहीं।"},
  {"id":"sci-biology-142","question":"Which pair of cell organelles contain their own DNA and ribosomes, and can therefore make some of their own proteins?","options":["Golgi apparatus and endoplasmic reticulum","Lysosomes and vacuoles","Mitochondria and plastids","Nucleolus and centrioles"],"answer":2,"explanation":"Mitochondria and plastids (such as chloroplasts) have their own DNA and ribosomes; the other organelles depend entirely on the nucleus for their proteins.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"कोशिकांगों का कौन-सा युग्म अपना DNA और राइबोसोम रखता है, और इसलिए अपने कुछ प्रोटीन स्वयं बना सकता है?","optionsHi":["गॉल्जी उपकरण और अंतःप्रद्रव्यी जालिका","लयनकाय और रिक्तिकाएँ","माइटोकॉन्ड्रिया और लवक","केंद्रिका और तारककेंद्र (सेंट्रीओल)"],"explanationHi":"माइटोकॉन्ड्रिया और लवकों (जैसे हरित लवक) में अपना DNA और राइबोसोम होते हैं; अन्य कोशिकांग अपने प्रोटीन के लिए पूरी तरह केंद्रक पर निर्भर होते हैं।"},
  {"id":"sci-biology-143","question":"In liver cells, the organelle that plays a key role in detoxifying many poisons and drugs, and in making lipids, is the:","options":["Lysosome","Golgi apparatus (Golgi complex)","Rough endoplasmic reticulum","Smooth endoplasmic reticulum"],"answer":3,"explanation":"The smooth ER makes lipids and, in liver cells, helps detoxify poisons and drugs. Lysosomes digest worn-out cell parts and foreign material; the rough ER makes proteins.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"यकृत कोशिकाओं में अनेक विषों और औषधियों के विषहरण तथा लिपिड बनाने में प्रमुख भूमिका निभाने वाला कोशिकांग कौन-सा है?","optionsHi":["लयनकाय (लाइसोसोम)","गॉल्जी उपकरण (गॉल्जी संकुल)","खुरदरी अंतःप्रद्रव्यी जालिका","चिकनी अंतःप्रद्रव्यी जालिका"],"explanationHi":"चिकनी अंतःप्रद्रव्यी जालिका लिपिड बनाती है और यकृत कोशिकाओं में विषों तथा औषधियों के विषहरण में सहायता करती है। लयनकाय घिसे हुए कोशिका भागों और बाहरी पदार्थ को पचाते हैं; खुरदरी अंतःप्रद्रव्यी जालिका प्रोटीन बनाती है।"},
  {"id":"sci-biology-144","question":"The stalks of leaves and the stems of climbers bend easily without breaking. The plant tissue that gives them this flexibility, with cells thickened mainly at the corners, is:","options":["Sclerenchyma","Parenchyma","Collenchyma","Xylem"],"answer":2,"explanation":"Collenchyma cells are living, elongated and irregularly thickened at the corners, giving mechanical support with flexibility. Sclerenchyma is rigid and lignified, so it gives strength but not flexibility.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"पत्तियों के डंठल और आरोही पौधों के तने बिना टूटे आसानी से मुड़ जाते हैं। वह पादप ऊतक, जिसकी कोशिकाएँ मुख्यतः कोनों पर मोटी होती हैं और जो उन्हें यह लचीलापन देता है, कौन-सा है?","optionsHi":["स्क्लेरेंकाइमा (दृढ़ोतक)","पैरेंकाइमा (मृदूतक)","कॉलेंकाइमा (स्थूलकोण ऊतक)","जाइलम"],"explanationHi":"कॉलेंकाइमा की कोशिकाएँ जीवित, लंबी और कोनों पर अनियमित रूप से मोटी होती हैं, जो लचीलेपन के साथ यांत्रिक सहारा देती हैं। स्क्लेरेंकाइमा कठोर और लिग्निनयुक्त होता है, इसलिए वह मजबूती देता है, लचीलापन नहीं।"},
  {"id":"sci-biology-145","question":"The tough fibrous husk of a coconut is made up mainly of:","options":["Sclerenchyma, whose cells are dead with thick lignified walls","Collenchyma, whose cells are living and thickened at the corners","Parenchyma, whose cells are living with thin walls","Chlorenchyma, whose cells contain chloroplasts"],"answer":0,"explanation":"Coconut husk fibres are sclerenchyma: dead cells with walls thickened by lignin, which makes the tissue hard and stiff.","difficulty":"moderate","source":"RRB Group D · SSC MTS","questionHi":"नारियल का कठोर रेशेदार छिलका मुख्यतः किससे बना होता है?","optionsHi":["स्क्लेरेंकाइमा, जिसकी कोशिकाएँ मृत होती हैं और जिनकी भित्तियाँ लिग्निन से मोटी होती हैं","कॉलेंकाइमा, जिसकी कोशिकाएँ जीवित होती हैं और कोनों पर मोटी होती हैं","पैरेंकाइमा, जिसकी कोशिकाएँ जीवित और पतली भित्ति वाली होती हैं","क्लोरेंकाइमा, जिसकी कोशिकाओं में हरित लवक होते हैं"],"explanationHi":"नारियल के छिलके के रेशे स्क्लेरेंकाइमा हैं: मृत कोशिकाएँ जिनकी भित्तियाँ लिग्निन से मोटी हो जाती हैं, जो ऊतक को कठोर और सख्त बनाती है।"},
  {"id":"sci-biology-146","question":"An athlete ruptures the strong cord that attaches the calf muscle to the heel bone. The tissue that is torn is a:","options":["Ligament","Cartilage","Areolar connective tissue","Tendon"],"answer":3,"explanation":"Tendons join muscles to bones (the calf muscle to the heel bone is the Achilles tendon). Ligaments join bone to bone, and cartilage cushions joints.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"एक खिलाड़ी की पिंडली की पेशी को एड़ी की अस्थि से जोड़ने वाली मजबूत रज्जु फट जाती है। जो ऊतक फटा है, वह है:","optionsHi":["स्नायुबंध (लिगामेंट)","उपास्थि","एरिओलर संयोजी ऊतक","कंडरा (टेंडन)"],"explanationHi":"कंडराएँ पेशियों को अस्थियों से जोड़ती हैं (पिंडली की पेशी को एड़ी की अस्थि से जोड़ने वाली एकिलीज़ कंडरा है)। स्नायुबंध अस्थि को अस्थि से जोड़ते हैं, और उपास्थि जोड़ों पर गद्दी का काम करती है।"},
  {"id":"sci-biology-147","question":"Which type of muscle is striated (shows light and dark bands) yet works involuntarily and rhythmically throughout life without tiring?","options":["Skeletal muscle of the limbs","Cardiac muscle","Smooth muscle of the intestine","Muscles of the tongue"],"answer":1,"explanation":"Cardiac muscle is striated like skeletal muscle but involuntary like smooth muscle. Limb and tongue muscles are striated but voluntary; gut muscle is involuntary but unstriated.","difficulty":"moderate","source":"RRB Group D · SSC CHSL","questionHi":"किस प्रकार की पेशी रेखित (हल्की और गहरी पट्टियाँ दर्शाने वाली) होती है, फिर भी जीवन भर बिना थके अनैच्छिक और लयबद्ध रूप से कार्य करती है?","optionsHi":["हाथ-पैरों की कंकालीय पेशी","हृदय पेशी","आँत की चिकनी पेशी","जीभ की पेशियाँ"],"explanationHi":"हृदय पेशी कंकालीय पेशी की तरह रेखित है, परंतु चिकनी पेशी की तरह अनैच्छिक। हाथ-पैर और जीभ की पेशियाँ रेखित पर ऐच्छिक हैं; आँत की पेशी अनैच्छिक पर अरेखित है।"},
  {"id":"sci-biology-148","question":"A potted plant with variegated leaves (green and white patches) is kept in sunlight for a day. One leaf is then boiled in alcohol and tested with iodine solution. What will be seen?","options":["The whole leaf turns blue-black because starch moves throughout the leaf","Only the white parts turn blue-black because they store the starch made by the green parts","No part turns blue-black because boiling in alcohol destroys starch","Only the parts that were green turn blue-black"],"answer":3,"explanation":"Starch forms only where chlorophyll was present, so only the formerly green areas give the blue-black iodine test; this shows chlorophyll is needed for photosynthesis. Alcohol removes chlorophyll, not starch.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"चितकबरी पत्तियों (हरे और सफेद धब्बों वाली) वाले एक गमले के पौधे को एक दिन धूप में रखा जाता है। फिर एक पत्ती को ऐल्कोहॉल में उबालकर आयोडीन विलयन से परीक्षण किया जाता है। क्या दिखाई देगा?","optionsHi":["पूरी पत्ती नीली-काली हो जाएगी क्योंकि स्टार्च पूरी पत्ती में फैल जाता है","केवल सफेद भाग नीले-काले होंगे क्योंकि वे हरे भागों में बने स्टार्च को संचित करते हैं","कोई भाग नीला-काला नहीं होगा क्योंकि ऐल्कोहॉल में उबालने से स्टार्च नष्ट हो जाता है","केवल वे भाग नीले-काले होंगे जो हरे थे"],"explanationHi":"स्टार्च केवल वहीं बनता है जहाँ पर्णहरित था, इसलिए केवल पहले हरे रहे भाग ही आयोडीन परीक्षण में नीला-काला रंग देते हैं; इससे सिद्ध होता है कि प्रकाश संश्लेषण के लिए पर्णहरित आवश्यक है। ऐल्कोहॉल पर्णहरित को हटाता है, स्टार्च को नहीं।"},
  {"id":"sci-biology-149","question":"Before an experiment to show that carbon dioxide is needed for photosynthesis, the potted plant is kept in complete darkness for about two days. The purpose of this step is to:","options":["Use up the starch already present in the leaves","Stop the plant from respiring during the experiment","Make the leaves produce more chlorophyll","Force all the stomata to close so that no gas enters"],"answer":0,"explanation":"Keeping the plant in darkness destarches the leaves, so any starch found later must have been made during the experiment. Respiration continues in the dark; it does not stop.","difficulty":"moderate","source":"RRB Group D · SSC MTS","questionHi":"यह दर्शाने वाले प्रयोग से पहले कि प्रकाश संश्लेषण के लिए कार्बन डाइऑक्साइड आवश्यक है, गमले के पौधे को लगभग दो दिन पूर्ण अंधकार में रखा जाता है। इस चरण का उद्देश्य है:","optionsHi":["पत्तियों में पहले से उपस्थित स्टार्च को समाप्त करना","प्रयोग के दौरान पौधे को श्वसन करने से रोकना","पत्तियों में अधिक पर्णहरित बनवाना","सभी रंध्रों को बंद करवाना ताकि कोई गैस भीतर न जाए"],"explanationHi":"पौधे को अंधकार में रखने से पत्तियाँ स्टार्चमुक्त हो जाती हैं, इसलिए बाद में मिलने वाला कोई भी स्टार्च प्रयोग के दौरान ही बना होगा। अंधकार में श्वसन चलता रहता है; वह रुकता नहीं।"},
  {"id":"sci-biology-150","question":"In a set-up to show that carbon dioxide is essential for photosynthesis, one leaf of a destarched plant is enclosed in a bottle containing potassium hydroxide. After some hours in sunlight this leaf gives a negative starch test, because potassium hydroxide:","options":["Absorbs the oxygen that the leaf needs for respiration","Absorbs carbon dioxide from the air inside the bottle","Destroys the chlorophyll in the enclosed leaf","Absorbs water vapour so the enclosed leaf dries out"],"answer":1,"explanation":"KOH absorbs CO₂, so the enclosed leaf has no carbon dioxide and cannot make starch, while the leaves outside the bottle can.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"यह दर्शाने के प्रयोग में कि प्रकाश संश्लेषण के लिए कार्बन डाइऑक्साइड आवश्यक है, स्टार्चमुक्त किए गए पौधे की एक पत्ती को पोटैशियम हाइड्रॉक्साइड वाली बोतल में बंद किया जाता है। कुछ घंटे धूप में रखने के बाद इस पत्ती का स्टार्च परीक्षण ऋणात्मक आता है, क्योंकि पोटैशियम हाइड्रॉक्साइड:","optionsHi":["उस ऑक्सीजन को सोख लेता है जिसकी पत्ती को श्वसन के लिए आवश्यकता है","बोतल के भीतर की वायु से कार्बन डाइऑक्साइड सोख लेता है","बंद पत्ती के पर्णहरित को नष्ट कर देता है","जलवाष्प सोख लेता है जिससे बंद पत्ती सूख जाती है"],"explanationHi":"KOH CO₂ को सोख लेता है, इसलिए बंद पत्ती को कार्बन डाइऑक्साइड नहीं मिलती और वह स्टार्च नहीं बना पाती, जबकि बोतल के बाहर की पत्तियाँ बना लेती हैं।"},
  {"id":"sci-biology-151","question":"Stomatal pores open when the guard cells:","options":["Lose water and become flaccid, pulling away from each other","Absorb water and swell, bowing apart due to uneven walls","Receive abscisic acid sent up from the roots in dry soil","Are surrounded by air rich in carbon dioxide inside the leaf"],"answer":1,"explanation":"When guard cells absorb water and become turgid, their unevenly thickened walls make them bow outwards, opening the pore. Water loss closes the pore, and abscisic acid causes closure during water stress.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"रंध्र के छिद्र तब खुलते हैं जब द्वार कोशिकाएँ:","optionsHi":["जल खोकर शिथिल हो जाती हैं और एक-दूसरे से दूर खिंच जाती हैं","जल सोखकर फूल जाती हैं और असमान भित्तियों के कारण बाहर की ओर मुड़ जाती हैं","सूखी मृदा में जड़ों से भेजा गया एब्सिसिक अम्ल प्राप्त करती हैं","पत्ती के भीतर कार्बन डाइऑक्साइड से भरपूर वायु से घिरी होती हैं"],"explanationHi":"जब द्वार कोशिकाएँ जल सोखकर स्फीत हो जाती हैं, तो उनकी असमान रूप से मोटी भित्तियाँ उन्हें बाहर की ओर मोड़ देती हैं, जिससे छिद्र खुल जाता है। जल की हानि छिद्र को बंद करती है, और जल-तनाव में एब्सिसिक अम्ल बंद होने का कारण बनता है।"},
  {"id":"sci-biology-152","question":"Water reaches the top leaves of a 40-metre-tall tree mainly because of:","options":["Root pressure pushing water up from the roots all the way to the top","Capillary action in the narrow xylem vessels acting alone","Transpiration pull created as water evaporates from the leaves","Active pumping of water by the living cells of the phloem"],"answer":2,"explanation":"Evaporation from leaves pulls a continuous column of water up the xylem; this transpiration pull is the main force in tall trees. Root pressure and capillarity can raise water only a short height.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"40 मीटर ऊँचे पेड़ की सबसे ऊपरी पत्तियों तक जल मुख्यतः किसके कारण पहुँचता है?","optionsHi":["मूल दाब, जो जल को जड़ों से सीधे शीर्ष तक धकेलता है","संकरी जाइलम वाहिकाओं में केवल केशिकत्व क्रिया","वाष्पोत्सर्जन खिंचाव, जो पत्तियों से जल के वाष्पन से उत्पन्न होता है","फ्लोएम की जीवित कोशिकाओं द्वारा जल का सक्रिय पंपन"],"explanationHi":"पत्तियों से वाष्पन जल के सतत स्तंभ को जाइलम में ऊपर खींचता है; ऊँचे वृक्षों में यह वाष्पोत्सर्जन खिंचाव ही मुख्य बल है। मूल दाब और केशिकत्व जल को केवल थोड़ी ऊँचाई तक ही उठा सकते हैं।"},
  {"id":"sci-biology-153","question":"Which statement correctly contrasts transport in the phloem with transport in the xylem?","options":["Phloem transport uses ATP and can move food upwards or downwards","Phloem transport is purely passive and moves materials only upwards","Phloem carries water and minerals, while xylem carries the food","Phloem transport takes place through dead, hollow, lignified cells"],"answer":0,"explanation":"Translocation in the phloem uses ATP and moves sugars from source to sink in either direction. Xylem transport is largely passive, upward, and through dead cells.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"फ्लोएम में परिवहन की जाइलम में परिवहन से तुलना करने वाला कौन-सा कथन सही है?","optionsHi":["फ्लोएम में परिवहन में ATP का उपयोग होता है और भोजन ऊपर या नीचे, दोनों ओर जा सकता है","फ्लोएम में परिवहन पूर्णतः निष्क्रिय होता है और पदार्थ केवल ऊपर की ओर जाते हैं","फ्लोएम जल और खनिज ले जाता है, जबकि जाइलम भोजन ले जाता है","फ्लोएम में परिवहन मृत, खोखली, लिग्निनयुक्त कोशिकाओं से होता है"],"explanationHi":"फ्लोएम में स्थानांतरण ATP का उपयोग करता है और शर्कराओं को स्रोत से सिंक तक किसी भी दिशा में ले जाता है। जाइलम में परिवहन मुख्यतः निष्क्रिय, ऊर्ध्वमुखी और मृत कोशिकाओं के द्वारा होता है।"},
  {"id":"sci-biology-154","question":"A complete ring of bark (including the phloem) is removed from the trunk of a woody plant. After some weeks, the bark just above the ring swells. The best conclusion is that:","options":["Water moves upwards through the phloem and collects above the cut","The xylem lies in the bark, so the upward water flow has been cut","Leaf-made food moves down the phloem and piles up above the cut","Food moves upwards through the xylem and is stopped just above the cut"],"answer":2,"explanation":"Removing the phloem blocks the downward flow of sugars from the leaves, so food piles up just above the ring. The xylem (wood) is untouched, so the leaves still get water.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"किसी काष्ठीय पौधे के तने से छाल का पूरा छल्ला (फ्लोएम सहित) हटा दिया जाता है। कुछ सप्ताह बाद छल्ले के ठीक ऊपर की छाल फूल जाती है। सबसे उचित निष्कर्ष है कि:","optionsHi":["जल फ्लोएम से ऊपर जाता है और कटे हुए भाग के ऊपर इकट्ठा हो जाता है","जाइलम छाल में स्थित है, इसलिए जल का ऊर्ध्व प्रवाह कट गया है","पत्तियों में बना भोजन फ्लोएम से नीचे जाता है और कटे भाग के ऊपर जमा हो जाता है","भोजन जाइलम से ऊपर जाता है और कटे भाग के ठीक ऊपर रुक जाता है"],"explanationHi":"फ्लोएम हटाने से पत्तियों से शर्कराओं का अधोमुखी प्रवाह रुक जाता है, इसलिए भोजन छल्ले के ठीक ऊपर जमा हो जाता है। जाइलम (काष्ठ) अछूता रहता है, इसलिए पत्तियों को जल मिलता रहता है।"},
  {"id":"sci-biology-155","question":"Dough left with yeast for some hours becomes soft and rises. The main reason is that yeast:","options":["Gives out oxygen through photosynthesis inside the dough","Produces lactic acid that makes the dough sour and light","Breaks down the flour protein into bubbles of ammonia gas","Releases CO₂ while fermenting the sugars in the dough"],"answer":3,"explanation":"Yeast ferments sugar into ethanol and carbon dioxide; the trapped CO₂ bubbles make the dough rise. Yeast cannot photosynthesise, and lactic acid is the product of anaerobic respiration in muscles and some bacteria.","difficulty":"moderate","source":"RRB Group D · SSC MTS","questionHi":"यीस्ट के साथ कुछ घंटे रखा आटा मुलायम होकर फूल जाता है। इसका मुख्य कारण यह है कि यीस्ट:","optionsHi":["आटे के भीतर प्रकाश संश्लेषण द्वारा ऑक्सीजन छोड़ता है","लैक्टिक अम्ल बनाता है जो आटे को खट्टा और हल्का बना देता है","आटे के प्रोटीन को अमोनिया गैस के बुलबुलों में तोड़ देता है","आटे की शर्कराओं का किण्वन करते समय CO₂ मुक्त करता है"],"explanationHi":"यीस्ट शर्करा को एथेनॉल और कार्बन डाइऑक्साइड में किण्वित करता है; फँसे हुए CO₂ के बुलबुले आटे को फुला देते हैं। यीस्ट प्रकाश संश्लेषण नहीं कर सकता, और लैक्टिक अम्ल पेशियों तथा कुछ जीवाणुओं के अवायवीय श्वसन का उत्पाद है।"},
  {"id":"sci-biology-156","question":"Aerobic respiration releases far more energy from one molecule of glucose than anaerobic respiration does, because in aerobic respiration:","options":["Pyruvate is fully oxidised to CO₂ and water in the mitochondria","Glucose is broken down only in the cytoplasm, which is more efficient","Ethanol is formed first and then burnt to release extra heat","Oxygen itself acts as a fuel and supplies energy to the cell"],"answer":0,"explanation":"Both kinds begin by splitting glucose into pyruvate in the cytoplasm; only with oxygen is pyruvate fully oxidised to CO₂ and water in mitochondria, releasing much more energy. Ethanol and lactic acid still hold unreleased energy.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"ग्लूकोज के एक अणु से वायवीय श्वसन अवायवीय श्वसन की तुलना में कहीं अधिक ऊर्जा मुक्त करता है, क्योंकि वायवीय श्वसन में:","optionsHi":["पाइरूवेट का माइटोकॉन्ड्रिया में CO₂ और जल में पूर्ण ऑक्सीकरण होता है","ग्लूकोज का विघटन केवल कोशिकाद्रव्य में होता है, जो अधिक दक्ष है","पहले एथेनॉल बनता है और फिर उसे जलाकर अतिरिक्त ऊष्मा मुक्त की जाती है","ऑक्सीजन स्वयं ईंधन की तरह कार्य करती है और कोशिका को ऊर्जा देती है"],"explanationHi":"दोनों प्रकार कोशिकाद्रव्य में ग्लूकोज को पाइरूवेट में तोड़ने से शुरू होते हैं; केवल ऑक्सीजन की उपस्थिति में ही पाइरूवेट माइटोकॉन्ड्रिया में CO₂ और जल में पूर्णतः ऑक्सीकृत होता है, जिससे कहीं अधिक ऊर्जा निकलती है। एथेनॉल और लैक्टिक अम्ल में अब भी अमुक्त ऊर्जा बची रहती है।"},
  {"id":"sci-biology-157","question":"Fishes have single circulation, while birds and mammals have double circulation. The main advantage of double circulation is that it:","options":["Lets oxygenated and deoxygenated blood mix so all organs get equal oxygen","Keeps oxygen-rich and oxygen-poor blood apart, raising oxygen supply","Reduces the work of the heart, since blood passes through it only once","Lets the lungs receive oxygenated blood directly from the left ventricle"],"answer":1,"explanation":"In double circulation blood passes the heart twice per circuit and oxygen-rich blood is kept apart from oxygen-poor blood; this efficient supply supports the high energy needs of keeping body temperature constant.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"मछलियों में एकल परिसंचरण होता है, जबकि पक्षियों और स्तनधारियों में दोहरा परिसंचरण होता है। दोहरे परिसंचरण का मुख्य लाभ यह है कि वह:","optionsHi":["ऑक्सीजनयुक्त और ऑक्सीजनरहित रक्त को मिलने देता है ताकि सभी अंगों को समान ऑक्सीजन मिले","ऑक्सीजन-समृद्ध और ऑक्सीजन-रहित रक्त को अलग रखता है, जिससे ऑक्सीजन की आपूर्ति बढ़ती है","हृदय का कार्य घटाता है, क्योंकि रक्त उसमें से केवल एक बार गुजरता है","फेफड़ों को बाएँ निलय से सीधे ऑक्सीजनयुक्त रक्त प्राप्त कराता है"],"explanationHi":"दोहरे परिसंचरण में रक्त प्रत्येक चक्र में हृदय से दो बार गुजरता है और ऑक्सीजन-समृद्ध रक्त ऑक्सीजन-रहित रक्त से अलग रहता है; यह दक्ष आपूर्ति शरीर का तापमान स्थिर रखने की उच्च ऊर्जा आवश्यकताओं को पूरा करती है।"},
  {"id":"sci-biology-158","question":"In which of these animals does the heart have three chambers, so that some oxygenated and deoxygenated blood mixes in the single ventricle?","options":["Rohu fish","Crocodile","Frog","Pigeon"],"answer":2,"explanation":"Amphibians such as the frog have two atria and one ventricle. Fishes have two chambers; crocodiles are reptiles with an exceptional four-chambered heart, and birds have four chambers.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"इनमें से किस जंतु के हृदय में तीन कक्ष होते हैं, जिससे एकल निलय में कुछ ऑक्सीजनयुक्त और ऑक्सीजनरहित रक्त मिल जाता है?","optionsHi":["रोहू मछली","मगरमच्छ","मेंढक","कबूतर"],"explanationHi":"मेंढक जैसे उभयचरों में दो अलिंद और एक निलय होता है। मछलियों में दो कक्ष होते हैं; मगरमच्छ सरीसृप हैं जिनमें अपवाद-स्वरूप चार कक्षों वाला हृदय होता है, और पक्षियों में चार कक्ष होते हैं।"},
  {"id":"sci-biology-159","question":"In a blood pressure reading of 120/80 mm Hg, the value 120 represents the pressure:","options":["Inside the veins when the atria contract","In the arteries when the ventricles relax","Inside the right ventricle when it contracts","In the arteries when the ventricles contract"],"answer":3,"explanation":"The upper value is the systolic pressure, recorded in the arteries during ventricular contraction; the lower value (80) is the diastolic pressure during ventricular relaxation.","difficulty":"moderate","source":"RRB NTPC · SSC CHSL","questionHi":"120/80 mm Hg के रक्तचाप माप में मान 120 किस दाब को दर्शाता है?","optionsHi":["अलिंदों के संकुचन के समय शिराओं के भीतर का दाब","निलयों के शिथिलन के समय धमनियों में दाब","दाएँ निलय के संकुचन के समय उसके भीतर का दाब","निलयों के संकुचन के समय धमनियों में दाब"],"explanationHi":"ऊपर वाला मान प्रकुंचन दाब है, जो निलयों के संकुचन के समय धमनियों में मापा जाता है; नीचे वाला मान (80) निलयों के शिथिलन के समय का अनुशिथिलन दाब है।"},
  {"id":"sci-biology-160","question":"Running a charcoal stove in a closed room can kill sleeping people. The main reason is that carbon monoxide:","options":["Binds haemoglobin far more firmly than oxygen, so blood carries less O₂","Destroys red blood cells by bursting them open inside the blood vessels","Turns into carbon dioxide in the blood and makes it dangerously acidic","Blocks the windpipe by irritating and swelling its inner lining"],"answer":0,"explanation":"CO combines with haemoglobin to form a stable carboxyhaemoglobin, about 200 times more readily than oxygen does, so tissues are starved of oxygen even though the red cells are intact.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"बंद कमरे में कोयले की अंगीठी जलाने से सोते हुए लोगों की मृत्यु हो सकती है। इसका मुख्य कारण यह है कि कार्बन मोनोऑक्साइड:","optionsHi":["हीमोग्लोबिन से ऑक्सीजन की अपेक्षा कहीं अधिक मजबूती से जुड़ता है, इसलिए रक्त कम O₂ ले जा पाता है","रक्त वाहिकाओं के भीतर लाल रक्त कोशिकाओं को फोड़कर नष्ट कर देता है","रक्त में कार्बन डाइऑक्साइड में बदलकर उसे खतरनाक रूप से अम्लीय बना देता है","श्वास नली की भीतरी परत में जलन और सूजन पैदा करके उसे अवरुद्ध कर देता है"],"explanationHi":"CO हीमोग्लोबिन से जुड़कर स्थायी कार्बोक्सीहीमोग्लोबिन बनाता है, ऑक्सीजन की तुलना में लगभग 200 गुना अधिक सरलता से, इसलिए लाल कोशिकाओं के साबुत रहने पर भी ऊतकों को ऑक्सीजन नहीं मिल पाती।"},
  {"id":"sci-biology-161","question":"Glucose is present in the filtrate formed in the glomerulus, yet the urine of a healthy person normally contains no glucose. This is because:","options":["Glucose molecules are too large to pass from the glomerulus into the capsule","Glucose is completely reabsorbed into the blood from the kidney tubule","The kidney cells use up all of the filtered glucose for their own energy","Filtered glucose is converted into urea in the tubule"],"answer":1,"explanation":"Glucose does pass into the filtrate, but the tubule reabsorbs all of it in a healthy person. Glucose appears in urine only when blood sugar is so high that reabsorption cannot keep up, as in uncontrolled diabetes.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"केशिका गुच्छ (ग्लोमेरुलस) में बने निस्यंद में ग्लूकोज उपस्थित होता है, फिर भी स्वस्थ व्यक्ति के मूत्र में सामान्यतः ग्लूकोज नहीं होता। इसका कारण यह है कि:","optionsHi":["ग्लूकोज के अणु केशिका गुच्छ से संपुट में जाने के लिए बहुत बड़े होते हैं","वृक्क नलिका से ग्लूकोज का रक्त में पूर्ण पुनरावशोषण हो जाता है","वृक्क कोशिकाएँ छने हुए सारे ग्लूकोज को अपनी ऊर्जा के लिए उपयोग कर लेती हैं","छना हुआ ग्लूकोज नलिका में यूरिया में बदल जाता है"],"explanationHi":"ग्लूकोज निस्यंद में जाता अवश्य है, परंतु स्वस्थ व्यक्ति में नलिका उसका पूरा पुनरावशोषण कर लेती है। ग्लूकोज मूत्र में तभी आता है जब रक्त शर्करा इतनी अधिक हो कि पुनरावशोषण उसके साथ न चल सके, जैसे अनियंत्रित मधुमेह में।"},
  {"id":"sci-biology-162","question":"In haemodialysis (an artificial kidney), nitrogenous wastes leave the patient's blood mainly by:","options":["Diffusion across a semi-permeable membrane into waste-free dialysing fluid","Active reabsorption of urea by special protein pumps in the tubing","Filtration of blood under pressure through a glomerulus-like knot of capillaries","Centrifuging the blood so that urea separates from the cells"],"answer":0,"explanation":"Blood flows through tubing with a semi-permeable lining bathed in dialysing fluid; urea diffuses out down its concentration gradient. There is no reabsorption in the machine, unlike a real nephron.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"हीमोडायलिसिस (कृत्रिम वृक्क) में रोगी के रक्त से नाइट्रोजनी अपशिष्ट मुख्यतः किस प्रकार बाहर निकलते हैं?","optionsHi":["अर्धपारगम्य झिल्ली के पार अपशिष्ट-रहित डायलिसिस द्रव में विसरण द्वारा","नलियों में विशेष प्रोटीन पंपों द्वारा यूरिया के सक्रिय पुनरावशोषण से","केशिका गुच्छ जैसी केशिकाओं की गाँठ में दाब के अंतर्गत रक्त के निस्यंदन से","रक्त को अपकेंद्रित करके जिससे यूरिया कोशिकाओं से अलग हो जाता है"],"explanationHi":"रक्त अर्धपारगम्य परत वाली नलियों से बहता है, जो डायलिसिस द्रव में डूबी रहती हैं; यूरिया अपने सांद्रता प्रवणता के अनुसार बाहर विसरित हो जाता है। वास्तविक नेफ्रॉन के विपरीत, मशीन में पुनरावशोषण नहीं होता।"},
  {"id":"sci-biology-163","question":"You touch a hot iron and pull your hand away before you even feel the pain. This happens because:","options":["The cerebellum detects the heat and directly moves the hand away","Sensory nerves connect directly to the arm muscles with no relay neuron at all","The spinal cord triggers the response; the signal reaches the brain later","The brain sends the command first, and the pain is delayed in the skin"],"answer":2,"explanation":"In a reflex arc, the spinal cord connects the sensory neuron to the motor neuron through a relay neuron and triggers the quick response; the information travels on to the brain, which is why pain is felt a moment later.","difficulty":"hard","source":"SSC CGL · RRB Group D","questionHi":"आप गर्म इस्त्री को छूते हैं और दर्द महसूस करने से पहले ही हाथ हटा लेते हैं। ऐसा इसलिए होता है क्योंकि:","optionsHi":["अनुमस्तिष्क गर्मी का पता लगाता है और सीधे हाथ को हटा देता है","संवेदी तंत्रिकाएँ बिना किसी योजक न्यूरॉन के सीधे बाँह की पेशियों से जुड़ी होती हैं","मेरुरज्जु प्रतिक्रिया को प्रेरित करती है; संकेत बाद में मस्तिष्क तक पहुँचता है","मस्तिष्क पहले आदेश भेजता है और त्वचा में दर्द देर से होता है"],"explanationHi":"प्रतिवर्ती चाप में मेरुरज्जु संवेदी न्यूरॉन को योजक न्यूरॉन के माध्यम से चालक न्यूरॉन से जोड़ती है और शीघ्र प्रतिक्रिया कराती है; सूचना आगे मस्तिष्क तक भी जाती है, इसीलिए दर्द कुछ क्षण बाद महसूस होता है।"},
  {"id":"sci-biology-164","question":"Damage to which part of the human brain is most likely to be immediately fatal, because it controls heartbeat, breathing and blood pressure?","options":["Cerebrum","Medulla oblongata","Cerebellum","Thalamus and hypothalamus"],"answer":1,"explanation":"The medulla in the hindbrain controls involuntary vital actions such as heartbeat, breathing and blood pressure. The cerebellum controls balance and posture, and the hypothalamus regulates temperature, hunger and thirst.","difficulty":"hard","source":"RRB NTPC · SSC CGL","questionHi":"मानव मस्तिष्क के किस भाग को क्षति पहुँचना तुरंत प्राणघातक होने की सबसे अधिक संभावना रखता है, क्योंकि वह हृदय गति, श्वसन और रक्तचाप को नियंत्रित करता है?","optionsHi":["प्रमस्तिष्क","मेडुला ऑब्लांगेटा","अनुमस्तिष्क","थैलेमस और हाइपोथैलेमस"],"explanationHi":"पश्च मस्तिष्क में स्थित मेडुला हृदय गति, श्वसन और रक्तचाप जैसी अनैच्छिक जीवनदायी क्रियाओं को नियंत्रित करता है। अनुमस्तिष्क संतुलन और मुद्रा को नियंत्रित करता है, और हाइपोथैलेमस तापमान, भूख तथा प्यास का नियमन करता है।"},
  {"id":"sci-biology-165","question":"A potted plant placed near a window bends its shoot towards the light. This happens because auxin:","options":["Is destroyed on the shaded side, so the lighted side grows faster","Collects on the lighted side and makes the cells there divide faster","Is made only in the roots and is carried up to the lighted side","Moves to the shaded side and makes the cells there grow longer"],"answer":3,"explanation":"Light causes auxin to collect on the shaded side of the shoot tip; those cells elongate more, so the shoot curves towards the light.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"खिड़की के पास रखे गमले के पौधे का प्ररोह प्रकाश की ओर मुड़ जाता है। ऐसा इसलिए होता है क्योंकि ऑक्सिन:","optionsHi":["छाया वाले पक्ष में नष्ट हो जाता है, इसलिए प्रकाश वाला पक्ष तेजी से बढ़ता है","प्रकाश वाले पक्ष में एकत्र हो जाता है और वहाँ की कोशिकाओं को तेजी से विभाजित कराता है","केवल जड़ों में बनता है और ऊपर प्रकाश वाले पक्ष तक पहुँचाया जाता है","छाया वाले पक्ष की ओर चला जाता है और वहाँ की कोशिकाओं को अधिक लंबा करता है"],"explanationHi":"प्रकाश के कारण ऑक्सिन प्ररोह के छाया वाले पक्ष में एकत्र हो जाता है; वहाँ की कोशिकाएँ अधिक दीर्घित होती हैं, इसलिए प्ररोह प्रकाश की ओर मुड़ जाता है।"},
  {"id":"sci-biology-166","question":"The leaflets of the touch-me-not plant (Mimosa pudica) fold up within seconds when touched. Which statement about this movement is correct?","options":["It is a growth movement caused by uneven distribution of auxin","It is phototropism, since the folding depends on the light","It is a non-growth movement due to rapid loss of water from cells","It is caused by nerve impulses travelling through the plant's tissues"],"answer":2,"explanation":"The folding is too fast to be growth; specialised cells rapidly lose water and change shape. Plants have no nerves, though electrical-chemical signals pass from cell to cell.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"छुईमुई (मिमोसा प्यूडिका) की पत्तियाँ छूने पर कुछ ही सेकंड में मुड़ जाती हैं। इस गति के बारे में कौन-सा कथन सही है?","optionsHi":["यह ऑक्सिन के असमान वितरण से होने वाली वृद्धि-गति है","यह प्रकाशानुवर्तन है, क्योंकि मुड़ना प्रकाश पर निर्भर है","यह कोशिकाओं से जल के तेजी से निकल जाने के कारण होने वाली अवृद्धि-गति है","यह पौधे के ऊतकों में चलने वाले तंत्रिका आवेगों के कारण होता है"],"explanationHi":"मुड़ना वृद्धि होने के लिए बहुत तेज है; विशिष्ट कोशिकाएँ तेजी से जल खोकर अपना आकार बदल लेती हैं। पौधों में तंत्रिकाएँ नहीं होतीं, यद्यपि विद्युत-रासायनिक संकेत कोशिका से कोशिका तक जाते हैं।"},
  {"id":"sci-biology-167","question":"The tendril of a pea plant coils around a support it touches because:","options":["The side away from the support grows faster than the side in contact","The side in contact with the support grows faster than the side away from it","Auxin is destroyed on the side away from the support","The tendril loses water and shrinks on the side touching the support"],"answer":0,"explanation":"In this response to touch, the part of the tendril in contact with the support grows less rapidly than the part away from it, so the tendril curls around the support.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"मटर के पौधे का प्रतान (टेंड्रिल) छूने वाले आधार के चारों ओर इसलिए लिपट जाता है क्योंकि:","optionsHi":["आधार से दूर वाला पक्ष संपर्क वाले पक्ष की तुलना में तेजी से बढ़ता है","आधार के संपर्क वाला पक्ष उससे दूर वाले पक्ष की तुलना में तेजी से बढ़ता है","आधार से दूर वाले पक्ष में ऑक्सिन नष्ट हो जाता है","प्रतान जल खोकर आधार को छूने वाले पक्ष की ओर सिकुड़ जाता है"],"explanationHi":"स्पर्श की इस प्रतिक्रिया में प्रतान का आधार के संपर्क वाला भाग, दूर वाले भाग की तुलना में धीरे बढ़ता है, इसलिए प्रतान आधार के चारों ओर कुंडली बना लेता है।"},
  {"id":"sci-biology-168","question":"A child shows stunted growth, delayed mental development and a puffy face because of a hormone deficiency that started in infancy. The most likely cause is a deficiency of:","options":["Growth hormone, causing pituitary dwarfism","Thyroxine, causing cretinism","Insulin, causing diabetes","Adrenaline, causing low blood pressure"],"answer":1,"explanation":"Lack of thyroxine from infancy causes cretinism, with both stunted body growth and impaired mental development. Growth hormone deficiency causes dwarfism but with normal intelligence.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"एक बच्चे में शैशवावस्था से शुरू हुई हॉर्मोन की कमी के कारण अवरुद्ध वृद्धि, विलंबित मानसिक विकास और सूजा हुआ चेहरा दिखाई देता है। इसका सबसे संभावित कारण किसकी कमी है?","optionsHi":["वृद्धि हॉर्मोन, जिससे पीयूष बौनापन होता है","थायरॉक्सिन, जिससे जड़वामनता (क्रेटिनिज़्म) होती है","इंसुलिन, जिससे मधुमेह होता है","एड्रीनलीन, जिससे निम्न रक्तचाप होता है"],"explanationHi":"शैशवावस्था से थायरॉक्सिन की कमी जड़वामनता का कारण बनती है, जिसमें शारीरिक वृद्धि अवरुद्ध होती है और मानसिक विकास भी बाधित होता है। वृद्धि हॉर्मोन की कमी से बौनापन होता है, परंतु बुद्धि सामान्य रहती है।"},
  {"id":"sci-biology-169","question":"Excess growth hormone secreted in an adult, after the long bones have stopped growing in length, leads to:","options":["Gigantism, with an abnormally tall body","Acromegaly, with enlarged hands, feet and jaw","Cretinism, with stunted growth and mental slowness","Dwarfism, with short stature and normal intelligence"],"answer":1,"explanation":"Once the growth plates have closed, extra growth hormone cannot add height, so bones of the hands, feet and face thicken (acromegaly). Excess before puberty causes gigantism.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"वयस्क में, लंबी अस्थियों की लंबाई बढ़ना बंद हो जाने के बाद, वृद्धि हॉर्मोन के अत्यधिक स्राव से क्या होता है?","optionsHi":["महाकायता, जिसमें शरीर असामान्य रूप से लंबा हो जाता है","अग्रातिकायता (एक्रोमेगेली), जिसमें हाथ, पैर और जबड़ा बढ़ जाते हैं","जड़वामनता, जिसमें वृद्धि अवरुद्ध और मानसिक मंदता होती है","बौनापन, जिसमें कद छोटा पर बुद्धि सामान्य होती है"],"explanationHi":"वृद्धि पट्टिकाएँ बंद हो जाने के बाद अतिरिक्त वृद्धि हॉर्मोन ऊँचाई नहीं बढ़ा सकता, इसलिए हाथ, पैर और चेहरे की अस्थियाँ मोटी हो जाती हैं (अग्रातिकायता)। यौवन से पहले अधिकता से महाकायता होती है।"},
  {"id":"sci-biology-170","question":"A patient is always thirsty and passes very large volumes of pale, dilute urine, but tests show no sugar in the urine. The hormone most likely to be deficient is:","options":["Insulin (from beta cells)","Thyroxine (from the thyroid)","Antidiuretic hormone (ADH)","Adrenaline (epinephrine)"],"answer":2,"explanation":"ADH makes the kidney tubules reabsorb water; without it, large volumes of dilute urine are passed (diabetes insipidus). Insulin deficiency would also cause thirst and much urine, but with sugar in it.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"एक रोगी को हमेशा प्यास लगती है और वह बहुत अधिक मात्रा में हल्का, तनु मूत्र त्यागता है, परंतु जाँच में मूत्र में शर्करा नहीं मिलती। किस हॉर्मोन की कमी होने की सबसे अधिक संभावना है?","optionsHi":["इंसुलिन (बीटा कोशिकाओं से)","थायरॉक्सिन (थायरॉइड से)","प्रतिमूत्रल हॉर्मोन (ADH)","एड्रीनलीन (एपिनेफ्रिन)"],"explanationHi":"ADH वृक्क नलिकाओं से जल का पुनरावशोषण कराता है; इसके बिना बड़ी मात्रा में तनु मूत्र निकलता है (डायबिटीज़ इन्सिपिडस)। इंसुलिन की कमी से भी प्यास और अधिक मूत्र होता है, परंतु उसमें शर्करा होती है।"},
  {"id":"sci-biology-171","question":"How many of these statements about excretion in plants are correct? I. Some waste products are stored in the vacuoles of cells. II. Some wastes are stored as resins and gums, especially in old xylem. III. Plants get rid of some wastes by shedding leaves that contain them. IV. Some plants release waste substances into the soil around them.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: plants store wastes in cell vacuoles, as resins and gums in old xylem, shed them with falling leaves, and also excrete some wastes into the surrounding soil through their roots.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"पादपों में उत्सर्जन से संबंधित इनमें से कितने कथन सही हैं? I. कुछ अपशिष्ट पदार्थ कोशिकाओं की रिक्तिकाओं में संचित रहते हैं। II. कुछ अपशिष्ट रेजिन और गोंद के रूप में, विशेषकर पुराने जाइलम में, संचित रहते हैं। III. पौधे कुछ अपशिष्ट उन पत्तियों को गिराकर निकाल देते हैं जिनमें वे होते हैं। IV. कुछ पौधे अपने आसपास की मृदा में अपशिष्ट पदार्थ छोड़ते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं: पौधे अपशिष्ट को कोशिका रिक्तिकाओं में, पुराने जाइलम में रेजिन और गोंद के रूप में संचित करते हैं, गिरती पत्तियों के साथ निकाल देते हैं, और कुछ अपशिष्ट जड़ों द्वारा आसपास की मृदा में भी छोड़ते हैं।"},
  {"id":"sci-biology-172","question":"In human females, the egg is normally fertilised in the:","options":["Uterus (womb)","Ovary (Graafian follicle)","Cervix and vagina","Fallopian tube (oviduct)"],"answer":3,"explanation":"The sperm meets the egg in the oviduct; the zygote then divides as it moves down and implants in the wall of the uterus.","difficulty":"moderate","source":"RRB Group D · SSC MTS","questionHi":"मानव स्त्रियों में अंडाणु का निषेचन सामान्यतः कहाँ होता है?","optionsHi":["गर्भाशय","अंडाशय (ग्राफी पुटिका)","ग्रीवा और योनि","अंडवाहिनी (फैलोपियन नली)"],"explanationHi":"शुक्राणु अंडवाहिनी में अंडाणु से मिलता है; फिर युग्मनज नीचे की ओर बढ़ते हुए विभाजित होता है और गर्भाशय की दीवार में स्थापित हो जाता है।"},
  {"id":"sci-biology-173","question":"Which of the following are functions of the human placenta? I. Passing glucose and oxygen from the mother to the embryo. II. Passing waste products from the embryo to the mother's blood. III. Letting the mother's blood flow directly into the embryo's blood vessels.","options":["I and II only","I only","II and III only","I, II and III"],"answer":0,"explanation":"The placenta provides a large surface for exchange of nutrients, oxygen and wastes between the two bloodstreams, but the mother's and embryo's blood do not mix directly.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"निम्नलिखित में से कौन-से मानव अपरा (प्लेसेंटा) के कार्य हैं? I. माता से भ्रूण तक ग्लूकोज और ऑक्सीजन पहुँचाना। II. भ्रूण से माता के रक्त में अपशिष्ट पदार्थ पहुँचाना। III. माता के रक्त को सीधे भ्रूण की रक्त वाहिकाओं में बहने देना।","optionsHi":["केवल I और II","केवल I","केवल II और III","I, II और III"],"explanationHi":"अपरा दोनों रक्त प्रवाहों के बीच पोषक तत्वों, ऑक्सीजन और अपशिष्टों के विनिमय के लिए बड़ा सतही क्षेत्र प्रदान करती है, परंतु माता और भ्रूण का रक्त सीधे नहीं मिलता।"},
  {"id":"sci-biology-174","question":"New plants grow from buds present in the notches along the margins of the leaves of:","options":["Potato","Ginger","Bryophyllum","Sweet potato"],"answer":2,"explanation":"Bryophyllum leaves bear buds in their marginal notches that grow into new plants. Potato (stem tuber), ginger (rhizome) and sweet potato (root) propagate from other parts.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"किसकी पत्तियों के किनारों की खाँचों में उपस्थित कलिकाओं से नए पौधे उगते हैं?","optionsHi":["आलू","अदरक","ब्रायोफिलम (पत्थरचट्टा)","शकरकंद"],"explanationHi":"ब्रायोफिलम की पत्तियों की किनारे की खाँचों में कलिकाएँ होती हैं जो नए पौधों में विकसित हो जाती हैं। आलू (तना कंद), अदरक (प्रकंद) और शकरकंद (जड़) अन्य भागों से प्रवर्धित होते हैं।"},
  {"id":"sci-biology-175","question":"Botanists classify a potato as a modified stem and not a root, even though it grows underground. The deciding feature is that the potato:","options":["Stores a large amount of starch","Grows below the soil surface","Has no chlorophyll in its tissue","Has ‘eyes’: nodes bearing buds"],"answer":3,"explanation":"Nodes with buds are a feature of stems, and the eyes of a potato sprout into new shoots. Storing starch and growing underground are true of many roots too, such as the sweet potato.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"वनस्पति विज्ञानी आलू को भूमिगत उगने के बावजूद रूपांतरित तना मानते हैं, जड़ नहीं। निर्णायक विशेषता यह है कि आलू में:","optionsHi":["स्टार्च की बड़ी मात्रा संचित होती है","वह मृदा की सतह के नीचे उगता है","उसके ऊतक में पर्णहरित नहीं होता","‘आँखें’ होती हैं: कलिकाओं वाली पर्वसंधियाँ"],"explanationHi":"कलिकाओं वाली पर्वसंधियाँ तने की विशेषता हैं, और आलू की आँखें नए प्ररोह के रूप में अंकुरित होती हैं। स्टार्च संचित करना और भूमिगत उगना अनेक जड़ों पर भी लागू होता है, जैसे शकरकंद।"},
  {"id":"sci-biology-176","question":"Match the organism with its usual method of asexual reproduction: A. Hydra B. Spirogyra C. Plasmodium D. Rhizopus; 1. Spore formation 2. Multiple fission 3. Budding 4. Fragmentation","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2","A-3, B-2, C-4, D-1"],"answer":0,"explanation":"Hydra buds, the filamentous alga Spirogyra breaks into fragments, the malaria parasite Plasmodium divides by multiple fission, and the bread mould Rhizopus forms spores in sporangia.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"जीव का उसकी अलैंगिक जनन की सामान्य विधि से मिलान कीजिए: A. हाइड्रा B. स्पाइरोगाइरा C. प्लाज्मोडियम D. राइज़ोपस; 1. बीजाणु निर्माण 2. बहुविखंडन 3. मुकुलन 4. खंडन","optionsHi":["A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2","A-3, B-2, C-4, D-1"],"explanationHi":"हाइड्रा मुकुलन करता है, तंतुमय शैवाल स्पाइरोगाइरा खंडों में टूटता है, मलेरिया परजीवी प्लाज्मोडियम बहुविखंडन से विभाजित होता है, और ब्रेड की फफूँद राइज़ोपस बीजाणुधानियों में बीजाणु बनाती है।"},
  {"id":"sci-biology-177","question":"After fertilisation in a flowering plant:","options":["The ovules become fruits and the ovary becomes the seed","The ovary develops into the fruit and the ovules into seeds","The petals develop into the fruit and the ovary into seeds","The stigma develops into the fruit and the ovules into the embryo"],"answer":1,"explanation":"The fertilised ovule becomes the seed, containing the embryo, while the ovary ripens into the fruit; petals and stigma usually wither and fall.","difficulty":"moderate","source":"RRB Group D · SSC MTS","questionHi":"पुष्पीय पादप में निषेचन के बाद:","optionsHi":["बीजांड फल बन जाते हैं और अंडाशय बीज बन जाता है","अंडाशय फल में और बीजांड बीजों में विकसित हो जाते हैं","पंखुड़ियाँ फल में और अंडाशय बीजों में विकसित हो जाते हैं","वर्तिकाग्र फल में और बीजांड भ्रूण में विकसित हो जाते हैं"],"explanationHi":"निषेचित बीजांड बीज बन जाता है, जिसमें भ्रूण होता है, जबकि अंडाशय पककर फल बन जाता है; पंखुड़ियाँ और वर्तिकाग्र प्रायः मुरझाकर गिर जाते हैं।"},
  {"id":"sci-biology-178","question":"Two parents both have blood group A, but their first child has blood group O. What is the probability that their next child will also have blood group O?","options":["0, because O cannot arise from two A parents","1/2","1/4","3/4"],"answer":2,"explanation":"An O child (I°I°) shows that both parents must be I^A I°. Crossing I^A I° × I^A I° gives I°I° with probability 1/4 for every child, regardless of earlier births.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"दोनों जनकों का रक्त समूह A है, परंतु उनकी पहली संतान का रक्त समूह O है। उनकी अगली संतान का रक्त समूह भी O होने की प्रायिकता क्या है?","optionsHi":["0, क्योंकि दो A जनकों से O उत्पन्न नहीं हो सकता","1/2","1/4","3/4"],"explanationHi":"O समूह की संतान (I°I°) दर्शाती है कि दोनों जनक I^A I° होने चाहिए। I^A I° × I^A I° के संकरण से प्रत्येक संतान के I°I° होने की प्रायिकता 1/4 होती है, पहले के जन्मों से स्वतंत्र।"},
  {"id":"sci-biology-179","question":"In many turtles and crocodiles, whether an egg hatches into a male or a female depends on:","options":["The X or Y sex chromosome received from the father's sperm","The temperature at which the fertilised egg is incubated","The amount of yolk stored in the egg before it is laid","The age and size of the mother at the time of laying"],"answer":1,"explanation":"In some reptiles the incubation temperature of the eggs decides the sex of the offspring; there are no sex chromosomes as in humans.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"अनेक कछुओं और मगरमच्छों में अंडे से नर निकलेगा या मादा, यह किस पर निर्भर करता है?","optionsHi":["पिता के शुक्राणु से मिले X या Y लिंग गुणसूत्र पर","जिस तापमान पर निषेचित अंडे को सेया जाता है उस पर","अंडा देने से पहले उसमें संचित पीतक की मात्रा पर","अंडा देते समय माता की आयु और आकार पर"],"explanationHi":"कुछ सरीसृपों में अंडों के सेने का तापमान संतान का लिंग तय करता है; उनमें मनुष्यों की तरह लिंग गुणसूत्र नहीं होते।"},
  {"id":"sci-biology-180","question":"A man builds very large muscles through years of weight training. His children will not inherit these large muscles because:","options":["Acquired muscles are broken down before the man reproduces","Muscle-building is a dominant trait that skips a generation","The children's muscles are formed only by the mother's genes","Body-cell changes do not alter the DNA of the germ cells"],"answer":3,"explanation":"Traits acquired during a lifetime change only body cells; they are not written into the DNA of sperm or eggs, so they are not inherited. This is why Lamarck's idea of inheritance of acquired characters was rejected.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"एक व्यक्ति वर्षों के भार प्रशिक्षण से बहुत बड़ी पेशियाँ बना लेता है। उसकी संतानों को ये बड़ी पेशियाँ विरासत में नहीं मिलेंगी, क्योंकि:","optionsHi":["अर्जित पेशियाँ पुरुष के जनन करने से पहले ही टूट जाती हैं","पेशी निर्माण एक प्रभावी लक्षण है जो एक पीढ़ी छोड़ देता है","संतानों की पेशियाँ केवल माता के जीनों से बनती हैं","काय कोशिकाओं में हुए परिवर्तन जनन कोशिकाओं के DNA को नहीं बदलते"],"explanationHi":"जीवनकाल में अर्जित लक्षण केवल काय कोशिकाओं को बदलते हैं; वे शुक्राणुओं या अंडाणुओं के DNA में अंकित नहीं होते, इसलिए वे विरासत में नहीं मिलते। इसीलिए लैमार्क का अर्जित लक्षणों की वंशागति का विचार अस्वीकार कर दिया गया।"},
  {"id":"sci-biology-181","question":"Which of the following pairs are homologous organs, having the same basic structure and origin but possibly different functions?","options":["Forelimb of a frog and flipper of a whale","Wing of a bat and wing of a butterfly","Potato tuber and sweet potato","Eye of an octopus and eye of a human being"],"answer":0,"explanation":"Frog forelimbs and whale flippers share the same pattern of vertebrate limb bones. The other pairs do similar jobs but have different structure and origin (analogous organs), e.g. a potato is a stem while a sweet potato is a root.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"निम्नलिखित में से कौन-से युग्म समजात अंग हैं, जिनकी मूल संरचना और उत्पत्ति समान होती है पर कार्य भिन्न हो सकते हैं?","optionsHi":["मेंढक की अग्रपाद और व्हेल का फ्लिपर","चमगादड़ का पंख और तितली का पंख","आलू का कंद और शकरकंद","ऑक्टोपस की आँख और मनुष्य की आँख"],"explanationHi":"मेंढक की अग्रपाद और व्हेल के फ्लिपर में कशेरुकी अग्रपाद की अस्थियों का एक ही प्रतिरूप होता है। अन्य युग्म समान कार्य करते हैं परंतु उनकी संरचना और उत्पत्ति भिन्न है (समरूप अंग), जैसे आलू तना है जबकि शकरकंद जड़ है।"},
  {"id":"sci-biology-182","question":"A pesticide that does not break down enters a lake. After some years its concentration in body tissues is likely to be highest in:","options":["Phytoplankton","Zooplankton","Small plankton-eating fish","Fish-eating birds"],"answer":3,"explanation":"Non-biodegradable chemicals accumulate at each step of the food chain (biological magnification), so the top consumers carry the highest concentration.","difficulty":"moderate","source":"RRB NTPC · SSC CHSL","questionHi":"एक ऐसा कीटनाशक जो विघटित नहीं होता, एक झील में पहुँच जाता है। कुछ वर्षों बाद उसकी सांद्रता शरीर के ऊतकों में सबसे अधिक किसमें होने की संभावना है?","optionsHi":["पादपप्लवक (फाइटोप्लैंकटन)","प्राणिप्लवक (जूप्लैंकटन)","प्लवक खाने वाली छोटी मछलियाँ","मछली खाने वाले पक्षी"],"explanationHi":"अजैवनिम्नीकरणीय रसायन खाद्य श्रृंखला के प्रत्येक चरण पर संचित होते जाते हैं (जैव आवर्धन), इसलिए शीर्ष उपभोक्ताओं में उनकी सांद्रता सबसे अधिक होती है।"},
  {"id":"sci-biology-183","question":"If all the decomposers in an ecosystem were suddenly wiped out, the most direct long-term effect would be that:","options":["Energy would start flowing back from the consumers to the producers","Producers would make more food, since fewer organisms compete with them","Dead matter would pile up and nutrients would not return to the soil","The oxygen content of the air would rise sharply and permanently"],"answer":2,"explanation":"Decomposers break down dead matter and return minerals to the soil for producers to reuse; without them nutrient cycling stops. Energy flow is one-way in any case.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"यदि किसी पारिस्थितिक तंत्र के सभी अपघटक अचानक नष्ट हो जाएँ, तो सबसे प्रत्यक्ष दीर्घकालिक प्रभाव क्या होगा?","optionsHi":["ऊर्जा उपभोक्ताओं से उत्पादकों की ओर वापस बहने लगेगी","उत्पादक अधिक भोजन बनाएँगे, क्योंकि उनसे प्रतिस्पर्धा करने वाले जीव कम होंगे","मृत पदार्थ जमा होता जाएगा और पोषक तत्व मृदा में नहीं लौटेंगे","वायु में ऑक्सीजन की मात्रा तेजी से और स्थायी रूप से बढ़ जाएगी"],"explanationHi":"अपघटक मृत पदार्थ को तोड़कर खनिजों को मृदा में लौटाते हैं ताकि उत्पादक उनका पुनः उपयोग कर सकें; इनके बिना पोषक चक्रण रुक जाता है। ऊर्जा का प्रवाह तो किसी भी स्थिति में एकदिशीय ही होता है।"},
  {"id":"sci-biology-184","question":"In the food chain grass → grasshopper → frog → snake → eagle, the snake is a:","options":["Secondary consumer at the third trophic level","Tertiary consumer at the fourth trophic level","Secondary consumer at the fourth trophic level","Quaternary consumer at the fifth trophic level"],"answer":1,"explanation":"Grass is level 1 (producer), grasshopper level 2 (primary consumer), frog level 3 (secondary consumer) and snake level 4 (tertiary consumer).","difficulty":"hard","source":"SSC CGL · RRB Group D","questionHi":"खाद्य श्रृंखला घास → टिड्डा → मेंढक → साँप → बाज़ में साँप है:","optionsHi":["तीसरे पोषी स्तर पर द्वितीयक उपभोक्ता","चौथे पोषी स्तर पर तृतीयक उपभोक्ता","चौथे पोषी स्तर पर द्वितीयक उपभोक्ता","पाँचवें पोषी स्तर पर चतुर्थक उपभोक्ता"],"explanationHi":"घास पहला स्तर (उत्पादक) है, टिड्डा दूसरा स्तर (प्राथमिक उपभोक्ता), मेंढक तीसरा स्तर (द्वितीयक उपभोक्ता) और साँप चौथा स्तर (तृतीयक उपभोक्ता) है।"},
  {"id":"sci-biology-185","question":"Farmers often grow a crop of pulses between two cereal crops because leguminous plants:","options":["Have root nodules whose Rhizobium bacteria fix atmospheric nitrogen","Absorb nitrogen gas from the air directly through their leaf stomata","Release nitrogen into the soil as they carry out photosynthesis","Kill the denitrifying bacteria present in the soil around them"],"answer":0,"explanation":"Rhizobium living in the root nodules of legumes fixes atmospheric N₂, enriching the soil with nitrogen compounds. Plants cannot use N₂ directly.","difficulty":"moderate","source":"RRB Group D · SSC MTS","questionHi":"किसान प्रायः दो अनाज वाली फसलों के बीच दलहन की फसल उगाते हैं, क्योंकि दलहनी पौधे:","optionsHi":["जड़ ग्रंथियों वाले होते हैं जिनमें राइज़ोबियम जीवाणु वायुमंडलीय नाइट्रोजन का स्थिरीकरण करते हैं","अपनी पत्तियों के रंध्रों से सीधे वायु की नाइट्रोजन गैस सोख लेते हैं","प्रकाश संश्लेषण करते समय मृदा में नाइट्रोजन मुक्त करते हैं","अपने आसपास की मृदा में उपस्थित विनाइट्रीकारी जीवाणुओं को मार देते हैं"],"explanationHi":"दलहनों की जड़ ग्रंथियों में रहने वाले राइज़ोबियम वायुमंडलीय N₂ का स्थिरीकरण करते हैं, जिससे मृदा नाइट्रोजन यौगिकों से समृद्ध होती है। पौधे N₂ का सीधे उपयोग नहीं कर सकते।"},
  {"id":"sci-biology-186","question":"Which of these diseases is caused by a protozoan and is commonly spread through food or water contaminated with faeces?","options":["Bacillary dysentery","Typhoid","Hepatitis A","Amoebic dysentery"],"answer":3,"explanation":"Amoebic dysentery (amoebiasis) is caused by the protozoan Entamoeba histolytica. Bacillary dysentery looks similar but is caused by the bacterium Shigella, typhoid is also bacterial, and hepatitis A is viral.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"इनमें से कौन-सा रोग प्रोटोज़ोआ से होता है और सामान्यतः मल से दूषित भोजन या जल द्वारा फैलता है?","optionsHi":["बैसिलरी पेचिश","टाइफाइड","हेपेटाइटिस A","अमीबी पेचिश"],"explanationHi":"अमीबी पेचिश (अमीबिएसिस) प्रोटोज़ोआ एंटअमीबा हिस्टोलिटिका से होती है। बैसिलरी पेचिश दिखने में समान है परंतु शिगेला जीवाणु से होती है, टाइफाइड भी जीवाणुजनित है, और हेपेटाइटिस A विषाणुजनित है।"},
  {"id":"sci-biology-187","question":"Doctors do not prescribe antibiotics such as penicillin for the common cold because:","options":["The cold virus multiplies too fast for any medicine to keep up with it","Antibiotics target bacterial parts, like cell walls, that viruses lack","Antibiotics kill only fungi and protozoans, not other microbes","A cold is caused by an allergy to pollen, not by any microbe"],"answer":1,"explanation":"Antibiotics block bacterial pathways, e.g. penicillin blocks bacterial cell-wall formation. Viruses have no cell wall and use the host cell's machinery, so antibiotics cannot stop them.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"चिकित्सक सामान्य सर्दी-ज़ुकाम के लिए पेनिसिलिन जैसे प्रतिजैविक नहीं लिखते, क्योंकि:","optionsHi":["सर्दी का विषाणु इतनी तेजी से बढ़ता है कि कोई दवा उसकी बराबरी नहीं कर सकती","प्रतिजैविक जीवाणु के उन भागों को लक्ष्य बनाते हैं, जैसे कोशिका भित्ति, जो विषाणुओं में नहीं होते","प्रतिजैविक केवल कवक और प्रोटोज़ोआ को मारते हैं, अन्य सूक्ष्मजीवों को नहीं","सर्दी परागकणों की एलर्जी से होती है, किसी सूक्ष्मजीव से नहीं"],"explanationHi":"प्रतिजैविक जीवाणुओं की क्रियाविधियों को रोकते हैं, जैसे पेनिसिलिन जीवाणु की कोशिका भित्ति के निर्माण को रोकता है। विषाणुओं में कोशिका भित्ति नहीं होती और वे परपोषी कोशिका की मशीनरी का उपयोग करते हैं, इसलिए प्रतिजैविक उन्हें नहीं रोक सकते।"},
  {"id":"sci-biology-188","question":"HIV gradually weakens the body's immune system mainly by destroying:","options":["Red blood cells","Platelets","Helper T-lymphocytes","Cells of the bone marrow that make red cells"],"answer":2,"explanation":"HIV infects and kills helper T-cells, which coordinate the immune response; as their number falls, the body cannot fight even minor infections (AIDS).","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"HIV शरीर के प्रतिरक्षा तंत्र को मुख्यतः किसे नष्ट करके धीरे-धीरे कमजोर करता है?","optionsHi":["लाल रक्त कोशिकाओं को","प्लेटलेट्स को","सहायक T-लिम्फोसाइट को","अस्थि मज्जा की उन कोशिकाओं को जो लाल कोशिकाएँ बनाती हैं"],"explanationHi":"HIV सहायक T-कोशिकाओं को संक्रमित कर नष्ट करता है, जो प्रतिरक्षा प्रतिक्रिया का समन्वय करती हैं; इनकी संख्या घटने पर शरीर मामूली संक्रमणों से भी नहीं लड़ पाता (AIDS)।"},
  {"id":"sci-biology-189","question":"Fresh amla and guava lose much of their value as a source of one vitamin when cut and left exposed or boiled for long. That vitamin is:","options":["Vitamin C","Vitamin A","Vitamin D","Vitamin K"],"answer":0,"explanation":"Vitamin C is water-soluble and easily destroyed by heat and exposure to air, so long cooking and storage of cut fruit lower it. Vitamins A, D and K are fat-soluble and more stable.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"ताज़ा आँवला और अमरूद काटकर खुला छोड़ देने या देर तक उबालने पर एक विटामिन के स्रोत के रूप में अपना बहुत मूल्य खो देते हैं। वह विटामिन है:","optionsHi":["विटामिन C","विटामिन A","विटामिन D","विटामिन K"],"explanationHi":"विटामिन C जल में घुलनशील है और ऊष्मा तथा वायु के संपर्क से आसानी से नष्ट हो जाता है, इसलिए देर तक पकाने और कटे फलों के भंडारण से इसकी मात्रा घट जाती है। विटामिन A, D और K वसा में घुलनशील तथा अधिक स्थिर होते हैं।"},
  {"id":"sci-biology-190","question":"Doctors advise anaemic patients to take iron-rich plant foods along with lemon juice or amla. This is because:","options":["Lemon juice contains a large amount of iron","Vitamin C helps the body absorb iron from plant foods","The acid in lemon kills the worms that cause anaemia","Vitamin C is itself a part of the haemoglobin molecule"],"answer":1,"explanation":"Vitamin C improves the absorption of non-haem iron from plant foods in the intestine. Haemoglobin contains iron, not vitamin C.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"चिकित्सक रक्ताल्पता के रोगियों को लोहे से भरपूर पादप खाद्य पदार्थों के साथ नींबू का रस या आँवला लेने की सलाह देते हैं। इसका कारण यह है कि:","optionsHi":["नींबू के रस में लोहा बड़ी मात्रा में होता है","विटामिन C शरीर को पादप खाद्य पदार्थों से लोहा अवशोषित करने में सहायता करता है","नींबू का अम्ल रक्ताल्पता फैलाने वाले कृमियों को मार देता है","विटामिन C स्वयं हीमोग्लोबिन अणु का भाग है"],"explanationHi":"विटामिन C आँत में पादप खाद्य पदार्थों से अहीम लोहे का अवशोषण बढ़ाता है। हीमोग्लोबिन में लोहा होता है, विटामिन C नहीं।"},
  {"id":"sci-biology-191","question":"Bile contains no digestive enzyme, yet a person whose bile flow is blocked digests fats poorly. Bile helps because it:","options":["Converts fats directly into fatty acids and glycerol by itself","Activates pepsin in the stomach so that it digests fats","Breaks fat globules into tiny droplets, giving lipase more surface","Absorbs fats from the intestine and carries them directly into the blood"],"answer":2,"explanation":"Bile salts emulsify fats, so pancreatic and intestinal lipase can work on a far larger surface. The actual chemical breakdown into fatty acids and glycerol is done by lipase.","difficulty":"hard","source":"SSC CGL · RRB Group D","questionHi":"पित्त में कोई पाचक एंजाइम नहीं होता, फिर भी जिस व्यक्ति का पित्त प्रवाह अवरुद्ध हो, उसे वसा का पाचन ठीक से नहीं होता। पित्त किस प्रकार सहायता करता है?","optionsHi":["वह स्वयं ही वसा को सीधे वसा अम्लों और ग्लिसरॉल में बदल देता है","वह आमाशय में पेप्सिन को सक्रिय करता है ताकि वह वसा का पाचन करे","वह वसा की गोलिकाओं को सूक्ष्म बूँदों में तोड़ता है, जिससे लाइपेज को अधिक सतह मिलती है","वह आँत से वसा को अवशोषित करके सीधे रक्त में पहुँचा देता है"],"explanationHi":"पित्त लवण वसा का इमल्सीकरण करते हैं, जिससे अग्न्याशयी और आंत्रीय लाइपेज को कहीं बड़ी सतह पर कार्य करने का अवसर मिलता है। वसा अम्लों और ग्लिसरॉल में वास्तविक रासायनिक विघटन लाइपेज द्वारा होता है।"},
  {"id":"sci-biology-192","question":"A herbivore such as a cow has a much longer small intestine than a carnivore such as a tiger because:","options":["Meat takes longer to digest than grass","Herbivores eat more often than carnivores","Herbivores have no stomach and need a longer intestine","The cellulose in plant food takes longer to digest"],"answer":3,"explanation":"Plant food rich in cellulose needs a longer time and a longer gut to digest; meat is easier to digest, so carnivores have shorter small intestines.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"गाय जैसे शाकाहारी की छोटी आँत बाघ जैसे माँसाहारी की तुलना में कहीं अधिक लंबी होती है, क्योंकि:","optionsHi":["घास की तुलना में माँस के पाचन में अधिक समय लगता है","शाकाहारी माँसाहारियों की तुलना में अधिक बार खाते हैं","शाकाहारियों में आमाशय नहीं होता और उन्हें लंबी आँत की आवश्यकता होती है","पादप भोजन में उपस्थित सेलुलोज के पाचन में अधिक समय लगता है"],"explanationHi":"सेलुलोज से भरपूर पादप भोजन को पचाने में अधिक समय और लंबी आँत की आवश्यकता होती है; माँस का पाचन सरल है, इसलिए माँसाहारियों की छोटी आँत छोटी होती है।"},
  {"id":"sci-biology-193","question":"The windpipe (trachea) has C-shaped rings of cartilage in its wall. Their main function is to:","options":["Prevent the trachea from collapsing when pressure inside falls","Filter dust and germs out of the air before it reaches the lungs","Vibrate to produce the sound of the voice during speech","Warm and moisten the inhaled air on its way down"],"answer":0,"explanation":"The cartilage rings keep the air passage open at all times. Dust is trapped by mucus and hairs, and sound is produced by the vocal cords in the larynx.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"श्वास नली (ट्रेकिया) की दीवार में उपास्थि के C-आकार के छल्ले होते हैं। इनका मुख्य कार्य है:","optionsHi":["भीतर का दाब घटने पर श्वास नली को पिचकने से रोकना","फेफड़ों तक पहुँचने से पहले वायु से धूल और रोगाणुओं को छानना","बोलते समय कंपित होकर वाणी की ध्वनि उत्पन्न करना","नीचे जाती हुई अंदर ली गई वायु को गर्म और नम करना"],"explanationHi":"उपास्थि के छल्ले वायु मार्ग को सदैव खुला रखते हैं। धूल श्लेष्मा और बालों में फँस जाती है, और ध्वनि स्वर यंत्र की स्वर रज्जुओं द्वारा उत्पन्न होती है।"},
  {"id":"sci-biology-194","question":"During inhalation in humans:","options":["The diaphragm relaxes into a dome and the chest cavity becomes much smaller","The ribs move down and in, which raises the pressure inside the lungs","The diaphragm flattens, the ribs move up and out, and lung pressure falls","Air is actively pumped in by the muscles in the walls of the lungs"],"answer":2,"explanation":"Contraction of the diaphragm and rib muscles enlarges the chest cavity; the lungs expand, pressure drops and air rushes in. The lungs have no muscles of their own.","difficulty":"hard","source":"SSC CGL · RRB Group D","questionHi":"मनुष्यों में अंतःश्वसन (साँस भीतर लेते) समय:","optionsHi":["डायाफ्राम शिथिल होकर गुंबद जैसा हो जाता है और वक्ष गुहा बहुत छोटी हो जाती है","पसलियाँ नीचे और भीतर की ओर जाती हैं, जिससे फेफड़ों के भीतर दाब बढ़ता है","डायाफ्राम चपटा हो जाता है, पसलियाँ ऊपर और बाहर की ओर जाती हैं और फेफड़ों का दाब घट जाता है","फेफड़ों की दीवारों की पेशियाँ वायु को सक्रिय रूप से भीतर पंप करती हैं"],"explanationHi":"डायाफ्राम और पसलियों की पेशियों के संकुचन से वक्ष गुहा बड़ी हो जाती है; फेफड़े फैलते हैं, दाब घटता है और वायु भीतर दौड़ती है। फेफड़ों की अपनी कोई पेशियाँ नहीं होतीं।"},
  {"id":"sci-biology-195","question":"Fishes and other aquatic animals breathe much faster than land animals of similar size because:","options":["Water holds much less oxygen than the same volume of air","Gills need more oxygen than lungs to function properly","Aquatic animals have a higher body temperature than land animals","Water contains more carbon dioxide, which speeds up breathing"],"answer":0,"explanation":"The amount of oxygen dissolved in water is far lower than in air, so aquatic animals must pass large volumes of water over their gills quickly.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"मछलियाँ और अन्य जलीय जंतु समान आकार के स्थलीय जंतुओं की तुलना में कहीं अधिक तेजी से साँस लेते हैं, क्योंकि:","optionsHi":["जल में उसी आयतन की वायु की तुलना में ऑक्सीजन बहुत कम होती है","क्लोम को ठीक से कार्य करने के लिए फेफड़ों से अधिक ऑक्सीजन चाहिए","जलीय जंतुओं का शरीर का तापमान स्थलीय जंतुओं से अधिक होता है","जल में कार्बन डाइऑक्साइड अधिक होती है, जो श्वसन को तेज करती है"],"explanationHi":"जल में घुली ऑक्सीजन की मात्रा वायु की तुलना में बहुत कम होती है, इसलिए जलीय जंतुओं को अपने क्लोमों के ऊपर से जल की बड़ी मात्रा शीघ्रता से प्रवाहित करनी पड़ती है।"},
  {"id":"sci-biology-196","question":"A cell in the human testis divides by meiosis to form sperms. Each sperm carries:","options":["46 chromosomes, including both X and Y","23 chromosomes, including either an X or a Y","23 chromosomes, all of them carrying a Y chromosome","22 chromosomes and no sex chromosome"],"answer":1,"explanation":"Meiosis halves the number from 46 to 23; each sperm has 22 autosomes plus one sex chromosome, X or Y, in roughly equal numbers.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"मानव वृषण की एक कोशिका अर्धसूत्री विभाजन द्वारा शुक्राणु बनाती है। प्रत्येक शुक्राणु में होते हैं:","optionsHi":["46 गुणसूत्र, जिनमें X और Y दोनों शामिल हैं","23 गुणसूत्र, जिनमें X या Y में से कोई एक शामिल है","23 गुणसूत्र, जिन सबमें Y गुणसूत्र है","22 गुणसूत्र और कोई लिंग गुणसूत्र नहीं"],"explanationHi":"अर्धसूत्री विभाजन संख्या को 46 से घटाकर 23 कर देता है; प्रत्येक शुक्राणु में 22 अलिंगी गुणसूत्र और एक लिंग गुणसूत्र, X या Y, होता है, लगभग बराबर संख्या में।"},
  {"id":"sci-biology-197","question":"If gametes were formed by ordinary mitosis instead of meiosis, what would happen over generations of sexually reproducing organisms?","options":["The chromosome number would stay the same in every generation","The chromosome number would halve in every generation","Offspring would show no variation at all","The chromosome number would double in every generation"],"answer":3,"explanation":"Gametes would carry the full set, so fusion would give a zygote with twice the parental number, doubling each generation. Meiosis halves the number so that fertilisation restores it.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"यदि युग्मक अर्धसूत्री विभाजन के बजाय सामान्य समसूत्री विभाजन से बनते, तो लैंगिक जनन करने वाले जीवों की पीढ़ियों में क्या होता?","optionsHi":["प्रत्येक पीढ़ी में गुणसूत्रों की संख्या समान रहती","प्रत्येक पीढ़ी में गुणसूत्रों की संख्या आधी हो जाती","संतानों में कोई विभिन्नता नहीं दिखती","प्रत्येक पीढ़ी में गुणसूत्रों की संख्या दोगुनी हो जाती"],"explanationHi":"युग्मक पूरा गुणसूत्र समूह लिए होते, इसलिए संयोजन से बने युग्मनज में जनकों की संख्या से दोगुनी संख्या होती, जो हर पीढ़ी में दोगुनी होती जाती। अर्धसूत्री विभाजन संख्या को आधा कर देता है ताकि निषेचन उसे पुनः पूरा कर दे।"},
  {"id":"sci-biology-198","question":"Which combination of features places mushrooms in a kingdom separate from green plants?","options":["They are prokaryotic, with no true nucleus in any of their cells","No chlorophyll, feeding on dead matter, and cell walls of chitin","They have no cell wall and move about actively to find food","They photosynthesise but have no true roots, stems or leaves"],"answer":1,"explanation":"Fungi are eukaryotic heterotrophs (saprotrophs) with cell walls made of chitin, while plants make their own food and have cellulose walls.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"विशेषताओं का कौन-सा संयोजन मशरूम को हरे पौधों से अलग जगत में रखता है?","optionsHi":["वे प्रोकैरियोटिक हैं और उनकी किसी भी कोशिका में सच्चा केंद्रक नहीं होता","पर्णहरित का अभाव, मृत पदार्थ पर पोषण, और काइटिन की कोशिका भित्ति","उनमें कोशिका भित्ति नहीं होती और वे भोजन खोजने के लिए सक्रिय रूप से चलते हैं","वे प्रकाश संश्लेषण करते हैं परंतु उनमें सच्ची जड़, तना या पत्तियाँ नहीं होतीं"],"explanationHi":"कवक यूकैरियोटिक विषमपोषी (मृतोपजीवी) हैं जिनकी कोशिका भित्ति काइटिन की बनी होती है, जबकि पादप अपना भोजन स्वयं बनाते हैं और उनकी भित्ति सेलुलोज की होती है।"},
  {"id":"sci-biology-199","question":"Which of these organisms is a prokaryote?","options":["Yeast","Amoeba","Nostoc (a blue-green alga)","Chlamydomonas (a green alga)"],"answer":2,"explanation":"Blue-green algae (cyanobacteria) such as Nostoc have no membrane-bound nucleus, so they belong to Monera. Yeast, Amoeba and Chlamydomonas are eukaryotes despite being single-celled.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"इनमें से कौन-सा जीव प्रोकैरियोट है?","optionsHi":["यीस्ट","अमीबा","नॉस्टॉक (नील-हरित शैवाल)","क्लैमाइडोमोनास (हरित शैवाल)"],"explanationHi":"नॉस्टॉक जैसे नील-हरित शैवाल (सायनोबैक्टीरिया) में झिल्लीयुक्त केंद्रक नहीं होता, इसलिए वे मोनेरा में आते हैं। यीस्ट, अमीबा और क्लैमाइडोमोनास एककोशिकीय होते हुए भी यूकैरियोट हैं।"},
  {"id":"sci-biology-200","question":"Which of these animals is NOT a fish, despite its common name?","options":["Seahorse","Starfish","Flying fish","Dogfish"],"answer":1,"explanation":"The starfish is an echinoderm, with spiny skin and a water-vascular system. The seahorse, flying fish and dogfish (a small shark) all have gills and fins and are true fishes.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"इनमें से कौन-सा जंतु अपने प्रचलित नाम के बावजूद मछली नहीं है?","optionsHi":["सीहॉर्स (समुद्री घोड़ा)","तारा मछली (स्टारफिश)","उड़न मछली","डॉगफिश"],"explanationHi":"तारा मछली एक एकाइनोडर्म है, जिसकी त्वचा काँटेदार होती है और जिसमें जल-संवहन तंत्र होता है। सीहॉर्स, उड़न मछली और डॉगफिश (एक छोटी शार्क) सभी में क्लोम और पख होते हैं और ये सच्ची मछलियाँ हैं।"},
  {"id":"sci-biology-201","question":"Which of these mammals lays eggs?","options":["Red kangaroo","Fruit bat (flying fox)","Blue whale","Duck-billed platypus"],"answer":3,"explanation":"The platypus (and the spiny anteater) are egg-laying mammals that still feed their young on milk. Kangaroos give birth to tiny young that develop in a pouch.","difficulty":"moderate","source":"RRB Group D · SSC MTS","questionHi":"इनमें से कौन-सा स्तनपायी अंडे देता है?","optionsHi":["लाल कंगारू","फल खाने वाला चमगादड़ (फ्लाइंग फॉक्स)","नीली व्हेल","बतखचोंच प्लैटिपस"],"explanationHi":"प्लैटिपस (और काँटेदार चींटीखोर) अंडे देने वाले स्तनपायी हैं जो फिर भी अपने बच्चों को दूध पिलाते हैं। कंगारू बहुत छोटे बच्चों को जन्म देते हैं जो थैली में विकसित होते हैं।"},
  {"id":"sci-biology-202","question":"Bt cotton suffers much less damage from bollworms because:","options":["It carries a Bacillus thuringiensis gene for a protein toxic to them","It is sprayed with a bacterial pesticide every week of the growing season","It is a hybrid whose bolls are too hard for the insects to bite","Its leaves give off a strong smell that repels the insects"],"answer":0,"explanation":"Bt cotton is genetically modified with the Bt gene, so the plant itself makes an insecticidal (Cry) protein; no spraying is needed for these pests.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"Bt कपास को सुंडी (बॉलवर्म) से बहुत कम क्षति होती है, क्योंकि:","optionsHi":["उसमें बैसिलस थुरिंजिएंसिस का एक जीन होता है जो उनके लिए विषैला प्रोटीन बनाता है","उसमें वृद्धि ऋतु के हर सप्ताह जीवाणु कीटनाशक का छिड़काव किया जाता है","वह एक संकर है जिसके टिंडे इतने कठोर होते हैं कि कीट उन्हें काट नहीं पाते","उसकी पत्तियाँ तेज गंध छोड़ती हैं जो कीटों को दूर भगाती है"],"explanationHi":"Bt कपास में Bt जीन डालकर उसे आनुवंशिक रूप से रूपांतरित किया गया है, इसलिए पौधा स्वयं कीटनाशी (Cry) प्रोटीन बनाता है; इन कीटों के लिए छिड़काव की आवश्यकता नहीं होती।"},
  {"id":"sci-biology-203","question":"‘Golden Rice’ was genetically engineered mainly to fight which deficiency in people who depend on rice?","options":["Vitamin B1 deficiency","Iodine deficiency","Vitamin A deficiency","Protein deficiency"],"answer":2,"explanation":"Golden Rice makes beta-carotene (a precursor of vitamin A) in its grain, which gives it a golden colour; it targets vitamin A deficiency and night blindness. Vitamin B1 lack (beriberi) is linked to polished rice but was not the aim of Golden Rice.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"चावल पर निर्भर लोगों में कौन-सी कमी से लड़ने के लिए ‘गोल्डन राइस’ को मुख्यतः आनुवंशिक रूप से इंजीनियर किया गया था?","optionsHi":["विटामिन B1 की कमी","आयोडीन की कमी","विटामिन A की कमी","प्रोटीन की कमी"],"explanationHi":"गोल्डन राइस अपने दानों में बीटा-कैरोटीन (विटामिन A का पूर्ववर्ती) बनाता है, जो उसे सुनहरा रंग देता है; यह विटामिन A की कमी और रतौंधी को लक्ष्य करता है। विटामिन B1 की कमी (बेरी-बेरी) पॉलिश किए चावल से जुड़ी है, पर गोल्डन राइस का लक्ष्य वह नहीं था।"},
  {"id":"sci-biology-204","question":"The first vaccine was developed by using material from cowpox sores to protect people against smallpox. This was done by:","options":["Louis Pasteur","Edward Jenner","Robert Koch","Alexander Fleming"],"answer":1,"explanation":"Edward Jenner showed in 1796 that cowpox protects against smallpox. Pasteur later made vaccines for rabies and anthrax, Koch identified the TB bacterium, and Fleming discovered penicillin.","difficulty":"moderate","source":"RRB NTPC · SSC CHSL","questionHi":"पहला टीका गाय की चेचक (काउपॉक्स) के घावों की सामग्री से चेचक के विरुद्ध लोगों को सुरक्षा देने के लिए विकसित किया गया था। यह किसने किया?","optionsHi":["लुई पाश्चर","एडवर्ड जेनर","रॉबर्ट कॉख","अलेक्ज़ेंडर फ्लेमिंग"],"explanationHi":"एडवर्ड जेनर ने 1796 में दिखाया कि काउपॉक्स चेचक से बचाता है। पाश्चर ने बाद में रेबीज़ और एंथ्रैक्स के टीके बनाए, कॉख ने क्षय रोग के जीवाणु की पहचान की, और फ्लेमिंग ने पेनिसिलिन की खोज की।"},
  {"id":"sci-biology-205","question":"Which blood vessel normally carries blood with the lowest concentration of urea?","options":["Hepatic vein","Renal artery","Renal vein","Pulmonary vein"],"answer":2,"explanation":"Urea is made in the liver (so the hepatic vein is rich in it) and removed by the kidneys, so blood leaving them in the renal vein has the least urea.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"कौन-सी रक्त वाहिका सामान्यतः यूरिया की सबसे कम सांद्रता वाला रक्त ले जाती है?","optionsHi":["यकृत शिरा","वृक्क धमनी","वृक्क शिरा","फुफ्फुसीय शिरा"],"explanationHi":"यूरिया यकृत में बनता है (इसलिए यकृत शिरा में इसकी मात्रा अधिक होती है) और वृक्कों द्वारा निकाला जाता है, इसलिए वृक्क शिरा में वृक्कों से निकलने वाले रक्त में यूरिया सबसे कम होता है।"},
  {"id":"sci-biology-206","question":"The first heart sound, ‘lub’, is produced mainly by the:","options":["Closing of the AV (tricuspid and bicuspid) valves as ventricles contract","Closing of the semilunar valves at the base of the aorta and pulmonary artery","Opening of the atrioventricular valves as the atria contract","Rush of blood from the left ventricle into the aorta"],"answer":0,"explanation":"‘Lub’ comes from the closure of the AV valves at the start of ventricular contraction; ‘dub’ comes from the closure of the semilunar valves when the ventricles relax.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"पहली हृदय ध्वनि ‘लब’ मुख्यतः किसके कारण उत्पन्न होती है?","optionsHi":["निलयों के संकुचन के समय AV (त्रिकपर्दी और द्विकपर्दी) कपाटों के बंद होने से","महाधमनी और फुफ्फुसीय धमनी के आधार पर अर्धचंद्राकार कपाटों के बंद होने से","अलिंदों के संकुचन के समय अलिंद-निलय कपाटों के खुलने से","बाएँ निलय से महाधमनी में रक्त के तेजी से बहने से"],"explanationHi":"‘लब’ निलयी संकुचन के आरंभ में AV कपाटों के बंद होने से आती है; ‘डब’ निलयों के शिथिलन के समय अर्धचंद्राकार कपाटों के बंद होने से आती है।"},
  {"id":"sci-biology-207","question":"Each heartbeat begins as an electrical impulse from a small patch of specialised tissue in the wall of the right atrium, called the natural pacemaker. It is the:","options":["Atrioventricular (AV) node","Sino-atrial (SA) node","Bundle of His","Purkinje fibres"],"answer":1,"explanation":"The SA node starts each beat; the impulse then passes to the AV node, the bundle of His and the Purkinje fibres, which spread it through the ventricles.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"प्रत्येक हृदय स्पंदन दाएँ अलिंद की दीवार में स्थित विशिष्ट ऊतक के एक छोटे-से भाग से विद्युत आवेग के रूप में शुरू होता है, जिसे प्राकृतिक गति-निर्धारक (पेसमेकर) कहते हैं। यह है:","optionsHi":["अलिंद-निलय (AV) पर्व","शिरा-अलिंद (SA) पर्व","हिस का बंडल","पुर्किंजे तंतु"],"explanationHi":"SA पर्व प्रत्येक स्पंदन आरंभ करता है; आवेग फिर AV पर्व, हिस के बंडल और पुर्किंजे तंतुओं में जाता है, जो उसे निलयों में फैला देते हैं।"},
  {"id":"sci-biology-208","question":"On a humid day at 35 °C we feel far more uncomfortable than on a dry day at the same temperature, because:","options":["Humid air contains less oxygen, so we breathe harder","Sweat glands stop secreting sweat when the outside air is humid","Humid air conducts heat into the body much faster","Sweat evaporates slowly into moist air, so it cools us less"],"answer":3,"explanation":"Sweating cools the body only when sweat evaporates, taking latent heat from the skin; in humid air evaporation is slow, so cooling is poor.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"35 °C पर उमस भरे दिन हमें उसी तापमान के शुष्क दिन की तुलना में कहीं अधिक बेचैनी होती है, क्योंकि:","optionsHi":["आर्द्र वायु में ऑक्सीजन कम होती है, इसलिए हम अधिक जोर से साँस लेते हैं","बाहर की वायु आर्द्र होने पर स्वेद ग्रंथियाँ पसीना बनाना बंद कर देती हैं","आर्द्र वायु ऊष्मा को शरीर में कहीं अधिक तेजी से चालित करती है","पसीना नम वायु में धीरे वाष्पित होता है, इसलिए हमें कम ठंडक मिलती है"],"explanationHi":"पसीना तभी ठंडक देता है जब वह वाष्पित होकर त्वचा से गुप्त ऊष्मा लेता है; आर्द्र वायु में वाष्पन धीमा होता है, इसलिए शीतलन कम होता है।"},
  {"id":"sci-biology-209","question":"A piece of plain bread chewed for a long time begins to taste sweet. This is because:","options":["Salivary amylase digests the starch in bread into sugar","Saliva itself contains sugar that mixes with the chewed bread","The bread releases the glucose it already contained","The taste buds get tired and start sensing sweetness"],"answer":0,"explanation":"Salivary amylase (ptyalin) digests starch into maltose, a sugar, which we taste as sweet.","difficulty":"moderate","source":"RRB Group D · SSC MTS","questionHi":"साधारण ब्रेड को देर तक चबाने पर वह मीठी लगने लगती है। इसका कारण यह है कि:","optionsHi":["लार का एमाइलेज ब्रेड के स्टार्च को शर्करा में पचा देता है","लार में स्वयं शर्करा होती है जो चबाई हुई ब्रेड में मिल जाती है","ब्रेड अपने भीतर पहले से मौजूद ग्लूकोज को मुक्त कर देती है","स्वाद कलिकाएँ थक जाती हैं और मिठास का अनुभव करने लगती हैं"],"explanationHi":"लार का एमाइलेज (टायलिन) स्टार्च को माल्टोज़ में, जो एक शर्करा है, पचा देता है, जिसे हम मीठे के रूप में चखते हैं।"},
  {"id":"sci-biology-210","question":"The stomach contains strong hydrochloric acid and the protein-digesting enzyme pepsin, yet it does not normally digest its own wall. The main reason is that:","options":["The stomach wall is made of fat, which pepsin cannot digest","A layer of mucus secreted by the stomach lining protects it","Hydrochloric acid stops pepsin from working","Bile from the liver neutralises the acid in the stomach"],"answer":1,"explanation":"Mucus protects the inner lining from the acid and pepsin; if this protection fails, ulcers can form. HCl actually activates pepsin, and bile acts in the small intestine, not the stomach.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"आमाशय में प्रबल हाइड्रोक्लोरिक अम्ल और प्रोटीन पचाने वाला एंजाइम पेप्सिन होता है, फिर भी वह सामान्यतः अपनी ही दीवार को नहीं पचाता। इसका मुख्य कारण है:","optionsHi":["आमाशय की दीवार वसा की बनी होती है, जिसे पेप्सिन नहीं पचा सकता","आमाशय की परत द्वारा स्रावित श्लेष्मा की एक परत उसकी रक्षा करती है","हाइड्रोक्लोरिक अम्ल पेप्सिन को कार्य करने से रोक देता है","यकृत से आया पित्त आमाशय के अम्ल को उदासीन कर देता है"],"explanationHi":"श्लेष्मा भीतरी परत को अम्ल और पेप्सिन से बचाता है; यह सुरक्षा विफल हो जाए तो अल्सर बन सकते हैं। HCl वास्तव में पेप्सिन को सक्रिय करता है, और पित्त छोटी आँत में कार्य करता है, आमाशय में नहीं।"},
  {"id":"sci-biology-211","question":"Most peptic ulcers in the stomach and duodenum are now known to be linked to infection by:","options":["The yeast-like fungus Candida albicans","A virus of the hepatitis group","The protozoan Giardia lamblia","The bacterium Helicobacter pylori"],"answer":3,"explanation":"Helicobacter pylori infection damages the protective mucus lining; this discovery earned a Nobel Prize in 2005. Excess acid and painkillers make ulcers worse but the bacterium is the leading cause.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"आमाशय और ग्रहणी के अधिकांश पेप्टिक अल्सर अब किसके संक्रमण से जुड़े माने जाते हैं?","optionsHi":["यीस्ट जैसे कवक कैंडिडा एल्बिकैंस","हेपेटाइटिस समूह का एक विषाणु","प्रोटोज़ोआ जियार्डिया लैम्ब्लिया","जीवाणु हेलिकोबैक्टर पाइलोरी"],"explanationHi":"हेलिकोबैक्टर पाइलोरी का संक्रमण सुरक्षात्मक श्लेष्मा परत को क्षति पहुँचाता है; इस खोज के लिए 2005 में नोबेल पुरस्कार मिला। अधिक अम्ल और दर्द निवारक अल्सर को बढ़ाते हैं, परंतु इसका प्रमुख कारण यह जीवाणु है।"},
  {"id":"sci-biology-212","question":"After a meal rich in carbohydrates, the extra glucose in the blood is stored in the liver and muscles as the polysaccharide:","options":["Starch","Cellulose","Glycogen","Chitin"],"answer":2,"explanation":"Animals store glucose as glycogen; plants store it as starch, cellulose forms plant cell walls, and chitin forms insect exoskeletons and fungal cell walls.","difficulty":"moderate","source":"RRB NTPC · SSC CHSL","questionHi":"कार्बोहाइड्रेट से भरपूर भोजन के बाद रक्त का अतिरिक्त ग्लूकोज यकृत और पेशियों में किस पॉलिसैकेराइड के रूप में संचित होता है?","optionsHi":["स्टार्च","सेलुलोज","ग्लाइकोजन","काइटिन"],"explanationHi":"जंतु ग्लूकोज को ग्लाइकोजन के रूप में संचित करते हैं; पादप उसे स्टार्च के रूप में संचित करते हैं, सेलुलोज पादप कोशिका भित्ति बनाता है, और काइटिन कीटों के बाह्य कंकाल और कवक की कोशिका भित्ति बनाता है।"},
  {"id":"sci-biology-213","question":"During a sudden fright, adrenaline is released into the blood. Which of these effects does it produce? I. Faster heartbeat II. More blood diverted to skeletal muscles III. Faster digestion in the stomach IV. Faster breathing","options":["I and II only","I, II and IV only","I, III and IV only","All four"],"answer":1,"explanation":"Adrenaline prepares the body for action: the heart beats faster, breathing quickens and blood is diverted to the muscles, while blood to the digestive system is reduced, slowing digestion.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"अचानक भय लगने पर रक्त में एड्रीनलीन मुक्त होता है। इनमें से कौन-से प्रभाव वह उत्पन्न करता है? I. तेज हृदय धड़कन II. कंकाल पेशियों की ओर अधिक रक्त का मोड़ा जाना III. आमाशय में तेज पाचन IV. तेज श्वसन","optionsHi":["केवल I और II","केवल I, II और IV","केवल I, III और IV","सभी चार"],"explanationHi":"एड्रीनलीन शरीर को कार्य के लिए तैयार करता है: हृदय तेज धड़कता है, श्वसन तेज होता है और रक्त पेशियों की ओर मोड़ा जाता है, जबकि पाचन तंत्र को रक्त कम मिलता है, जिससे पाचन धीमा हो जाता है।"},
  {"id":"sci-biology-214","question":"In iodine deficiency, the thyroid gland swells to form a goitre. Why does lack of iodine make the gland bigger?","options":["Iodine normally keeps the gland small, so without iodine the gland swells up","Undigested iodine salts slowly collect inside the gland and enlarge it","Low thyroxine makes the pituitary release more TSH, which enlarges the gland","Lack of iodine lets bacteria infect the thyroid and make it swell"],"answer":2,"explanation":"The thyroid cannot make enough thyroxine without iodine; the pituitary responds by secreting more TSH, which stimulates the thyroid to enlarge (feedback control).","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"आयोडीन की कमी में थायरॉइड ग्रंथि फूलकर घेंघा (गॉयटर) बन जाती है। आयोडीन की कमी ग्रंथि को बड़ा क्यों बना देती है?","optionsHi":["आयोडीन सामान्यतः ग्रंथि को छोटा रखता है, इसलिए आयोडीन के बिना ग्रंथि फूल जाती है","अपचित आयोडीन लवण धीरे-धीरे ग्रंथि के भीतर जमा होकर उसे बड़ा कर देते हैं","थायरॉक्सिन कम होने पर पीयूष ग्रंथि अधिक TSH छोड़ती है, जो ग्रंथि को बड़ा कर देता है","आयोडीन की कमी से जीवाणु थायरॉइड को संक्रमित कर उसे सुजा देते हैं"],"explanationHi":"आयोडीन के बिना थायरॉइड पर्याप्त थायरॉक्सिन नहीं बना सकती; पीयूष ग्रंथि प्रतिक्रिया में अधिक TSH का स्राव करती है, जो थायरॉइड को बड़ा होने के लिए प्रेरित करता है (पुनर्भरण नियंत्रण)।"},
  {"id":"sci-biology-215","question":"Seeds are placed in water that has been boiled and cooled, with a layer of oil on top. Similar seeds are placed on moist cotton in open air. Only the second set germinates. This shows that germination needs:","options":["Light","Carbon dioxide","Soil","Oxygen (air)"],"answer":3,"explanation":"Boiling removes dissolved air and the oil layer stops it dissolving again, so the seeds get no oxygen for respiration. Both sets had water, so water is not the variable tested.","difficulty":"hard","source":"SSC CGL · RRB Group D","questionHi":"बीजों को उबालकर ठंडे किए गए पानी में रखा जाता है, जिसके ऊपर तेल की परत है। इसी प्रकार के बीजों को खुली हवा में नम रूई पर रखा जाता है। केवल दूसरा समूह अंकुरित होता है। इससे पता चलता है कि अंकुरण के लिए आवश्यक है:","optionsHi":["प्रकाश","कार्बन डाइऑक्साइड","मृदा","ऑक्सीजन (वायु)"],"explanationHi":"उबालने से घुली हुई वायु निकल जाती है और तेल की परत उसे दोबारा घुलने से रोकती है, इसलिए बीजों को श्वसन के लिए ऑक्सीजन नहीं मिलती। दोनों समूहों को जल मिला था, इसलिए जल परीक्षित चर नहीं है।"},
  {"id":"sci-biology-216","question":"Maize and grasses are pollinated by wind. Which set of features are their flowers most likely to have?","options":["Plenty of light, dry pollen and feathery stigmas","Bright, large petals and plenty of sweet nectar","Small amounts of heavy, sticky pollen grains","A strong scent that attracts insects from a distance"],"answer":0,"explanation":"Wind pollination is chancy, so such flowers make huge amounts of light, dry pollen and have large feathery stigmas to catch it; colour, scent and nectar attract animals and are not needed.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"मक्का और घासें वायु द्वारा परागित होती हैं। उनके पुष्पों में सबसे अधिक संभावना किन विशेषताओं के समूह की होती है?","optionsHi":["बहुत अधिक हल्के, शुष्क परागकण और पंखदार वर्तिकाग्र","चमकीली, बड़ी पंखुड़ियाँ और बहुत सारा मीठा मकरंद","भारी, चिपचिपे परागकणों की थोड़ी मात्रा","तेज गंध जो दूर से कीटों को आकर्षित करती है"],"explanationHi":"वायु परागण अनिश्चित होता है, इसलिए ऐसे पुष्प बहुत अधिक मात्रा में हल्के, शुष्क परागकण बनाते हैं और उन्हें पकड़ने के लिए बड़े पंखदार वर्तिकाग्र होते हैं; रंग, गंध और मकरंद जंतुओं को आकर्षित करते हैं और यहाँ आवश्यक नहीं हैं।"},
  {"id":"sci-biology-217","question":"Which of these birth-control methods also gives protection against sexually transmitted infections such as HIV?","options":["Oral contraceptive pills","Copper-T placed in the uterus","Condom","Vasectomy"],"answer":2,"explanation":"Only a barrier method like the condom prevents contact of body fluids. Pills, Copper-T and vasectomy can prevent pregnancy but give no protection against infections.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"इनमें से कौन-सी जन्म नियंत्रण विधि HIV जैसे यौन संचारित संक्रमणों से भी सुरक्षा देती है?","optionsHi":["खाने वाली गर्भनिरोधक गोलियाँ","गर्भाशय में लगाई गई कॉपर-T","कंडोम","पुरुष नसबंदी (वैसेक्टॉमी)"],"explanationHi":"केवल कंडोम जैसी अवरोधक विधि ही शरीर के तरलों के संपर्क को रोकती है। गोलियाँ, कॉपर-T और नसबंदी गर्भ को रोक सकती हैं, परंतु संक्रमणों से कोई सुरक्षा नहीं देतीं।"},
  {"id":"sci-biology-218","question":"Mangrove trees growing in salty, waterlogged mud have roots that grow upwards out of the mud, called pneumatophores. Their main function is to:","options":["Absorb excess salt from the sea water around them","Take in air for the respiration of buried roots","Anchor the plant firmly against waves and tides","Store food made in the leaves for the whole plant"],"answer":1,"explanation":"Waterlogged mud has very little oxygen, so these breathing roots, with pores called lenticels, bring air to the submerged root system.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"खारे, जलमग्न कीचड़ में उगने वाले मैंग्रोव वृक्षों की जड़ें कीचड़ से ऊपर की ओर बढ़ती हैं, जिन्हें श्वसन मूल (न्यूमेटोफोर) कहते हैं। इनका मुख्य कार्य है:","optionsHi":["अपने आसपास के समुद्री जल से अतिरिक्त नमक सोखना","दबी हुई जड़ों के श्वसन के लिए वायु ग्रहण करना","पौधे को लहरों और ज्वार के विरुद्ध मजबूती से टिकाए रखना","पत्तियों में बने भोजन को पूरे पौधे के लिए संचित करना"],"explanationHi":"जलमग्न कीचड़ में ऑक्सीजन बहुत कम होती है, इसलिए वातरंध्र नामक छिद्रों वाली ये श्वसन जड़ें डूबे हुए मूल तंत्र तक वायु पहुँचाती हैं।"},
  {"id":"sci-biology-219","question":"In a cactus, food is made mainly by the:","options":["Spines, which are modified leaves","Roots, which spread widely","Flowers, which are brightly coloured","Green, fleshy stem"],"answer":3,"explanation":"Cactus leaves are reduced to spines to cut water loss, so the green, flattened or fleshy stem carries out photosynthesis and stores water.","difficulty":"moderate","source":"RRB Group D · SSC MTS","questionHi":"नागफनी (कैक्टस) में भोजन मुख्यतः किसके द्वारा बनाया जाता है?","optionsHi":["काँटे, जो रूपांतरित पत्तियाँ हैं","जड़ें, जो दूर तक फैलती हैं","पुष्प, जो चमकीले रंग के होते हैं","हरा, मांसल तना"],"explanationHi":"नागफनी की पत्तियाँ जल की हानि घटाने के लिए काँटों में बदल गई हैं, इसलिए हरा, चपटा या मांसल तना प्रकाश संश्लेषण करता है और जल संचित करता है।"},
  {"id":"sci-biology-220","question":"Lichens are often absent from trees in industrial cities. This makes them useful indicators of air polluted especially by:","options":["Sulphur dioxide","Carbon dioxide","Carbon monoxide","Water vapour"],"answer":0,"explanation":"Lichens (an alga or cyanobacterium living with a fungus) absorb substances directly from the air and are very sensitive to sulphur dioxide, so they disappear where SO₂ pollution is high.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"औद्योगिक शहरों में पेड़ों पर लाइकेन प्रायः नहीं होते। इसलिए वे मुख्यतः किससे प्रदूषित वायु के उपयोगी सूचक हैं?","optionsHi":["सल्फर डाइऑक्साइड","कार्बन डाइऑक्साइड","कार्बन मोनोऑक्साइड","जलवाष्प"],"explanationHi":"लाइकेन (कवक के साथ रहने वाला शैवाल या सायनोबैक्टीरिया) पदार्थों को सीधे वायु से सोखते हैं और सल्फर डाइऑक्साइड के प्रति बहुत संवेदनशील होते हैं, इसलिए जहाँ SO₂ प्रदूषण अधिक होता है वहाँ वे लुप्त हो जाते हैं।"},
  {"id":"sci-biology-221","question":"Runoff carrying chemical fertilisers enters a pond. A few weeks later, many fish die. The main reason is that:","options":["The fertilisers are directly poisonous to the fish and their eggs","The fertilisers make the pond water far too salty for the fish to survive","Algae bloom, and bacteria decomposing the dead algae use up the oxygen","The algae release carbon dioxide that poisons the fish by day"],"answer":2,"explanation":"Nitrates and phosphates cause an algal bloom (eutrophication); dead algae are broken down by aerobic decomposers that use up the dissolved oxygen, so fish suffocate.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"रासायनिक उर्वरकों से युक्त अपवाह जल एक तालाब में पहुँचता है। कुछ सप्ताह बाद अनेक मछलियाँ मर जाती हैं। इसका मुख्य कारण है:","optionsHi":["उर्वरक मछलियों और उनके अंडों के लिए सीधे विषैले होते हैं","उर्वरक तालाब के जल को इतना खारा कर देते हैं कि मछलियाँ जीवित नहीं रह पातीं","शैवाल की बहुतायत हो जाती है और मृत शैवाल को अपघटित करने वाले जीवाणु ऑक्सीजन समाप्त कर देते हैं","शैवाल दिन में कार्बन डाइऑक्साइड छोड़ते हैं जो मछलियों को विषाक्त कर देती है"],"explanationHi":"नाइट्रेट और फॉस्फेट शैवाल प्रस्फुटन (सुपोषण) का कारण बनते हैं; मृत शैवाल को वायवीय अपघटक तोड़ते हैं जो घुली हुई ऑक्सीजन समाप्त कर देते हैं, इसलिए मछलियों का दम घुट जाता है।"},
  {"id":"sci-biology-222","question":"The idea that all cells arise only from pre-existing cells (‘omnis cellula e cellula’) was proposed by:","options":["Robert Hooke","Matthias Schleiden","Rudolf Virchow","Antonie van Leeuwenhoek"],"answer":2,"explanation":"Virchow (1855) added this idea to the cell theory of Schleiden and Schwann. Hooke named cells from cork in 1665, and Leeuwenhoek first saw free-living cells.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"यह विचार कि सभी कोशिकाएँ केवल पहले से मौजूद कोशिकाओं से ही उत्पन्न होती हैं (‘ओम्निस सेलुला ई सेलुला’) किसने प्रस्तावित किया?","optionsHi":["रॉबर्ट हुक","मैथियास श्लाइडन","रुडोल्फ विरचो","एंटोनी वैन ल्यूवेनहॉक"],"explanationHi":"विरचो (1855) ने श्लाइडन और श्वान के कोशिका सिद्धांत में यह विचार जोड़ा। हुक ने 1665 में कॉर्क से कोशिकाओं को नाम दिया, और ल्यूवेनहॉक ने पहली बार स्वतंत्र जीवित कोशिकाओं को देखा।"},
  {"id":"sci-biology-223","question":"Amoeba takes in food particles by:","options":["Absorbing them through tiny pores in its rigid cell wall","Engulfing them with pseudopodia to form a food vacuole","Sweeping them into a fixed mouth with its beating cilia","Digesting them outside the body and absorbing the products"],"answer":1,"explanation":"Amoeba has no cell wall and no fixed mouth; its flexible membrane pushes out pseudopodia that surround the food to form a food vacuole. Paramecium uses cilia to sweep food into its oral groove.","difficulty":"hard","source":"SSC CGL · RRB Group D","questionHi":"अमीबा भोजन के कणों को किस प्रकार ग्रहण करता है?","optionsHi":["अपनी कठोर कोशिका भित्ति के सूक्ष्म छिद्रों से सोखकर","पादाभों (कूटपादों) से घेरकर खाद्य धानी बनाकर","अपने गतिशील सिलिया से उन्हें एक निश्चित मुख में बुहारकर","शरीर के बाहर पचाकर और उसके उत्पादों को सोखकर"],"explanationHi":"अमीबा में कोशिका भित्ति और निश्चित मुख नहीं होता; उसकी लचीली झिल्ली कूटपाद निकालती है जो भोजन को घेरकर खाद्य धानी बना लेते हैं। पैरामीशियम सिलिया से भोजन को अपने मुख-खाँच में बुहारता है।"},
  {"id":"sci-biology-224","question":"Down syndrome, which causes characteristic facial features and learning difficulties, is caused by:","options":["An extra copy of chromosome 21","A missing X chromosome in a female","An extra X chromosome in a male","A recessive gene carried on the X chromosome"],"answer":0,"explanation":"Down syndrome is trisomy 21: three copies of chromosome 21, usually from an error in meiosis. A missing X gives Turner syndrome and XXY gives Klinefelter syndrome.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"डाउन सिंड्रोम, जिससे विशिष्ट चेहरे की बनावट और सीखने में कठिनाई होती है, किसके कारण होता है?","optionsHi":["गुणसूत्र 21 की एक अतिरिक्त प्रति","स्त्री में एक X गुणसूत्र का न होना","पुरुष में एक अतिरिक्त X गुणसूत्र","X गुणसूत्र पर स्थित एक अप्रभावी जीन"],"explanationHi":"डाउन सिंड्रोम त्रिसूत्रता 21 है: गुणसूत्र 21 की तीन प्रतियाँ, जो प्रायः अर्धसूत्री विभाजन की त्रुटि से होती है। X के न होने से टर्नर सिंड्रोम और XXY से क्लाइनफेल्टर सिंड्रोम होता है।"},
  {"id":"sci-biology-225","question":"Identical twins are always of the same sex, while fraternal twins may be a boy and a girl. The reason is that identical twins:","options":["Are born at the same time and always share one placenta in the uterus","Receive exactly the same set of genes from the mother alone","Are formed from two eggs fertilised by one and the same sperm","Arise from one zygote that splits, so share the same sex chromosomes"],"answer":3,"explanation":"One fertilised egg splitting into two embryos gives twins with identical chromosome sets, so the same XX or XY. Fraternal twins come from two different eggs fertilised by two different sperms.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"समरूप (एकसमान) जुड़वाँ सदैव एक ही लिंग के होते हैं, जबकि भ्रातृ जुड़वाँ लड़का और लड़की हो सकते हैं। इसका कारण यह है कि समरूप जुड़वाँ:","optionsHi":["एक ही समय पर जन्म लेते हैं और गर्भाशय में सदैव एक ही अपरा साझा करते हैं","केवल माता से जीनों का बिल्कुल एक-सा समूह प्राप्त करते हैं","एक ही शुक्राणु द्वारा निषेचित दो अंडाणुओं से बनते हैं","एक ही युग्मनज के विभाजित होने से बनते हैं, इसलिए लिंग गुणसूत्र भी समान होते हैं"],"explanationHi":"एक निषेचित अंडाणु के दो भ्रूणों में विभाजित होने से समान गुणसूत्र समूह वाले जुड़वाँ बनते हैं, इसलिए दोनों XX या दोनों XY होते हैं। भ्रातृ जुड़वाँ दो भिन्न अंडाणुओं से बनते हैं जो दो भिन्न शुक्राणुओं द्वारा निषेचित होते हैं।"},
  {"id":"sci-biology-226","question":"Dolly, the first mammal to be cloned from a cell taken from an adult body, was a:","options":["Sheep","Cow","Goat","Mouse"],"answer":0,"explanation":"Dolly the sheep was born in 1996 in Scotland, cloned by placing the nucleus of an adult udder cell into an egg cell whose own nucleus had been removed.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"डॉली, जो वयस्क शरीर से ली गई कोशिका से क्लोन किया गया पहला स्तनपायी था, एक:","optionsHi":["भेड़ थी","गाय थी","बकरी थी","चूहा थी"],"explanationHi":"भेड़ डॉली का जन्म 1996 में स्कॉटलैंड में हुआ, जिसे वयस्क थन कोशिका के केंद्रक को उस अंडाणु में डालकर क्लोन किया गया जिसका अपना केंद्रक निकाल दिया गया था।"},
  {"id":"sci-biology-227","question":"Milk is pasteurised by heating it to about 63 °C for 30 minutes (or 72 °C for 15 seconds) and then cooling it quickly. The purpose is to:","options":["Kill every microbe and spore present, so that the milk never spoils","Kill most disease-causing microbes while keeping taste and nutrients","Remove extra water from the milk and raise its fat content","Break down lactose so that the milk becomes easier to digest"],"answer":1,"explanation":"Pasteurisation is mild heating that destroys most pathogens; it does not sterilise, which is why pasteurised milk must still be refrigerated and used within days.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"दूध को लगभग 63 °C पर 30 मिनट (या 72 °C पर 15 सेकंड) तक गर्म करके शीघ्रता से ठंडा करके पाश्चुरीकृत किया जाता है। इसका उद्देश्य है:","optionsHi":["उपस्थित प्रत्येक सूक्ष्मजीव और बीजाणु को मार देना, ताकि दूध कभी खराब न हो","अधिकांश रोगकारक सूक्ष्मजीवों को मारना और स्वाद तथा पोषक तत्वों को बनाए रखना","दूध से अतिरिक्त जल निकालकर उसकी वसा की मात्रा बढ़ाना","लैक्टोज को तोड़ना ताकि दूध सरलता से पच सके"],"explanationHi":"पाश्चुरीकरण हल्का गर्म करना है जो अधिकांश रोगाणुओं को नष्ट कर देता है; यह निर्जर्मीकरण नहीं है, इसीलिए पाश्चुरीकृत दूध को फिर भी रेफ्रिजरेटर में रखना और कुछ दिनों में उपयोग करना होता है।"},
  {"id":"sci-biology-228","question":"A spoonful of curd added to warm milk turns the milk into curd in a few hours because:","options":["Yeast in the curd converts the milk sugar into alcohol and gas","The curd adds rennin, an enzyme that digests the fat in the milk","Lactobacillus turns milk sugar into lactic acid, which curdles the protein","The heat of the warm milk alone is enough to make the protein coagulate"],"answer":2,"explanation":"Lactic acid bacteria multiply in warm milk and ferment lactose to lactic acid; the acid makes the milk protein (casein) coagulate into curd.","difficulty":"hard","source":"RRB Group D · SSC MTS","questionHi":"गुनगुने दूध में एक चम्मच दही डालने से कुछ घंटों में दूध दही बन जाता है, क्योंकि:","optionsHi":["दही में उपस्थित यीस्ट दूध की शर्करा को ऐल्कोहॉल और गैस में बदल देता है","दही रेनिन एंजाइम जोड़ता है जो दूध की वसा को पचाता है","लैक्टोबैसिलस दूध की शर्करा को लैक्टिक अम्ल में बदल देता है, जो प्रोटीन को जमा देता है","गुनगुने दूध की गर्मी अकेले ही प्रोटीन को जमाने के लिए पर्याप्त है"],"explanationHi":"लैक्टिक अम्ल जीवाणु गुनगुने दूध में बढ़ते हैं और लैक्टोज का किण्वन करके लैक्टिक अम्ल बनाते हैं; यह अम्ल दूध के प्रोटीन (केसीन) को जमाकर दही बना देता है।"},
  {"id":"sci-biology-229","question":"Pickles and jams keep for months without spoiling mainly because:","options":["Salt and sugar react chemically with microbes and dissolve them","Strong salt or sugar draws water out of microbes by osmosis","Salt and sugar release oxygen that kills the anaerobic bacteria","Salt and sugar make the food too alkaline for microbes to grow"],"answer":1,"explanation":"In a strong salt or sugar solution any microbe loses water by osmosis and becomes dehydrated, so it cannot multiply.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"अचार और जैम महीनों तक खराब हुए बिना मुख्यतः इसलिए टिके रहते हैं क्योंकि:","optionsHi":["नमक और चीनी सूक्ष्मजीवों से रासायनिक अभिक्रिया करके उन्हें घोल देते हैं","तेज नमक या चीनी परासरण द्वारा सूक्ष्मजीवों से जल खींच लेती है","नमक और चीनी ऑक्सीजन मुक्त करते हैं जो अवायवीय जीवाणुओं को मार देती है","नमक और चीनी भोजन को इतना क्षारीय बना देते हैं कि सूक्ष्मजीव नहीं पनप सकते"],"explanationHi":"तेज नमक या चीनी के विलयन में कोई भी सूक्ष्मजीव परासरण द्वारा जल खो देता है और निर्जलित हो जाता है, इसलिए वह गुणित नहीं हो सकता।"},
  {"id":"sci-biology-230","question":"Certain bacteria in waterlogged soil convert nitrates back into free nitrogen gas, which returns to the air. This process is called:","options":["Nitrification","Nitrogen fixation","Ammonification","Denitrification"],"answer":3,"explanation":"Denitrification returns N₂ to the atmosphere. Nitrogen fixation turns N₂ into compounds, ammonification releases ammonia from dead matter, and nitrification turns ammonia into nitrites and nitrates.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"जलमग्न मृदा में कुछ जीवाणु नाइट्रेटों को पुनः मुक्त नाइट्रोजन गैस में बदल देते हैं, जो वायु में लौट जाती है। इस प्रक्रिया को कहते हैं:","optionsHi":["नाइट्रीकरण","नाइट्रोजन स्थिरीकरण","अमोनीकरण","विनाइट्रीकरण"],"explanationHi":"विनाइट्रीकरण N₂ को वायुमंडल में लौटाता है। नाइट्रोजन स्थिरीकरण N₂ को यौगिकों में बदलता है, अमोनीकरण मृत पदार्थ से अमोनिया मुक्त करता है, और नाइट्रीकरण अमोनिया को नाइट्राइट तथा नाइट्रेट में बदलता है।"},
  {"id":"sci-biology-231","question":"A person with blood group B has:","options":["B antigens on the red cells and anti-A antibodies in the plasma","A antigens on the red cells and anti-B antibodies in the plasma","B antigens on the red cells and anti-B antibodies in the plasma","No antigens on the red cells and both anti-A and anti-B antibodies"],"answer":0,"explanation":"Blood group is named after the antigen on the red cells; the plasma carries antibodies against the antigen the person does not have. Having anti-B with B antigen would make one's own blood clump.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"रक्त समूह B वाले व्यक्ति में होता है:","optionsHi":["लाल कोशिकाओं पर B प्रतिजन और प्लाज्मा में anti-A प्रतिरक्षी","लाल कोशिकाओं पर A प्रतिजन और प्लाज्मा में anti-B प्रतिरक्षी","लाल कोशिकाओं पर B प्रतिजन और प्लाज्मा में anti-B प्रतिरक्षी","लाल कोशिकाओं पर कोई प्रतिजन नहीं और प्लाज्मा में anti-A तथा anti-B दोनों प्रतिरक्षी"],"explanationHi":"रक्त समूह का नाम लाल कोशिकाओं पर उपस्थित प्रतिजन के आधार पर रखा जाता है; प्लाज्मा में उस प्रतिजन के विरुद्ध प्रतिरक्षी होते हैं जो व्यक्ति में नहीं है। B प्रतिजन के साथ anti-B होने पर व्यक्ति का अपना रक्त ही चिपक जाता।"},
  {"id":"sci-biology-232","question":"A person who steps on a rusty nail is given an anti-tetanus injection. Tetanus is actually caused by:","options":["Iron oxide (rust) from the nail entering the bloodstream","A virus that survives for years on metal surfaces","A fungus that grows on rusted iron in damp places","A bacterium whose spores live in soil, dust and dung"],"answer":3,"explanation":"Tetanus is caused by the bacterium Clostridium tetani, whose spores enter deep wounds; rusty objects are risky only because they are often dirty and make deep punctures, not because of rust itself.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"जंग लगी कील पर पैर पड़ने वाले व्यक्ति को टिटनेस-रोधी इंजेक्शन दिया जाता है। टिटनेस वास्तव में किससे होता है?","optionsHi":["कील से रक्तधारा में प्रवेश करने वाले आयरन ऑक्साइड (जंग) से","धातु की सतहों पर वर्षों तक जीवित रहने वाले विषाणु से","नम स्थानों में जंग लगे लोहे पर उगने वाले कवक से","ऐसे जीवाणु से जिसके बीजाणु मिट्टी, धूल और गोबर में रहते हैं"],"explanationHi":"टिटनेस क्लॉस्ट्रिडियम टेटानी जीवाणु से होता है, जिसके बीजाणु गहरे घावों में प्रवेश करते हैं; जंग लगी वस्तुएँ इसलिए जोखिम भरी हैं क्योंकि वे प्रायः गंदी होती हैं और गहरा घाव करती हैं, जंग के कारण नहीं।"},
  {"id":"sci-biology-233","question":"The Widal test is a blood test commonly used to help diagnose:","options":["Malaria","Typhoid","Tuberculosis","Dengue"],"answer":1,"explanation":"The Widal test detects antibodies against Salmonella typhi, the bacterium that causes typhoid. Malaria is diagnosed by examining a blood smear for the parasite.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"विडाल परीक्षण एक रक्त परीक्षण है जिसका सामान्यतः किस रोग के निदान में सहायता के लिए उपयोग होता है?","optionsHi":["मलेरिया","टाइफाइड","क्षय रोग (तपेदिक)","डेंगू"],"explanationHi":"विडाल परीक्षण साल्मोनेला टाइफी, जो टाइफाइड का जीवाणु है, के विरुद्ध प्रतिरक्षियों का पता लगाता है। मलेरिया का निदान रक्त के धब्बे में परजीवी की जाँच से होता है।"},
  {"id":"sci-biology-234","question":"Leprosy, a disease that damages the skin and nerves, is caused by a:","options":["Virus","Fungus","Bacterium","Protozoan"],"answer":2,"explanation":"Leprosy is caused by the bacterium Mycobacterium leprae and is curable with multi-drug therapy (a combination of antibiotics).","difficulty":"moderate","source":"RRB Group D · SSC MTS","questionHi":"कुष्ठ रोग (लेप्रोसी), जो त्वचा और तंत्रिकाओं को क्षति पहुँचाता है, किसके कारण होता है?","optionsHi":["विषाणु","कवक","जीवाणु","प्रोटोज़ोआ"],"explanationHi":"कुष्ठ रोग माइकोबैक्टीरियम लेप्री जीवाणु से होता है और बहु-औषधि चिकित्सा (प्रतिजैविकों के संयोजन) से ठीक हो जाता है।"},
  {"id":"sci-biology-235","question":"Elephantiasis (filariasis), which causes great swelling of the legs, is caused by ___ and spread by the ___ mosquito.","options":["A virus; Aedes","A protozoan; Anopheles","A bacterium; housefly","A roundworm; Culex"],"answer":3,"explanation":"Filariasis is caused by the thread-like roundworm Wuchereria, which blocks lymph vessels, and is spread by Culex mosquitoes. Aedes spreads dengue and Anopheles spreads malaria.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"फाइलेरिया (हाथीपाँव), जिसमें पैरों में बहुत सूजन आ जाती है, ___ के कारण होता है और ___ मच्छर द्वारा फैलता है।","optionsHi":["विषाणु; एडीज़","प्रोटोज़ोआ; ऐनोफ़िलीज़","जीवाणु; घरेलू मक्खी","गोलकृमि; क्यूलेक्स"],"explanationHi":"फाइलेरिया धागे जैसे गोलकृमि वुचेरेरिया से होता है, जो लसीका वाहिकाओं को अवरुद्ध कर देता है, और क्यूलेक्स मच्छरों द्वारा फैलता है। एडीज़ डेंगू और ऐनोफ़िलीज़ मलेरिया फैलाता है।"},
  {"id":"sci-biology-236","question":"Kala-azar, which causes fever and an enlarged spleen and is found in parts of Bihar and Jharkhand, is spread by the bite of the:","options":["Sandfly","Tsetse fly","Housefly","Culex mosquito"],"answer":0,"explanation":"Kala-azar is caused by the protozoan Leishmania and spread by sandflies. The tsetse fly spreads sleeping sickness, another protozoan disease.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"कालाज़ार, जिसमें बुखार और प्लीहा का बढ़ना होता है और जो बिहार तथा झारखंड के कुछ भागों में पाया जाता है, किसके काटने से फैलता है?","optionsHi":["बालू मक्खी (सैंडफ्लाई)","सी-सी मक्खी (ट्सेट्सी)","घरेलू मक्खी","क्यूलेक्स मच्छर"],"explanationHi":"कालाज़ार प्रोटोज़ोआ लीशमैनिया से होता है और बालू मक्खियों द्वारा फैलता है। सी-सी मक्खी निद्रा रोग फैलाती है, जो एक अन्य प्रोटोज़ोआजनित रोग है।"},
  {"id":"sci-biology-237","question":"A child with severe diarrhoea is given oral rehydration solution (ORS). Its main purpose is to:","options":["Kill the bacteria that are causing the diarrhoea","Replace the water and salts lost from the body","Provide proteins that repair the damaged intestine","Slow down the movement of the intestines"],"answer":1,"explanation":"The main danger in diarrhoea and cholera is dehydration; ORS (water, salts and a little sugar) replaces lost water and electrolytes. It does not kill microbes.","difficulty":"moderate","source":"RRB Group D · SSC MTS","questionHi":"गंभीर दस्त से पीड़ित बच्चे को मौखिक पुनर्जलीकरण घोल (ORS) दिया जाता है। इसका मुख्य उद्देश्य है:","optionsHi":["दस्त पैदा करने वाले जीवाणुओं को मारना","शरीर से निकले जल और लवणों की पूर्ति करना","क्षतिग्रस्त आँत की मरम्मत के लिए प्रोटीन देना","आँतों की गति को धीमा करना"],"explanationHi":"दस्त और हैजे में मुख्य खतरा निर्जलीकरण है; ORS (जल, लवण और थोड़ी शर्करा) खोए हुए जल और विद्युत-अपघट्यों की पूर्ति करता है। यह सूक्ष्मजीवों को नहीं मारता।"},
  {"id":"sci-biology-238","question":"Roughage (dietary fibre) is an important part of a balanced diet even though humans cannot digest it. Its main benefit is that it:","options":["Is the body's main and quickest source of energy","Provides the essential amino acids needed for growth","Adds bulk that helps bowel movement and prevents constipation","Supplies the vitamins and minerals the body needs to fight infection"],"answer":2,"explanation":"Fibre such as cellulose is not digested in humans but holds water and adds bulk, which helps bowel movement.","difficulty":"moderate","source":"RRB Group D · SSC MTS","questionHi":"रूक्षांश (आहारी रेशे) संतुलित आहार का महत्वपूर्ण भाग हैं, जबकि मनुष्य उन्हें पचा नहीं सकते। इनका मुख्य लाभ यह है कि ये:","optionsHi":["शरीर के लिए ऊर्जा का मुख्य और सबसे शीघ्र स्रोत हैं","वृद्धि के लिए आवश्यक अनिवार्य अमीनो अम्ल प्रदान करते हैं","आयतन बढ़ाकर मल त्याग में सहायता करते हैं और कब्ज को रोकते हैं","संक्रमण से लड़ने के लिए शरीर को आवश्यक विटामिन और खनिज देते हैं"],"explanationHi":"सेलुलोज जैसे रेशे मनुष्यों में पचते नहीं, परंतु जल को रोकते हैं और आयतन बढ़ाते हैं, जिससे मल त्याग में सहायता मिलती है।"},
  {"id":"sci-biology-239","question":"Gram for gram, which nutrient gives the body the most energy when fully oxidised?","options":["Fats","Carbohydrates","Proteins","Vitamins"],"answer":0,"explanation":"Fats give about 9 kcal per gram, more than twice the roughly 4 kcal per gram of carbohydrates and proteins. Carbohydrates are the main and quickest source, not the richest; vitamins give no energy.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"प्रति ग्राम के आधार पर, पूर्ण ऑक्सीकरण होने पर कौन-सा पोषक तत्व शरीर को सबसे अधिक ऊर्जा देता है?","optionsHi":["वसा","कार्बोहाइड्रेट","प्रोटीन","विटामिन"],"explanationHi":"वसा लगभग 9 kcal प्रति ग्राम देती है, जो कार्बोहाइड्रेट और प्रोटीन के लगभग 4 kcal प्रति ग्राम के दोगुने से भी अधिक है। कार्बोहाइड्रेट मुख्य और सबसे शीघ्र स्रोत हैं, सबसे अधिक ऊर्जा देने वाले नहीं; विटामिन ऊर्जा नहीं देते।"},
  {"id":"sci-biology-240","question":"Match the organism with its mode of nutrition: A. Cuscuta (amarbel) B. Mushroom C. Lichen D. Pitcher plant; 1. Saprotrophic 2. Parasitic 3. Symbiotic 4. Insectivorous (also photosynthetic)","options":["A-1, B-2, C-3, D-4","A-2, B-3, C-1, D-4","A-2, B-1, C-4, D-3","A-2, B-1, C-3, D-4"],"answer":3,"explanation":"Cuscuta is a leafless parasite on host plants, mushrooms feed on dead matter, a lichen is an alga and a fungus living together, and the green pitcher plant traps insects for extra nitrogen.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"जीव का उसके पोषण की विधि से मिलान कीजिए: A. कस्कूटा (अमरबेल) B. मशरूम C. लाइकेन D. घटपर्णी; 1. मृतोपजीवी 2. परजीवी 3. सहजीवी 4. कीटभक्षी (प्रकाश संश्लेषी भी)","optionsHi":["A-1, B-2, C-3, D-4","A-2, B-3, C-1, D-4","A-2, B-1, C-4, D-3","A-2, B-1, C-3, D-4"],"explanationHi":"कस्कूटा परपोषी पौधों पर रहने वाला पर्णरहित परजीवी है, मशरूम मृत पदार्थ पर पोषित होते हैं, लाइकेन एक शैवाल और एक कवक का साथ रहने वाला सहजीवी संबंध है, और हरी घटपर्णी अतिरिक्त नाइट्रोजन के लिए कीटों को फँसाती है।"},
  {"id":"sci-biology-241","question":"Assertion (A): Mature human red blood cells cannot carry out aerobic respiration. Reason (R): Mature human red blood cells have no mitochondria.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Mature RBCs lose their nucleus and mitochondria, so they make ATP only by anaerobic breakdown of glucose; this also means they do not use up the oxygen they carry.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"अभिकथन (A): परिपक्व मानव लाल रक्त कोशिकाएँ वायवीय श्वसन नहीं कर सकतीं। कारण (R): परिपक्व मानव लाल रक्त कोशिकाओं में माइटोकॉन्ड्रिया नहीं होते।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"परिपक्व लाल रक्त कोशिकाएँ अपना केंद्रक और माइटोकॉन्ड्रिया खो देती हैं, इसलिए वे ग्लूकोज के अवायवीय विघटन से ही ATP बनाती हैं; इसका अर्थ यह भी है कि वे अपने द्वारा ले जाई जाने वाली ऑक्सीजन का उपयोग नहीं करतीं।"},
  {"id":"sci-biology-242","question":"Which of these statements about viruses are correct? I. They show signs of life only inside a living host cell. II. They can be grown on a nutrient medium in a dish, like bacteria. III. Some, such as tobacco mosaic virus, can be crystallised. IV. They contain either DNA or RNA as genetic material.","options":["I, III and IV only","I and II only","II, III and IV only","I, II, III and IV"],"answer":0,"explanation":"Viruses multiply only inside living cells, so they cannot be grown on a nutrient medium like bacteria; outside a host they can even be crystallised. Each virus has DNA or RNA, not both.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"विषाणुओं से संबंधित इनमें से कौन-से कथन सही हैं? I. वे केवल जीवित परपोषी कोशिका के भीतर ही जीवन के लक्षण दर्शाते हैं। II. उन्हें जीवाणुओं की तरह पोषक माध्यम पर पेट्री डिश में उगाया जा सकता है। III. कुछ, जैसे तंबाकू मोज़ेक विषाणु, क्रिस्टलीकृत किए जा सकते हैं। IV. उनमें आनुवंशिक पदार्थ के रूप में DNA या RNA होता है।","optionsHi":["केवल I, III और IV","केवल I और II","केवल II, III और IV","I, II, III और IV"],"explanationHi":"विषाणु केवल जीवित कोशिकाओं के भीतर ही गुणित होते हैं, इसलिए उन्हें जीवाणुओं की तरह पोषक माध्यम पर नहीं उगाया जा सकता; परपोषी के बाहर उन्हें क्रिस्टलीकृत भी किया जा सकता है। प्रत्येक विषाणु में DNA या RNA होता है, दोनों नहीं।"},
  {"id":"sci-biology-243","question":"How many of these statements about sex determination in humans are correct? I. Every egg carries an X chromosome. II. About half of all sperms carry a Y chromosome. III. The mother's egg decides whether the child will be a boy or a girl. IV. A child who receives an X chromosome from the father will be a girl.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Statements I, II and IV are correct. Since every egg carries X, it is the sperm (X or Y) that decides the sex of the child, so III is wrong.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"मनुष्यों में लिंग निर्धारण से संबंधित इनमें से कितने कथन सही हैं? I. प्रत्येक अंडाणु में X गुणसूत्र होता है। II. लगभग आधे शुक्राणुओं में Y गुणसूत्र होता है। III. माता का अंडाणु तय करता है कि संतान लड़का होगी या लड़की। IV. जिस संतान को पिता से X गुणसूत्र मिलता है, वह लड़की होगी।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"कथन I, II और IV सही हैं। चूँकि प्रत्येक अंडाणु में X होता है, इसलिए संतान का लिंग शुक्राणु (X या Y) तय करता है, अतः III गलत है।"},
  {"id":"sci-biology-244","question":"A pure tall pea plant (TT) is crossed with a pure dwarf plant (tt), and the F₁ plants are self-pollinated. Among the tall plants of the F₂ generation, what fraction will breed true (give only tall plants) on self-pollination?","options":["1/4","3/4","1/2","1/3"],"answer":3,"explanation":"F₂ is 1 TT : 2 Tt : 1 tt, so among the three tall plants only one (TT) is pure-breeding: 1/3. The trap 1/4 is the fraction of TT among all F₂ plants, not among the tall ones.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"शुद्ध लंबे मटर के पौधे (TT) का संकरण शुद्ध बौने पौधे (tt) से कराया जाता है और F₁ पौधों का स्वपरागण किया जाता है। F₂ पीढ़ी के लंबे पौधों में से कितना भाग स्वपरागण पर शुद्ध प्रजनन करेगा (केवल लंबे पौधे देगा)?","optionsHi":["1/4","3/4","1/2","1/3"],"explanationHi":"F₂ में 1 TT : 2 Tt : 1 tt होता है, इसलिए तीन लंबे पौधों में से केवल एक (TT) शुद्ध प्रजनन करने वाला है: 1/3। भ्रम का विकल्प 1/4 सभी F₂ पौधों में TT का अनुपात है, लंबे पौधों में नहीं।"},
  {"id":"sci-biology-245","question":"A person's daytime vision is normal, but he can hardly see in dim light. A deficiency of which vitamin is most likely?","options":["Vitamin B1","Vitamin A","Vitamin D","Vitamin E"],"answer":1,"explanation":"Rod cells of the retina, used in dim light, need a pigment made from vitamin A; its lack causes night blindness. B1 deficiency causes beriberi and D deficiency causes rickets.","difficulty":"moderate","source":"RRB Group D · SSC MTS","questionHi":"एक व्यक्ति की दिन की दृष्टि सामान्य है, परंतु वह मंद प्रकाश में मुश्किल से देख पाता है। किस विटामिन की कमी की सबसे अधिक संभावना है?","optionsHi":["विटामिन B1","विटामिन A","विटामिन D","विटामिन E"],"explanationHi":"दृष्टिपटल की शलाका कोशिकाओं को, जो मंद प्रकाश में कार्य करती हैं, विटामिन A से बने वर्णक की आवश्यकता होती है; इसकी कमी से रतौंधी होती है। B1 की कमी से बेरी-बेरी और D की कमी से रिकेट्स होता है।"},
  {"id":"sci-biology-246","question":"In a neuron, a nerve impulse normally travels in which direction?","options":["Axon → cell body → dendrites → nerve ending","Cell body → dendrites → axon → nerve ending","Nerve ending → axon → cell body → dendrites","Dendrites → cell body → axon → nerve ending"],"answer":3,"explanation":"Dendrites pick up the signal, it passes through the cell body and along the axon to its endings, where chemicals are released to cross the synapse to the next cell.","difficulty":"hard","source":"SSC CGL · RRB Group D","questionHi":"न्यूरॉन में तंत्रिका आवेग सामान्यतः किस दिशा में चलता है?","optionsHi":["तंत्रिकाक्ष → कोशिका काय → द्रुमिकाएँ → तंत्रिका अंत","कोशिका काय → द्रुमिकाएँ → तंत्रिकाक्ष → तंत्रिका अंत","तंत्रिका अंत → तंत्रिकाक्ष → कोशिका काय → द्रुमिकाएँ","द्रुमिकाएँ → कोशिका काय → तंत्रिकाक्ष → तंत्रिका अंत"],"explanationHi":"द्रुमिकाएँ संकेत ग्रहण करती हैं, वह कोशिका काय से होकर तंत्रिकाक्ष के साथ उसके सिरों तक जाता है, जहाँ रसायन मुक्त होकर अगली कोशिका तक सिनैप्स पार करते हैं।"},
  {"id":"sci-biology-247","question":"A person who has drunk too much alcohol walks unsteadily and cannot keep his balance. This is mainly because alcohol affects the:","options":["Medulla oblongata","Hypothalamus","Cerebellum","Pituitary gland"],"answer":2,"explanation":"The cerebellum coordinates muscle movements and maintains posture and balance, so its impairment causes staggering. The medulla controls heartbeat and breathing.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"अधिक शराब पीने वाला व्यक्ति लड़खड़ाकर चलता है और संतुलन नहीं रख पाता। यह मुख्यतः इसलिए होता है क्योंकि शराब प्रभावित करती है:","optionsHi":["मेडुला ऑब्लांगेटा को","हाइपोथैलेमस को","अनुमस्तिष्क को","पीयूष ग्रंथि को"],"explanationHi":"अनुमस्तिष्क पेशियों की गतियों का समन्वय करता है और मुद्रा तथा संतुलन बनाए रखता है, इसलिए इसके बाधित होने से लड़खड़ाहट होती है। मेडुला हृदय गति और श्वसन को नियंत्रित करता है।"},
  {"id":"sci-biology-248","question":"Which structure is usually absent from the cells of flowering plants but present in animal cells?","options":["Centrioles","Mitochondria","Golgi apparatus","Endoplasmic reticulum"],"answer":0,"explanation":"Animal cells have a pair of centrioles that help in cell division; cells of higher plants generally lack them. Mitochondria, Golgi bodies and ER occur in both.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"कौन-सी संरचना सामान्यतः पुष्पीय पादपों की कोशिकाओं में नहीं होती परंतु जंतु कोशिकाओं में होती है?","optionsHi":["तारककेंद्र (सेंट्रीओल)","माइटोकॉन्ड्रिया","गॉल्जी उपकरण","अंतःप्रद्रव्यी जालिका"],"explanationHi":"जंतु कोशिकाओं में तारककेंद्रों का एक जोड़ा होता है जो कोशिका विभाजन में सहायता करता है; उच्च पादपों की कोशिकाओं में ये सामान्यतः नहीं होते। माइटोकॉन्ड्रिया, गॉल्जी काय और अंतःप्रद्रव्यी जालिका दोनों में होते हैं।"},
  {"id":"sci-biology-249","question":"Which of these cell structures is found in both a bacterial cell and a human cell?","options":["Mitochondria","Nucleus bounded by a membrane","Endoplasmic reticulum","Ribosomes"],"answer":3,"explanation":"All living cells need ribosomes to make proteins. Bacteria are prokaryotes, lacking a membrane-bound nucleus and membrane-bound organelles like mitochondria and ER.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"इनमें से कौन-सी कोशिकीय संरचना जीवाणु कोशिका और मानव कोशिका, दोनों में पाई जाती है?","optionsHi":["माइटोकॉन्ड्रिया","झिल्ली से घिरा केंद्रक","अंतःप्रद्रव्यी जालिका","राइबोसोम"],"explanationHi":"प्रोटीन बनाने के लिए सभी जीवित कोशिकाओं को राइबोसोम की आवश्यकता होती है। जीवाणु प्रोकैरियोट हैं, जिनमें झिल्ली से घिरा केंद्रक और माइटोकॉन्ड्रिया तथा अंतःप्रद्रव्यी जालिका जैसे झिल्लीयुक्त कोशिकांग नहीं होते।"},
  {"id":"sci-biology-250","question":"When a Planaria is cut into several pieces, each piece grows into a complete animal. This ability is called:","options":["Regeneration","Fragmentation","Budding","Binary fission"],"answer":0,"explanation":"Regeneration rebuilds a whole organism from a body part using specialised cells. Fragmentation, as in Spirogyra, is the natural breaking of the body as a regular means of reproduction.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"जब प्लैनेरिया को कई टुकड़ों में काटा जाता है, तो प्रत्येक टुकड़ा एक पूर्ण जंतु में विकसित हो जाता है। इस क्षमता को कहते हैं:","optionsHi":["पुनरुद्भवन (रीजेनरेशन)","खंडन","मुकुलन","द्विविखंडन"],"explanationHi":"पुनरुद्भवन विशिष्ट कोशिकाओं की सहायता से शरीर के किसी भाग से पूरे जीव का पुनर्निर्माण करता है। खंडन, जैसा स्पाइरोगाइरा में होता है, जनन के नियमित साधन के रूप में शरीर का प्राकृतिक रूप से टूटना है।"},
  {"id":"sci-biology-251","question":"E. coli bacteria grown for many generations in a medium with heavy nitrogen (¹⁵N) are shifted to a medium with ordinary nitrogen (¹⁴N). After three rounds of DNA replication, what fraction of the DNA molecules has one ¹⁵N strand and one ¹⁴N strand?","options":["1/2","1/4","1/8","3/4"],"answer":1,"explanation":"Replication is semi-conservative, so the two original ¹⁵N strands always end up in just two molecules. After three rounds there are 8 molecules: 2 hybrid (1/4) and 6 made wholly of ¹⁴N.","difficulty":"very-hard","questionHi":"E. coli जीवाणुओं को कई पीढ़ियों तक भारी नाइट्रोजन (¹⁵N) वाले माध्यम में उगाया गया, फिर उन्हें सामान्य नाइट्रोजन (¹⁴N) वाले माध्यम में रखा गया। DNA का तीन बार द्विगुणन होने के बाद, DNA के कितने भाग में एक रज्जुक ¹⁵N का और दूसरा ¹⁴N का है?","optionsHi":["1/2","1/4","1/8","3/4"],"explanationHi":"द्विगुणन अर्ध-संरक्षी होता है, इसलिए मूल दोनों ¹⁵N रज्जुक केवल दो अणुओं में ही रहते हैं। तीन चक्रों के बाद कुल 8 अणु बनते हैं: 2 संकर (1/4) और 6 पूरी तरह ¹⁴N वाले।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-252","question":"In a double-stranded DNA sample, adenine makes up 30% of the nucleotides. What percentage of the nucleotides is cytosine?","options":["10%","30%","40%","20%"],"answer":3,"explanation":"Base pairing gives A = T = 30%, so A + T = 60%. The remaining 40% is shared equally by G and C, so cytosine is 20%.","difficulty":"moderate","questionHi":"दोहरे रज्जुक वाले एक DNA नमूने में एडेनीन 30% न्यूक्लियोटाइड है। साइटोसीन कितने प्रतिशत न्यूक्लियोटाइड है?","optionsHi":["10%","30%","40%","20%"],"explanationHi":"क्षार युग्मन से A = T = 30%, अतः A + T = 60%। शेष 40% को G और C बराबर बाँट लेते हैं, इसलिए साइटोसीन 20% है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-253","question":"The coding region of a gene, from the start codon up to and including the stop codon, specifies a protein of 150 amino acids. How many nucleotides does this region of the mRNA contain?","options":["453","450","456","300"],"answer":0,"explanation":"150 amino acids need 150 codons, and the stop codon adds one more: 151 codons × 3 = 453 nucleotides. The stop codon codes for no amino acid but is still part of the mRNA.","difficulty":"hard","questionHi":"एक जीन का कूटलेखन क्षेत्र, प्रारंभ कोडॉन से लेकर समापन कोडॉन तक (उसे मिलाकर), 150 अमीनो अम्ल वाले प्रोटीन को निर्दिष्ट करता है। mRNA के इस क्षेत्र में कितने न्यूक्लियोटाइड होते हैं?","optionsHi":["453","450","456","300"],"explanationHi":"150 अमीनो अम्लों के लिए 150 कोडॉन चाहिए और समापन कोडॉन एक और जोड़ता है: 151 कोडॉन × 3 = 453 न्यूक्लियोटाइड। समापन कोडॉन किसी अमीनो अम्ल को कूटबद्ध नहीं करता, फिर भी वह mRNA का भाग है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-254","question":"How many chromatids are present in a human primary spermatocyte at the beginning of meiosis I, after the DNA has replicated?","options":["23","46","92","184"],"answer":2,"explanation":"The cell has 46 chromosomes; after the S phase each consists of two sister chromatids, so there are 92 chromatids. The chromosome number (counted by centromeres) is still 46.","difficulty":"very-hard","questionHi":"अर्धसूत्री विभाजन I के प्रारंभ में, DNA के द्विगुणन के बाद, मानव प्राथमिक शुक्राणु कोशिका (प्राथमिक स्पर्मेटोसाइट) में कितने क्रोमैटिड होते हैं?","optionsHi":["23","46","92","184"],"explanationHi":"कोशिका में 46 गुणसूत्र होते हैं; S प्रावस्था के बाद प्रत्येक में दो सहोदर क्रोमैटिड होते हैं, अतः कुल 92 क्रोमैटिड होते हैं। गुणसूत्रों की संख्या (सेंट्रोमियर गिनने पर) अब भी 46 ही रहती है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-255","question":"A girl with Turner syndrome has which chromosome make-up in her body cells?","options":["47 chromosomes with sex chromosomes XXY","45 chromosomes with a single X as her only sex chromosome","47 chromosomes with sex chromosomes XXX","45 chromosomes because one copy of chromosome 21 is missing"],"answer":1,"explanation":"Turner syndrome is XO: 44 autosomes plus one X gives 45 chromosomes. XXY is Klinefelter syndrome and trisomy 21 is Down syndrome, both with 47.","difficulty":"hard","questionHi":"टर्नर सिंड्रोम वाली एक लड़की की शरीर कोशिकाओं में गुणसूत्र संरचना क्या होती है?","optionsHi":["47 गुणसूत्र, लिंग गुणसूत्र XXY","45 गुणसूत्र, एकमात्र लिंग गुणसूत्र एक X","47 गुणसूत्र, लिंग गुणसूत्र XXX","45 गुणसूत्र, क्योंकि गुणसूत्र 21 की एक प्रति नहीं है"],"explanationHi":"टर्नर सिंड्रोम XO होता है: 44 अलिंग गुणसूत्र और एक X मिलकर 45 गुणसूत्र बनाते हैं। XXY क्लाइनफेल्टर सिंड्रोम है और ट्राइसोमी 21 डाउन सिंड्रोम है, दोनों में 47 गुणसूत्र होते हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-256","question":"A haemophilic woman (XʰXʰ) marries a normal man (XY). What can be expected in their children?","options":["All daughters are haemophilic and all sons are normal","Half of the sons and half of the daughters are haemophilic","All sons are haemophilic and all daughters are carriers","All sons and all daughters are carriers but none is haemophilic"],"answer":2,"explanation":"Every son receives her Xʰ and the father's Y, so he is haemophilic. Every daughter receives Xʰ from her and a normal X from the father, so she is a carrier.","difficulty":"very-hard","questionHi":"एक haemophilic (हीमोफीलिया पीड़ित) स्त्री (XʰXʰ) का विवाह एक सामान्य पुरुष (XY) से होता है। उनकी संतानों में क्या अपेक्षित है?","optionsHi":["सभी पुत्रियाँ हीमोफीलिया पीड़ित और सभी पुत्र सामान्य","आधे पुत्र और आधी पुत्रियाँ हीमोफीलिया पीड़ित","सभी पुत्र हीमोफीलिया पीड़ित और सभी पुत्रियाँ वाहक","सभी पुत्र और पुत्रियाँ वाहक हैं, पर कोई पीड़ित नहीं"],"explanationHi":"प्रत्येक पुत्र को माँ का Xʰ और पिता का Y मिलता है, इसलिए वह पीड़ित होता है। प्रत्येक पुत्री को माँ से Xʰ और पिता से सामान्य X मिलता है, इसलिए वह वाहक होती है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-257","question":"Both parents are carriers (Aa) of the recessive allele for albinism. What is the probability that, among their three children, exactly two have normal pigmentation?","options":["27/64","9/64","9/16","3/8"],"answer":0,"explanation":"Each child is normal with probability 3/4 and albino with 1/4. Exactly two normal out of three: 3 × (3/4)² × (1/4) = 27/64. The value 9/64 is the chance of exactly two albino children.","difficulty":"very-hard","questionHi":"माता-पिता दोनों ऐल्बिनिज़्म के अप्रभावी ऐलील के वाहक (Aa) हैं। उनके तीन बच्चों में से ठीक दो का वर्णक (रंजकता) सामान्य होने की प्रायिकता क्या है?","optionsHi":["27/64","9/64","9/16","3/8"],"explanationHi":"प्रत्येक बच्चा 3/4 प्रायिकता से सामान्य और 1/4 से ऐल्बिनो होता है। तीन में से ठीक दो सामान्य: 3 × (3/4)² × (1/4) = 27/64। 9/64 ठीक दो ऐल्बिनो बच्चों की प्रायिकता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-258","question":"A man of blood group B whose mother had group O marries a woman of group AB. What is the probability that their child has blood group A?","options":["1/2","3/4","1/8","1/4"],"answer":3,"explanation":"The man must be IᴮI° (he got i from his mother), the woman is IᴬIᴮ. The four equally likely children are IᴬIᴮ, IᴮIᴮ, IᴬI° and IᴮI°, so only IᴬI° (group A) is 1/4. Group B has probability 1/2.","difficulty":"very-hard","questionHi":"रक्त समूह B वाले एक पुरुष की माता का रक्त समूह O था। उसका विवाह रक्त समूह AB वाली स्त्री से होता है। उनके बच्चे का रक्त समूह A होने की प्रायिकता क्या है?","optionsHi":["1/2","3/4","1/8","1/4"],"explanationHi":"पुरुष का जीनप्ररूप IᴮI° होगा (उसे माता से i मिला), स्त्री IᴬIᴮ है। चार समसंभावी संतानें IᴬIᴮ, IᴮIᴮ, IᴬI° और IᴮI° हैं, इसलिए केवल IᴬI° (समूह A) की प्रायिकता 1/4 है। समूह B की प्रायिकता 1/2 है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-259","question":"After a lawn is mown, the grass grows back quickly from its base. Which tissue is responsible for this regrowth?","options":["Apical meristem at the tip of the shoot and the growing buds","Intercalary meristem at the base of the leaves","Lateral meristem (cambium) of the stem and the roots","Parenchyma tissue of the leaf blade and the leaf sheath"],"answer":1,"explanation":"Grasses have intercalary meristems at the base of leaves and nodes, so growth continues even after the leaf tips are removed. The apical meristem is cut off with the shoot tip and cambium adds thickness, not length.","difficulty":"hard","questionHi":"लॉन की घास काट देने के बाद वह अपने आधार से तेज़ी से फिर उग आती है। इस पुनर्वृद्धि के लिए कौन-सा ऊतक उत्तरदायी है?","optionsHi":["प्ररोह के शीर्ष और वर्धी कलिकाओं पर शीर्षस्थ विभज्योतक","पत्तियों के आधार पर अंतर्वेशी विभज्योतक","तने और जड़ों का पार्श्व विभज्योतक (एधा)","पत्ती के फलक और आच्छद का मृदूतक ऊतक"],"explanationHi":"घासों में पत्तियों और पर्वसंधियों के आधार पर अंतर्वेशी विभज्योतक होते हैं, इसलिए पत्ती का सिरा कटने पर भी वृद्धि चलती रहती है। शीर्षस्थ विभज्योतक प्ररोह के सिरे के साथ कट जाता है और एधा मोटाई बढ़ाती है, लंबाई नहीं।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-260","question":"How many of these statements about plant tissues are correct? I. Mature xylem vessels and tracheids are dead cells. II. Sieve tube elements are living, although they have no nucleus when mature. III. Companion cells are associated with the sieve tubes of phloem. IV. Collenchyma has cell walls thickened with lignin.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Collenchyma walls are thickened with cellulose and pectin at the corners, while lignin thickening is typical of sclerenchyma and xylem.","difficulty":"very-hard","questionHi":"पादप ऊतकों के बारे में इनमें से कितने कथन सही हैं? I. परिपक्व जाइलम वाहिकाएँ और वाहिनिकाएँ मृत कोशिकाएँ होती हैं। II. चालनी नलिका तत्व जीवित होते हैं, यद्यपि परिपक्व अवस्था में उनमें केंद्रक नहीं होता। III. सहचर कोशिकाएँ फ्लोएम की चालनी नलिकाओं से संबद्ध होती हैं। IV. स्थूलकोण ऊतक (कॉलेन्काइमा) की कोशिका भित्ति लिग्निन से मोटी होती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। स्थूलकोण ऊतक की भित्ति कोनों पर सेल्युलोस और पेक्टिन से मोटी होती है, जबकि लिग्निन का मोटापन दृढ़ोतक और जाइलम की विशेषता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-261","question":"Which tissue forms the very thin lining of the lung alveoli and of the walls of blood capillaries, allowing quick diffusion of gases?","options":["Simple cuboidal epithelium","Simple columnar epithelium","Stratified squamous epithelium","Simple squamous epithelium"],"answer":3,"explanation":"Simple squamous epithelium is a single layer of flat cells, so the diffusion distance is tiny. Stratified squamous epithelium (as in skin) has many layers and protects instead.","difficulty":"moderate","questionHi":"कौन-सा ऊतक फेफड़ों की वायुकोशिकाओं और रुधिर केशिकाओं की दीवारों का अत्यंत पतला अस्तर बनाता है, जिससे गैसों का तेज़ विसरण हो पाता है?","optionsHi":["सरल घनाकार उपकला","सरल स्तंभाकार उपकला","स्तरित शल्की उपकला","सरल शल्की उपकला"],"explanationHi":"सरल शल्की उपकला चपटी कोशिकाओं की एक ही परत होती है, इसलिए विसरण की दूरी बहुत कम होती है। स्तरित शल्की उपकला (जैसे त्वचा में) कई परतों की होती है और सुरक्षा देती है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-262","question":"Which of these body parts contains no cartilage?","options":["Lobe of the ear","Tip of the nose","Epiglottis","Outer ear flap (pinna)"],"answer":0,"explanation":"The earlobe is only skin, fat and connective tissue. The pinna, the tip of the nose and the epiglottis are all supported by cartilage, which is why they bend and spring back.","difficulty":"hard","questionHi":"शरीर के इनमें से किस भाग में उपास्थि (कार्टिलेज) नहीं होती?","optionsHi":["कान की लौ","नाक की नोक","घाँटी ढक्कन (एपिग्लॉटिस)","बाह्य कर्ण पल्लव (पिन्ना)"],"explanationHi":"कान की लौ केवल त्वचा, वसा और संयोजी ऊतक की होती है। कर्ण पल्लव, नाक की नोक और एपिग्लॉटिस उपास्थि से सहारा पाते हैं, इसीलिए वे मुड़कर फिर अपनी जगह आ जाते हैं।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-263","question":"Which event takes place in meiosis I but never in mitosis?","options":["Duplication of DNA before the division begins","Alignment of chromosomes at the equator of the cell","Pairing of homologous chromosomes and exchange of segments between them","Formation of spindle fibres from the poles of the cell"],"answer":2,"explanation":"Synapsis (pairing of homologues) and crossing over occur in prophase I of meiosis only. DNA replication, metaphase alignment and spindle formation occur in mitosis as well.","difficulty":"hard","questionHi":"कौन-सी घटना अर्धसूत्री विभाजन I में होती है, पर समसूत्री विभाजन में कभी नहीं होती?","optionsHi":["विभाजन शुरू होने से पहले DNA का द्विगुणन","कोशिका की मध्य रेखा पर गुणसूत्रों का पंक्तिबद्ध होना","समजात गुणसूत्रों का युग्मन और उनके बीच खंडों का आदान-प्रदान","कोशिका के ध्रुवों से तर्कु तंतुओं का बनना"],"explanationHi":"सूत्रयुग्मन (समजातों का युग्मन) और जीन विनिमय केवल अर्धसूत्री विभाजन की प्रोफ़ेज़ I में होते हैं। DNA द्विगुणन, मेटाफ़ेज़ में पंक्तिबद्धता और तर्कु का बनना समसूत्री विभाजन में भी होते हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-264","question":"A flowering plant has 24 chromosomes in its leaf cells. How many chromosomes are present in the primary endosperm nucleus formed after double fertilisation?","options":["24","36","18","48"],"answer":1,"explanation":"Each gamete carries 12 chromosomes. The primary endosperm nucleus forms when one male gamete (12) fuses with the two polar nuclei (12 + 12), giving 36, which is triploid (3n).","difficulty":"very-hard","questionHi":"एक पुष्पी पादप की पत्ती कोशिकाओं में 24 गुणसूत्र होते हैं। द्विनिषेचन के बाद बने प्राथमिक भ्रूणपोष केंद्रक में कितने गुणसूत्र होते हैं?","optionsHi":["24","36","18","48"],"explanationHi":"प्रत्येक युग्मक में 12 गुणसूत्र होते हैं। एक नर युग्मक (12) दो ध्रुवीय केंद्रकों (12 + 12) से मिलकर प्राथमिक भ्रूणपोष केंद्रक बनाता है, जिसमें 36 गुणसूत्र होते हैं और वह त्रिगुणित (3n) होता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-265","question":"Seedless bananas develop fruits without any fertilisation of the ovule. This process is called:","options":["Parthenogenesis","Apomixis","Polyembryony","Parthenocarpy"],"answer":3,"explanation":"Parthenocarpy is fruit formation without fertilisation, giving seedless fruits. Apomixis and parthenogenesis produce seeds or embryos without fertilisation, and polyembryony means several embryos in one seed.","difficulty":"moderate","questionHi":"बीजरहित केले में बीजांड के निषेचन के बिना ही फल बन जाता है। इस प्रक्रिया को क्या कहते हैं?","optionsHi":["अनिषेकजनन (पार्थेनोजेनेसिस)","असंगजनन (एपोमिक्सिस)","बहुभ्रूणता","अनिषेकफलन (पार्थेनोकार्पी)"],"explanationHi":"निषेचन के बिना फल बनना अनिषेकफलन है, जिससे बीजरहित फल मिलते हैं। असंगजनन और अनिषेकजनन में निषेचन के बिना बीज या भ्रूण बनता है, और बहुभ्रूणता का अर्थ एक बीज में कई भ्रूण होना है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-266","question":"Which of these seeds shows hypogeal germination, in which the cotyledons stay below the soil surface?","options":["Gram (chickpea)","Castor","Bean","Cucumber"],"answer":0,"explanation":"In hypogeal germination the epicotyl elongates and the cotyledons remain underground, as in gram, pea and maize. Castor, bean and cucumber show epigeal germination: the hypocotyl lifts the cotyledons above the soil.","difficulty":"hard","questionHi":"इनमें से किस बीज में अधोभूमिक अंकुरण होता है, जिसमें बीजपत्र मिट्टी की सतह के नीचे ही रहते हैं?","optionsHi":["चना","अरंडी","सेम","खीरा"],"explanationHi":"अधोभूमिक अंकुरण में एपिकोटिल लंबा होता है और बीजपत्र भूमि के नीचे ही रहते हैं, जैसे चना, मटर और मक्का में। अरंडी, सेम और खीरे में उपरिभूमिक अंकुरण होता है: हाइपोकोटिल बीजपत्रों को मिट्टी के ऊपर उठा देता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-267","question":"Which sequence correctly shows the passage of sperms from their site of formation to the outside?","options":["Seminiferous tubule → vas deferens → epididymis → urethra","Epididymis → seminiferous tubule → vas deferens → urethra","Seminiferous tubule → epididymis → vas deferens → urethra","Seminiferous tubule → epididymis → urethra → vas deferens"],"answer":2,"explanation":"Sperms form in the seminiferous tubules, mature and are stored in the epididymis, travel through the vas deferens (joined by seminal vesicle secretion at the ejaculatory duct) and leave through the urethra.","difficulty":"hard","questionHi":"कौन-सा क्रम शुक्राणुओं के बनने के स्थान से शरीर के बाहर तक के मार्ग को सही दर्शाता है?","optionsHi":["शुक्रजनक नलिका → शुक्रवाहिका → अधिवृषण → मूत्रमार्ग","अधिवृषण → शुक्रजनक नलिका → शुक्रवाहिका → मूत्रमार्ग","शुक्रजनक नलिका → अधिवृषण → शुक्रवाहिका → मूत्रमार्ग","शुक्रजनक नलिका → अधिवृषण → मूत्रमार्ग → शुक्रवाहिका"],"explanationHi":"शुक्राणु शुक्रजनक नलिकाओं में बनते हैं, अधिवृषण में परिपक्व होकर संचित रहते हैं, शुक्रवाहिका से गुज़रते हैं (स्खलन वाहिनी पर शुक्राशय का स्राव मिलता है) और मूत्रमार्ग से बाहर निकलते हैं।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-268","question":"The testes lie outside the abdominal cavity in the scrotum because sperm formation needs:","options":["a higher oxygen supply than is available inside the abdomen","a temperature about 2–3 °C lower than the body temperature","protection from hormones that circulate in the blood","a lower pressure than the one inside the abdomen"],"answer":1,"explanation":"Spermatogenesis works best a little below core body temperature, which the scrotum provides. In cryptorchidism, where the testes stay in the abdomen, sperm production is impaired.","difficulty":"moderate","questionHi":"वृषण उदर गुहा के बाहर वृषणकोष में स्थित होते हैं, क्योंकि शुक्राणु निर्माण के लिए आवश्यक है:","optionsHi":["उदर के भीतर उपलब्ध मात्रा से अधिक ऑक्सीजन की आपूर्ति","शरीर के तापमान से लगभग 2–3 °C कम तापमान","रक्त में घूमने वाले हॉर्मोनों से सुरक्षा","उदर के भीतर के दाब से कम दाब"],"explanationHi":"शुक्राणुजनन शरीर के आंतरिक तापमान से थोड़े कम तापमान पर सबसे अच्छा होता है, जो वृषणकोष प्रदान करता है। अधोवृषणता (क्रिप्टोर्किडिज़्म) में वृषण उदर में ही रह जाते हैं और शुक्राणु निर्माण बाधित हो जाता है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-269","question":"Home pregnancy test kits detect which hormone in the urine?","options":["LH, the hormone that surges just before ovulation","FSH, the hormone that matures the follicle","Progesterone, the hormone of the corpus luteum","hCG, the hormone made by the developing placenta"],"answer":3,"explanation":"hCG (human chorionic gonadotropin) is made by the trophoblast and placenta only in pregnancy, and it rises rapidly in the first weeks. Progesterone is also high in pregnancy but is present in every luteal phase, so it is not a specific marker.","difficulty":"hard","questionHi":"घर पर प्रयोग की जाने वाली गर्भावस्था जाँच किट मूत्र में किस हॉर्मोन का पता लगाती है?","optionsHi":["LH, वह हॉर्मोन जो अंडोत्सर्ग से ठीक पहले बढ़ता है","FSH, वह हॉर्मोन जो पुटिका को परिपक्व करता है","प्रोजेस्टेरोन, पीत पिंड का हॉर्मोन","hCG, विकसित हो रहे अपरा द्वारा बनाया जाने वाला हॉर्मोन"],"explanationHi":"hCG (ह्यूमन कोरियॉनिक गोनैडोट्रॉपिन) केवल गर्भावस्था में ट्रोफोब्लास्ट और अपरा द्वारा बनता है और पहले सप्ताहों में तेज़ी से बढ़ता है। प्रोजेस्टेरोन भी गर्भावस्था में अधिक होता है, पर वह हर ल्यूटियल प्रावस्था में मौजूद रहता है, इसलिए विशिष्ट संकेतक नहीं है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-270","question":"In a woman with a regular menstrual cycle of 30 days (day 1 is the first day of bleeding), ovulation is expected on about which day?","options":["10","14","16","20"],"answer":2,"explanation":"The luteal phase is fairly constant at about 14 days, so ovulation falls about 14 days before the next menstruation: 30 − 14 = day 16. Day 14 holds only for a 28-day cycle.","difficulty":"very-hard","questionHi":"30 दिन के नियमित ऋतुस्राव चक्र वाली स्त्री में (रक्तस्राव का पहला दिन दिन 1 मानें), अंडोत्सर्ग लगभग किस दिन होने की संभावना है?","optionsHi":["10","14","16","20"],"explanationHi":"ल्यूटियल प्रावस्था लगभग 14 दिन की स्थिर रहती है, इसलिए अंडोत्सर्ग अगले ऋतुस्राव से लगभग 14 दिन पहले होता है: 30 − 14 = दिन 16। दिन 14 केवल 28 दिन के चक्र के लिए सही है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-271","question":"A copper-T placed in the uterus prevents pregnancy mainly by:","options":["reducing the movement of sperms and making the uterus unsuitable for implantation","blocking the oviducts so that the egg cannot travel down to the uterus","stopping ovulation by supplying extra oestrogen to the blood","killing the sperms in the vagina with a chemical film on its surface"],"answer":0,"explanation":"Copper ions released by the intrauterine device lower sperm motility and fertilising ability and make the uterine lining unfavourable for implantation. It does not stop ovulation, unlike hormonal pills.","difficulty":"hard","questionHi":"गर्भाशय में लगाया गया कॉपर-T मुख्य रूप से किस प्रकार गर्भधारण रोकता है?","optionsHi":["शुक्राणुओं की गति घटाकर और गर्भाशय को रोपण के लिए अनुपयुक्त बनाकर","अंडवाहिनियों को अवरुद्ध करके ताकि अंडा गर्भाशय तक न पहुँच सके","रक्त में अतिरिक्त ईस्ट्रोजन देकर अंडोत्सर्ग रोककर","अपनी सतह पर लगी रासायनिक परत से योनि में शुक्राणुओं को मारकर"],"explanationHi":"अंतःगर्भाशयी युक्ति से निकलने वाले कॉपर आयन शुक्राणुओं की गतिशीलता और निषेचन क्षमता घटाते हैं और गर्भाशय की परत को रोपण के प्रतिकूल बना देते हैं। हॉर्मोन गोलियों के विपरीत यह अंडोत्सर्ग नहीं रोकता।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-272","question":"Which Indian law bans sex determination of the foetus, with the aim of preventing female foeticide?","options":["The MTP Act, 1971","The PCPNDT Act, 1994","The POCSO Act, 2012","The Dowry Prohibition Act, 1961"],"answer":1,"explanation":"The Pre-Conception and Pre-Natal Diagnostic Techniques (PCPNDT) Act, 1994 prohibits prenatal sex determination, for example through ultrasound or amniocentesis. The MTP Act, 1971 regulates legal termination of pregnancy.","difficulty":"moderate","questionHi":"भारत का कौन-सा कानून कन्या भ्रूण हत्या रोकने के उद्देश्य से भ्रूण के लिंग निर्धारण पर प्रतिबंध लगाता है?","optionsHi":["MTP अधिनियम, 1971","PCPNDT अधिनियम, 1994","POCSO अधिनियम, 2012","दहेज प्रतिषेध अधिनियम, 1961"],"explanationHi":"गर्भधारण-पूर्व और प्रसव-पूर्व निदान तकनीक (PCPNDT) अधिनियम, 1994 अल्ट्रासाउंड या एम्नियोसेंटेसिस जैसे साधनों से जन्म-पूर्व लिंग निर्धारण को प्रतिबंधित करता है। MTP अधिनियम, 1971 गर्भ के वैध समापन को नियंत्रित करता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-273","question":"Before birth, which blood vessel carries oxygen-rich blood from the placenta to the foetus?","options":["Umbilical artery","Pulmonary vein","Hepatic portal vein","Umbilical vein"],"answer":3,"explanation":"The umbilical vein brings oxygenated, nutrient-rich blood from the placenta to the foetus, while the two umbilical arteries return deoxygenated blood to it. This reverses the usual rule that arteries carry oxygenated blood.","difficulty":"hard","questionHi":"जन्म से पहले कौन-सी रुधिर वाहिका ऑक्सीजन-समृद्ध रक्त को अपरा से भ्रूण तक ले जाती है?","optionsHi":["नाभि धमनी","फुफ्फुस शिरा","यकृत निवाहिका शिरा","नाभि शिरा"],"explanationHi":"नाभि शिरा अपरा से ऑक्सीजन और पोषक तत्वों से भरपूर रक्त भ्रूण तक लाती है, जबकि दो नाभि धमनियाँ ऑक्सीजनरहित रक्त को वापस अपरा तक ले जाती हैं। यह धमनियों में ऑक्सीजनित रक्त होने के सामान्य नियम का अपवाद है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-274","question":"Oxytocin and vasopressin (ADH) are released from the posterior pituitary, but they are actually synthesised in the:","options":["Hypothalamus","Anterior pituitary","Adrenal medulla","Thalamus"],"answer":0,"explanation":"These two hormones are made by neurosecretory cells of the hypothalamus and travel along their axons to the posterior pituitary, which only stores and releases them.","difficulty":"moderate","questionHi":"ऑक्सीटोसिन और वैसोप्रेसिन (ADH) पश्च पीयूष ग्रंथि से मुक्त होते हैं, पर वास्तव में इनका संश्लेषण कहाँ होता है?","optionsHi":["अधश्चेतक (हाइपोथैलेमस)","अग्र पीयूष ग्रंथि","अधिवृक्क मेडुला","चेतक (थैलेमस)"],"explanationHi":"ये दोनों हॉर्मोन अधश्चेतक की तंत्रिकास्रावी कोशिकाओं में बनते हैं और उनके एक्सॉनों के सहारे पश्च पीयूष ग्रंथि तक पहुँचते हैं, जो इन्हें केवल संचित करके मुक्त करती है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-275","question":"Weakness, low blood pressure, low blood sodium and darkening of the skin point to underactivity of which gland?","options":["Adrenal medulla","Posterior pituitary","Adrenal cortex","Parathyroid gland"],"answer":2,"explanation":"These are signs of Addison's disease, caused by too little cortisol and aldosterone from the adrenal cortex; sodium is lost and ACTH rises, which darkens the skin. The adrenal medulla makes adrenaline.","difficulty":"hard","questionHi":"कमज़ोरी, निम्न रक्तचाप, रक्त में सोडियम की कमी और त्वचा का गहरा पड़ना किस ग्रंथि की अल्प सक्रियता की ओर संकेत करते हैं?","optionsHi":["अधिवृक्क मेडुला","पश्च पीयूष ग्रंथि","अधिवृक्क वल्कुट (कॉर्टेक्स)","परावटु ग्रंथि"],"explanationHi":"ये एडिसन रोग के लक्षण हैं, जो अधिवृक्क वल्कुट से कॉर्टिसोल और ऐल्डोस्टेरोन कम बनने के कारण होता है; सोडियम की हानि होती है और ACTH बढ़ने से त्वचा गहरी पड़ जाती है। अधिवृक्क मेडुला ऐड्रीनलीन बनाता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-276","question":"In a healthy adult the tidal volume is 500 mL, inspiratory reserve volume 3000 mL, expiratory reserve volume 1100 mL and residual volume 1200 mL. What is the inspiratory capacity (the largest volume that can be breathed in after a normal quiet expiration)?","options":["3500 mL","5800 mL","4600 mL","2300 mL"],"answer":0,"explanation":"Inspiratory capacity = tidal volume + inspiratory reserve volume = 500 + 3000 = 3500 mL. The 4600 mL figure is the vital capacity (adds ERV), 5800 mL is the total lung capacity and 2300 mL is the functional residual capacity.","difficulty":"very-hard","questionHi":"एक स्वस्थ वयस्क में ज्वारीय आयतन 500 mL, प्रश्वसन आरक्षित आयतन 3000 mL, निःश्वसन आरक्षित आयतन 1100 mL और अवशिष्ट आयतन 1200 mL है। उसकी प्रश्वसन क्षमता (सामान्य शांत निःश्वास के बाद अंदर ली जा सकने वाली अधिकतम वायु) कितनी है?","optionsHi":["3500 mL","5800 mL","4600 mL","2300 mL"],"explanationHi":"प्रश्वसन क्षमता = ज्वारीय आयतन + प्रश्वसन आरक्षित आयतन = 500 + 3000 = 3500 mL। 4600 mL जैव क्षमता है (इसमें ERV जुड़ता है), 5800 mL कुल फेफड़ा क्षमता है और 2300 mL कार्यात्मक अवशिष्ट क्षमता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-277","question":"A 100 g food sample contains 20 g protein, 10 g fat and 50 g carbohydrate, the rest being water and fibre. Using 4 kcal/g for protein and carbohydrate and 9 kcal/g for fat, what is its energy value?","options":["370 kcal","420 kcal","320 kcal","470 kcal"],"answer":0,"explanation":"Energy = 20 × 4 + 10 × 9 + 50 × 4 = 80 + 90 + 200 = 370 kcal. Using 9 kcal/g for protein too gives 470, and using 4 kcal/g for fat gives 320.","difficulty":"very-hard","questionHi":"100 g के एक खाद्य नमूने में 20 g प्रोटीन, 10 g वसा और 50 g कार्बोहाइड्रेट है, शेष जल और रेशा है। प्रोटीन और कार्बोहाइड्रेट के लिए 4 kcal/g तथा वसा के लिए 9 kcal/g मानकर उसका ऊर्जा मान कितना है?","optionsHi":["370 kcal","420 kcal","320 kcal","470 kcal"],"explanationHi":"ऊर्जा = 20 × 4 + 10 × 9 + 50 × 4 = 80 + 90 + 200 = 370 kcal। प्रोटीन के लिए भी 9 kcal/g लेने पर 470 और वसा के लिए 4 kcal/g लेने पर 320 आता है।","source":"RRB NTPC · SSC CGL"},
  {"id":"sci-biology-278","question":"Blood serum differs from blood plasma mainly in lacking:","options":["Albumin","Antibodies","Water","Fibrinogen"],"answer":3,"explanation":"When blood clots, fibrinogen and the other clotting factors are used up, and the straw-coloured fluid left is serum. Albumin, antibodies and water are present in both plasma and serum.","difficulty":"hard","questionHi":"रक्त सीरम और रक्त प्लाज़्मा में मुख्य अंतर यह है कि सीरम में नहीं होता:","optionsHi":["ऐल्ब्यूमिन","प्रतिरक्षी","जल","फाइब्रिनोजन"],"explanationHi":"रक्त के थक्का बनने पर फाइब्रिनोजन और अन्य स्कंदन कारक प्रयुक्त हो जाते हैं और शेष पीले रंग का द्रव सीरम होता है। ऐल्ब्यूमिन, प्रतिरक्षी और जल प्लाज़्मा और सीरम दोनों में होते हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-279","question":"The pus that forms at the site of a bacterial wound consists mainly of dead cells of which white blood cell type?","options":["Lymphocytes","Neutrophils","Basophils","Eosinophils"],"answer":1,"explanation":"Neutrophils are the most abundant WBCs and the first to reach an infection, where they engulf bacteria and die, forming pus. Eosinophils mainly act in allergy and parasitic infections, and basophils release histamine.","difficulty":"very-hard","questionHi":"जीवाणु संक्रमित घाव पर बनने वाला मवाद मुख्यतः किस प्रकार की श्वेत रुधिर कोशिकाओं की मृत कोशिकाओं से बना होता है?","optionsHi":["लिम्फोसाइट","न्यूट्रोफिल","बेसोफिल","ईओसिनोफिल"],"explanationHi":"न्यूट्रोफिल सबसे अधिक संख्या वाली श्वेत रुधिर कोशिकाएँ हैं और संक्रमण स्थल पर सबसे पहले पहुँचती हैं, जहाँ वे जीवाणुओं को निगलकर मर जाती हैं और मवाद बनता है। ईओसिनोफिल मुख्यतः एलर्जी और परजीवी संक्रमण में कार्य करती हैं तथा बेसोफिल हिस्टामिन मुक्त करती हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-280","question":"T-lymphocytes complete their maturation in which organ, which is relatively large in childhood and shrinks after puberty?","options":["Spleen","Bone marrow","Thymus","Tonsils"],"answer":2,"explanation":"Immature T cells from the bone marrow mature in the thymus, which is most active in childhood and gradually shrinks after puberty. B cells mature in the bone marrow itself.","difficulty":"hard","questionHi":"T-लिम्फोसाइट किस अंग में परिपक्व होती हैं, जो बचपन में अपेक्षाकृत बड़ा होता है और यौवन के बाद सिकुड़ जाता है?","optionsHi":["प्लीहा","अस्थि मज्जा","थाइमस","टॉन्सिल"],"explanationHi":"अस्थि मज्जा से आई अपरिपक्व T कोशिकाएँ थाइमस में परिपक्व होती हैं, जो बचपन में सबसे सक्रिय रहता है और यौवन के बाद धीरे-धीरे सिकुड़ता है। B कोशिकाएँ अस्थि मज्जा में ही परिपक्व होती हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-281","question":"In sickle cell anaemia, the abnormal haemoglobin results from a change in:","options":["one amino acid of the beta chain of globin (glutamic acid replaced by valine)","the iron atom of haem, which is replaced by a different metal","the whole alpha chain of globin, which fails to be made","the number of haem groups, which falls from four to two"],"answer":0,"explanation":"A single base change in the gene for the beta chain replaces glutamic acid by valine, so the haemoglobin crystallises at low oxygen and bends red cells into a sickle shape. Haem and its iron are normal.","difficulty":"very-hard","questionHi":"दात्र कोशिका अरक्तता (सिकल सेल एनीमिया) में असामान्य हीमोग्लोबिन किसमें परिवर्तन के कारण बनता है?","optionsHi":["ग्लोबिन की बीटा शृंखला के एक अमीनो अम्ल में (ग्लूटैमिक अम्ल के स्थान पर वैलीन)","हीम के लौह परमाणु में, जिसका स्थान कोई अन्य धातु ले लेती है","ग्लोबिन की संपूर्ण ऐल्फा शृंखला में, जो बन ही नहीं पाती","हीम समूहों की संख्या में, जो चार से घटकर दो रह जाती है"],"explanationHi":"बीटा शृंखला के जीन में एक क्षार परिवर्तन से ग्लूटैमिक अम्ल के स्थान पर वैलीन आ जाता है, जिससे कम ऑक्सीजन पर हीमोग्लोबिन क्रिस्टलित होकर लाल रुधिर कोशिकाओं को हँसिये का आकार दे देता है। हीम और उसका लोहा सामान्य रहते हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-282","question":"In cattle, cellulose of the fodder is digested with the help of microorganisms living in which part of the stomach?","options":["Abomasum (true stomach)","Omasum","Small intestine","Rumen"],"answer":3,"explanation":"The rumen is a large fermentation chamber whose bacteria and protozoa break down cellulose, since the animal itself makes no cellulase. The abomasum is the true, acid-secreting stomach.","difficulty":"moderate","questionHi":"पशुओं (गाय-भैंस) में चारे का सेल्युलोस आमाशय के किस भाग में रहने वाले सूक्ष्मजीवों की सहायता से पचता है?","optionsHi":["अबोमेसम (वास्तविक आमाशय)","ओमेसम","छोटी आँत","रूमेन (प्रथम आमाशय)"],"explanationHi":"रूमेन एक बड़ा किण्वन कक्ष है, जिसके जीवाणु और प्रोटोज़ोआ सेल्युलोस को तोड़ते हैं, क्योंकि पशु स्वयं सेल्युलेज़ नहीं बनाता। अबोमेसम अम्ल स्रावित करने वाला वास्तविक आमाशय है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-283","question":"A person gets bloating and diarrhoea after drinking milk but is comfortable after eating curd made from the same milk. The best explanation is:","options":["a lack of lipase, and curd has much less fat than milk","a lack of lactase, and curd bacteria have already changed much of the lactose to lactic acid","a lack of sucrase, and curd contains no cane sugar","a lack of pepsin, and the proteins of curd are already partly digested"],"answer":1,"explanation":"Lactose intolerance is caused by too little lactase to digest milk sugar. During curdling, Lactobacillus converts a large part of lactose into lactic acid, so curd contains less lactose.","difficulty":"very-hard","questionHi":"एक व्यक्ति को दूध पीने के बाद पेट फूलने और दस्त की शिकायत होती है, पर उसी दूध से बना दही खाने के बाद वह सहज रहता है। सबसे उपयुक्त स्पष्टीकरण है:","optionsHi":["लाइपेज़ की कमी, और दही में दूध से बहुत कम वसा होती है","लैक्टेज़ की कमी, और दही के जीवाणु लैक्टोस के बड़े भाग को पहले ही लैक्टिक अम्ल में बदल चुके होते हैं","सुक्रेज़ की कमी, और दही में गन्ने की शर्करा नहीं होती","पेप्सिन की कमी, और दही के प्रोटीन पहले ही आंशिक रूप से पच चुके होते हैं"],"explanationHi":"लैक्टोस असहिष्णुता में दूध की शर्करा पचाने के लिए लैक्टेज़ कम होता है। दही जमने के दौरान लैक्टोबैसिलस लैक्टोस के बड़े भाग को लैक्टिक अम्ल में बदल देता है, इसलिए दही में लैक्टोस कम होता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-284","question":"Under normal conditions, the breathing rate of a person rises during exercise mainly because of an increase in the blood level of:","options":["nitrogen","oxygen","carbon dioxide","glucose"],"answer":2,"explanation":"The respiratory centre in the medulla is most sensitive to rising CO₂ (and the fall in pH it causes) in the blood. A modest fall in oxygen is a weaker stimulus under normal conditions.","difficulty":"hard","questionHi":"सामान्य परिस्थितियों में व्यायाम के दौरान व्यक्ति की श्वसन दर मुख्यतः रक्त में किसकी मात्रा बढ़ने के कारण बढ़ती है?","optionsHi":["नाइट्रोजन","ऑक्सीजन","कार्बन डाइऑक्साइड","ग्लूकोस"],"explanationHi":"मेडुला का श्वसन केंद्र रक्त में CO₂ के बढ़ने (और उससे pH घटने) के प्रति सबसे अधिक संवेदनशील होता है। सामान्य परिस्थितियों में ऑक्सीजन का थोड़ा घटना अपेक्षाकृत कमज़ोर उद्दीपन है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-285","question":"Which sequence correctly shows the path of a nerve impulse in a simple reflex arc?","options":["Receptor → motor neuron → spinal cord → sensory neuron → effector","Receptor → spinal cord → sensory neuron → motor neuron → effector","Effector → sensory neuron → spinal cord → motor neuron → receptor","Receptor → sensory neuron → spinal cord → motor neuron → effector"],"answer":3,"explanation":"A stimulus is picked up by the receptor, carried by the sensory neuron to the spinal cord, passed to the motor neuron and acted on by the effector (muscle or gland). The brain is not needed for the response itself.","difficulty":"hard","questionHi":"एक सरल प्रतिवर्ती चाप में तंत्रिका आवेग का मार्ग कौन-सा क्रम सही दर्शाता है?","optionsHi":["ग्राही → प्रेरक न्यूरॉन → मेरुरज्जु → संवेदी न्यूरॉन → प्रभावी अंग","ग्राही → मेरुरज्जु → संवेदी न्यूरॉन → प्रेरक न्यूरॉन → प्रभावी अंग","प्रभावी अंग → संवेदी न्यूरॉन → मेरुरज्जु → प्रेरक न्यूरॉन → ग्राही","ग्राही → संवेदी न्यूरॉन → मेरुरज्जु → प्रेरक न्यूरॉन → प्रभावी अंग"],"explanationHi":"उद्दीपन को ग्राही ग्रहण करता है, संवेदी न्यूरॉन उसे मेरुरज्जु तक ले जाता है, वहाँ से प्रेरक न्यूरॉन को मिलता है और प्रभावी अंग (पेशी या ग्रंथि) प्रतिक्रिया करता है। प्रतिक्रिया के लिए मस्तिष्क की आवश्यकता नहीं होती।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-286","question":"Nerve impulses travel much faster along myelinated axons than along non-myelinated ones because the impulse:","options":["jumps from one node of Ranvier to the next","is carried along the myelin sheath like current in a wire","is amplified by the Schwann cells at every point of the axon","travels through the tissue fluid that surrounds the sheath"],"answer":0,"explanation":"Myelin insulates the axon, so the impulse regenerates only at the gaps (nodes of Ranvier) and leaps from node to node. This saltatory conduction is faster and uses less energy.","difficulty":"hard","questionHi":"माइलिन युक्त ऐक्सॉन में तंत्रिका आवेग माइलिन रहित ऐक्सॉन की तुलना में बहुत तेज़ चलते हैं, क्योंकि आवेग:","optionsHi":["एक रेनवियर पर्व से अगले रेनवियर पर्व तक कूदता जाता है","माइलिन आवरण के सहारे तार में धारा की तरह चलता है","ऐक्सॉन के प्रत्येक बिंदु पर श्वान कोशिकाओं द्वारा प्रवर्धित होता है","आवरण को घेरे हुए ऊतक द्रव से होकर चलता है"],"explanationHi":"माइलिन ऐक्सॉन को विद्युतरोधी बनाता है, इसलिए आवेग केवल अंतरालों (रेनवियर पर्वों) पर पुनः उत्पन्न होता है और एक पर्व से दूसरे पर्व पर छलाँग लगाता है। यह लवणीय संचरण तेज़ होता है और कम ऊर्जा लेता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-287","question":"Which structure of the brain is a thick band of nerve fibres that connects the right and left cerebral hemispheres?","options":["Pons","Corpus callosum","Medulla oblongata","Thalamus"],"answer":1,"explanation":"The corpus callosum carries impulses between the two cerebral hemispheres so that they work together. The pons relays signals between the cerebrum and cerebellum and helps control breathing.","difficulty":"moderate","questionHi":"मस्तिष्क की कौन-सी संरचना तंत्रिका तंतुओं की मोटी पट्टी है जो दाएँ और बाएँ प्रमस्तिष्क गोलार्धों को जोड़ती है?","optionsHi":["पोन्स","कॉर्पस कैलोसम (महासंयोजक)","मेडुला ऑब्लांगेटा","थैलेमस"],"explanationHi":"कॉर्पस कैलोसम दोनों प्रमस्तिष्क गोलार्धों के बीच आवेग पहुँचाता है ताकि वे साथ मिलकर कार्य करें। पोन्स प्रमस्तिष्क और अनुमस्तिष्क के बीच संदेश पहुँचाता है और श्वसन के नियंत्रण में सहायक है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-288","question":"A normal human being has how many pairs of cranial nerves and how many pairs of spinal nerves?","options":["10 pairs and 31 pairs","31 pairs and 12 pairs","12 pairs and 33 pairs","12 pairs and 31 pairs"],"answer":3,"explanation":"Humans have 12 pairs of cranial nerves arising from the brain and 31 pairs of spinal nerves arising from the spinal cord (8 cervical, 12 thoracic, 5 lumbar, 5 sacral, 1 coccygeal).","difficulty":"hard","questionHi":"सामान्य मनुष्य में कपाल तंत्रिकाओं के कितने जोड़े और मेरु तंत्रिकाओं के कितने जोड़े होते हैं?","optionsHi":["10 जोड़े और 31 जोड़े","31 जोड़े और 12 जोड़े","12 जोड़े और 33 जोड़े","12 जोड़े और 31 जोड़े"],"explanationHi":"मनुष्य में मस्तिष्क से निकलने वाली 12 जोड़ी कपाल तंत्रिकाएँ और मेरुरज्जु से निकलने वाली 31 जोड़ी मेरु तंत्रिकाएँ होती हैं (8 ग्रीवा, 12 वक्षीय, 5 कटि, 5 त्रिक, 1 अनुत्रिक)।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-289","question":"Which set of changes is typical of stimulation of the parasympathetic nervous system?","options":["Faster heartbeat, dilated pupils and slower digestion","Dilated bronchi, release of glucose and dilated pupils","Slower heartbeat, constricted pupils and increased digestive secretion","Faster breathing, raised blood pressure and sweating"],"answer":2,"explanation":"The parasympathetic system works in rest and digestion: it slows the heart, constricts the pupils and increases gut secretion and movement. The other options describe sympathetic (fight-or-flight) effects.","difficulty":"hard","questionHi":"परानुकंपी तंत्रिका तंत्र के उद्दीपन पर सामान्यतः कौन-से परिवर्तन होते हैं?","optionsHi":["हृदय की धड़कन तेज़, पुतलियाँ फैलना और पाचन धीमा","श्वसनिकाओं का फैलना, ग्लूकोस का मुक्त होना और पुतलियाँ फैलना","हृदय की धड़कन धीमी, पुतलियाँ सिकुड़ना और पाचन स्राव बढ़ना","श्वसन तेज़, रक्तचाप बढ़ना और पसीना आना"],"explanationHi":"परानुकंपी तंत्र विश्राम और पाचन की अवस्था में कार्य करता है: वह हृदय की गति धीमी करता है, पुतलियाँ सिकोड़ता है और आँत का स्राव तथा गति बढ़ाता है। शेष विकल्प अनुकंपी (संघर्ष-या-पलायन) प्रभाव हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-290","question":"When the gaze shifts from a distant tree to a book held close, the ciliary muscles ___ and the lens becomes ___.","options":["contract; thicker","relax; thicker","contract; thinner","relax; thinner"],"answer":0,"explanation":"For near vision the ciliary muscles contract, the suspensory ligaments slacken and the lens bulges, becoming thicker with a shorter focal length. For distant vision the muscles relax and the lens flattens.","difficulty":"very-hard","questionHi":"जब दृष्टि दूर के पेड़ से पास रखी पुस्तक पर आती है, तब पक्ष्माभी पेशियाँ ___ और लेंस ___ हो जाता है।","optionsHi":["संकुचित होती हैं; मोटा","शिथिल होती हैं; मोटा","संकुचित होती हैं; पतला","शिथिल होती हैं; पतला"],"explanationHi":"निकट दृष्टि के लिए पक्ष्माभी पेशियाँ संकुचित होती हैं, निलंबन स्नायु ढीले पड़ते हैं और लेंस उभरकर मोटा हो जाता है तथा उसकी फोकस दूरी घट जाती है। दूर देखने पर पेशियाँ शिथिल होती हैं और लेंस चपटा हो जाता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-291","question":"A student can read a book comfortably but cannot see the writing on the blackboard clearly. The defect and the lens that corrects it are:","options":["hypermetropia; convex lens","myopia; concave lens","myopia; convex lens","presbyopia; bifocal lens"],"answer":1,"explanation":"Seeing near objects clearly but not distant ones is myopia, where the image forms in front of the retina. A concave (diverging) lens moves the image back onto the retina.","difficulty":"hard","questionHi":"एक विद्यार्थी पुस्तक आराम से पढ़ लेता है, पर श्यामपट्ट पर लिखा स्पष्ट नहीं देख पाता। यह दोष और उसे ठीक करने वाला लेंस कौन-सा है?","optionsHi":["दूर-दृष्टि दोष; उत्तल लेंस","निकट-दृष्टि दोष; अवतल लेंस","निकट-दृष्टि दोष; उत्तल लेंस","जरा-दृष्टिता; द्विफोकसी लेंस"],"explanationHi":"निकट की वस्तुएँ स्पष्ट और दूर की धुँधली दिखना निकट-दृष्टि दोष है, जिसमें प्रतिबिंब रेटिना के आगे बनता है। अवतल (अपसारी) लेंस प्रतिबिंब को पीछे खिसकाकर रेटिना पर ला देता है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-292","question":"The blind spot of the human eye is the point where:","options":["only cones are present and no rods","only rods are present and no cones","vision is sharpest because the cones are densest","the optic nerve leaves the eye and no rods or cones are present"],"answer":3,"explanation":"At the blind spot the optic nerve fibres leave the retina, so there are no photoreceptors and an image falling there is not seen. The yellow spot (fovea), with densest cones, is the region of sharpest vision.","difficulty":"moderate","questionHi":"मानव नेत्र का अंध बिंदु वह स्थान है जहाँ:","optionsHi":["केवल शंकु होते हैं, शलाकाएँ नहीं","केवल शलाकाएँ होती हैं, शंकु नहीं","दृष्टि सबसे तीक्ष्ण होती है क्योंकि शंकु सबसे सघन होते हैं","दृक् तंत्रिका नेत्र से बाहर निकलती है और शलाकाएँ या शंकु नहीं होते"],"explanationHi":"अंध बिंदु पर दृक् तंत्रिका के तंतु रेटिना से बाहर निकलते हैं, इसलिए वहाँ प्रकाशग्राही नहीं होते और वहाँ पड़ने वाला प्रतिबिंब दिखाई नहीं देता। सबसे अधिक शंकु वाला पीत बिंदु (फोविया) सबसे तीक्ष्ण दृष्टि का क्षेत्र है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-293","question":"Which sequence lists the three ear ossicles in order from the eardrum towards the inner ear?","options":["Incus → malleus → stapes","Stapes → incus → malleus","Malleus → incus → stapes","Malleus → stapes → incus"],"answer":2,"explanation":"The malleus touches the eardrum, the incus lies in the middle and the stapes presses on the oval window of the cochlea. They pass on and amplify the vibrations.","difficulty":"hard","questionHi":"कान की तीन अस्थिकाओं को कर्ण पटह से भीतरी कान की ओर किस क्रम में रखा गया है?","optionsHi":["इन्कस → मैलियस → स्टेपीज़","स्टेपीज़ → इन्कस → मैलियस","मैलियस → इन्कस → स्टेपीज़","मैलियस → स्टेपीज़ → इन्कस"],"explanationHi":"मैलियस कर्ण पटह को छूता है, इन्कस बीच में होता है और स्टेपीज़ कर्णावर्त की अंडाकार खिड़की पर दबाव डालता है। ये कंपनों को आगे पहुँचाती और प्रवर्धित करती हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-294","question":"While an aeroplane is landing, swallowing or yawning relieves the discomfort in the ears because it:","options":["drains the extra fluid from the cochlea into the middle ear cavity","opens the Eustachian tube and equalises pressure across the eardrum","tightens the ear ossicles to dampen the loud sounds of the engines","stops the semicircular canals from sensing the motion of the aeroplane"],"answer":1,"explanation":"The Eustachian tube links the middle ear to the throat. Swallowing opens it briefly and lets the air pressure in the middle ear match the outside pressure, so the eardrum stops bulging.","difficulty":"hard","questionHi":"विमान के उतरते समय निगलने या जम्हाई लेने से कानों की बेचैनी दूर हो जाती है, क्योंकि इससे:","optionsHi":["कर्णावर्त से अतिरिक्त द्रव मध्य कर्ण गुहा में बाहर निकाल देता है","यूस्टेकियन नली खोलकर कर्ण पटह के आर-पार दाब बराबर कर देता है","इंजनों की तेज़ आवाज़ को घटाने के लिए कर्ण अस्थिकाओं को कस देता है","अर्धवृत्ताकार नलिकाओं को वायुयान की गति महसूस करने से रोक देता है"],"explanationHi":"यूस्टेकियन नली मध्य कान को गले से जोड़ती है। निगलने पर वह थोड़ी देर के लिए खुलती है और मध्य कान का वायुदाब बाहरी दाब के बराबर हो जाता है, जिससे कर्ण पटह का उभार समाप्त हो जाता है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-295","question":"How many cervical (neck) vertebrae does a giraffe have in its very long neck?","options":["7","12","14","9"],"answer":0,"explanation":"Almost all mammals, including humans, giraffes and mice, have seven cervical vertebrae. The giraffe's neck is long because each vertebra is greatly elongated, not because there are more of them.","difficulty":"hard","questionHi":"जिराफ़ की बहुत लंबी गर्दन में कितनी ग्रीवा (गर्दन की) कशेरुकाएँ होती हैं?","optionsHi":["7","12","14","9"],"explanationHi":"मनुष्य, जिराफ़ और चूहे सहित लगभग सभी स्तनधारियों में सात ग्रीवा कशेरुकाएँ होती हैं। जिराफ़ की गर्दन इसलिए लंबी है कि प्रत्येक कशेरुका बहुत लंबी होती है, इसलिए नहीं कि उनकी संख्या अधिक है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-296","question":"How many ribs does an adult human have in all, and how many of them are true ribs (attached directly to the sternum)?","options":["24 in all; 7 true ribs","24 in all; 10 true ribs","12 in all; 7 true ribs","24 in all; 14 true ribs"],"answer":3,"explanation":"There are 12 pairs, 24 ribs in all. The first seven pairs are true ribs, so 14 ribs; the next three pairs are false ribs and the last two pairs are floating ribs.","difficulty":"very-hard","questionHi":"एक वयस्क मनुष्य में कुल कितनी पसलियाँ होती हैं और उनमें से कितनी वास्तविक पसलियाँ (उरोस्थि से सीधी जुड़ी) हैं?","optionsHi":["कुल 24; 7 वास्तविक पसलियाँ","कुल 24; 10 वास्तविक पसलियाँ","कुल 12; 7 वास्तविक पसलियाँ","कुल 24; 14 वास्तविक पसलियाँ"],"explanationHi":"कुल 12 जोड़ी अर्थात 24 पसलियाँ होती हैं। पहले सात जोड़े वास्तविक पसलियाँ हैं, यानी 14 पसलियाँ; अगले तीन जोड़े मिथ्या पसलियाँ और अंतिम दो जोड़े मुक्त पसलियाँ हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-297","question":"The body of a dead animal becomes stiff a few hours after death (rigor mortis) mainly because:","options":["blood clots inside the muscle fibres and blocks their movement","water evaporates from the muscles and shrinks the fibres","no ATP is left, so myosin cannot release actin","tendons contract because of the cold of the surrounding air"],"answer":2,"explanation":"After death ATP is no longer made, and ATP is needed to break the actin-myosin cross-bridges. The muscles therefore stay locked in contraction until the proteins themselves begin to break down.","difficulty":"very-hard","questionHi":"मृत्यु के कुछ घंटे बाद मृत जंतु का शरीर अकड़ जाता है (मृत्यु-काठिन्य), मुख्यतः क्योंकि:","optionsHi":["पेशी तंतुओं के भीतर रक्त जमकर उनकी गति रोक देता है","पेशियों से जल वाष्पित होकर तंतुओं को सिकोड़ देता है","ATP नहीं बचता, इसलिए मायोसिन ऐक्टिन को छोड़ नहीं पाता","आसपास की हवा की ठंड के कारण कंडराएँ सिकुड़ जाती हैं"],"explanationHi":"मृत्यु के बाद ATP बनना बंद हो जाता है, जबकि ऐक्टिन-मायोसिन सेतुओं को तोड़ने के लिए ATP चाहिए। इसलिए जब तक प्रोटीन स्वयं विघटित नहीं होने लगते, पेशियाँ संकुचित अवस्था में जकड़ी रहती हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-298","question":"Which feature is found only in cardiac muscle and in no other type of muscle?","options":["Branched fibres joined end to end by intercalated discs","Spindle-shaped cells with no cross striations","Long, unbranched, multinucleate fibres under voluntary control","Cylindrical cells with many nuclei lying beneath the cell membrane"],"answer":0,"explanation":"Cardiac muscle fibres branch and are joined by intercalated discs, which let impulses spread quickly through the heart. Skeletal fibres are long and multinucleate, and smooth muscle cells are spindle-shaped.","difficulty":"moderate","questionHi":"कौन-सी विशेषता केवल हृदय पेशी में पाई जाती है, किसी अन्य पेशी में नहीं?","optionsHi":["शाखित तंतु, जो अंतर्वेशी बिंबों द्वारा सिरे से सिरे तक जुड़े होते हैं","तर्कुरूप कोशिकाएँ, जिनमें आड़ी धारियाँ नहीं होतीं","लंबे, अशाखित, बहुकेंद्रकी तंतु, जो ऐच्छिक नियंत्रण में होते हैं","बेलनाकार कोशिकाएँ, जिनमें कोशिका झिल्ली के नीचे अनेक केंद्रक होते हैं"],"explanationHi":"हृदय पेशी के तंतु शाखित होते हैं और अंतर्वेशी बिंबों से जुड़े रहते हैं, जिससे आवेग हृदय में तेज़ी से फैलता है। कंकाल पेशी के तंतु लंबे और बहुकेंद्रकी होते हैं तथा चिकनी पेशी की कोशिकाएँ तर्कुरूप होती हैं।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-299","question":"The elbow joint and the joint between the first two neck vertebrae (atlas and axis, which lets the head turn side to side) are respectively:","options":["ball-and-socket and gliding","hinge and pivot","pivot and hinge","gliding and hinge"],"answer":1,"explanation":"The elbow bends in one plane like a door, so it is a hinge joint. The atlas rotates around the peg-like odontoid process of the axis, a pivot joint that lets the head turn.","difficulty":"hard","questionHi":"कोहनी का जोड़ और गर्दन की पहली दो कशेरुकाओं (ऐटलस और ऐक्सिस, जो सिर को दाएँ-बाएँ घुमाने देती हैं) के बीच का जोड़ क्रमशः हैं:","optionsHi":["गेंद-खल्लिका और विसर्पी जोड़","कब्ज़ा जोड़ और धुराग्र जोड़","धुराग्र जोड़ और कब्ज़ा जोड़","विसर्पी जोड़ और कब्ज़ा जोड़"],"explanationHi":"कोहनी दरवाज़े की तरह एक ही तल में मुड़ती है, इसलिए वह कब्ज़ा जोड़ है। ऐटलस ऐक्सिस की खूँटीनुमा प्रवर्ध के चारों ओर घूमता है, जो धुराग्र जोड़ है और सिर को घुमाने देता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-300","question":"How many oxygen molecules can one molecule of adult haemoglobin carry at most?","options":["1","2","8","4"],"answer":3,"explanation":"Haemoglobin has four polypeptide chains, each with one haem group whose iron binds one O₂ molecule, so it carries up to four O₂ molecules. Myoglobin, with a single haem, carries one.","difficulty":"moderate","questionHi":"वयस्क हीमोग्लोबिन का एक अणु अधिकतम कितने ऑक्सीजन अणु ले जा सकता है?","optionsHi":["1","2","8","4"],"explanationHi":"हीमोग्लोबिन में चार पॉलीपेप्टाइड शृंखलाएँ होती हैं, प्रत्येक में एक हीम समूह होता है जिसका लौह एक O₂ अणु से जुड़ता है, इसलिए वह अधिकतम चार O₂ अणु ले जाता है। एक हीम वाला मायोग्लोबिन केवल एक ले जाता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-301","question":"A plant shows yellowing of its OLDER leaves first while the young leaves stay green. Which mineral deficiency is the most likely cause?","options":["Iron","Calcium","Nitrogen","Sulphur"],"answer":2,"explanation":"Nitrogen is a mobile nutrient: a deficient plant moves it from old leaves to growing tips, so old leaves turn yellow first. Iron, calcium and sulphur are poorly mobile, so their deficiency shows first in young leaves.","difficulty":"very-hard","questionHi":"किसी पौधे की पुरानी पत्तियाँ सबसे पहले पीली पड़ती हैं जबकि नई पत्तियाँ हरी रहती हैं। इसका सबसे संभावित कारण किस खनिज की कमी है?","optionsHi":["लोहा","कैल्सियम","नाइट्रोजन","सल्फर"],"explanationHi":"नाइट्रोजन गतिशील पोषक है: कमी होने पर पौधा उसे पुरानी पत्तियों से वृद्धि वाले सिरों की ओर भेज देता है, इसलिए पुरानी पत्तियाँ पहले पीली पड़ती हैं। लोहा, कैल्सियम और सल्फर कम गतिशील हैं, इसलिए उनकी कमी पहले नई पत्तियों में दिखती है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-302","question":"Which of these crops carries out C₄ photosynthesis, with Kranz anatomy in its leaves?","options":["Sugarcane","Wheat","Rice","Soybean"],"answer":0,"explanation":"Sugarcane, like maize and sorghum, is a C₄ plant: its bundle sheath cells form a wreath (Kranz) around the vascular bundles and it loses very little carbon through photorespiration. Wheat, rice and soybean are C₃ plants.","difficulty":"hard","questionHi":"इनमें से कौन-सी फ़सल C₄ प्रकाश संश्लेषण करती है, जिसकी पत्तियों में क्रैंज़ शारीर होता है?","optionsHi":["गन्ना","गेहूँ","चावल (धान)","सोयाबीन"],"explanationHi":"गन्ना, मक्का और ज्वार की तरह C₄ पौधा है: उसकी पूलाच्छद कोशिकाएँ संवहन बंडलों के चारों ओर माला (क्रैंज़) बनाती हैं और उसमें प्रकाश-श्वसन से कार्बन की हानि बहुत कम होती है। गेहूँ, धान और सोयाबीन C₃ पौधे हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-303","question":"Green plants were supplied with water containing heavy oxygen (H₂¹⁸O) and ordinary carbon dioxide. The oxygen gas released contained ¹⁸O. This shows that the oxygen released in photosynthesis comes from:","options":["carbon dioxide","glucose","chlorophyll","water"],"answer":3,"explanation":"The labelled oxygen appears in the O₂ gas, so it must have come from water, which is split by light (photolysis) in the light reaction. The oxygen of CO₂ ends up in glucose and water, not in the released O₂.","difficulty":"hard","questionHi":"हरे पौधों को भारी ऑक्सीजन वाला जल (H₂¹⁸O) और सामान्य कार्बन डाइऑक्साइड दी गई। निकली ऑक्सीजन गैस में ¹⁸O पाई गई। इससे सिद्ध होता है कि प्रकाश संश्लेषण में निकलने वाली ऑक्सीजन आती है:","optionsHi":["कार्बन डाइऑक्साइड से","ग्लूकोस से","क्लोरोफ़िल से","जल से"],"explanationHi":"चिह्नित ऑक्सीजन O₂ गैस में मिली, अतः वह जल से आई है, जो प्रकाश अभिक्रिया में प्रकाश द्वारा विघटित (प्रकाश-अपघटन) होता है। CO₂ की ऑक्सीजन ग्लूकोस और जल में चली जाती है, निकलने वाली O₂ में नहीं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-304","question":"Which of these substances gives a respiratory quotient (CO₂ released ÷ O₂ used) clearly LESS than 1 when oxidised completely in respiration?","options":["Glucose","Tripalmitin (a fat)","Sucrose","Starch"],"answer":1,"explanation":"Carbohydrates such as glucose have as much oxygen in them as they need, so they give RQ = 1 (6 CO₂ ÷ 6 O₂). A fat is poor in oxygen and needs much more O₂ for oxidation, so its RQ is about 0.7.","difficulty":"very-hard","questionHi":"इनमें से कौन-सा पदार्थ श्वसन में पूर्ण ऑक्सीकरण पर 1 से स्पष्टतः कम श्वसन भागफल (मुक्त CO₂ ÷ प्रयुक्त O₂) देता है?","optionsHi":["ग्लूकोस","ट्राइपामिटिन (एक वसा)","सुक्रोस","स्टार्च"],"explanationHi":"ग्लूकोस जैसे कार्बोहाइड्रेट में ऑक्सीजन पर्याप्त होती है, इसलिए श्वसन भागफल 1 होता है (6 CO₂ ÷ 6 O₂)। वसा में ऑक्सीजन कम होती है और ऑक्सीकरण के लिए बहुत अधिक O₂ चाहिए, इसलिए उसका श्वसन भागफल लगभग 0.7 होता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-305","question":"Which of these sets contains only Kharif crops (sown with the onset of the monsoon)?","options":["Wheat, gram, mustard","Rice, wheat, barley","Maize, cotton, soybean","Pea, linseed, paddy"],"answer":2,"explanation":"Maize, cotton and soybean are sown in June-July and harvested in autumn. Wheat, gram, mustard, barley, pea and linseed are rabi crops sown in winter, so every other set contains at least one rabi crop.","difficulty":"moderate","questionHi":"इनमें से किस समूह में केवल खरीफ़ फ़सलें (मानसून के आरंभ में बोई जाने वाली) हैं?","optionsHi":["गेहूँ, चना, सरसों","चावल, गेहूँ, जौ","मक्का, कपास, सोयाबीन","मटर, अलसी, धान"],"explanationHi":"मक्का, कपास और सोयाबीन जून-जुलाई में बोई जाती हैं और शरद ऋतु में काटी जाती हैं। गेहूँ, चना, सरसों, जौ, मटर और अलसी सर्दियों में बोई जाने वाली रबी फ़सलें हैं, इसलिए शेष हर समूह में कम से कम एक रबी फ़सल है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-306","question":"Farmers grow dhaincha (Sesbania) and plough it back into the soil before sowing paddy. This practice, called green manuring, mainly serves to:","options":["kill soil insects with the toxins in its leaves","make the soil acidic so that it suits paddy","reduce salinity by absorbing the salts of the soil","add nitrogen and organic matter to the soil"],"answer":3,"explanation":"Dhaincha is a leguminous crop whose root nodules fix nitrogen; when the green plants are ploughed in and decay, they add nitrogen and humus to the soil.","difficulty":"hard","questionHi":"किसान धान की बुवाई से पहले ढैंचा (सेस्बेनिया) उगाकर उसे मिट्टी में जोत देते हैं। हरी खाद कहलाने वाली इस प्रथा का मुख्य उद्देश्य है:","optionsHi":["अपनी पत्तियों के विषैले पदार्थों से मिट्टी के कीटों को मारना","मिट्टी को अम्लीय बनाना ताकि वह धान के अनुकूल हो","मिट्टी के लवण सोखकर लवणता घटाना","मिट्टी में नाइट्रोजन और कार्बनिक पदार्थ जोड़ना"],"explanationHi":"ढैंचा एक दलहनी फ़सल है जिसकी जड़ों की ग्रंथिकाएँ नाइट्रोजन स्थिर करती हैं; हरे पौधों को जोतने पर वे सड़कर मिट्टी में नाइट्रोजन और ह्यूमस जोड़ते हैं।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-307","question":"Which combination is widely used as a biofertiliser in paddy fields to add nitrogen to the soil?","options":["Azolla with the cyanobacterium Anabaena","Rhizobium living in the root nodules of rice","Mycorrhizal fungus living inside Azolla","Nostoc living in the root nodules of Rhizobium"],"answer":0,"explanation":"The small water fern Azolla hosts the nitrogen-fixing cyanobacterium Anabaena azollae in its leaf cavities and is spread on flooded paddy fields as a nitrogen source. Rice does not form root nodules with Rhizobium.","difficulty":"very-hard","questionHi":"धान के खेतों में मिट्टी में नाइट्रोजन जोड़ने के लिए जैव उर्वरक के रूप में कौन-सा संयोग व्यापक रूप से प्रयोग होता है?","optionsHi":["ऐज़ोला और उसके साथ सायनोबैक्टीरिया ऐनाबीना","चावल की जड़ग्रंथिकाओं में रहने वाला राइज़ोबियम","ऐज़ोला के भीतर रहने वाला माइकोराइज़ा कवक","राइज़ोबियम की जड़ग्रंथिकाओं में रहने वाला नॉस्टॉक"],"explanationHi":"छोटी जलीय फर्न ऐज़ोला अपनी पत्ती की गुहाओं में नाइट्रोजन स्थिरीकरण करने वाले सायनोबैक्टीरिया ऐनाबीना ऐज़ोली को आश्रय देती है और पानी भरे धान के खेतों में नाइट्रोजन स्रोत के रूप में डाली जाती है। धान में राइज़ोबियम की जड़ग्रंथिकाएँ नहीं बनतीं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-308","question":"Which ecological pyramid can never be inverted in any natural ecosystem?","options":["Pyramid of numbers","Pyramid of energy","Pyramid of biomass","None; every pyramid can be inverted in some ecosystem"],"answer":1,"explanation":"Energy is lost as heat at each trophic level, so the energy available always falls upwards. Numbers can be inverted (one tree, many insects) and biomass can be inverted in a pond (small phytoplankton, larger zooplankton and fish).","difficulty":"very-hard","questionHi":"किसी भी प्राकृतिक पारिस्थितिक तंत्र में कौन-सा पारिस्थितिक पिरामिड कभी उल्टा नहीं हो सकता?","optionsHi":["संख्या का पिरामिड","ऊर्जा का पिरामिड","जैवभार का पिरामिड","कोई नहीं; प्रत्येक पिरामिड किसी न किसी पारितंत्र में उल्टा हो सकता है"],"explanationHi":"प्रत्येक पोषण स्तर पर ऊर्जा ऊष्मा के रूप में नष्ट होती है, इसलिए उपलब्ध ऊर्जा ऊपर की ओर हमेशा घटती है। संख्या का पिरामिड उल्टा हो सकता है (एक वृक्ष, अनेक कीट) और तालाब में जैवभार का पिरामिड भी उल्टा हो सकता है (छोटे पादपप्लवक, बड़े प्राणिप्लवक और मछलियाँ)।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-309","question":"On a bare rock, which organisms are usually the first to colonise it and start primary succession?","options":["Mosses","Grasses","Lichens","Shrubs"],"answer":2,"explanation":"Crustose lichens are the pioneer species on bare rock: they release acids that slowly weather the rock into soil, which later allows mosses, grasses and shrubs to grow.","difficulty":"moderate","questionHi":"नंगी चट्टान पर प्राथमिक अनुक्रमण शुरू करने के लिए सामान्यतः सबसे पहले कौन-से जीव बसते हैं?","optionsHi":["मॉस","घासें","लाइकेन","झाड़ियाँ"],"explanationHi":"क्रस्टोस लाइकेन नंगी चट्टान पर अग्रणी जाति हैं: वे अम्ल छोड़ती हैं जो चट्टान को धीरे-धीरे अपक्षयित करके मिट्टी बनाते हैं, जिसके बाद मॉस, घासें और झाड़ियाँ उग पाती हैं।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-310","question":"Which of these pairs of organisms and their relationship is NOT correctly matched?","options":["Orchid growing on a mango tree – parasitism","Cuscuta on a host plant – parasitism","Mycorrhiza on pine roots – mutualism","Cattle egret near grazing cattle – commensalism"],"answer":0,"explanation":"An epiphytic orchid only uses the mango branch for support and takes no food from it, so it is commensalism (one benefits, the other is unaffected). Cuscuta draws food from its host, so that is true parasitism.","difficulty":"hard","questionHi":"जीवों के इनमें से कौन-से युग्म और उनके संबंध का मिलान सही नहीं है?","optionsHi":["आम के पेड़ पर उगने वाला ऑर्किड – परजीविता","पोषक पादप पर अमरबेल (कस्कुटा) – परजीविता","चीड़ की जड़ों पर माइकोराइज़ा – सहोपकारिता","चरते पशुओं के पास बगुला – सहभोजिता"],"explanationHi":"अधिपादप ऑर्किड आम की शाखा का केवल सहारा लेता है और उससे भोजन नहीं लेता, इसलिए यह सहभोजिता है (एक को लाभ, दूसरे पर प्रभाव नहीं)। अमरबेल अपने पोषक से भोजन खींचती है, इसलिए वह वास्तविक परजीविता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-311","question":"Which pair names two of the biodiversity hotspots found in India?","options":["Thar Desert and Western Ghats","Aravalli Hills and Himalaya","Gangetic Plains and Western Ghats","Himalaya and Western Ghats"],"answer":3,"explanation":"India has parts of four hotspots: the Himalaya, Indo-Burma, the Western Ghats (with Sri Lanka) and Sundaland (the Nicobar Islands). The Thar Desert, Aravallis and Gangetic Plains are not hotspots.","difficulty":"hard","questionHi":"कौन-सा युग्म भारत में पाए जाने वाले दो जैव विविधता हॉटस्पॉट बताता है?","optionsHi":["थार मरुस्थल और पश्चिमी घाट","अरावली पहाड़ियाँ और हिमालय","गंगा का मैदान और पश्चिमी घाट","हिमालय और पश्चिमी घाट"],"explanationHi":"भारत में चार हॉटस्पॉट के भाग हैं: हिमालय, इंडो-बर्मा, पश्चिमी घाट (श्रीलंका सहित) और सुंडालैंड (निकोबार द्वीप)। थार मरुस्थल, अरावली और गंगा का मैदान हॉटस्पॉट नहीं हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-312","question":"A river sample shows a very high biochemical oxygen demand (BOD). This indicates that the water has:","options":["very high dissolved oxygen and is almost pure","a heavy load of biodegradable organic waste","heavy metals as the only pollutant","very high salinity from the sea"],"answer":1,"explanation":"BOD is the oxygen microbes consume to break down organic matter in water. A high BOD means much biodegradable waste (such as sewage), so the dissolved oxygen falls and aquatic life suffers.","difficulty":"hard","questionHi":"किसी नदी के नमूने में जैव रासायनिक ऑक्सीजन माँग (BOD) बहुत अधिक पाई गई। इससे संकेत मिलता है कि जल में:","optionsHi":["विलीन ऑक्सीजन बहुत अधिक है और जल लगभग शुद्ध है","जैव-निम्नीकरणीय कार्बनिक अपशिष्ट का भारी भार है","एकमात्र प्रदूषक भारी धातुएँ हैं","समुद्र से आई बहुत अधिक लवणता है"],"explanationHi":"BOD वह ऑक्सीजन है जो सूक्ष्मजीव जल में कार्बनिक पदार्थ को तोड़ने में खर्च करते हैं। अधिक BOD का अर्थ है बहुत अधिक जैव-निम्नीकरणीय अपशिष्ट (जैसे वाहित मल), जिससे विलीन ऑक्सीजन घटती है और जलीय जीव प्रभावित होते हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-313","question":"Which organisms produce methane in a biogas plant by acting on cattle dung and other waste in the absence of oxygen?","options":["Nitrosomonas","Yeast","Methanobacterium","Rhizobium"],"answer":2,"explanation":"Methanogens such as Methanobacterium (archaebacteria) are strict anaerobes that convert the products of fermentation of dung into methane, the main component of biogas. The same bacteria live in the rumen of cattle.","difficulty":"hard","questionHi":"बायोगैस संयंत्र में ऑक्सीजन की अनुपस्थिति में गोबर और अन्य अपशिष्ट पर क्रिया करके मेथेन कौन-से जीव बनाते हैं?","optionsHi":["नाइट्रोसोमोनास","यीस्ट","मेथेनोबैक्टीरियम","राइज़ोबियम"],"explanationHi":"मेथेनोबैक्टीरियम जैसे मेथेनोजन (आर्कीबैक्टीरिया) अनिवार्य अवायवीय जीव हैं जो गोबर के किण्वन से बने उत्पादों को मेथेन में बदलते हैं, जो बायोगैस का मुख्य घटक है। यही जीवाणु पशुओं के रूमेन में भी रहते हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-314","question":"The silk fibre obtained from the cocoon of the silkworm Bombyx mori is made chiefly of the protein:","options":["Keratin","Collagen","Casein","Fibroin"],"answer":3,"explanation":"The silkworm secretes the protein fibroin, held together by a gummy coating of sericin, to spin its cocoon. Keratin forms wool, hair and nails, and collagen is a connective-tissue protein.","difficulty":"hard","questionHi":"रेशमकीट बॉम्बिक्स मोराई के कोकून से मिलने वाला रेशम का तंतु मुख्यतः किस प्रोटीन का बना होता है?","optionsHi":["केराटिन","कोलैजन","केसीन","फाइब्रोइन"],"explanationHi":"रेशमकीट कोकून बुनने के लिए प्रोटीन फाइब्रोइन स्रावित करता है, जिसे सेरिसिन की चिपचिपी परत जोड़े रखती है। केराटिन ऊन, बाल और नाखून बनाता है और कोलैजन संयोजी ऊतक का प्रोटीन है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-315","question":"In a honeybee colony, the male bees (drones) develop from:","options":["unfertilised eggs","fertilised eggs fed on royal jelly","fertilised eggs laid by worker bees","larvae that are fed pollen by the queen"],"answer":0,"explanation":"Drones develop from unfertilised eggs (parthenogenesis) and are haploid, while queens and workers develop from fertilised eggs and are diploid. The queen becomes a queen because her larva is fed royal jelly.","difficulty":"very-hard","questionHi":"मधुमक्खी के छत्ते में नर मक्खियाँ (ड्रोन) किससे विकसित होती हैं?","optionsHi":["अनिषेचित अंडों से","रॉयल जेली खिलाए गए निषेचित अंडों से","श्रमिक मक्खियों द्वारा दिए गए निषेचित अंडों से","रानी द्वारा पराग खिलाए गए लार्वा से"],"explanationHi":"ड्रोन अनिषेचित अंडों (अनिषेकजनन) से विकसित होते हैं और अगुणित होते हैं, जबकि रानी और श्रमिक निषेचित अंडों से विकसित होकर द्विगुणित होती हैं। रानी इसलिए रानी बनती है कि उसके लार्वा को रॉयल जेली खिलाई जाती है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-316","question":"Arrange these taxonomic categories from the smallest group to the largest: Class, Family, Genus, Order, Phylum.","options":["Family, Genus, Order, Class, Phylum","Genus, Family, Order, Class, Phylum","Genus, Family, Class, Order, Phylum","Genus, Order, Family, Class, Phylum"],"answer":1,"explanation":"The hierarchy rises from species to genus, family, order, class, phylum (division in plants) and kingdom. Order is a broader group than family, and class is broader than order.","difficulty":"very-hard","questionHi":"इन वर्गीकरण श्रेणियों को सबसे छोटे समूह से सबसे बड़े समूह के क्रम में व्यवस्थित कीजिए: वर्ग, कुल, वंश, गण, संघ।","optionsHi":["कुल, वंश, गण, वर्ग, संघ","वंश, कुल, गण, वर्ग, संघ","वंश, कुल, वर्ग, गण, संघ","वंश, गण, कुल, वर्ग, संघ"],"explanationHi":"श्रेणीक्रम जाति से वंश, कुल, गण, वर्ग, संघ (पादपों में प्रभाग) और जगत की ओर बढ़ता है। गण कुल से बड़ा समूह है और वर्ग गण से बड़ा।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-317","question":"Which of these animal phyla has the largest number of known species?","options":["Mollusca","Chordata","Arthropoda","Annelida"],"answer":2,"explanation":"Arthropoda, which includes insects, spiders and crustaceans, is the largest phylum and contains more than two-thirds of all known animal species. Insects alone outnumber all vertebrates.","difficulty":"moderate","questionHi":"इनमें से किस जंतु संघ में ज्ञात जातियों की संख्या सबसे अधिक है?","optionsHi":["मोलस्का","कॉर्डेटा","आर्थ्रोपोडा","ऐनेलिडा"],"explanationHi":"आर्थ्रोपोडा, जिसमें कीट, मकड़ियाँ और क्रस्टेशियाई आते हैं, सबसे बड़ा संघ है और उसमें सभी ज्ञात जंतु जातियों के दो-तिहाई से अधिक सदस्य हैं। अकेले कीट सभी कशेरुकियों से अधिक हैं।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-318","question":"Which of these animal and excretory organ pairs is NOT correctly matched?","options":["Cockroach – nephridia","Earthworm – nephridia","Prawn – green glands","Planaria – flame cells"],"answer":0,"explanation":"Insects such as the cockroach excrete through Malpighian tubules; nephridia are the excretory organs of earthworms and other annelids. Prawns use green (antennal) glands and Planaria use flame cells.","difficulty":"very-hard","questionHi":"जंतु और उसके उत्सर्जी अंग के इनमें से कौन-से युग्म का मिलान सही नहीं है?","optionsHi":["तिलचट्टा – वृक्कक (नेफ्रीडिया)","केंचुआ – वृक्कक (नेफ्रीडिया)","झींगा – हरी ग्रंथियाँ","प्लेनेरिया – ज्वाला कोशिकाएँ"],"explanationHi":"तिलचट्टे जैसे कीट मैल्पीघी नलिकाओं से उत्सर्जन करते हैं; वृक्कक केंचुए और अन्य ऐनेलिडों के उत्सर्जी अंग हैं। झींगा हरी (शृंगिका) ग्रंथियों और प्लेनेरिया ज्वाला कोशिकाओं का उपयोग करता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-319","question":"Which of these animals has an open circulatory system, in which blood flows through body cavities instead of closed vessels?","options":["Earthworm","Octopus","Fish","Cockroach"],"answer":3,"explanation":"Arthropods such as the cockroach have an open circulation with blood (haemolymph) bathing the tissues in a haemocoel. The earthworm, the octopus and fishes all have closed circulatory systems.","difficulty":"hard","questionHi":"इनमें से किस जंतु में खुला परिसंचरण तंत्र होता है, जिसमें रक्त बंद वाहिकाओं के बजाय देहगुहाओं में बहता है?","optionsHi":["केंचुआ","ऑक्टोपस","मछली","तिलचट्टा"],"explanationHi":"तिलचट्टे जैसे आर्थ्रोपोडा में खुला परिसंचरण होता है, जिसमें रक्त (हीमोलिम्फ) हीमोसील में ऊतकों को भिगोता है। केंचुए, ऑक्टोपस और मछलियों, सभी में बंद परिसंचरण तंत्र होता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-320","question":"Plants with mycorrhizal fungi on their roots grow better, mainly because the fungal hyphae:","options":["convert atmospheric nitrogen into nitrates for the plant","absorb phosphorus and water from a large soil volume and pass them to the root","digest cellulose in the soil to release glucose for the root","make food by photosynthesis and send it to the root cells"],"answer":1,"explanation":"Mycorrhizal hyphae form a fine network far beyond the root hairs and absorb phosphorus and water, in return for sugars from the plant. Fungi cannot fix nitrogen or photosynthesise.","difficulty":"hard","questionHi":"जिन पौधों की जड़ों पर माइकोराइज़ा कवक होते हैं वे बेहतर बढ़ते हैं, मुख्यतः क्योंकि कवक तंतु:","optionsHi":["वायुमंडलीय नाइट्रोजन को पौधे के लिए नाइट्रेट में बदलते हैं","मिट्टी के बड़े आयतन से फ़ॉस्फ़ोरस और जल सोखकर जड़ को देते हैं","मिट्टी में सेल्युलोस पचाकर जड़ के लिए ग्लूकोस बनाते हैं","प्रकाश संश्लेषण से भोजन बनाकर जड़ कोशिकाओं को भेजते हैं"],"explanationHi":"माइकोराइज़ा के तंतु मूलरोमों से बहुत दूर तक महीन जाल बनाकर फ़ॉस्फ़ोरस और जल सोखते हैं, बदले में पौधे से शर्कराएँ पाते हैं। कवक न तो नाइट्रोजन स्थिर कर सकते हैं और न प्रकाश संश्लेषण।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-321","question":"Which of these viruses has RNA, and not DNA, as its genetic material?","options":["Smallpox virus","Bacteriophage T4","Tobacco mosaic virus","Hepatitis B virus"],"answer":2,"explanation":"Tobacco mosaic virus is a classic RNA virus (it was the first virus to be crystallised). The smallpox virus, bacteriophage T4 and the hepatitis B virus all have DNA genomes.","difficulty":"very-hard","questionHi":"इनमें से किस विषाणु का आनुवंशिक पदार्थ DNA नहीं, बल्कि RNA है?","optionsHi":["चेचक का विषाणु","जीवाणुभोजी T4","तंबाकू मोज़ेक विषाणु","हेपेटाइटिस B विषाणु"],"explanationHi":"तंबाकू मोज़ेक विषाणु RNA विषाणु का उत्कृष्ट उदाहरण है (यही पहला विषाणु था जिसे क्रिस्टल रूप में प्राप्त किया गया)। चेचक का विषाणु, जीवाणुभोजी T4 और हेपेटाइटिस B विषाणु, तीनों का जीनोम DNA है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-322","question":"The antibiotic streptomycin, used against tuberculosis, is obtained from:","options":["Penicillium","Aspergillus","Rhizopus","Streptomyces"],"answer":3,"explanation":"Streptomycin is produced by the soil bacterium Streptomyces griseus. Penicillin comes from the mould Penicillium, so the mould-sounding names in the other options are traps.","difficulty":"hard","questionHi":"क्षय रोग (टीबी) में प्रयुक्त होने वाला प्रतिजैविक स्ट्रेप्टोमाइसिन किससे प्राप्त होता है?","optionsHi":["पेनिसिलियम","ऐस्परजिलस","राइज़ोपस","स्ट्रेप्टोमाइसीज़"],"explanationHi":"स्ट्रेप्टोमाइसिन मृदा जीवाणु स्ट्रेप्टोमाइसीज़ ग्रिसियस से बनता है। पेनिसिलिन फफूँद पेनिसिलियम से मिलता है, इसलिए अन्य विकल्पों के फफूँद जैसे नाम भ्रम पैदा करते हैं।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-323","question":"A malignant tumour differs from a benign tumour mainly because it:","options":["can spread to distant organs through blood or lymph","stays enclosed in a capsule and does not invade","is always painful and kills the patient within days","is produced only by viruses and never by chemicals"],"answer":0,"explanation":"Malignant tumour cells invade neighbouring tissue and spread to distant organs through blood or lymph (metastasis). Benign tumours stay localised, and both kinds can arise from chemicals, radiation or viruses.","difficulty":"hard","questionHi":"कैंसरकारी (दुर्दम) ट्यूमर और सुदम (अहानिकर) ट्यूमर में मुख्य अंतर यह है कि दुर्दम ट्यूमर:","optionsHi":["रक्त या लसीका द्वारा दूर के अंगों तक फैल सकता है","एक कैप्सूल में बंद रहता है और आक्रमण नहीं करता","सदा पीड़ादायक होता है और रोगी को कुछ ही दिनों में मार देता है","केवल विषाणुओं से बनता है, रसायनों से कभी नहीं"],"explanationHi":"दुर्दम ट्यूमर की कोशिकाएँ आसपास के ऊतकों पर आक्रमण करती हैं और रक्त या लसीका द्वारा दूर के अंगों तक फैल जाती हैं (मेटास्टेसिस)। सुदम ट्यूमर एक ही स्थान पर सीमित रहते हैं, और दोनों प्रकार रसायनों, विकिरण या विषाणुओं से हो सकते हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-324","question":"Plague, caused by the bacterium Yersinia pestis, is spread to humans mainly through the bite of:","options":["female Anopheles mosquito","rat flea","tsetse fly","sandfly"],"answer":1,"explanation":"The plague bacterium lives in rodents and is passed on by the rat flea (Xenopsylla); pneumonic plague also spreads from person to person through droplets. Anopheles carries malaria, tsetse the sleeping sickness and sandflies kala-azar.","difficulty":"hard","questionHi":"यर्सीनिया पेस्टिस जीवाणु से होने वाला प्लेग मनुष्यों में मुख्यतः किसके काटने से फैलता है?","optionsHi":["मादा एनोफ़िलीज़ मच्छर","चूहे का पिस्सू","त्सेत्से मक्खी","बालू मक्खी"],"explanationHi":"प्लेग का जीवाणु कृंतकों में रहता है और चूहे के पिस्सू (ज़ेनोप्सिला) द्वारा फैलता है; न्यूमोनिक प्लेग बूँदों से एक व्यक्ति से दूसरे में भी फैलता है। एनोफ़िलीज़ मलेरिया, त्सेत्से निद्रा रोग और बालू मक्खी कालाजार फैलाती हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-325","question":"Which of these diseases is spread mainly through food or water contaminated by faecal matter?","options":["Hepatitis B","AIDS","Hepatitis A","Syphilis"],"answer":2,"explanation":"Hepatitis A virus spreads by the faecal-oral route through contaminated food and water. Hepatitis B, AIDS and syphilis spread mainly through blood, body fluids and sexual contact.","difficulty":"moderate","questionHi":"इनमें से कौन-सा रोग मुख्यतः मल से दूषित भोजन या जल से फैलता है?","optionsHi":["हेपेटाइटिस B","एड्स","हेपेटाइटिस A","सिफिलिस"],"explanationHi":"हेपेटाइटिस A विषाणु दूषित भोजन और जल के माध्यम से मल-मुख मार्ग से फैलता है। हेपेटाइटिस B, एड्स और सिफिलिस मुख्यतः रक्त, शारीरिक द्रवों और यौन संपर्क से फैलते हैं।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-326","question":"How many of these statements are correct? I. Ribosomes in the cytoplasm of bacteria are 70S, while those in the cytoplasm of eukaryotic cells are 80S. II. Mitochondria and chloroplasts contain their own 70S ribosomes. III. Centrioles are present in the cells of all flowering plants. IV. The nucleolus is the main site where rRNA is made.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. Higher plants lack centrioles, so III is wrong; their spindle forms without them.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. जीवाणुओं के कोशिकाद्रव्य में राइबोसोम 70S के होते हैं, जबकि सुकेंद्रकी कोशिकाओं के कोशिकाद्रव्य में 80S के। II. माइटोकॉन्ड्रिया और हरितलवक में अपने 70S राइबोसोम होते हैं। III. सभी पुष्पी पादपों की कोशिकाओं में तारककाय (सेंट्रिओल) होते हैं। IV. केंद्रिका वह मुख्य स्थान है जहाँ rRNA बनता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और IV सही हैं। उच्च पादपों में तारककाय नहीं होते, इसलिए III गलत है; उनमें तर्कु इनके बिना ही बन जाता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-327","question":"A tomato changes from green to red as it ripens. At the cell level this is mainly due to the conversion of:","options":["chloroplasts into chromoplasts","leucoplasts into chloroplasts","chromoplasts into amyloplasts","amyloplasts into elaioplasts"],"answer":0,"explanation":"During ripening the chlorophyll in chloroplasts breaks down and the plastids make red carotenoid (lycopene) pigments, becoming chromoplasts. The reverse change, from colourless plastids to chloroplasts, happens when a potato tuber turns green in light.","difficulty":"hard","questionHi":"पकने पर टमाटर हरे से लाल हो जाता है। कोशिका स्तर पर इसका मुख्य कारण किसका रूपांतरण है?","optionsHi":["हरितलवकों का वर्णीलवकों में","अवर्णीलवकों का हरितलवकों में","वर्णीलवकों का मंडलवकों (ऐमाइलोप्लास्ट) में","मंडलवकों का तैललवकों में"],"explanationHi":"पकने के दौरान हरितलवकों का क्लोरोफ़िल टूट जाता है और लवक लाल कैरोटिनॉइड (लाइकोपीन) वर्णक बनाकर वर्णीलवक बन जाते हैं। रंगहीन लवकों का हरितलवक बन जाना उलटा परिवर्तन है, जो प्रकाश में आलू का कंद हरा पड़ने पर होता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-328","question":"Which of these pairs of organism and the main material of its cell wall is NOT correctly matched?","options":["Plant – cellulose","Fungus – chitin","Bacterium – peptidoglycan","Diatom – cellulose"],"answer":3,"explanation":"Diatoms have a cell wall of silica (the glassy frustule), not cellulose. Plant walls are cellulose, fungal walls are chitin and bacterial walls are peptidoglycan.","difficulty":"hard","questionHi":"जीव और उसकी कोशिका भित्ति की मुख्य सामग्री के इनमें से कौन-से युग्म का मिलान सही नहीं है?","optionsHi":["पादप – सेल्युलोस","कवक – काइटिन","जीवाणु – पेप्टिडोग्लाइकन","डायटम – सेल्युलोस"],"explanationHi":"डायटम की कोशिका भित्ति सिलिका (काँच जैसा फ्रस्चूल) की होती है, सेल्युलोस की नहीं। पादप भित्ति सेल्युलोस की, कवक भित्ति काइटिन की और जीवाणु भित्ति पेप्टिडोग्लाइकन की होती है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-329","question":"In each cycle of the sodium-potassium pump of animal cell membranes, which movement of ions takes place using ATP?","options":["2 Na⁺ out of the cell and 3 K⁺ into the cell","3 Na⁺ out of the cell and 2 K⁺ into the cell","3 Na⁺ into the cell and 2 K⁺ out of the cell","2 Na⁺ into the cell and 2 K⁺ out of the cell"],"answer":1,"explanation":"The pump uses one ATP to push 3 Na⁺ out and bring 2 K⁺ in, both against their concentration gradients. This keeps the cell interior negative and sodium low.","difficulty":"very-hard","questionHi":"जंतु कोशिका झिल्ली के सोडियम-पोटैशियम पंप के प्रत्येक चक्र में ATP के उपयोग से आयनों का कौन-सा स्थानांतरण होता है?","optionsHi":["2 Na⁺ कोशिका से बाहर और 3 K⁺ कोशिका के अंदर","3 Na⁺ कोशिका से बाहर और 2 K⁺ कोशिका के अंदर","3 Na⁺ कोशिका के अंदर और 2 K⁺ कोशिका से बाहर","2 Na⁺ कोशिका के अंदर और 2 K⁺ कोशिका से बाहर"],"explanationHi":"पंप एक ATP खर्च करके 3 Na⁺ बाहर निकालता और 2 K⁺ अंदर लाता है, दोनों अपने सांद्रण प्रवणता के विरुद्ध। इससे कोशिका का भीतरी भाग ऋणात्मक और सोडियम कम बना रहता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-330","question":"Root hairs take up mineral ions from the soil even when the soil has a lower concentration of those ions than the cell sap. This is possible mainly through:","options":["osmosis","simple diffusion","active transport","imbibition"],"answer":2,"explanation":"Moving ions from a lower to a higher concentration goes against the gradient and needs energy, so it is active transport using carrier proteins and ATP. Osmosis is the movement of water, and diffusion follows the gradient.","difficulty":"hard","questionHi":"मूलरोम मिट्टी से खनिज आयन तब भी सोख लेते हैं जब मिट्टी में उन आयनों की सांद्रता कोशिका रस से कम होती है। यह मुख्यतः किसके द्वारा संभव होता है?","optionsHi":["परासरण","सरल विसरण","सक्रिय परिवहन","अंतःशोषण"],"explanationHi":"आयनों को कम सांद्रता से अधिक सांद्रता की ओर ले जाना प्रवणता के विरुद्ध है और ऊर्जा माँगता है, इसलिए यह वाहक प्रोटीनों और ATP से होने वाला सक्रिय परिवहन है। परासरण जल की गति है और विसरण प्रवणता के अनुसार होता है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-331","question":"A solution of an enzyme is cooled to 0 °C and then warmed back to 37 °C. What happens to its activity?","options":["It is lost for ever, because cold denatures enzymes","It is lost for ever, because the enzyme molecules freeze and break","It is higher than normal, because cooling makes enzymes more stable","It is restored, because cooling only slows the enzyme without denaturing it"],"answer":3,"explanation":"Low temperature only reduces the kinetic energy of molecules, so the enzyme becomes inactive but keeps its shape and works again on warming. High temperature (above about 50-60 °C) denatures the protein permanently.","difficulty":"very-hard","questionHi":"एक एंज़ाइम के विलयन को 0 °C तक ठंडा किया जाता है और फिर वापस 37 °C तक गर्म किया जाता है। उसकी सक्रियता का क्या होता है?","optionsHi":["वह सदा के लिए नष्ट हो जाती है, क्योंकि ठंड एंज़ाइमों का विकृतीकरण कर देती है","वह सदा के लिए नष्ट हो जाती है, क्योंकि एंज़ाइम अणु जमकर टूट जाते हैं","वह सामान्य से अधिक हो जाती है, क्योंकि ठंडक एंज़ाइमों को अधिक स्थायी बनाती है","वह लौट आती है, क्योंकि ठंड केवल एंज़ाइम को धीमा करती है, उसका विकृतीकरण नहीं करती"],"explanationHi":"निम्न ताप केवल अणुओं की गतिज ऊर्जा घटाता है, इसलिए एंज़ाइम निष्क्रिय हो जाता है पर अपना आकार बनाए रखता है और गर्म करने पर फिर कार्य करने लगता है। उच्च ताप (लगभग 50-60 °C से ऊपर) प्रोटीन का स्थायी विकृतीकरण कर देता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-332","question":"Hydrolysis of lactose, the sugar of milk, gives:","options":["glucose and galactose","glucose and fructose","two molecules of glucose","fructose and galactose"],"answer":0,"explanation":"Lactose is a disaccharide of glucose and galactose, split by lactase. Sucrose gives glucose and fructose, and maltose gives two molecules of glucose.","difficulty":"moderate","questionHi":"दूध की शर्करा लैक्टोस के जल-अपघटन से क्या प्राप्त होता है?","optionsHi":["ग्लूकोस और गैलेक्टोस","ग्लूकोस और फ्रक्टोस","ग्लूकोस के दो अणु","फ्रक्टोस और गैलेक्टोस"],"explanationHi":"लैक्टोस ग्लूकोस और गैलेक्टोस का द्विशर्करा है, जिसे लैक्टेज़ तोड़ता है। सुक्रोस से ग्लूकोस और फ्रक्टोस तथा माल्टोस से ग्लूकोस के दो अणु मिलते हैं।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-333","question":"Which of these biomolecules does NOT contain phosphorus?","options":["ATP","Phospholipids","Glycogen","DNA"],"answer":2,"explanation":"Glycogen is a polymer of glucose made only of carbon, hydrogen and oxygen. ATP, DNA and phospholipids all contain phosphate groups.","difficulty":"hard","questionHi":"इनमें से किस जैव अणु में फ़ॉस्फ़ोरस नहीं होता?","optionsHi":["ATP","फ़ॉस्फ़ोलिपिड","ग्लाइकोजन","DNA"],"explanationHi":"ग्लाइकोजन ग्लूकोस का बहुलक है जो केवल कार्बन, हाइड्रोजन और ऑक्सीजन से बना है। ATP, DNA और फ़ॉस्फ़ोलिपिड सभी में फ़ॉस्फ़ेट समूह होते हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-334","question":"Assertion (A): A plant raised by vegetative propagation shows more genetic variation from its parent than a plant raised from seed. Reason (R): Vegetative propagation involves only mitotic divisions.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"Vegetative propagation uses only mitosis, so the new plant is a clone of its parent with almost no variation; the reason is true but it makes the assertion false. Seed-raised plants arise from gamete fusion and vary.","difficulty":"hard","questionHi":"अभिकथन (A): कायिक प्रवर्धन से उगाए गए पौधे में बीज से उगाए गए पौधे की तुलना में अपने जनक से अधिक आनुवंशिक विविधता होती है। कारण (R): कायिक प्रवर्धन में केवल समसूत्री विभाजन होते हैं।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं, पर R, A की सही व्याख्या नहीं है","A सही है पर R गलत है","A गलत है पर R सही है"],"explanationHi":"कायिक प्रवर्धन में केवल समसूत्री विभाजन होता है, इसलिए नया पौधा जनक का क्लोन होता है और उसमें लगभग कोई विविधता नहीं होती; कारण सही है पर वह अभिकथन को गलत बनाता है। बीज से उगे पौधे युग्मक संलयन से बनते हैं और उनमें विविधता होती है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-335","question":"Match the branch of biology with what it studies: 1. Pomology 2. Mycology 3. Ornithology 4. Phycology; a. Birds b. Algae c. Fungi d. Fruits.","options":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-a, 4-b","1-d, 2-c, 3-b, 4-a","1-a, 2-c, 3-d, 4-b"],"answer":1,"explanation":"Pomology is the study of fruits, mycology of fungi, ornithology of birds and phycology of algae.","difficulty":"moderate","questionHi":"जीव विज्ञान की शाखा का उसके अध्ययन विषय से मिलान कीजिए: 1. पोमोलॉजी 2. माइकोलॉजी 3. ऑर्निथोलॉजी 4. फाइकोलॉजी; a. पक्षी b. शैवाल c. कवक d. फल।","optionsHi":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-a, 4-b","1-d, 2-c, 3-b, 4-a","1-a, 2-c, 3-d, 4-b"],"explanationHi":"पोमोलॉजी फलों का, माइकोलॉजी कवकों का, ऑर्निथोलॉजी पक्षियों का और फाइकोलॉजी शैवालों का अध्ययन है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-336","question":"Match the title with the scientist: 1. Father of Genetics 2. Father of Modern Taxonomy 3. Father of Zoology 4. Father of Botany; a. Aristotle b. Linnaeus c. Mendel d. Theophrastus.","options":["1-c, 2-b, 3-a, 4-d","1-c, 2-a, 3-b, 4-d","1-b, 2-c, 3-a, 4-d","1-c, 2-b, 3-d, 4-a"],"answer":0,"explanation":"Mendel is the father of genetics, Linnaeus of modern taxonomy, Aristotle of zoology and his pupil Theophrastus of botany.","difficulty":"hard","questionHi":"उपाधि का वैज्ञानिक से मिलान कीजिए: 1. आनुवंशिकी के जनक 2. आधुनिक वर्गिकी के जनक 3. जंतु विज्ञान के जनक 4. वनस्पति विज्ञान के जनक; a. अरस्तू b. लिनियस c. मेंडल d. थियोफ्रेस्टस।","optionsHi":["1-c, 2-b, 3-a, 4-d","1-c, 2-a, 3-b, 4-d","1-b, 2-c, 3-a, 4-d","1-c, 2-b, 3-d, 4-a"],"explanationHi":"मेंडल आनुवंशिकी के जनक, लिनियस आधुनिक वर्गिकी के जनक, अरस्तू जंतु विज्ञान के जनक और उनके शिष्य थियोफ्रेस्टस वनस्पति विज्ञान के जनक हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-337","question":"Match the scientist with the contribution: 1. William Harvey 2. Karl Landsteiner 3. Robert Hooke 4. Robert Koch; a. Cells seen in a slice of cork b. Circulation of blood c. Bacterium causing tuberculosis d. ABO blood groups.","options":["1-d, 2-b, 3-a, 4-c","1-b, 2-d, 3-c, 4-a","1-b, 2-a, 3-d, 4-c","1-b, 2-d, 3-a, 4-c"],"answer":3,"explanation":"Harvey described the circulation of blood (1628), Landsteiner discovered the ABO groups (1901), Hooke saw cells in cork (1665) and Koch identified the tubercle bacillus (1882).","difficulty":"hard","questionHi":"वैज्ञानिक का योगदान से मिलान कीजिए: 1. विलियम हार्वे 2. कार्ल लैंडस्टाइनर 3. रॉबर्ट हुक 4. रॉबर्ट कोच; a. कॉर्क के टुकड़े में कोशिकाओं का अवलोकन b. रक्त परिसंचरण c. क्षय रोग उत्पन्न करने वाला जीवाणु d. ABO रक्त समूह।","optionsHi":["1-d, 2-b, 3-a, 4-c","1-b, 2-d, 3-c, 4-a","1-b, 2-a, 3-d, 4-c","1-b, 2-d, 3-a, 4-c"],"explanationHi":"हार्वे ने रक्त परिसंचरण (1628) का वर्णन किया, लैंडस्टाइनर ने ABO समूह (1901) खोजे, हुक ने कॉर्क में कोशिकाएँ देखीं (1665) और कोच ने क्षय रोग के जीवाणु की पहचान की (1882)।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-338","question":"In industrial areas of England, dark-coloured peppered moths became much commoner than light-coloured ones during the 19th century because:","options":["birds could not see the dark moths against any background, including the pale lichen-covered bark","dark moths were better camouflaged on sooty trunks, so birds ate more light ones","pollution made the light moths change colour into dark ones within a single generation","dark moths migrated in large numbers from the countryside into the industrial towns"],"answer":1,"explanation":"On sooty trunks light moths stood out and were eaten, so dark moths survived and bred more: natural selection acting on existing variation. Individual moths did not change colour because of pollution.","difficulty":"hard","questionHi":"इंग्लैंड के औद्योगिक क्षेत्रों में 19वीं सदी में गहरे रंग के पेपर्ड पतंगे हल्के रंग वालों से बहुत अधिक हो गए, क्योंकि:","optionsHi":["पक्षी किसी भी पृष्ठभूमि पर, हल्के लाइकेन वाली छाल पर भी, गहरे पतंगों को नहीं देख पाते थे","कालिख वाले तनों पर गहरे पतंगों का छद्मावरण बेहतर था, इसलिए पक्षी हल्के पतंगों को अधिक खाते थे","प्रदूषण से हल्के पतंगे एक ही पीढ़ी में रंग बदलकर गहरे हो गए","गहरे पतंगे बड़ी संख्या में गाँवों से औद्योगिक कस्बों में प्रवास करके आ गए"],"explanationHi":"कालिख वाले तनों पर हल्के पतंगे साफ़ दिखते और खाए जाते थे, इसलिए गहरे पतंगे जीवित रहकर अधिक संतान पैदा करते रहे: यह विद्यमान विविधता पर प्राकृतिक चयन है। प्रदूषण से किसी पतंगे का रंग नहीं बदला।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-339","question":"Archaeopteryx, a fossil animal with feathers, teeth and a long bony tail, is regarded as a connecting link between:","options":["fishes and amphibians","amphibians and reptiles","reptiles and birds","reptiles and mammals"],"answer":2,"explanation":"Archaeopteryx had bird-like feathers and wings but reptile-like teeth, claws and a long tail, so it links reptiles and birds. It supports the idea that birds evolved from reptiles.","difficulty":"moderate","questionHi":"पंख, दाँत और लंबी अस्थिल पूँछ वाला जीवाश्म जंतु आर्कियोप्टेरिक्स किन दो वर्गों के बीच की संयोजक कड़ी माना जाता है?","optionsHi":["मत्स्य और उभयचर","उभयचर और सरीसृप","सरीसृप और पक्षी","सरीसृप और स्तनधारी"],"explanationHi":"आर्कियोप्टेरिक्स में पक्षियों जैसे पंख और डैने थे, पर सरीसृपों जैसे दाँत, नखर और लंबी पूँछ थी, इसलिए वह सरीसृपों और पक्षियों को जोड़ता है। यह इस विचार का समर्थन करता है कि पक्षी सरीसृपों से विकसित हुए।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-340","question":"In the 1953 experiment of Miller and Urey that simulated conditions on the early Earth, which mixture of gases was exposed to electric sparks?","options":["Methane, ammonia, hydrogen and water vapour","Oxygen, nitrogen, carbon dioxide and water vapour","Ammonia, oxygen, hydrogen and carbon monoxide","Carbon dioxide, nitrogen, oxygen and argon"],"answer":0,"explanation":"They used a reducing atmosphere of CH₄, NH₃, H₂ and water vapour, and amino acids formed after days of sparking. Free oxygen was deliberately left out, since it was absent from the early atmosphere.","difficulty":"hard","questionHi":"पृथ्वी की आरंभिक परिस्थितियों का अनुकरण करने वाले 1953 के मिलर और यूरे के प्रयोग में विद्युत स्फुलिंगों के संपर्क में कौन-सा गैस मिश्रण रखा गया था?","optionsHi":["मेथेन, अमोनिया, हाइड्रोजन और जलवाष्प","ऑक्सीजन, नाइट्रोजन, कार्बन डाइऑक्साइड और जलवाष्प","अमोनिया, ऑक्सीजन, हाइड्रोजन और कार्बन मोनोक्साइड","कार्बन डाइऑक्साइड, नाइट्रोजन, ऑक्सीजन और ऑर्गन"],"explanationHi":"उन्होंने CH₄, NH₃, H₂ और जलवाष्प का अपचायक वायुमंडल प्रयोग किया और कई दिन चिंगारियाँ देने पर अमीनो अम्ल बने। मुक्त ऑक्सीजन जानबूझकर नहीं रखी गई, क्योंकि आरंभिक वायुमंडल में वह नहीं थी।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-341","question":"The different beak shapes of the finches of the Galapagos Islands, each suited to a different food, are an example of:","options":["convergent evolution","genetic drift","artificial selection","adaptive radiation"],"answer":3,"explanation":"Adaptive radiation is the evolution of many different forms from a common ancestor in a new environment. Darwin's finches arose from one ancestral species and adapted to seeds, insects or cactus.","difficulty":"hard","questionHi":"गैलापागोस द्वीपों के फ़िंच पक्षियों की भिन्न-भिन्न चोंच आकृतियाँ, जिनमें से प्रत्येक अलग भोजन के अनुकूल है, किसका उदाहरण हैं?","optionsHi":["अभिसारी विकास","आनुवंशिक विचलन","कृत्रिम चयन","अनुकूली विकिरण"],"explanationHi":"अनुकूली विकिरण में किसी नए पर्यावरण में एक ही पूर्वज से अनेक भिन्न रूप विकसित होते हैं। डार्विन के फ़िंच एक ही पूर्वज जाति से बने और बीजों, कीटों या कैक्टस के अनुकूल हुए।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-342","question":"Which sequence shows the correct order of appearance of these human ancestors, earliest first?","options":["Homo habilis, Australopithecus, Homo erectus, Homo sapiens","Australopithecus, Homo erectus, Homo habilis, Homo sapiens","Australopithecus, Homo habilis, Homo erectus, Homo sapiens","Homo erectus, Australopithecus, Homo habilis, Homo sapiens"],"answer":2,"explanation":"Australopithecus appeared first, then Homo habilis (the handy man, tool user), then Homo erectus (the upright man) and finally Homo sapiens.","difficulty":"hard","questionHi":"इन मानव पूर्वजों के प्रकट होने का सही क्रम (सबसे पहले वाला पहले) कौन-सा है?","optionsHi":["होमो हैबिलिस, ऑस्ट्रैलोपिथेकस, होमो इरेक्टस, होमो सेपिएन्स","ऑस्ट्रैलोपिथेकस, होमो इरेक्टस, होमो हैबिलिस, होमो सेपिएन्स","ऑस्ट्रैलोपिथेकस, होमो हैबिलिस, होमो इरेक्टस, होमो सेपिएन्स","होमो इरेक्टस, ऑस्ट्रैलोपिथेकस, होमो हैबिलिस, होमो सेपिएन्स"],"explanationHi":"सबसे पहले ऑस्ट्रैलोपिथेकस आया, फिर होमो हैबिलिस (औज़ार बनाने वाला), फिर होमो इरेक्टस (सीधा खड़ा होने वाला) और अंत में होमो सेपिएन्स।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-343","question":"A person bitten by a venomous snake is given an injection of antivenom. This gives the person:","options":["active immunity, because the body makes its own antibodies at once","passive immunity, because ready-made antibodies are supplied from outside","innate immunity, because it was present from birth","herd immunity, because the people nearby also become protected"],"answer":1,"explanation":"Antivenom contains ready-made antibodies raised in an animal, so it gives immediate but short-lived passive immunity. A vaccine, in contrast, makes the body produce its own antibodies and memory cells.","difficulty":"hard","questionHi":"विषैले साँप द्वारा काटे गए व्यक्ति को प्रतिविष (ऐंटीवेनम) का इंजेक्शन दिया जाता है। इससे व्यक्ति को मिलती है:","optionsHi":["सक्रिय प्रतिरक्षा, क्योंकि शरीर तुरंत अपने प्रतिरक्षी बनाता है","निष्क्रिय प्रतिरक्षा, क्योंकि बने-बनाए प्रतिरक्षी बाहर से दिए जाते हैं","सहज प्रतिरक्षा, क्योंकि वह जन्म से ही मौजूद थी","झुंड प्रतिरक्षा, क्योंकि आसपास के लोग भी सुरक्षित हो जाते हैं"],"explanationHi":"प्रतिविष में किसी जंतु में बनाए गए बने-बनाए प्रतिरक्षी होते हैं, इसलिए वह तुरंत पर थोड़े समय की निष्क्रिय प्रतिरक्षा देता है। इसके विपरीत टीका शरीर को अपने प्रतिरक्षी और स्मृति कोशिकाएँ बनाने के लिए प्रेरित करता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-344","question":"Antihistamine tablets relieve the sneezing and itching of a pollen allergy mainly by blocking the action of:","options":["heparin","insulin","adrenaline","histamine"],"answer":3,"explanation":"In an allergy, mast cells release histamine, which widens blood vessels and causes sneezing, itching and watery eyes. Antihistamines block its receptors.","difficulty":"moderate","questionHi":"परागकण से होने वाली एलर्जी में छींक और खुजली को एंटीहिस्टामिन गोलियाँ मुख्यतः किसकी क्रिया रोककर कम करती हैं?","optionsHi":["हेपेरिन","इंसुलिन","ऐड्रीनलीन","हिस्टामिन"],"explanationHi":"एलर्जी में मास्ट कोशिकाएँ हिस्टामिन मुक्त करती हैं, जो रुधिर वाहिकाओं को चौड़ा करता है और छींक, खुजली तथा आँखों से पानी आने का कारण बनता है। एंटीहिस्टामिन उसके ग्राहियों को रोक देते हैं।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-345","question":"Type 1 (juvenile-onset) diabetes mellitus is mainly due to:","options":["destruction of the beta cells of the pancreas, so little insulin is made","body cells failing to respond to insulin although it is plentiful","over-production of glucagon by the thyroid gland","lack of ADH from the posterior pituitary"],"answer":0,"explanation":"In type 1 diabetes the immune system destroys the insulin-making beta cells, so insulin injections are needed. Type 2 is mainly resistance of body cells to insulin.","difficulty":"hard","questionHi":"टाइप 1 (किशोरावस्था में शुरू होने वाला) मधुमेह मुख्यतः किस कारण होता है?","optionsHi":["अग्न्याशय की बीटा कोशिकाओं के नष्ट होने से, जिससे इंसुलिन कम बनता है","इंसुलिन भरपूर होने पर भी शरीर की कोशिकाओं का उस पर प्रतिक्रिया न करना","थायरॉइड ग्रंथि द्वारा ग्लूकागॉन का अत्यधिक बनना","पश्च पीयूष ग्रंथि से ADH की कमी"],"explanationHi":"टाइप 1 मधुमेह में प्रतिरक्षा तंत्र इंसुलिन बनाने वाली बीटा कोशिकाओं को नष्ट कर देता है, इसलिए इंसुलिन के इंजेक्शन आवश्यक होते हैं। टाइप 2 मुख्यतः कोशिकाओं के इंसुलिन के प्रति प्रतिरोधी होने से होता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-346","question":"Each villus of the small intestine contains a lymph vessel called the lacteal. It mainly absorbs:","options":["glucose and amino acids, which are carried to the liver","water and mineral salts, which are carried to the large intestine","fatty acids and glycerol, carried away as fat","vitamin C and the B vitamins, which dissolve in water"],"answer":2,"explanation":"Fat digestion products are re-formed into small fat droplets that enter the lacteals and travel in the lymph. Glucose, amino acids and water-soluble vitamins enter the blood capillaries of the villus.","difficulty":"hard","questionHi":"छोटी आँत के प्रत्येक रसांकुर में लैक्टियल नामक लसीका वाहिनी होती है। वह मुख्यतः क्या अवशोषित करती है?","optionsHi":["ग्लूकोस और अमीनो अम्ल, जो यकृत तक ले जाए जाते हैं","जल और खनिज लवण, जो बड़ी आँत तक ले जाए जाते हैं","वसीय अम्ल और ग्लिसरॉल, जो वसा के रूप में ले जाए जाते हैं","विटामिन C और B समूह के विटामिन, जो जल में घुल जाते हैं"],"explanationHi":"वसा के पाचन उत्पाद पुनः छोटी वसा बूँदों में बनकर लैक्टियल में प्रवेश करते हैं और लसीका में बह जाते हैं। ग्लूकोस, अमीनो अम्ल और जल में घुलनशील विटामिन रसांकुर की रुधिर केशिकाओं में जाते हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-347","question":"The inactive trypsinogen of pancreatic juice is converted into active trypsin by:","options":["hydrochloric acid of the stomach","enterokinase of the intestinal juice","bile salts from the liver","pepsin of the gastric juice"],"answer":1,"explanation":"Enterokinase (enteropeptidase) secreted by the intestinal wall activates trypsinogen, and trypsin then activates other pancreatic enzymes. Keeping enzymes inactive until they reach the intestine protects the pancreas from digesting itself.","difficulty":"very-hard","questionHi":"अग्न्याशयिक रस का निष्क्रिय ट्रिप्सिनोजन किसके द्वारा सक्रिय ट्रिप्सिन में बदला जाता है?","optionsHi":["आमाशय के हाइड्रोक्लोरिक अम्ल द्वारा","आंत्र रस के एंटेरोकाइनेज़ द्वारा","यकृत के पित्त लवणों द्वारा","जठर रस के पेप्सिन द्वारा"],"explanationHi":"आँत की दीवार से स्रावित एंटेरोकाइनेज़ (एंटेरोपेप्टिडेज़) ट्रिप्सिनोजन को सक्रिय करता है और ट्रिप्सिन फिर अग्न्याशय के अन्य एंज़ाइमों को सक्रिय करता है। एंज़ाइमों को आँत तक निष्क्रिय रखना अग्न्याशय को स्वयं के पाचन से बचाता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-348","question":"Most kidney stones are made mainly of crystals of:","options":["sodium chloride","urea","calcium sulphate","calcium oxalate"],"answer":3,"explanation":"Kidney stones usually form when calcium oxalate (or calcium phosphate) crystallises from concentrated urine. A good water intake and less oxalate-rich food help to prevent them.","difficulty":"moderate","questionHi":"अधिकांश गुर्दे की पथरियाँ मुख्यतः किसके क्रिस्टलों से बनी होती हैं?","optionsHi":["सोडियम क्लोराइड","यूरिया","कैल्सियम सल्फ़ेट","कैल्सियम ऑक्सलेट"],"explanationHi":"गुर्दे की पथरी सामान्यतः तब बनती है जब सांद्र मूत्र से कैल्सियम ऑक्सलेट (या कैल्सियम फ़ॉस्फ़ेट) क्रिस्टलित हो जाता है। पर्याप्त जल पीना और ऑक्सलेट-समृद्ध भोजन कम लेना इन्हें रोकने में सहायक है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-349","question":"An adult's kidneys filter about 180 litres of fluid from the blood in a day but only about 1.8 litres of urine is passed. What percentage of the filtrate is reabsorbed into the blood?","options":["99%","90%","95%","99.9%"],"answer":0,"explanation":"Urine is 1.8 ÷ 180 = 1% of the filtrate, so 100 − 1 = 99% is reabsorbed by the tubules. Most of this water, with all the glucose and amino acids, goes back to the blood.","difficulty":"moderate","questionHi":"एक वयस्क के गुर्दे दिन भर में रक्त से लगभग 180 लीटर द्रव छानते हैं, पर केवल लगभग 1.8 लीटर मूत्र निकलता है। छनित का कितना प्रतिशत रक्त में पुनः अवशोषित होता है?","optionsHi":["99%","90%","95%","99.9%"],"explanationHi":"मूत्र छनित का 1.8 ÷ 180 = 1% है, इसलिए 100 − 1 = 99% नलिकाओं द्वारा पुनः अवशोषित हो जाता है। इसमें से अधिकांश जल, तथा सारा ग्लूकोस और अमीनो अम्ल, रक्त में लौट जाते हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-350","question":"On a hot day when a person drinks very little water, the secretion of ADH ___ and the urine becomes ___.","options":["increases; dilute","increases; concentrated","decreases; concentrated","decreases; dilute"],"answer":1,"explanation":"Lack of water raises the concentration of the blood and the hypothalamus signals the release of more ADH, which makes the collecting ducts reabsorb more water. Less water in the urine means a smaller volume of more concentrated urine.","difficulty":"hard","questionHi":"गर्म दिन में जब कोई व्यक्ति बहुत कम पानी पीता है, तब ADH का स्राव ___ और मूत्र ___ हो जाता है।","optionsHi":["बढ़ता है; तनु","बढ़ता है; सांद्र","घटता है; सांद्र","घटता है; तनु"],"explanationHi":"जल की कमी से रक्त की सांद्रता बढ़ती है और अधश्चेतक अधिक ADH मुक्त करने का संकेत देता है, जिससे संग्रह नलिकाएँ अधिक जल पुनः अवशोषित करती हैं। मूत्र में जल कम होने से कम मात्रा का अधिक सांद्र मूत्र बनता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-351","question":"Doctors advise women who are planning a pregnancy to take folic acid (vitamin B9) because it lowers the risk of defects of the:","options":["heart valves and the major arteries of the baby","neural tube, the future brain and spinal cord","limbs, fingers and toes of the developing baby","kidneys and the urinary bladder of the baby"],"answer":1,"explanation":"Folic acid is needed for rapid cell division and DNA synthesis in the early weeks, when the neural tube closes. Lack of it raises the risk of defects such as spina bifida.","difficulty":"hard","questionHi":"गर्भधारण की योजना बना रही महिलाओं को डॉक्टर फ़ोलिक अम्ल (विटामिन B9) लेने की सलाह देते हैं, क्योंकि यह किस भाग के दोषों का जोखिम घटाता है?","optionsHi":["शिशु के हृदय के वाल्व और प्रमुख धमनियाँ","तंत्रिका नलिका, भावी मस्तिष्क और मेरुरज्जु","विकसित हो रहे शिशु के हाथ-पैर, अँगुलियाँ और पादांगुलियाँ","शिशु के गुर्दे और मूत्राशय"],"explanationHi":"आरंभिक सप्ताहों में, जब तंत्रिका नलिका बंद होती है, तेज़ कोशिका विभाजन और DNA संश्लेषण के लिए फ़ोलिक अम्ल चाहिए। इसकी कमी से स्पाइना बिफ़िडा जैसे दोषों का जोखिम बढ़ जाता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-352","question":"Strict vegetarians (vegans) run a risk of vitamin B12 deficiency mainly because:","options":["B12 is found only in fruits and vegetables that are lost in cooking","B12 is made by the human skin only in sunlight","B12 is made by microorganisms and occurs naturally almost only in foods of animal origin","B12 is destroyed by plant proteins inside the intestine"],"answer":2,"explanation":"Vitamin B12 (cobalamin) is synthesised by bacteria and reaches us through milk, eggs, meat and fish, so plant foods contain almost none. Deficiency causes pernicious anaemia and nerve damage.","difficulty":"hard","questionHi":"कठोर शाकाहारियों (वीगन) में विटामिन B12 की कमी का जोखिम मुख्यतः इसलिए रहता है क्योंकि:","optionsHi":["B12 केवल उन फलों और सब्ज़ियों में होता है जो पकाने में नष्ट हो जाते हैं","B12 मानव त्वचा में केवल धूप में बनता है","B12 सूक्ष्मजीवों द्वारा बनता है और प्राकृतिक रूप से लगभग केवल पशु-स्रोत वाले भोजन में मिलता है","B12 को पादप प्रोटीन आँत में नष्ट कर देते हैं"],"explanationHi":"विटामिन B12 (कोबालामिन) जीवाणुओं द्वारा बनाया जाता है और दूध, अंडे, मांस तथा मछली के रास्ते हम तक पहुँचता है, इसलिए पादप भोजन में लगभग नहीं होता। इसकी कमी से हानिकारक अरक्तता और तंत्रिका क्षति होती है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-353","question":"Even when the diet has enough calcium, a child who stays indoors and has little vitamin D may develop rickets because vitamin D is needed to:","options":["supply phosphorus that makes up the whole bone material","convert calcium into phosphate in the liver","protect the calcium in food from stomach acid","help the intestine absorb calcium from the food"],"answer":3,"explanation":"Vitamin D (formed in the skin in sunlight) promotes absorption of calcium and phosphate from the intestine. Without it the bones stay soft and bend, giving rickets in children.","difficulty":"hard","questionHi":"भोजन में पर्याप्त कैल्सियम होने पर भी घर के भीतर रहने वाले और कम विटामिन D पाने वाले बच्चे को रिकेट्स हो सकता है, क्योंकि विटामिन D की आवश्यकता होती है:","optionsHi":["फ़ॉस्फ़ोरस देने के लिए, जो पूरे अस्थि पदार्थ को बनाता है","यकृत में कैल्सियम को फ़ॉस्फ़ेट में बदलने के लिए","भोजन के कैल्सियम को आमाशय के अम्ल से बचाने के लिए","आँत को भोजन से कैल्सियम अवशोषित करने में सहायता देने के लिए"],"explanationHi":"विटामिन D (जो धूप में त्वचा में बनता है) आँत से कैल्सियम और फ़ॉस्फ़ेट के अवशोषण को बढ़ावा देता है। उसके बिना हड्डियाँ नरम रहकर मुड़ जाती हैं, जिससे बच्चों में रिकेट्स होता है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-354","question":"Which hormone lowers the level of calcium in the blood?","options":["Calcitonin","Parathormone","Thyroxine","Aldosterone"],"answer":0,"explanation":"Calcitonin from the thyroid gland lowers blood calcium by promoting its deposition in bone. Parathormone from the parathyroids does the opposite and raises blood calcium.","difficulty":"very-hard","questionHi":"कौन-सा हॉर्मोन रक्त में कैल्सियम का स्तर घटाता है?","optionsHi":["कैल्सिटोनिन","पैराथॉर्मोन","थायरॉक्सिन","ऐल्डोस्टेरोन"],"explanationHi":"थायरॉइड ग्रंथि का कैल्सिटोनिन कैल्सियम को अस्थियों में जमा कराकर रक्त का कैल्सियम घटाता है। परावटु ग्रंथियों का पैराथॉर्मोन इसके विपरीत कार्य करके रक्त का कैल्सियम बढ़ाता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-355","question":"When a baby suckles, which hormone triggers the ejection of milk from the mother's mammary glands?","options":["Prolactin","Oxytocin","Progesterone","Oestrogen"],"answer":1,"explanation":"Suckling stimulates the posterior pituitary to release oxytocin, which contracts the cells around the milk ducts and pushes the milk out. Prolactin makes the milk but does not eject it.","difficulty":"very-hard","questionHi":"जब शिशु दूध पीता है, तब माता की स्तन ग्रंथियों से दूध के निष्कासन को कौन-सा हॉर्मोन प्रेरित करता है?","optionsHi":["प्रोलैक्टिन","ऑक्सीटोसिन","प्रोजेस्टेरोन","ईस्ट्रोजन"],"explanationHi":"दूध चूसने से पश्च पीयूष ग्रंथि ऑक्सीटोसिन मुक्त करती है, जो दुग्ध नलिकाओं के चारों ओर की कोशिकाओं को सिकोड़कर दूध बाहर धकेलता है। प्रोलैक्टिन दूध बनाता है पर उसे बाहर नहीं निकालता।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-356","question":"In very cold weather the small arteries (arterioles) of the skin ___, which helps the body to ___.","options":["dilate; bring more warm blood to the skin and keep the body warm","dilate; let sweat evaporate faster from the skin and cool the body","constrict; reduce blood flow near the skin and lose less heat","constrict; make the skin itself produce more heat by shivering"],"answer":2,"explanation":"Vasoconstriction in the skin cuts blood flow near the surface and so reduces heat loss, while shivering produces extra heat. In hot weather the arterioles dilate to lose heat.","difficulty":"very-hard","questionHi":"बहुत ठंडे मौसम में त्वचा की छोटी धमनिकाएँ ___, जिससे शरीर को ___ में सहायता मिलती है।","optionsHi":["फैलती हैं; त्वचा तक अधिक गर्म रक्त लाने और शरीर को गर्म रखने","फैलती हैं; त्वचा से पसीने को तेज़ी से वाष्पित होने देने और शरीर को ठंडा करने","सिकुड़ती हैं; त्वचा के पास रक्त प्रवाह घटाने और कम ऊष्मा खोने","सिकुड़ती हैं; त्वचा द्वारा कंपकंपी से स्वयं अधिक ऊष्मा उत्पन्न कराने"],"explanationHi":"त्वचा में वाहिकासंकीर्णन सतह के पास रक्त प्रवाह घटाकर ऊष्मा की हानि कम करता है, जबकि कंपकंपी अतिरिक्त ऊष्मा उत्पन्न करती है। गर्मी में धमनिकाएँ ऊष्मा खोने के लिए फैल जाती हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-357","question":"Which chamber of the human heart has the thickest muscular wall?","options":["Right atrium","Right ventricle","Left atrium","Left ventricle"],"answer":3,"explanation":"The left ventricle pumps blood at high pressure to the whole body, so its wall is about three times thicker than that of the right ventricle, which supplies only the nearby lungs. The atria have thin walls.","difficulty":"moderate","questionHi":"मानव हृदय के किस कक्ष की पेशीय भित्ति सबसे मोटी होती है?","optionsHi":["दायाँ अलिंद","दायाँ निलय","बायाँ अलिंद","बायाँ निलय"],"explanationHi":"बायाँ निलय पूरे शरीर में उच्च दाब पर रक्त पंप करता है, इसलिए उसकी भित्ति दाएँ निलय से लगभग तीन गुनी मोटी होती है, जो केवल पास के फेफड़ों को रक्त देता है। अलिंदों की भित्ति पतली होती है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-358","question":"Which pair of enzyme and its function, as used in genetic engineering, is correct?","options":["DNA ligase – seals the cut ends of DNA pieces together","Restriction enzyme – seals the cut ends of DNA pieces together","DNA polymerase – cuts DNA at specific base sequences","RNA polymerase – cuts DNA at specific base sequences"],"answer":0,"explanation":"Restriction enzymes act as molecular scissors, cutting DNA at specific recognition sequences, and DNA ligase acts as the glue that joins the fragments. Polymerases build new nucleic acid strands; they do not cut at specific sites.","difficulty":"hard","questionHi":"आनुवंशिक इंजीनियरी में प्रयुक्त एंज़ाइम और उसके कार्य का कौन-सा युग्म सही है?","optionsHi":["DNA लाइगेज़ – DNA के कटे टुकड़ों के सिरों को जोड़ता है","प्रतिबंध एंज़ाइम – DNA के कटे टुकड़ों के सिरों को जोड़ता है","DNA पॉलिमरेज़ – DNA को विशिष्ट क्षार अनुक्रमों पर काटता है","RNA पॉलिमरेज़ – DNA को विशिष्ट क्षार अनुक्रमों पर काटता है"],"explanationHi":"प्रतिबंध एंज़ाइम आणविक कैंची की तरह DNA को विशिष्ट पहचान अनुक्रमों पर काटते हैं और DNA लाइगेज़ गोंद की तरह टुकड़ों को जोड़ता है। पॉलिमरेज़ नई न्यूक्लिक अम्ल शृंखलाएँ बनाते हैं; वे विशिष्ट स्थलों पर नहीं काटते।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-359","question":"The heat-stable enzyme Taq polymerase, used in the polymerase chain reaction (PCR), is obtained from:","options":["Escherichia coli of the human gut","Thermus aquaticus, a bacterium of hot springs","Bacillus thuringiensis of the soil","Agrobacterium tumefaciens of plant roots"],"answer":1,"explanation":"Thermus aquaticus lives in hot springs, so its DNA polymerase is not denatured at the roughly 95 °C used to separate DNA strands in each PCR cycle. Enzymes of E. coli would be destroyed.","difficulty":"very-hard","questionHi":"पॉलिमरेज़ शृंखला अभिक्रिया (PCR) में प्रयुक्त ऊष्मा-स्थायी एंज़ाइम टैक पॉलिमरेज़ किससे प्राप्त होता है?","optionsHi":["मानव आँत के एशेरिकिया कोलाई से","गर्म सोतों के जीवाणु थर्मस एक्वाटिकस से","मृदा के बैसिलस थुरिन्जिएन्सिस से","पादप जड़ों के एग्रोबैक्टीरियम ट्यूमिफेशियन्स से"],"explanationHi":"थर्मस एक्वाटिकस गर्म सोतों में रहता है, इसलिए प्रत्येक PCR चक्र में DNA रज्जुकों को अलग करने के लिए प्रयुक्त लगभग 95 °C पर उसका DNA पॉलिमरेज़ विकृत नहीं होता। E. coli के एंज़ाइम नष्ट हो जाते।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-360","question":"DNA fingerprinting is useful in identifying a person because:","options":["the DNA inside every cell of the same person is different","a person's DNA pattern keeps changing with age and food habits","every individual, except identical twins, has a unique pattern of repeated DNA sequences (VNTRs)","only the blood proteins of a person can be matched in a laboratory"],"answer":2,"explanation":"The number of repeats of short DNA sequences varies between people, giving a band pattern that is unique to each individual except identical twins. It stays the same in all body cells and throughout life.","difficulty":"hard","questionHi":"DNA अंगुलिछापन किसी व्यक्ति की पहचान में इसलिए उपयोगी है क्योंकि:","optionsHi":["एक ही व्यक्ति की प्रत्येक कोशिका का DNA भिन्न होता है","व्यक्ति का DNA प्रतिरूप आयु और खान-पान के साथ बदलता रहता है","समरूप जुड़वाँ को छोड़कर हर व्यक्ति में दोहराए गए DNA अनुक्रमों (VNTR) का अनूठा प्रतिरूप होता है","प्रयोगशाला में केवल व्यक्ति के रक्त प्रोटीनों का मिलान हो सकता है"],"explanationHi":"छोटे DNA अनुक्रमों की दोहराव संख्या लोगों में भिन्न होती है, जिससे समरूप जुड़वाँ को छोड़कर प्रत्येक व्यक्ति के लिए अनूठा बैंड प्रतिरूप बनता है। यह शरीर की सभी कोशिकाओं में और जीवन भर समान रहता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-361","question":"Plant breeders treat dividing cells with colchicine to produce polyploid plants because colchicine:","options":["makes DNA replicate twice as fast, so cells divide twice as often","breaks the cell wall, so that the cells swell to double their size","removes the nuclear membrane, so that many genes are lost","blocks spindle formation, so duplicated chromosomes stay in one cell and the number doubles"],"answer":3,"explanation":"Colchicine prevents spindle fibres from forming, so the chromosomes replicate but are not pulled apart; the cell ends up with a doubled chromosome number. This is used to raise polyploid crops such as seedless watermelon.","difficulty":"very-hard","questionHi":"पादप प्रजनक विभाजित हो रही कोशिकाओं पर कोल्चिसिन का उपचार करके बहुगुणित पौधे बनाते हैं, क्योंकि कोल्चिसिन:","optionsHi":["DNA का द्विगुणन दोगुनी गति से कराता है, जिससे कोशिकाएँ दोगुनी बार विभाजित होती हैं","कोशिका भित्ति तोड़ देता है, जिससे कोशिकाएँ दोगुने आकार तक फूल जाती हैं","केंद्रक झिल्ली हटा देता है, जिससे अनेक जीन नष्ट हो जाते हैं","तर्कु निर्माण रोक देता है, जिससे द्विगुणित गुणसूत्र एक ही कोशिका में रह जाते हैं और उनकी संख्या दोगुनी हो जाती है"],"explanationHi":"कोल्चिसिन तर्कु तंतुओं को बनने से रोकता है, इसलिए गुणसूत्र द्विगुणित तो होते हैं पर अलग नहीं खींचे जाते; कोशिका में गुणसूत्रों की संख्या दोगुनी हो जाती है। इसका उपयोग बीजरहित तरबूज़ जैसी बहुगुणित फ़सलें बनाने में होता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-362","question":"The synthetic auxin 2,4-D is sprayed on wheat fields to kill weeds without harming the wheat, because:","options":["broad-leaved dicot weeds are far more sensitive to it than narrow-leaved cereals such as wheat","it is absorbed only by weed roots and never by wheat roots","it speeds up wheat growth so that the wheat shades out the weeds","it is a nutrient that only dicot weeds are unable to take up"],"answer":0,"explanation":"2,4-D upsets the growth of broad-leaved dicot plants, which grow abnormally and die, while monocot cereals tolerate it. It is therefore a selective weedicide.","difficulty":"very-hard","questionHi":"कृत्रिम ऑक्सिन 2,4-D का गेहूँ के खेतों में छिड़काव खरपतवारों को मारने के लिए किया जाता है, जिससे गेहूँ को हानि नहीं होती, क्योंकि:","optionsHi":["चौड़ी पत्ती वाले द्विबीजपत्री खरपतवार गेहूँ जैसे संकरी पत्ती वाले अनाजों की तुलना में इसके प्रति कहीं अधिक संवेदनशील होते हैं","यह केवल खरपतवारों की जड़ों द्वारा अवशोषित होता है, गेहूँ की जड़ों द्वारा कभी नहीं","यह गेहूँ की वृद्धि तेज़ करता है, जिससे गेहूँ खरपतवारों को छाया में दबा देता है","यह एक पोषक है जिसे केवल द्विबीजपत्री खरपतवार ही नहीं ले पाते"],"explanationHi":"2,4-D चौड़ी पत्ती वाले द्विबीजपत्री पौधों की वृद्धि बिगाड़ देता है, जिससे वे असामान्य रूप से बढ़कर मर जाते हैं, जबकि एकबीजपत्री अनाज इसे सह लेते हैं। इसीलिए यह चयनात्मक खरपतवारनाशी है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-363","question":"Gardeners cut the tips of hedge shoots to make the hedge bushier. This works because the shoot tip is the source of a hormone that suppresses the growth of lateral buds. That hormone is:","options":["gibberellin","auxin","abscisic acid","ethylene"],"answer":1,"explanation":"Auxin made in the apical bud moves down and inhibits the side buds (apical dominance). Removing the tip removes this source, so lateral buds sprout and the plant becomes bushy.","difficulty":"very-hard","questionHi":"माली बाड़ के प्ररोहों की नोकें काट देते हैं ताकि बाड़ घनी हो जाए। यह इसलिए कारगर है क्योंकि प्ररोह का शीर्ष उस हॉर्मोन का स्रोत है जो पार्श्व कलिकाओं की वृद्धि को दबाता है। वह हॉर्मोन है:","optionsHi":["जिबरेलिन","ऑक्सिन","एब्सिसिक अम्ल","एथिलीन"],"explanationHi":"शीर्ष कलिका में बनने वाला ऑक्सिन नीचे की ओर जाकर पार्श्व कलिकाओं को रोकता है (शीर्ष प्रभाविता)। नोक हटाने से यह स्रोत हट जाता है, इसलिए पार्श्व कलिकाएँ फूट पड़ती हैं और पौधा घना हो जाता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-364","question":"Which of these was NOT a reason why Mendel chose the garden pea for his experiments?","options":["It has several clearly contrasting pairs of characters","Its flowers normally self-pollinate, so pure lines can be kept","It is easy to cross artificially by removing the anthers","Its flowers are naturally cross-pollinated, which ensures plenty of variety"],"answer":3,"explanation":"Pea flowers are bisexual and normally self-pollinate, which let Mendel raise pure lines and then cross them by hand. Natural cross-pollination would have made controlled crosses difficult.","difficulty":"hard","questionHi":"इनमें से कौन-सा कारण नहीं था जिससे मेंडल ने अपने प्रयोगों के लिए बगीचे की मटर चुनी?","optionsHi":["उसमें अनेक स्पष्ट विपर्यासी लक्षण-युग्म हैं","उसके फूल सामान्यतः स्व-परागित होते हैं, इसलिए शुद्ध वंश बनाए रखे जा सकते हैं","परागकोश हटाकर उसमें कृत्रिम संकरण करना आसान है","उसके फूल प्राकृतिक रूप से पर-परागित होते हैं, जिससे प्रचुर विविधता मिलती है"],"explanationHi":"मटर के फूल द्विलिंगी होते हैं और सामान्यतः स्व-परागित होते हैं, जिससे मेंडल शुद्ध वंश उगा पाए और फिर उनमें हाथ से संकरण करा पाए। प्राकृतिक पर-परागण से नियंत्रित संकरण कठिन हो जाता।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-365","question":"In an apple, the fleshy part that we eat is mostly the:","options":["mesocarp of the ovary","endosperm of the seed","thalamus (swollen flower base)","seed coat of the seeds"],"answer":2,"explanation":"In the apple the thalamus (receptacle) grows around the ovary and becomes the juicy flesh, so the apple is a false fruit (pome). The true fruit is the thin core that holds the seeds.","difficulty":"hard","questionHi":"सेब में जो गूदेदार भाग हम खाते हैं, वह मुख्यतः क्या है?","optionsHi":["अंडाशय का मध्य फलभित्ति","बीज का भ्रूणपोष","पुष्पासन (फूल का फूला हुआ आधार)","बीजों का बीजचोल"],"explanationHi":"सेब में पुष्पासन (थैलेमस) अंडाशय के चारों ओर बढ़कर रसीला गूदा बन जाता है, इसलिए सेब असत्य फल (पोम) है। वास्तविक फल बीजों को घेरे हुए पतला भीतरी भाग है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-366","question":"Which of these edible parts is a modified adventitious root and not a stem?","options":["Potato","Ginger","Sweet potato","Colocasia (arbi)"],"answer":2,"explanation":"Sweet potato is a tuberous adventitious root that stores food. Potato is a stem tuber, ginger a rhizome and colocasia a corm, all of which are modified stems.","difficulty":"hard","questionHi":"इनमें से कौन-सा खाद्य भाग रूपांतरित अपस्थानिक जड़ है, तना नहीं?","optionsHi":["आलू","अदरक","शकरकंद","अरबी (कचालू)"],"explanationHi":"शकरकंद भोजन संचित करने वाली कंदिल अपस्थानिक जड़ है। आलू तना कंद है, अदरक प्रकंद और अरबी घनकंद है, ये सभी रूपांतरित तने हैं।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-367","question":"Which statement correctly contrasts cytokinesis in plant and animal cells?","options":["Plant cells divide by a cell plate formed in the middle, animal cells by a furrow that pinches the cell in two","Plant cells divide by a furrow that pinches the cell in two, animal cells by a cell plate formed in the middle","Both plant and animal cells divide by a cell plate formed in the middle of the cell","Both plant and animal cells divide by a furrow that pinches the cell in two"],"answer":0,"explanation":"The rigid cell wall prevents a plant cell from being pinched, so a cell plate grows from the centre outwards and becomes the new wall. An animal cell has no wall, so a cleavage furrow deepens until the cell separates.","difficulty":"hard","questionHi":"पादप और जंतु कोशिकाओं में कोशिकाद्रव्य विभाजन (साइटोकाइनेसिस) का सही अंतर कौन-सा कथन बताता है?","optionsHi":["पादप कोशिका मध्य में बनी कोशिका पट्टिका से और जंतु कोशिका कोशिका को दो में दबाने वाले खाँचे से विभाजित होती है","पादप कोशिका कोशिका को दो में दबाने वाले खाँचे से और जंतु कोशिका मध्य में बनी कोशिका पट्टिका से विभाजित होती है","पादप और जंतु दोनों कोशिकाएँ मध्य में बनी कोशिका पट्टिका से विभाजित होती हैं","पादप और जंतु दोनों कोशिकाएँ कोशिका को दो में दबाने वाले खाँचे से विभाजित होती हैं"],"explanationHi":"कठोर कोशिका भित्ति के कारण पादप कोशिका को दबाया नहीं जा सकता, इसलिए केंद्र से बाहर की ओर कोशिका पट्टिका बनती है जो नई भित्ति बन जाती है। जंतु कोशिका में भित्ति नहीं होती, इसलिए विदलन खाँचा गहरा होकर कोशिका को अलग कर देता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-368","question":"Which component of tobacco smoke is chiefly responsible for addiction to smoking?","options":["Tar","Nicotine","Carbon monoxide","Ammonia"],"answer":1,"explanation":"Nicotine acts on the brain and makes smokers dependent. Tar contains many carcinogens and carbon monoxide lowers the oxygen carried by blood, but neither causes the dependence.","difficulty":"hard","questionHi":"तंबाकू के धुएँ का कौन-सा घटक धूम्रपान की लत के लिए मुख्य रूप से उत्तरदायी है?","optionsHi":["टार","निकोटीन","कार्बन मोनोक्साइड","अमोनिया"],"explanationHi":"निकोटीन मस्तिष्क पर कार्य करके धूम्रपान करने वालों को आदी बना देता है। टार में अनेक कैंसरजन होते हैं और कार्बन मोनोक्साइड रक्त द्वारा ले जाई जाने वाली ऑक्सीजन घटाती है, पर लत इनसे नहीं लगती।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-369","question":"The DPT vaccine protects children against which three diseases?","options":["Diphtheria, pertussis (whooping cough) and tetanus","Dengue, polio and tuberculosis (pulmonary TB)","Diarrhoea, plague and typhoid (enteric fever)","Diabetes, polio and tetanus (lockjaw) in newborns"],"answer":0,"explanation":"DPT stands for Diphtheria, Pertussis and Tetanus. Polio is covered by a separate polio vaccine, and tuberculosis by BCG.","difficulty":"moderate","questionHi":"DPT टीका बच्चों को किन तीन रोगों से बचाता है?","optionsHi":["डिप्थीरिया, पर्टुसिस (काली खाँसी) और टिटनेस","डेंगू, पोलियो और क्षय रोग (फेफड़ों का टीबी)","दस्त, प्लेग और टाइफ़ाइड (आंत्र ज्वर)","मधुमेह, पोलियो और टिटनेस (जबड़ा जकड़न) नवजातों में"],"explanationHi":"DPT का अर्थ है डिप्थीरिया, पर्टुसिस और टिटनेस। पोलियो के लिए अलग पोलियो टीका और क्षय रोग के लिए BCG टीका होता है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-370","question":"Which hormone of the adrenal cortex helps the body to cope with long-term stress by raising the blood glucose level?","options":["Adrenaline","Noradrenaline","Aldosterone","Cortisol"],"answer":3,"explanation":"Cortisol, made by the adrenal cortex, raises blood glucose and is the main long-term stress hormone. Adrenaline and noradrenaline come from the adrenal medulla and give the quick fight-or-flight response; aldosterone controls sodium balance.","difficulty":"hard","questionHi":"अधिवृक्क वल्कुट का कौन-सा हॉर्मोन रक्त ग्लूकोस स्तर बढ़ाकर शरीर को दीर्घकालिक तनाव से निपटने में सहायता देता है?","optionsHi":["ऐड्रीनलीन","नॉरऐड्रीनलीन","ऐल्डोस्टेरोन","कॉर्टिसोल"],"explanationHi":"अधिवृक्क वल्कुट द्वारा बनाया गया कॉर्टिसोल रक्त ग्लूकोस बढ़ाता है और दीर्घकालिक तनाव का मुख्य हॉर्मोन है। ऐड्रीनलीन और नॉरऐड्रीनलीन अधिवृक्क मेडुला से आते हैं और त्वरित संघर्ष-या-पलायन प्रतिक्रिया देते हैं; ऐल्डोस्टेरोन सोडियम संतुलन नियंत्रित करता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-371","question":"After an infected female Anopheles bites a person, the malarial parasite first multiplies in the ___ and then invades the red blood cells.","options":["spleen","liver cells","brain","lymph nodes"],"answer":1,"explanation":"Sporozoites injected by the mosquito go to the liver, multiply there without symptoms, and then burst out to infect red blood cells. The cyclic bursting of red cells causes the fever with chills.","difficulty":"very-hard","questionHi":"संक्रमित मादा एनोफ़िलीज़ के काटने के बाद मलेरिया परजीवी पहले ___ में गुणन करता है और फिर लाल रुधिर कोशिकाओं पर आक्रमण करता है।","optionsHi":["प्लीहा","यकृत कोशिकाओं","मस्तिष्क","लसीका गाँठों"],"explanationHi":"मच्छर द्वारा डाले गए स्पोरोज़ॉइट यकृत में जाकर बिना लक्षण के गुणन करते हैं और फिर फूटकर लाल रुधिर कोशिकाओं को संक्रमित करते हैं। लाल कोशिकाओं के चक्रीय रूप से फूटने से ठंड के साथ बुखार आता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-372","question":"When the pigments of a leaf are separated by paper chromatography, which pigment travels the farthest from the starting spot?","options":["Chlorophyll b","Chlorophyll a","Carotene","Xanthophyll"],"answer":2,"explanation":"Carotene is the least polar and most soluble in the solvent, so it runs farthest and gives the top, yellow-orange band. In order of distance travelled: carotene, xanthophyll, chlorophyll a, chlorophyll b.","difficulty":"very-hard","questionHi":"जब किसी पत्ती के वर्णकों को पेपर क्रोमैटोग्राफ़ी से पृथक किया जाता है, तब कौन-सा वर्णक प्रारंभिक बिंदु से सबसे दूर तक जाता है?","optionsHi":["क्लोरोफ़िल b","क्लोरोफ़िल a","कैरोटीन","ज़ैन्थोफ़िल"],"explanationHi":"कैरोटीन सबसे कम ध्रुवीय और विलायक में सबसे अधिक घुलनशील है, इसलिए वह सबसे दूर जाता है और ऊपर की पीली-नारंगी पट्टी बनाता है। तय की गई दूरी के क्रम में: कैरोटीन, ज़ैन्थोफ़िल, क्लोरोफ़िल a, क्लोरोफ़िल b।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-373","question":"An insect survives even though its blood contains no oxygen-carrying pigment like haemoglobin. This is because:","options":["its blood carries a very large amount of oxygen dissolved in the plasma","air is carried through tracheal tubes directly to the tissues","it breathes through gills that extract oxygen from the air","it stores oxygen in its muscles and uses it slowly"],"answer":1,"explanation":"Insects breathe through spiracles and a network of tracheae that carry air right up to the cells, so the blood does not need to transport oxygen. Their blood (haemolymph) mainly carries nutrients and wastes.","difficulty":"very-hard","questionHi":"कीट के रक्त में हीमोग्लोबिन जैसा ऑक्सीजन वाहक वर्णक नहीं होता, फिर भी वह जीवित रहता है। इसका कारण है:","optionsHi":["उसका रक्त प्लाज़्मा में घुली हुई बहुत अधिक ऑक्सीजन ले जाता है","वायु श्वास नलिकाओं (ट्रेकिया) द्वारा सीधे ऊतकों तक पहुँचाई जाती है","वह गिल्स से साँस लेता है जो वायु से ऑक्सीजन निकालते हैं","वह ऑक्सीजन को अपनी पेशियों में संचित करके धीरे-धीरे उपयोग करता है"],"explanationHi":"कीट श्वासरंध्रों और श्वास नलिकाओं के जाल से साँस लेते हैं जो वायु को सीधे कोशिकाओं तक पहुँचाता है, इसलिए रक्त को ऑक्सीजन ले जाने की आवश्यकता नहीं होती। उनका रक्त (हीमोलिम्फ) मुख्यतः पोषक पदार्थ और अपशिष्ट ले जाता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-374","question":"Project Tiger, the scheme to protect the tiger and its habitat, was launched in India in:","options":["1973","1963","1983","1993"],"answer":0,"explanation":"Project Tiger was launched in 1973 from Jim Corbett National Park, with a number of tiger reserves set up in different states. The Wildlife (Protection) Act followed in 1972.","difficulty":"moderate","questionHi":"बाघ और उसके आवास की रक्षा की योजना प्रोजेक्ट टाइगर भारत में किस वर्ष शुरू की गई?","optionsHi":["1973","1963","1983","1993"],"explanationHi":"प्रोजेक्ट टाइगर 1973 में जिम कॉर्बेट राष्ट्रीय उद्यान से शुरू हुआ और विभिन्न राज्यों में कई बाघ अभयारण्य बनाए गए। वन्यजीव (संरक्षण) अधिनियम उससे एक वर्ष पहले, 1972 में बना था।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-375","question":"Besides carbon dioxide, which greenhouse gas is released in large quantities from flooded paddy fields and from the guts of cattle?","options":["Nitrous oxide","Methane","Sulphur dioxide","Ozone"],"answer":1,"explanation":"Anaerobic bacteria in waterlogged paddy soil and in the rumen of cattle produce methane. Gram for gram it traps far more heat than carbon dioxide.","difficulty":"moderate","questionHi":"कार्बन डाइऑक्साइड के अतिरिक्त, पानी भरे धान के खेतों और पशुओं की आँतों से कौन-सी ग्रीनहाउस गैस बड़ी मात्रा में निकलती है?","optionsHi":["नाइट्रस ऑक्साइड","मेथेन","सल्फर डाइऑक्साइड","ओज़ोन"],"explanationHi":"जलमग्न धान की मिट्टी और पशुओं के रूमेन में अवायवीय जीवाणु मेथेन बनाते हैं। भार के अनुसार यह कार्बन डाइऑक्साइड से कहीं अधिक ऊष्मा रोकती है।","source":"SSC CGL · RRB Group D"},
];

